<template>
  <div class="quan-ly-hang-hoa qlhh-page" :class="{ 'theme-light-blue': uiTheme === 'light' }">
    <!-- =========================================================
         1. DẢI 3 THẺ BENTO KPI (TỔNG QUAN & LỌC NHANH)
    ========================================================== -->
    <section class="qlhh-kpi-grid" aria-label="Tổng quan danh mục hàng hóa">
      <!-- KPI 1: TỔNG DANH MỤC HÀNG HÓA (Sky) -->
      <div
        role="button"
        tabindex="0"
        class="qlhh-kpi-card is-sky"
        :class="{ active: !selectedBrandFilter && !selectedPriceListId && !hasActiveSearchOrFilter }"
        @click="resetAllSearchAndFilters(); selectedPriceListId = ''"
        @keydown.enter.prevent="resetAllSearchAndFilters(); selectedPriceListId = ''"
        title="Bấm để xem toàn bộ danh mục hàng hóa"
      >
        <div class="kpi-head">
          <span class="kpi-label">Tổng Kho Danh Mục</span>
          <span class="kpi-icon is-sky">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/></svg>
          </span>
        </div>
        <div class="kpi-main-row">
          <div class="kpi-val tabular-nums">
            {{ items.length }}
            <span class="kpi-unit">SKU</span>
          </div>
          <div class="kpi-sub-pills">
            <span class="kpi-mini-pill tabular-nums">{{ allCategoriesTotalCount }} danh mục</span>
            <span class="kpi-mini-pill tabular-nums">{{ supplierFilterOptions.length }} NCC</span>
          </div>
        </div>
      </div>

      <!-- KPI 2: PHÂN BỔ HÃNG CHỦ LỰC (Emerald) -->
      <div
        role="button"
        tabindex="0"
        class="qlhh-kpi-card is-emerald"
        :class="{ active: Boolean(selectedBrandFilter) }"
        @click="selectedBrandFilter = ''"
        @keydown.enter.prevent="selectedBrandFilter = ''"
        title="Bấm vào từng hãng để lọc nhanh, hoặc bấm nền thẻ để bỏ lọc hãng"
      >
        <div class="kpi-head">
          <span class="kpi-label">Phân Bổ Hãng Chủ Lực</span>
          <span class="kpi-icon is-emerald">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
          </span>
        </div>
        <div class="kpi-brand-chips" @click.stop>
          <button
            type="button"
            class="kpi-brand-chip"
            :class="{ active: selectedBrandFilter === 'SOPHOS' }"
            @click.stop="toggleBrandQuickFilter('SOPHOS')"
          >
            <span>Sophos</span>
            <strong class="tabular-nums">{{ brandKpiCounts.sophos }}</strong>
          </button>
          <button
            type="button"
            class="kpi-brand-chip"
            :class="{ active: selectedBrandFilter === 'KASPERSKY' }"
            @click.stop="toggleBrandQuickFilter('KASPERSKY')"
          >
            <span>Kaspersky</span>
            <strong class="tabular-nums">{{ brandKpiCounts.kaspersky }}</strong>
          </button>
          <button
            type="button"
            class="kpi-brand-chip"
            :class="{ active: selectedBrandFilter === 'ACRONIS' }"
            @click.stop="toggleBrandQuickFilter('ACRONIS')"
          >
            <span>Acronis</span>
            <strong class="tabular-nums">{{ brandKpiCounts.acronis }}</strong>
          </button>
          <button
            type="button"
            class="kpi-brand-chip"
            :class="{ active: selectedBrandFilter === '__OTHER_BRANDS__' }"
            @click.stop="toggleBrandQuickFilter('__OTHER_BRANDS__')"
          >
            <span>Khác</span>
            <strong class="tabular-nums">{{ brandKpiCounts.others }}</strong>
          </button>
        </div>
      </div>

      <!-- KPI 3: BẢNG GIÁ & TỈ GIÁ USD (Amber) -->
      <div
        role="button"
        tabindex="0"
        class="qlhh-kpi-card is-amber"
        :class="{ active: Boolean(selectedPriceListId) }"
        @click.stop="toggleFilterDropdown('pricelist')"
        @keydown.enter.prevent="toggleFilterDropdown('pricelist')"
        title="Quản lý bảng giá áp dụng và tỉ giá quy đổi USD"
      >
        <div class="kpi-head">
          <span class="kpi-label">Bảng Giá &amp; Tỉ Giá USD</span>
          <span class="kpi-icon is-amber">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
          </span>
        </div>
        <div class="kpi-main-row kpi-main-row--wrap">
          <div class="kpi-pl-name" :title="activePriceList ? activePriceList.ten_bang_gia : 'Giá gốc hệ thống'">
            {{ activePriceList ? activePriceList.ten_bang_gia : 'Giá gốc hệ thống' }}
          </div>
          <div class="kpi-sub-pills" @click.stop>
            <button
              type="button"
              class="kpi-action-pill is-amber tabular-nums"
              title="Thay đổi tỉ giá đồng loạt cho các sản phẩm USD"
              @click.stop="openUsdRateModal"
            >
              USD: {{ currentSystemUsdRate > 1 ? formatNumberPlain(currentSystemUsdRate) + ' ₫' : 'Đặt tỉ giá' }}
            </button>
            <button
              type="button"
              class="kpi-action-pill is-sky"
              title="Tạo bảng giá tùy chỉnh mới"
              @click.stop="openCreatePriceListModal"
            >
              + Bảng giá ({{ priceLists.length }})
            </button>
          </div>
        </div>
      </div>
    </section>

    <!-- =========================================================
         2. THANH BỘ LỌC, TÌM KIẾM BO TRÒN & THAO TÁC HỢP NHẤT
    ========================================================== -->
    <section class="qlhh-filter-bar">
      <div class="qlhh-filter-row-main">
        <!-- BÊN TRÁI: CÁC PICKER BỘ LỌC GỌN GÀNG -->
        <div class="qlhh-filter-left">
          <!-- 1. Lọc Hãng -->
          <div class="qlhh-picker-root" @click.stop>
            <button
              type="button"
              class="qlhh-picker-btn"
              :class="{ 'is-active': Boolean(selectedBrandFilter), 'is-open': openDropdownType === 'brand' }"
              @click="toggleFilterDropdown('brand')"
              title="Lọc theo hãng sản xuất"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
              <span class="picker-btn-text">{{ selectedBrandBtnLabel }}</span>
              <span
                v-if="selectedBrandFilter"
                class="picker-clear-dot"
                title="Bỏ lọc hãng"
                @click.stop="selectedBrandFilter = ''"
              >✕</span>
              <svg v-else width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" class="picker-chev"><polyline points="6 9 12 15 18 9"/></svg>
            </button>

            <div v-if="openDropdownType === 'brand'" class="qlhh-pop-backdrop" @click="openDropdownType = ''"></div>
            <div v-if="openDropdownType === 'brand'" class="qlhh-pop-menu" :class="{ 'theme-light-blue': uiTheme === 'light' }">
              <div class="mob-sheet-grabber"></div>
              <div class="qlhh-pop-head">
                <span>Chọn Hãng sản xuất</span>
                <button type="button" class="qlhh-pop-close" @click="openDropdownType = ''">✕</button>
              </div>
              <div class="qlhh-pop-search-wrap">
                <input
                  type="text"
                  v-model="brandDropdownSearch"
                  placeholder="Tìm nhanh hãng..."
                  class="qlhh-pop-search"
                />
              </div>
              <div class="qlhh-pop-list" @scroll="onFilterDropdownScroll($event, 'brand')">
                <button
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: !selectedBrandFilter }"
                  @click="selectFilterOption('brand', '')"
                >
                  <span>Tất cả Hãng</span>
                  <span class="qlhh-pop-count tabular-nums">{{ items.length }}</span>
                </button>
                <button
                  v-for="opt in displayedBrandOptions"
                  :key="opt.value"
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: selectedBrandFilter === opt.value }"
                  @click="selectFilterOption('brand', opt.value)"
                >
                  <span>{{ opt.label }}</span>
                  <span class="qlhh-pop-count tabular-nums">{{ opt.count }}</span>
                </button>
                <div v-if="!filteredBrandOptions.length" class="qlhh-pop-empty">Không tìm thấy hãng phù hợp</div>
                <button
                  v-if="displayedBrandOptions.length < filteredBrandOptions.length"
                  type="button"
                  class="qlhh-pop-more"
                  @click="brandDropdownLimit += FILTER_DROPDOWN_PAGE_SIZE"
                >
                  Đang hiện {{ displayedBrandOptions.length }}/{{ filteredBrandOptions.length }} — Bấm tải thêm
                </button>
              </div>
            </div>
          </div>

          <!-- 2. Lọc Danh mục -->
          <div class="qlhh-picker-root" @click.stop>
            <button
              type="button"
              class="qlhh-picker-btn"
              :class="{ 'is-active': Boolean(selectedCategoryFilter), 'is-open': openDropdownType === 'category' }"
              @click="toggleFilterDropdown('category')"
              title="Lọc theo danh mục sản phẩm"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
              <span class="picker-btn-text">{{ selectedCategoryFilter ? 'DM: ' + selectedCategoryFilter : `Danh mục (${categoryFilterOptions.length})` }}</span>
              <span
                v-if="selectedCategoryFilter"
                class="picker-clear-dot"
                title="Bỏ lọc danh mục"
                @click.stop="selectedCategoryFilter = ''"
              >✕</span>
              <svg v-else width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" class="picker-chev"><polyline points="6 9 12 15 18 9"/></svg>
            </button>

            <div v-if="openDropdownType === 'category'" class="qlhh-pop-backdrop" @click="openDropdownType = ''"></div>
            <div v-if="openDropdownType === 'category'" class="qlhh-pop-menu is-wide" :class="{ 'theme-light-blue': uiTheme === 'light' }">
              <div class="mob-sheet-grabber"></div>
              <div class="qlhh-pop-head">
                <span>Chọn Danh mục</span>
                <button type="button" class="qlhh-pop-close" @click="openDropdownType = ''">✕</button>
              </div>
              <div class="qlhh-pop-search-wrap">
                <input
                  type="text"
                  v-model="categoryDropdownSearch"
                  placeholder="Tìm nhanh danh mục..."
                  class="qlhh-pop-search"
                />
              </div>
              <div class="qlhh-pop-list" @scroll="onFilterDropdownScroll($event, 'category')">
                <button
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: !selectedCategoryFilter }"
                  @click="selectFilterOption('category', '')"
                >
                  <span>Tất cả Danh mục</span>
                  <span class="qlhh-pop-count tabular-nums">{{ categoryFilterTotalItems }}</span>
                </button>
                <button
                  v-for="opt in displayedCategoryOptions"
                  :key="opt.value"
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: selectedCategoryFilter === opt.value }"
                  @click="selectFilterOption('category', opt.value)"
                >
                  <span :title="opt.label">{{ opt.label }}</span>
                  <span class="qlhh-pop-count tabular-nums">{{ opt.count }}</span>
                </button>
                <div v-if="!filteredCategoryOptions.length" class="qlhh-pop-empty">Không tìm thấy danh mục phù hợp</div>
                <button
                  v-if="displayedCategoryOptions.length < filteredCategoryOptions.length"
                  type="button"
                  class="qlhh-pop-more"
                  @click="categoryDropdownLimit += FILTER_DROPDOWN_PAGE_SIZE"
                >
                  Đang hiện {{ displayedCategoryOptions.length }}/{{ filteredCategoryOptions.length }} — Bấm tải thêm
                </button>
              </div>
            </div>
          </div>

          <!-- 3. Chọn Bảng Giá -->
          <div class="qlhh-picker-root" @click.stop>
            <button
              type="button"
              class="qlhh-picker-btn"
              :class="{ 'is-active': Boolean(selectedPriceListId), 'is-open': openDropdownType === 'pricelist' }"
              @click="toggleFilterDropdown('pricelist')"
              title="Chọn bảng giá hiển thị"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
              <span class="picker-btn-text">{{ activePriceList ? activePriceList.ten_bang_gia : 'Giá gốc' }}</span>
              <span
                v-if="selectedPriceListId"
                class="picker-clear-dot"
                title="Quay về Giá gốc hệ thống"
                @click.stop="selectedPriceListId = ''"
              >✕</span>
              <svg v-else width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" class="picker-chev"><polyline points="6 9 12 15 18 9"/></svg>
            </button>

            <div v-if="openDropdownType === 'pricelist'" class="qlhh-pop-backdrop" @click="openDropdownType = ''"></div>
            <div v-if="openDropdownType === 'pricelist'" class="qlhh-pop-menu is-wide" :class="{ 'theme-light-blue': uiTheme === 'light' }">
              <div class="mob-sheet-grabber"></div>
              <div class="qlhh-pop-head">
                <span>Chọn Bảng giá áp dụng</span>
                <button type="button" class="qlhh-pop-close" @click="openDropdownType = ''">✕</button>
              </div>
              <div class="qlhh-pop-list">
                <button
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: !selectedPriceListId }"
                  @click="selectedPriceListId = ''; openDropdownType = ''"
                >
                  <span>Giá gốc hệ thống</span>
                  <span class="qlhh-pop-count tabular-nums">{{ items.length }} SP</span>
                </button>
                <button
                  v-for="pl in priceLists"
                  :key="pl._firebaseKey"
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: selectedPriceListId === pl._firebaseKey }"
                  @click="selectedPriceListId = pl._firebaseKey; openDropdownType = ''"
                >
                  <span :title="pl.ten_bang_gia + formatPriceListPeriodInline(pl)">
                    {{ pl.ten_bang_gia }}{{ formatPriceListPeriodInline(pl) }}
                  </span>
                  <span class="qlhh-pop-count tabular-nums">{{ (pl.items || []).length }} SP</span>
                </button>
              </div>
              <div class="qlhh-pop-foot">
                <button
                  type="button"
                  class="qlhh-pop-create-btn"
                  @click="openDropdownType = ''; openCreatePriceListModal()"
                >
                  + Tạo bảng giá mới
                </button>
              </div>
            </div>
          </div>

          <!-- 6. Sắp xếp -->
          <div class="qlhh-picker-root" @click.stop>
            <button
              type="button"
              class="qlhh-picker-btn"
              :class="{ 'is-active': sortOrder !== 'default', 'is-open': openDropdownType === 'sort' }"
              @click="toggleFilterDropdown('sort')"
              title="Chọn thứ tự sắp xếp"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><polyline points="19 12 12 19 5 12"/></svg>
              <span class="picker-btn-text">{{ sortOrderLabel }}</span>
              <span
                v-if="sortOrder !== 'default'"
                class="picker-clear-dot"
                title="Về sắp xếp mặc định"
                @click.stop="sortOrder = 'default'"
              >✕</span>
              <svg v-else width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" class="picker-chev"><polyline points="6 9 12 15 18 9"/></svg>
            </button>

            <div v-if="openDropdownType === 'sort'" class="qlhh-pop-backdrop" @click="openDropdownType = ''"></div>
            <div v-if="openDropdownType === 'sort'" class="qlhh-pop-menu" :class="{ 'theme-light-blue': uiTheme === 'light' }">
              <div class="mob-sheet-grabber"></div>
              <div class="qlhh-pop-head">
                <span>Sắp xếp danh sách</span>
                <button type="button" class="qlhh-pop-close" @click="openDropdownType = ''">✕</button>
              </div>
              <div class="qlhh-pop-list">
                <button
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: sortOrder === 'default' }"
                  @click="sortOrder = 'default'; openDropdownType = ''"
                >
                  <span>Mặc định (theo danh mục)</span>
                  <span v-if="sortOrder === 'default'" class="qlhh-pop-check">✓</span>
                </button>
                <button
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: sortOrder === 'newest' }"
                  @click="sortOrder = 'newest'; openDropdownType = ''"
                >
                  <span>Mới cập nhật → Cũ nhất</span>
                  <span v-if="sortOrder === 'newest'" class="qlhh-pop-check">✓</span>
                </button>
                <button
                  type="button"
                  class="qlhh-pop-item"
                  :class="{ active: sortOrder === 'oldest' }"
                  @click="sortOrder = 'oldest'; openDropdownType = ''"
                >
                  <span>Cũ nhất → Mới cập nhật</span>
                  <span v-if="sortOrder === 'oldest'" class="qlhh-pop-check">✓</span>
                </button>
              </div>
            </div>
          </div>

          <button
            v-if="hasActiveSearchOrFilter || selectedPriceListId"
            type="button"
            class="qlhh-reset-btn"
            @click="resetAllSearchAndFilters(); selectedPriceListId = ''"
            title="Đặt lại toàn bộ bộ lọc & tìm kiếm"
          >
            <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            <span>Đặt lại</span>
          </button>
        </div>

        <!-- Ở GIỮA: KHUNG TÌM KIẾM BO TRÒN VIỀN XANH NHẸ (TÍCH HỢP Ô LỌC USER / VOLUME) -->
        <div class="qlhh-search-box" :class="{ 'has-vol-active': userVolumeFilter !== '' }">
          <svg class="qlhh-search-ico" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          <input
            v-model="searchQuery"
            type="text"
            class="qlhh-search-input"
            placeholder="Tìm mã hàng, SKU, tên hàng, danh mục..."
          />
          <button
            v-if="searchQuery"
            type="button"
            class="qlhh-search-clear"
            @click="searchQuery = ''"
          >
            Xóa
          </button>

          <span class="qlhh-search-sep" aria-hidden="true"></span>

          <div
            class="qlhh-search-vol"
            :class="{ 'is-active': userVolumeFilter !== '' }"
            title="Nhập số user / thiết bị để lọc dải Volume tương ứng"
          >
            <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
            <NumberInput
              :modelValue="userVolumeFilter"
              @update:modelValue="onUserVolumeInput"
              :decimals="0"
              :emptyOnZero="true"
              placeholder="User..."
              class="qlhh-search-vol-input tabular-nums"
              aria-label="Lọc theo số user / Volume"
            />
            <button
              v-if="userVolumeFilter !== ''"
              type="button"
              class="picker-clear-dot"
              title="Xóa lọc User"
              @click="userVolumeFilter = ''"
            >✕</button>
          </div>

          <span v-if="hasActiveSearchOrFilter || selectedPriceListId" class="qlhh-search-count tabular-nums">
            {{ totalProductsCount }} SP
          </span>
        </div>

        <!-- BÊN PHẢI: CHẾ ĐỘ HIỂN THỊ · NHÓM · ĐỒNG BỘ · IMPORT HUB · THÊM MỚI -->
        <div class="qlhh-filter-right">
          <!-- Nút Chế độ hiển thị hợp nhất (Thẻ / Bảng & Light / Dark Mode) -->
          <div class="qlhh-picker-root hide-mob-dock" @click.stop>
            <button
              type="button"
              class="qlhh-picker-btn qlhh-display-btn"
              :class="{ 'is-open': openDropdownType === 'display' }"
              @click="toggleFilterDropdown('display')"
              title="Chế độ hiển thị (Thẻ / Bảng & Light / Dark Mode)"
            >
              <svg width="14.5" height="14.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">
                <circle cx="12" cy="12" r="3"/>
                <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/>
              </svg>
              <span>Chế độ hiển thị</span>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" class="picker-chev"><polyline points="6 9 12 15 18 9"/></svg>
            </button>

            <div v-if="openDropdownType === 'display'" class="qlhh-pop-backdrop" @click="openDropdownType = ''"></div>
            <div v-if="openDropdownType === 'display'" class="qlhh-pop-menu is-align-right is-display-pop" :class="{ 'theme-light-blue': uiTheme === 'light' }">
              <div class="mob-sheet-grabber"></div>
              <div class="qlhh-pop-head">
                <span>Chế độ hiển thị</span>
                <button type="button" class="qlhh-pop-close" @click="openDropdownType = ''">✕</button>
              </div>
              <div class="qlhh-display-pop-body">
                <div class="qlhh-display-sec">
                  <div class="qlhh-display-sec-lbl">Kiểu danh sách</div>
                  <div class="qlhh-display-grid">
                    <button
                      type="button"
                      class="qlhh-display-opt"
                      :class="{ active: viewMode === 'card' }"
                      @click="setViewMode('card')"
                    >
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/></svg>
                      <span>Thẻ</span>
                    </button>
                    <button
                      type="button"
                      class="qlhh-display-opt"
                      :class="{ active: viewMode === 'table' }"
                      @click="setViewMode('table')"
                    >
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>
                      <span>Bảng</span>
                    </button>
                  </div>
                </div>

                <div class="qlhh-display-sec">
                  <div class="qlhh-display-sec-lbl">Giao diện (Theme)</div>
                  <div class="qlhh-display-grid">
                    <button
                      type="button"
                      class="qlhh-display-opt"
                      :class="{ active: uiTheme === 'light' }"
                      @click="uiTheme !== 'light' && toggleUiTheme()"
                    >
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>
                      <span>Light Mode</span>
                    </button>
                    <button
                      type="button"
                      class="qlhh-display-opt"
                      :class="{ active: uiTheme === 'dark' }"
                      @click="uiTheme !== 'dark' && toggleUiTheme()"
                    >
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>
                      <span>Dark Mode</span>
                    </button>
                  </div>
                </div>

                <div v-if="totalGroupsCount > 0" class="qlhh-display-sec">
                  <div class="qlhh-display-sec-lbl">Nhóm danh mục</div>
                  <div class="qlhh-display-grid">
                    <button
                      type="button"
                      class="qlhh-display-opt"
                      :class="{ active: !areAllCategoriesCollapsed }"
                      @click="areAllCategoriesCollapsed && toggleAllCategoriesCollapse()"
                    >
                      <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
                      <span>Mở rộng</span>
                    </button>
                    <button
                      type="button"
                      class="qlhh-display-opt"
                      :class="{ active: areAllCategoriesCollapsed }"
                      @click="!areAllCategoriesCollapsed && toggleAllCategoriesCollapse()"
                    >
                      <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg>
                      <span>Thu gọn</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <button
            type="button"
            class="qlhh-ghost-btn qlhh-bulk-toggle-btn hide-mob-dock"
            :class="{ 'is-active': bulkEditMode }"
            @click="toggleBulkEditMode"
            :title="bulkEditMode ? 'Thoát chế độ chọn & sửa hàng loạt' : 'Bật chế độ tick chọn để sửa hoặc xóa nhiều sản phẩm cùng lúc'"
          >
            <svg width="14.5" height="14.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 11 12 14 22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
            <span>{{ bulkEditMode ? 'Đang chọn sửa' : 'Sửa hàng loạt' }}</span>
            <span v-if="bulkEditMode && bulkSelectedKeys.length > 0" class="qlhh-bulk-btn-count tabular-nums">
              {{ bulkSelectedKeys.length }}
            </span>
          </button>

          <button
            type="button"
            class="qlhh-icon-btn hide-mob-dock"
            :disabled="loading"
            @click="fetchData"
            title="Đồng bộ lại dữ liệu"
          >
            <svg :class="{ 'is-spin': loading }" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>
          </button>

          <button
            type="button"
            class="qlhh-ghost-btn is-hub-btn hide-mob-dock"
            @click="openImportHub()"
            title="Import Excel/PDF danh mục hãng, giá vốn & mức off"
          >
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
            <span>Import</span>
          </button>

          <button
            type="button"
            class="qlhh-ghost-btn is-compare-hub-btn hide-mob-dock"
            @click="openCompareHub()"
            title="Đối chiếu ảnh/bảng giá hãng & quản lý file tham chiếu Cloudinary"
          >
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
            <span>Đối chiếu</span>
          </button>

          <button
            type="button"
            class="qlhh-ghost-btn is-usd-rate-btn hide-mob-dock"
            @click="openUsdRateModal()"
            :title="`Đổi tỉ giá USD toàn hệ thống (hiện tại: ${currentSystemUsdRate > 1 ? formatNumberPlain(currentSystemUsdRate) + ' ₫' : 'Chưa đặt'})`"
          >
            <svg width="14.5" height="14.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
            <span>Đổi tỉ giá</span>
          </button>

          <button
            type="button"
            class="qlhh-ghost-btn is-pricelist-btn hide-mob-dock"
            @click="openCreatePriceListModal()"
            :title="`Tạo bảng giá riêng mới (hiện có ${priceLists.length} bảng giá)`"
          >
            <svg width="14.5" height="14.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
            <span>Tạo bảng giá</span>
          </button>

          <button
            type="button"
            class="qlhh-btn-primary hide-mob-dock"
            @click="openAddModal"
          >
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            <span>Thêm mới</span>
          </button>
        </div>
      </div>

      <!-- DẢI PHỤ NGỮ CẢNH: CHỈ HIỆN KHI ĐANG CHỌN BẢNG GIÁ TÙY CHỈNH -->
      <div v-if="activePriceList" class="qlhh-pricelist-context-bar">
        <div class="pl-ctx-left">
          <span class="pl-ctx-title">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
            <strong>{{ activePriceList.ten_bang_gia }}</strong>
          </span>
          <span v-if="activePriceList.ngay_bat_dau || activePriceList.ngay_ket_thuc" class="pricelist-period-badge tabular-nums">
            {{ formatPriceListPeriod(activePriceList) }}
          </span>
          <span class="pricelist-status-badge" :class="getPriceListStatusInfo(activePriceList).cls">
            {{ getPriceListStatusInfo(activePriceList).label }}
          </span>
          <span v-if="activePriceList.default_rule && activePriceList.default_rule.value" class="pricelist-rule-badge tabular-nums">
            {{ activePriceList.default_rule.direction === 'decrease' ? 'Giảm (-)' : 'Tăng (+)' }}
            {{ activePriceList.default_rule.type === 'percent' ? activePriceList.default_rule.value + '%' : formatNumberPlain(activePriceList.default_rule.value) }}
          </span>
        </div>

        <div class="pl-ctx-right">
          <button
            type="button"
            class="pricelist-autosync-btn"
            :class="activePriceList.auto_sync_base_price ? 'on' : 'off'"
            @click="togglePriceListAutoSync(activePriceList)"
            :title="activePriceList.auto_sync_base_price ? 'Đang BẬT: Khi giá gốc thay đổi, bảng giá này tự động tính lại. Nhấn để TẮT.' : 'Đang TẮT: Giữ cố định giá bán hiện tại. Nhấn để BẬT tự động cập nhật.'"
          >
            <span>{{ activePriceList.auto_sync_base_price ? 'Auto-sync giá gốc: BẬT' : 'Giá cố định (Tắt Auto-sync)' }}</span>
          </button>
          <button type="button" class="pricelist-action-btn edit" @click="openEditPriceListModal(activePriceList)">
            <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            <span>Sửa</span>
          </button>
          <button type="button" class="pricelist-action-btn export" @click="exportPriceListToExcel(activePriceList)">
            <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
            <span>Xuất Excel</span>
          </button>
          <button type="button" class="pricelist-action-btn delete" @click="requestDeletePriceList(activePriceList)" title="Xóa bảng giá này">
            <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
          </button>
        </div>
      </div>
    </section>

    <!-- =========================================================
         3. DANH SÁCH SẢN PHẨM (NHÓM THU GỌN + THẺ 4 TẦNG ↔ BẢNG)
    ========================================================== -->
    <div v-if="loading && !items.length" class="qlhh-skeleton-wrap">
      <div class="qlhh-skeleton-bar"></div>
      <div class="qlhh-cards-grid">
        <div v-for="i in 6" :key="'skeleton-' + i" class="qlhh-skeleton-card">
          <div class="sk-row-top">
            <div class="skeleton sk-pill"></div>
            <div class="skeleton sk-pill w60"></div>
          </div>
          <div class="skeleton sk-code"></div>
          <div class="skeleton sk-title"></div>
          <div class="skeleton sk-title w70"></div>
          <div class="sk-chips">
            <div class="skeleton sk-chip"></div>
            <div class="skeleton sk-chip"></div>
          </div>
          <div class="sk-footer">
            <div class="skeleton sk-price"></div>
            <div class="skeleton sk-btn"></div>
          </div>
        </div>
      </div>
    </div>

    <div v-else-if="!filteredItems.length" class="qlhh-empty-state">
      <div class="empty-ico">
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/></svg>
      </div>
      <h3>Không tìm thấy hàng hóa phù hợp</h3>
      <p>Thử điều chỉnh từ khóa, bộ lọc Hãng/Danh mục hoặc thêm sản phẩm mới vào kho.</p>
      <div class="empty-actions">
        <button
          v-if="hasActiveSearchOrFilter || selectedPriceListId"
          type="button"
          class="qlhh-ghost-btn"
          @click="resetAllSearchAndFilters(); selectedPriceListId = ''"
        >
          Xóa toàn bộ bộ lọc
        </button>
        <button type="button" class="qlhh-btn-primary" @click="openAddModal">+ Thêm hàng hóa mới</button>
      </div>
    </div>

    <div v-else class="qlhh-groups-stack">
      <section
        v-for="(groupItems, category) in groupedItems"
        :key="category"
        class="qlhh-group-block"
        :class="{ 'is-collapsed': Boolean(collapsedCategories[category]) }"
      >
        <!-- HEADER NHÓM DANH MỤC (BẤM THU GỌN / MỞ RỘNG) -->
        <div class="qlhh-group-header" @click="toggleCategoryCollapse(category)">
          <div class="gh-left">
            <button
              v-if="bulkEditMode"
              type="button"
              class="qlhh-bulk-check is-on-header"
              :class="{
                selected: isBulkCategoryAllSelected(category),
                'is-partial': isBulkCategoryPartialSelected(category)
              }"
              :title="isBulkCategoryAllSelected(category) ? 'Bỏ chọn tất cả sản phẩm trong nhóm này' : 'Chọn tất cả sản phẩm trong nhóm này'"
              @click.stop="toggleBulkCategorySelection(category)"
            >
              <svg v-if="isBulkCategoryAllSelected(category)" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
              <span v-else-if="isBulkCategoryPartialSelected(category)" class="qlhh-bulk-chk-dash"></span>
            </button>
            <span class="gh-folder-ico">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
            </span>
            <div class="gh-title-wrap">
              <h3 class="gh-title" :title="category">{{ category }}</h3>
              <span
                v-if="!collapsedCategories[category] && (categoryTotalCounts[category] || 0) > groupItems.length"
                class="gh-sub-hint tabular-nums"
              >
                Đang hiển thị {{ groupItems.length }}/{{ categoryTotalCounts[category] }}
              </span>
            </div>
          </div>

          <div class="gh-right">
            <span class="gh-count-pill tabular-nums">
              {{ categoryTotalCounts[category] || groupItems.length }} SP
            </span>
            <button
              type="button"
              class="gh-toggle-btn"
              :aria-expanded="!collapsedCategories[category]"
              :title="collapsedCategories[category] ? 'Mở rộng nhóm danh mục' : 'Thu gọn nhóm danh mục'"
              @click.stop="toggleCategoryCollapse(category)"
            >
              <svg
                class="gh-chevron"
                :class="{ 'is-collapsed': Boolean(collapsedCategories[category]) }"
                width="15"
                height="15"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2.4"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <polyline points="6 9 12 15 18 9"/>
              </svg>
            </button>
          </div>
        </div>

        <!-- NỘI DUNG NHÓM KHI MỞ RỘNG -->
        <template v-if="!collapsedCategories[category] && groupItems.length > 0">
          <!-- CHẾ ĐỘ BẢNG DỮ LIỆU (TABLE VIEW — DESKTOP / TABLET) -->
          <div v-if="viewMode === 'table' && !isCompactPhoneViewport" class="qlhh-table-wrap">
            <table class="qlhh-data-table">
              <thead>
                <tr>
                  <th v-if="bulkEditMode" class="col-bulk-chk">
                    <button
                      type="button"
                      class="qlhh-bulk-check"
                      :class="{
                        selected: isBulkCategoryAllSelected(category),
                        'is-partial': isBulkCategoryPartialSelected(category)
                      }"
                      :title="isBulkCategoryAllSelected(category) ? 'Bỏ chọn cả nhóm' : 'Chọn cả nhóm'"
                      @click.stop="toggleBulkCategorySelection(category)"
                    >
                      <svg v-if="isBulkCategoryAllSelected(category)" width="10.5" height="10.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                      <span v-else-if="isBulkCategoryPartialSelected(category)" class="qlhh-bulk-chk-dash"></span>
                    </button>
                  </th>
                  <th class="col-code">Mã / SKU</th>
                  <th class="col-name">Tên hàng hóa</th>
                  <th class="col-spec">Volume &amp; Thời hạn</th>
                  <th class="col-cur text-center">Tiền tệ</th>
                  <th class="col-cost text-right">Giá vốn / Off</th>
                  <th class="col-price text-right">{{ activePriceList ? 'Giá bảng giá' : 'Giá bán' }}</th>
                  <th class="col-act text-right">Giỏ &amp; Thao tác</th>
                </tr>
              </thead>
              <tbody>
                <tr
                  v-for="(item, index) in groupItems"
                  :key="item._firebaseKey || item.Ma_hang || index"
                  class="qlhh-table-row"
                  :class="{
                    'in-quote-cart': isInQuoteCart(item),
                    'is-bulk-selected': bulkEditMode && isBulkItemSelected(item)
                  }"
                  @click="bulkEditMode ? toggleBulkItemSelection(item) : openEditModal(item)"
                >
                  <td v-if="bulkEditMode" class="col-bulk-chk" @click.stop>
                    <button
                      type="button"
                      class="qlhh-bulk-check"
                      :class="{ selected: isBulkItemSelected(item) }"
                      :title="isBulkItemSelected(item) ? 'Bỏ chọn sản phẩm này' : 'Chọn sản phẩm này'"
                      @click.stop="toggleBulkItemSelection(item)"
                    >
                      <svg v-if="isBulkItemSelected(item)" width="10.5" height="10.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                    </button>
                  </td>
                  <td class="col-code">
                    <div class="tbl-code-stack">
                      <span
                        v-if="item.sku_code"
                        class="qlhh-code-pill is-sku tabular-nums"
                        v-html="highlightText(item.sku_code, searchQuery)"
                      ></span>
                      <span
                        v-if="item.Ma_hang && item.Ma_hang !== item.sku_code"
                        class="qlhh-code-pill is-ma tabular-nums"
                        v-html="highlightText(item.Ma_hang, searchQuery)"
                      ></span>
                      <span v-if="!item.sku_code && !item.Ma_hang" class="text-muted">—</span>
                    </div>
                  </td>

                  <td class="col-name">
                    <div class="tbl-name-main" :title="item.Ten_hang" v-html="highlightText(item.Ten_hang, searchQuery)"></div>
                    <div class="tbl-name-badges">
                      <span class="qlhh-brand-tag">{{ getItemBrand(item) }}</span>
                      <span
                        v-if="item.Type"
                        class="qlhh-type-tag"
                        :class="String(item.Type).toLowerCase().includes('renewal') ? 'is-amber' : 'is-emerald'"
                      >
                        {{ item.Type }}
                      </span>
                      <span v-if="item.DVT" class="qlhh-dvt-tag">ĐVT: {{ item.DVT }}</span>
                    </div>
                  </td>

                  <td class="col-spec">
                    <div class="tbl-spec-stack">
                      <span v-if="item.volume" class="qlhh-spec-chip is-sky tabular-nums">{{ item.volume }}</span>
                      <span v-if="item.License_duration || item.thoi_han_bao_hanh" class="qlhh-spec-chip tabular-nums">
                        {{ item.License_duration || item.thoi_han_bao_hanh }}
                      </span>
                      <span v-if="!item.volume && !item.License_duration && !item.thoi_han_bao_hanh" class="text-muted">—</span>
                    </div>
                  </td>

                  <td class="col-cur text-center">
                    <span class="qlhh-cur-pill tabular-nums">{{ item.Don_vi_tien_te || 'VND' }}</span>
                    <div
                      v-if="String(item.Don_vi_tien_te || '').trim().toUpperCase() === 'USD' && item.Ti_gia"
                      class="tbl-rate-sub tabular-nums"
                    >
                      {{ formatNumberPlain(item.Ti_gia) }} ₫
                    </div>
                  </td>

                  <td class="col-cost text-right tabular-nums">
                    <span class="qlhh-cost-val">{{ formatCurrency(item.Gia_tieu_chuan || 0, item.Don_vi_tien_te) }}</span>
                  </td>

                  <td class="col-price text-right tabular-nums">
                    <template v-if="getPriceListEntry(item)">
                      <div class="qlhh-price-strike">
                        {{ formatCurrency(activePriceList?.auto_sync_base_price ? item.Don_gia : getPriceListEntry(item).gia_goc, item.Don_vi_tien_te) }}
                      </div>
                      <div class="qlhh-price-main-line is-right">
                        <span
                          class="pl-card-diff-badge"
                          :class="getPriceListDiffClass(getPriceListEntry(item), activePriceList?.auto_sync_base_price ? item.Don_gia : getPriceListEntry(item).gia_goc)"
                        >
                          {{ formatPriceListRuleShort(getPriceListEntry(item), activePriceList?.auto_sync_base_price ? item.Don_gia : getPriceListEntry(item).gia_goc) }}
                        </span>
                        <strong class="qlhh-sell-val">{{ formatCurrency(getPriceListEntry(item).gia_ban_moi, item.Don_vi_tien_te) }}</strong>
                      </div>
                    </template>
                    <template v-else>
                      <div class="qlhh-price-main-line is-right">
                        <span
                          v-if="toNum(item.Gia_tieu_chuan) > 0 && toNum(item.Don_gia) > 0 && toNum(item.Don_gia) !== toNum(item.Gia_tieu_chuan)"
                          class="pl-card-diff-badge"
                          :class="toNum(item.Don_gia) > toNum(item.Gia_tieu_chuan) ? 'up' : 'down'"
                        >
                          {{ formatCardMarkupBadge(item) }}
                        </span>
                        <strong class="qlhh-sell-val">{{ formatCurrency(item.Don_gia, item.Don_vi_tien_te) }}</strong>
                      </div>
                    </template>
                  </td>

                  <td class="col-act text-right" @click.stop>
                    <div class="tbl-act-cluster">
                      <button
                        v-if="!isInQuoteCart(item)"
                        type="button"
                        class="qlhh-add-cart-btn is-compact"
                        @click.stop="addToQuoteCart(item)"
                      >
                        + Giỏ
                      </button>
                      <div v-else class="qlhh-capsule-stepper" @click.stop>
                        <button type="button" class="step-cir minus" @click.stop="updateQuoteCartQty(item, -1, false)">−</button>
                        <input
                          type="number"
                          min="1"
                          inputmode="numeric"
                          class="step-num tabular-nums"
                          :value="getCartItemQty(item)"
                          @click.stop
                          @change="onCardCartQtyInputChange(item, $event)"
                        />
                        <button type="button" class="step-cir plus" @click.stop="updateQuoteCartQty(item, 1, false)">+</button>
                      </div>

                      <div class="qlhh-row-icons">
                        <button
                          v-if="getCardVendorType(item)"
                          type="button"
                          class="qlhh-ico-act is-sky"
                          title="Đối chiếu file gốc hãng"
                          @click.stop="openCardOriginalFileCompare(item)"
                        >
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
                        </button>
                        <button
                          type="button"
                          class="qlhh-ico-act"
                          :class="{ 'has-files': getProductFileHistory(item).length > 0 }"
                          :title="`Lịch sử file đính kèm (${getProductFileHistory(item).length})`"
                          @click.stop="openProductFilesModal(item)"
                        >
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>
                          <span v-if="getProductFileHistory(item).length" class="ico-mini-dot tabular-nums">{{ getProductFileHistory(item).length }}</span>
                        </button>
                        <button type="button" class="qlhh-ico-act is-edit" title="Chỉnh sửa chi tiết" @click.stop="openEditModal(item)">
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                        </button>
                        <button type="button" class="qlhh-ico-act is-del" title="Xóa hàng hóa" @click.stop="requestDelete(item)">
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
                        </button>
                      </div>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <!-- CHẾ ĐỘ LƯỚI THẺ 4 TẦNG TINH GỌN (CARD VIEW) -->
          <div v-else class="qlhh-cards-grid is-inside-group">
            <article
              v-for="(item, index) in groupItems"
              :key="item._firebaseKey || item.Ma_hang || index"
              class="qlhh-card"
              :class="{
                'in-quote-cart': isInQuoteCart(item),
                'is-bulk-selected': bulkEditMode && isBulkItemSelected(item)
              }"
              @click="bulkEditMode ? toggleBulkItemSelection(item) : openEditModal(item)"
            >
              <!-- Tầng 1: Checkbox (khi sửa hàng loạt) + Hãng + Giỏ đã chọn -->
              <div class="qlhh-card-top">
                <div class="qlhh-card-badges">
                  <button
                    v-if="bulkEditMode"
                    type="button"
                    class="qlhh-bulk-check"
                    :class="{ selected: isBulkItemSelected(item) }"
                    :title="isBulkItemSelected(item) ? 'Bỏ chọn sản phẩm này' : 'Chọn sản phẩm này'"
                    @click.stop="toggleBulkItemSelection(item)"
                  >
                    <svg v-if="isBulkItemSelected(item)" width="10.5" height="10.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                  </button>
                  <span class="qlhh-brand-tag">{{ item.Ten_nha_cung_cap || getItemBrand(item) }}</span>
                  <span v-if="isInQuoteCart(item)" class="qlhh-selected-tag tabular-nums">
                    ✓ x{{ getCartItemQty(item) }}
                  </span>
                </div>
              </div>

              <!-- Tầng 2: Tên hàng hóa + Dòng SKU & Thời hạn dạng chữ thường -->
              <div class="qlhh-card-identity">
                <h4 class="qlhh-card-title" :title="item.Ten_hang" v-html="highlightText(item.Ten_hang, searchQuery)"></h4>
                <div v-if="item.sku_code" class="qlhh-card-sku-line tabular-nums" :title="'SKU: ' + item.sku_code">
                  <span class="qlhh-card-sku-lbl">SKU:</span>
                  <span class="qlhh-card-sku-val" v-html="highlightText(item.sku_code, searchQuery)"></span>
                </div>
                <div
                  v-if="item.License_duration || item.thoi_han_bao_hanh"
                  class="qlhh-card-sku-line tabular-nums"
                  :title="'Thời hạn: ' + (item.License_duration || item.thoi_han_bao_hanh)"
                >
                  <span class="qlhh-card-sku-lbl">Thời hạn:</span>
                  <span class="qlhh-card-sku-val">{{ item.License_duration || item.thoi_han_bao_hanh }}</span>
                </div>
              </div>

              <!-- Tầng 3: Chip Volume (nếu có) -->
              <div v-if="item.volume" class="qlhh-spec-row">
                <span class="qlhh-spec-chip is-sky tabular-nums">
                  {{ item.volume }}
                </span>
              </div>

              <!-- Tầng 4: Giá List + Nút + Giỏ & Hàng 4 nút thao tác riêng ở đáy Card -->
              <div class="qlhh-card-footer">
                <div class="qlhh-card-price-row">
                  <div class="qlhh-price-stack tabular-nums">
                    <template v-if="getPriceListEntry(item)">
                      <div class="qlhh-price-lbl-row">
                        <div class="qlhh-price-strike">
                          Giá List: {{ formatCardDisplayPrice(activePriceList?.auto_sync_base_price ? item.Don_gia : getPriceListEntry(item).gia_goc, item) }}
                        </div>
                        <button
                          v-if="isCardUsdItem(item)"
                          type="button"
                          class="qlhh-cur-switch"
                          :class="{ 'is-vnd': isCardShowingVnd(item) }"
                          :title="`Chuyển đổi USD ↔ VND (tỉ giá ${formatNumberPlain(getCardUsdRate(item))} ₫)`"
                          @click.stop="toggleCardUsdToVnd(item)"
                        >
                          <span class="cur-sw-opt" :class="{ active: !isCardShowingVnd(item) }">USD</span>
                          <span class="cur-sw-opt" :class="{ active: isCardShowingVnd(item) }">VND</span>
                        </button>
                        <span v-if="isCardUsdItem(item)" class="qlhh-usd-rate-txt tabular-nums">
                          Tỉ giá: {{ formatNumberPlain(getCardUsdRate(item)) }}₫
                        </span>
                      </div>
                      <div class="qlhh-price-main-line">
                        <strong class="qlhh-sell-val">{{ formatCardDisplayPrice(getPriceListEntry(item).gia_ban_moi, item) }}</strong>
                        <small v-if="item.DVT" class="qlhh-sell-dvt">/ {{ item.DVT }}</small>
                        <span
                          class="pl-card-diff-badge"
                          :class="getPriceListDiffClass(getPriceListEntry(item), activePriceList?.auto_sync_base_price ? item.Don_gia : getPriceListEntry(item).gia_goc)"
                        >
                          {{ formatPriceListRuleShort(getPriceListEntry(item), activePriceList?.auto_sync_base_price ? item.Don_gia : getPriceListEntry(item).gia_goc) }}
                        </span>
                      </div>
                    </template>
                    <template v-else>
                      <div class="qlhh-price-lbl-row">
                        <span class="qlhh-price-list-lbl">Giá List</span>
                        <button
                          v-if="isCardUsdItem(item)"
                          type="button"
                          class="qlhh-cur-switch"
                          :class="{ 'is-vnd': isCardShowingVnd(item) }"
                          :title="`Chuyển đổi USD ↔ VND (tỉ giá ${formatNumberPlain(getCardUsdRate(item))} ₫)`"
                          @click.stop="toggleCardUsdToVnd(item)"
                        >
                          <span class="cur-sw-opt" :class="{ active: !isCardShowingVnd(item) }">USD</span>
                          <span class="cur-sw-opt" :class="{ active: isCardShowingVnd(item) }">VND</span>
                        </button>
                        <span v-if="isCardUsdItem(item)" class="qlhh-usd-rate-txt tabular-nums">
                          Tỉ giá: {{ formatNumberPlain(getCardUsdRate(item)) }}₫
                        </span>
                      </div>
                      <div class="qlhh-price-main-line">
                        <strong class="qlhh-sell-val">{{ formatCardDisplayPrice(item.Don_gia, item) }}</strong>
                        <small v-if="item.DVT" class="qlhh-sell-dvt">/ {{ item.DVT }}</small>
                      </div>
                    </template>
                  </div>

                  <div class="qlhh-cart-ctrl" @click.stop>
                    <button
                      v-if="!isInQuoteCart(item)"
                      type="button"
                      class="qlhh-add-cart-btn is-icon-only"
                      title="Thêm vào giỏ báo giá"
                      aria-label="Thêm vào giỏ báo giá"
                      @click.stop="addToQuoteCart(item)"
                    >
                      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                    </button>

                    <div v-else class="qlhh-capsule-stepper" @click.stop>
                      <button
                        type="button"
                        class="step-cir minus"
                        title="Giảm số lượng (về 0 sẽ bỏ khỏi giỏ)"
                        @click.stop="updateQuoteCartQty(item, -1, false)"
                      >−</button>
                      <input
                        type="number"
                        min="1"
                        inputmode="numeric"
                        class="step-num tabular-nums"
                        :value="getCartItemQty(item)"
                        @click.stop
                        @change="onCardCartQtyInputChange(item, $event)"
                      />
                      <button
                        type="button"
                        class="step-cir plus"
                        title="Tăng số lượng"
                        @click.stop="updateQuoteCartQty(item, 1, false)"
                      >+</button>
                    </div>
                  </div>
                </div>

                <!-- Hàng 4 nút thao tác riêng ở đáy card (2 nút mỗi hàng) -->
                <div
                  class="qlhh-card-bottom-bar"
                  :class="{ 'is-3btn': !getCardVendorType(item) }"
                  @click.stop
                >
                  <button
                    v-if="getCardVendorType(item)"
                    type="button"
                    class="qlhh-ico-act is-sky"
                    title="Đối chiếu file gốc hãng"
                    @click.stop="openCardOriginalFileCompare(item)"
                  >
                    <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
                    <span>Đối chiếu</span>
                  </button>
                  <button
                    type="button"
                    class="qlhh-ico-act is-doc-btn"
                    :class="{ 'has-files': getProductFileHistory(item).length > 0 }"
                    :title="`Tài liệu & lịch sử file đính kèm (${getProductFileHistory(item).length})`"
                    @click.stop="openProductFilesModal(item)"
                  >
                    <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>
                    <span class="tabular-nums">Tài liệu<template v-if="getProductFileHistory(item).length"> ({{ getProductFileHistory(item).length }})</template></span>
                  </button>
                  <button type="button" class="qlhh-ico-act is-edit" title="Chỉnh sửa chi tiết" @click.stop="openEditModal(item)">
                    <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                    <span>Sửa</span>
                  </button>
                  <button type="button" class="qlhh-ico-act is-del" title="Xóa hàng hóa" @click.stop="requestDelete(item)">
                    <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
                    <span>Xóa</span>
                  </button>
                </div>
              </div>
            </article>
          </div>
        </template>
      </section>

      <!-- LAZY LOADING SENTINEL & NÚT TẢI THÊM -->
      <div
        v-if="!loading && uncollapsedProductsCount > 0"
        ref="lazyLoadSentinelRef"
        class="qlhh-lazy-footer"
      >
        <div class="qlhh-lazy-status tabular-nums">
          Đang hiển thị <strong>{{ displayedProductsCount }}</strong> / <strong>{{ uncollapsedProductsCount }}</strong> sản phẩm đang mở
          <template v-if="uncollapsedProductsCount < totalProductsCount">
            (Tổng lọc: {{ totalProductsCount }} SP)
          </template>
        </div>
        <button
          v-if="hasMoreProducts"
          type="button"
          class="qlhh-load-more-btn tabular-nums"
          @click="loadMoreProducts"
        >
          Tải thêm +{{ Math.min(PRODUCT_PAGE_SIZE, uncollapsedProductsCount - displayedProductsCount) }} sản phẩm (còn {{ uncollapsedProductsCount - displayedProductsCount }} SP)
        </button>
      </div>
    </div>

    <!-- =========================================================
         MODAL FULLSCREEN 100%: THÊM MỚI / CẬP NHẬT HÀNG HÓA (BENTO CHUẨN TEMPLATE)
    ========================================================== -->
    <div
      v-if="showModal"
      class="qlhh-modal-backdrop qlhh-fm-overlay"
      :class="{ 'theme-light-blue': uiTheme === 'light' }"
      @click.self="closeModal"
    >
      <div class="qlhh-fm-modal" :class="{ 'theme-light-blue': uiTheme === 'light' }">
        <!-- HEADER STICKY -->
        <header class="qlhh-fm-head">
          <div class="qlhh-fm-head-left">
            <span class="qlhh-fm-head-ico" :class="isEditing ? 'is-sky' : 'is-emerald'">
              <svg v-if="isEditing" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
              <svg v-else width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            </span>

            <div class="qlhh-fm-title-block">
              <div class="qlhh-fm-title-row">
                <h2>{{ isEditing ? 'Cập Nhật Hàng Hóa' : 'Thêm Hàng Hóa Mới' }}</h2>
                <span
                  v-if="formData.sku_code || formData.Ma_hang"
                  class="qlhh-code-pill is-sku tabular-nums"
                >
                  {{ formData.sku_code || formData.Ma_hang }}
                </span>
              </div>

              <div v-if="isEditing && (formData.last_updated || (activePriceList && formData._has_pl_entry))" class="qlhh-fm-meta-row">
                <span v-if="formData.last_updated" class="qlhh-fm-meta-pill tabular-nums">
                  <svg width="12.5" height="12.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                  <span>Cập nhật: <strong>{{ formatLastUpdated(formData.last_updated) }}</strong></span>
                </span>
                <span v-if="activePriceList && formData._has_pl_entry" class="qlhh-fm-meta-pill is-amber">
                  <svg width="12.5" height="12.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
                  <span>Đang sửa theo bảng giá: <strong>{{ activePriceList.ten_bang_gia }}</strong></span>
                </span>
              </div>
            </div>
          </div>

          <div class="qlhh-fm-head-right">
            <div class="qlhh-fm-live-pills hide-sm-head tabular-nums">
              <span class="fm-live-pill is-violet">
                <small>Giá vốn:</small>
                <strong>{{ formatCurrency(formData.Gia_tieu_chuan || 0, formData.Don_vi_tien_te) }}</strong>
              </span>
              <span class="fm-live-pill is-emerald">
                <small>{{ isEditing && activePriceList && formData._has_pl_entry ? 'Giá bảng giá:' : 'Giá List:' }}</small>
                <strong>{{ formatCurrency(formData.Don_gia || 0, formData.Don_vi_tien_te) }}</strong>
              </span>
            </div>

            <button type="button" class="qlhh-fm-close" @click="closeModal" aria-label="Đóng">✕</button>
          </div>
        </header>

        <!-- BODY 2 CỘT BENTO RỘNG 100% -->
        <div class="qlhh-fm-body">
          <form @submit.prevent="saveItem" class="qlhh-fm-2col">
            <!-- CỘT TRÁI: ĐỊNH DANH & MÔ TẢ KỸ THUẬT -->
            <div class="qlhh-fm-col">
              <!-- BENTO 1: ĐỊNH DANH & PHÂN LOẠI -->
              <section class="qlhh-bento-box">
                <div class="qlhh-bento-head is-sky">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/></svg>
                  <span>Định Danh &amp; Phân Loại Sản Phẩm</span>
                </div>

                <div class="qlhh-fm-grid">
                  <div class="qlhh-field">
                    <label>Mã hàng <span class="required">*</span></label>
                    <input
                      v-model="formData.Ma_hang"
                      type="text"
                      required
                      :disabled="isEditing"
                      class="qlhh-fm-input is-mono tabular-nums"
                      placeholder="Tự ghép kèm SKU Code (hoặc tự nhập)..."
                      @input="onFormMaHangManualInput"
                    />
                  </div>

                  <div class="qlhh-field">
                    <label>SKU Code (Mã SKU hãng)</label>
                    <input
                      v-model="formData.sku_code"
                      type="text"
                      class="qlhh-fm-input is-mono tabular-nums"
                      placeholder="VD: XS230012ZZNCAA, KL4867RA*FQ..."
                    />
                  </div>

                  <div class="qlhh-field col-span-2">
                    <label>Tên hàng hóa <span class="required">*</span></label>
                    <input
                      v-model="formData.Ten_hang"
                      type="text"
                      required
                      class="qlhh-fm-input"
                      placeholder="Nhập tên chính thức của sản phẩm / dịch vụ..."
                    />
                  </div>

                  <div class="qlhh-field col-span-2">
                    <label>Tên hàng hóa khi xuất báo giá</label>
                    <input
                      v-model="formData.Ten_hang_bao_gia"
                      type="text"
                      class="qlhh-fm-input"
                      placeholder="Tên tùy chỉnh hiển thị trên bảng báo giá khách hàng (tùy chọn)..."
                    />
                  </div>

                  <div class="qlhh-field">
                    <label>Nhà cung cấp / Hãng</label>
                    <input
                      v-model="formData.Ten_nha_cung_cap"
                      type="text"
                      list="ncc-options"
                      class="qlhh-fm-input"
                      placeholder="VD: SOPHOS, KASPERSKY, ACRONIS..."
                    />
                    <datalist id="ncc-options">
                      <option value="SOPHOS"></option>
                      <option value="KASPERSKY"></option>
                      <option value="ACRONIS"></option>
                    </datalist>
                  </div>

                  <div class="qlhh-field">
                    <label>Danh mục</label>
                    <input
                      v-model="formData.Danh_muc"
                      type="text"
                      class="qlhh-fm-input"
                      placeholder="VD: ENDPOINT PROTECTION, FIREWALL..."
                    />
                  </div>

                  <div class="qlhh-field">
                    <label>Loại hàng (New / Renewal)</label>
                    <input
                      v-model="formData.Type"
                      type="text"
                      list="type-options"
                      class="qlhh-fm-input"
                      placeholder="New / Renewal / Hardware..."
                    />
                    <datalist id="type-options">
                      <option value="New"></option>
                      <option value="Renewal"></option>
                      <option value="Base Plus"></option>
                      <option value="Renewal Plus"></option>
                      <option value="Hardware"></option>
                      <option value="Software"></option>
                    </datalist>
                  </div>

                  <div class="qlhh-field">
                    <label>Đơn vị tính</label>
                    <input
                      v-model="formData.DVT"
                      type="text"
                      class="qlhh-fm-input"
                      placeholder="VD: License, Thiết bị, Gói, Năm..."
                    />
                  </div>

                  <div class="qlhh-fm-grid-3 col-span-2">
                    <div class="qlhh-field">
                      <label>Volume (Users / Blocks)</label>
                      <input
                        v-model="formData.volume"
                        type="text"
                        class="qlhh-fm-input tabular-nums"
                        placeholder="VD: 1-9 users, 10-24 users..."
                      />
                    </div>

                    <div class="qlhh-field">
                      <label>License duration</label>
                      <input
                        v-model="formData.License_duration"
                        type="text"
                        class="qlhh-fm-input tabular-nums"
                        placeholder="VD: 12 months, 36 months..."
                      />
                    </div>

                    <div class="qlhh-field">
                      <label>Thời hạn bảo hành</label>
                      <input
                        v-model="formData.thoi_han_bao_hanh"
                        type="text"
                        class="qlhh-fm-input tabular-nums"
                        placeholder="VD: 12 tháng..."
                      />
                    </div>
                  </div>
                </div>
              </section>

              <!-- BENTO 2: MÔ TẢ & DIỄN GIẢI BÁO GIÁ -->
              <section class="qlhh-bento-box">
                <div class="qlhh-bento-head is-slate">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
                  <span>Mô Tả Kỹ Thuật &amp; Diễn Giải Báo Giá</span>
                </div>

                <div class="qlhh-fm-stack">
                  <div class="qlhh-field">
                    <label>Description nội bộ</label>
                    <ExcelEditor
                      v-model="formData.Description"
                      placeholder="VD: Workspace Protection - 1-9 users - 12 MOS..."
                      class="features-excel-editor"
                    />
                  </div>

                  <div class="qlhh-field">
                    <label>Diễn giải kỹ thuật nội bộ</label>
                    <ExcelEditor
                      v-model="formData.Features"
                      placeholder="Nhập thông số kỹ thuật / tính năng chi tiết..."
                      class="features-excel-editor"
                    />
                  </div>

                  <div class="qlhh-field">
                    <label>Diễn giải hiển thị trên báo giá</label>
                    <ExcelEditor
                      v-model="formData.Dien_giai_bao_gia"
                      placeholder="Nhập diễn giải tùy chỉnh khi xuất báo giá cho khách (tùy chọn)..."
                      class="features-excel-editor"
                    />
                  </div>

                  <div class="qlhh-field">
                    <label>Ghi chú nội bộ</label>
                    <textarea
                      v-model="formData.Ghi_chu"
                      rows="2"
                      class="qlhh-fm-textarea"
                      placeholder="Ghi chú lưu ý riêng cho sale / mua hàng..."
                    ></textarea>
                  </div>
                </div>
              </section>
            </div>

            <!-- CỘT PHẢI: CẤU TRÚC GIÁ & HỒ SƠ FILE LỊCH SỬ GIÁ -->
            <div class="qlhh-fm-col">
              <!-- BENTO 3: CẤU TRÚC GIÁ & QUY ĐỔI TIỀN TỆ -->
              <section class="qlhh-bento-box">
                <div class="qlhh-bento-head is-emerald">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
                  <span>Cấu Trúc Giá &amp; Quy Đổi Tiền Tệ</span>
                </div>

                <div class="qlhh-fm-grid">
                  <div class="qlhh-field" :class="{ 'col-span-2': formData.Don_vi_tien_te === 'VND' }">
                    <label>Đơn vị tiền tệ</label>
                    <select v-model="formData.Don_vi_tien_te" class="qlhh-fm-select">
                      <option value="VND">VND — Việt Nam Đồng</option>
                      <option value="USD">USD — Đô la Mỹ</option>
                    </select>
                  </div>

                  <div v-if="formData.Don_vi_tien_te !== 'VND'" class="qlhh-field">
                    <label>Tỉ giá quy đổi (VND)</label>
                    <NumberInput v-model="formData.Ti_gia" :decimals="0" class="qlhh-fm-input tabular-nums" />
                  </div>

                  <div class="qlhh-field">
                    <label>Thuế VAT (%)</label>
                    <NumberInput v-model="formData.Thue_VAT" :decimals="2" class="qlhh-fm-input tabular-nums" />
                  </div>

                  <div class="qlhh-field">
                    <label>Giá nhập tham chiếu</label>
                    <NumberInput
                      v-model="formData.gia_nhap"
                      :decimals="String(formData.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0"
                      class="qlhh-fm-input tabular-nums"
                    />
                  </div>
                </div>

                <!-- KHỐI 1: GIÁ VỐN / OFF HÃNG -->
                <div class="qlhh-price-calc-card is-violet">
                  <div class="pcc-top-row">
                    <label class="pcc-label is-violet">Giá vốn / Off hãng</label>
                    <span class="pcc-caption">Đơn giá mua sau thuế từ NCC / Hãng</span>
                  </div>

                  <NumberInput
                    v-model="formData.Gia_tieu_chuan"
                    :decimals="String(formData.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0"
                    class="qlhh-fm-input is-hero-num is-cost-hero tabular-nums"
                    @update:modelValue="onModalGiaVonChange"
                  />
                </div>

                <!-- KHỐI CẦU NỐI TÁCH BIỆT: TÍNH TOÁN 2 CHIỀU GIÁ VỐN ↔ GIÁ LIST -->
                <div class="qlhh-price-calc-card is-sky is-formula-bridge">
                  <div class="pcc-top-row">
                    <label class="pcc-label is-sky">Tính toán Giá vốn ↔ Giá List</label>
                    <span class="pcc-caption">
                      {{ modalCostMarkup.flow === 'sell_to_cost' ? 'Đang tính ngược từ Giá List → Giá vốn' : 'Đang tính xuôi từ Giá vốn → Giá List' }}
                    </span>
                  </div>

                  <div class="qlhh-formula-bar">
                    <button
                      type="button"
                      class="formula-title qlhh-flow-toggle-btn"
                      :class="{ 'is-reverse': modalCostMarkup.flow === 'sell_to_cost' }"
                      @click.stop="toggleModalCostMarkupFlow"
                      :title="modalCostMarkup.flow === 'sell_to_cost' ? 'Đang tính ngược: giữ Giá List → tính Giá vốn (nhấn để đảo chiều)' : 'Đang tính xuôi: giữ Giá vốn → tính Giá List (nhấn để đảo chiều)'"
                    >
                      <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 16V4M7 4L3 8M7 4L11 8M17 8v12m0 0 4-4m-4 4-4-4"/></svg>
                      <span>{{ modalCostMarkup.flow === 'sell_to_cost' ? 'Giá List → Giá vốn' : 'Giá vốn → Giá List' }}</span>
                    </button>

                    <div class="formula-controls">
                      <select
                        v-model="modalCostMarkup.direction"
                        class="qlhh-mini-select"
                        :class="modalCostMarkup.direction === 'decrease' ? 'is-rose' : 'is-emerald'"
                        @change="applyModalCostMarkup"
                      >
                        <option value="increase">Tăng (+)</option>
                        <option value="decrease">Giảm (-)</option>
                      </select>

                      <select
                        v-model="modalCostMarkup.type"
                        class="qlhh-mini-select"
                        @change="applyModalCostMarkup"
                      >
                        <option value="percent">Theo %</option>
                        <option value="amount">Số tiền</option>
                      </select>

                      <div v-if="modalCostMarkup.type === 'percent'" class="qlhh-unit-input-wrap">
                        <NumberInput
                          v-model="modalCostMarkup.value"
                          :decimals="2"
                          class="qlhh-mini-num tabular-nums"
                          @update:modelValue="applyModalCostMarkup"
                        />
                        <span class="unit-suffix">%</span>
                      </div>
                      <div v-else class="qlhh-unit-input-wrap is-amount">
                        <NumberInput
                          v-model="modalCostMarkup.value"
                          :decimals="String(formData.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0"
                          class="qlhh-mini-num is-wide tabular-nums"
                          @update:modelValue="applyModalCostMarkup"
                        />
                      </div>
                    </div>
                  </div>
                </div>

                <!-- KHỐI 2: GIÁ LIST / ĐƠN GIÁ BẢNG GIÁ -->
                <div class="qlhh-price-calc-card is-emerald">
                  <div class="pcc-top-row">
                    <div class="pcc-label-cluster">
                      <label class="pcc-label is-emerald">
                        {{ isEditing && activePriceList && formData._has_pl_entry ? `Đơn giá (${activePriceList.ten_bang_gia})` : 'Giá List' }}
                      </label>
                      <span
                        v-if="isEditing && activePriceList && formData._has_pl_entry"
                        class="pl-card-diff-badge tabular-nums"
                        :class="toNum(formData.Don_gia) > toNum(formData._gia_goc_he_thong) ? 'up' : (toNum(formData.Don_gia) < toNum(formData._gia_goc_he_thong) ? 'down' : 'neutral')"
                      >
                        {{ formatModalPriceListBadge() }}
                      </span>
                      <span
                        v-else-if="toNum(formData.Gia_tieu_chuan) > 0 && toNum(formData.Don_gia) > 0"
                        class="pl-card-diff-badge tabular-nums"
                        :class="toNum(formData.Don_gia) > toNum(formData.Gia_tieu_chuan) ? 'up' : (toNum(formData.Don_gia) < toNum(formData.Gia_tieu_chuan) ? 'down' : 'neutral')"
                      >
                        {{ formatModalCostDiffBadge() }}
                      </span>
                    </div>

                    <div class="pcc-right-cluster">
                      <span v-if="isEditing && activePriceList && formData._has_pl_entry" class="pcc-caption tabular-nums">
                        Giá gốc HT: <strong>{{ formatCurrency(formData._gia_goc_he_thong, formData.Don_vi_tien_te) }}</strong>
                      </span>
                      <button
                        v-if="isEditing && getCardVendorType(formData)"
                        type="button"
                        class="qlhh-ghost-btn is-xs is-sky-tint"
                        @click="openCardOriginalFileCompare(originalItem || formData)"
                        title="Đối chiếu thông số & giá với file gốc của hãng"
                      >
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
                        <span>Đối chiếu file gốc</span>
                      </button>
                    </div>
                  </div>

                  <NumberInput
                    v-model="formData.Don_gia"
                    :decimals="String(formData.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0"
                    class="qlhh-fm-input is-hero-num is-sell-hero tabular-nums"
                    @update:modelValue="onModalDonGiaChange"
                  />

                  <div v-if="isEditing && activePriceList && formData._has_pl_entry" class="qlhh-formula-bar is-amber">
                    <span class="formula-title">
                      <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg>
                      <span>Chỉnh % theo giá gốc hệ thống</span>
                    </span>

                    <div class="formula-controls">
                      <select
                        v-model="formData._pl_direction"
                        class="qlhh-mini-select"
                        :class="formData._pl_direction === 'decrease' ? 'is-rose' : 'is-emerald'"
                        @change="onModalPriceListPctChange"
                      >
                        <option value="increase">Tăng (+)</option>
                        <option value="decrease">Giảm (-)</option>
                      </select>

                      <div class="qlhh-unit-input-wrap">
                        <NumberInput
                          v-model="formData._pl_pct"
                          :decimals="2"
                          class="qlhh-mini-num tabular-nums"
                          @update:modelValue="onModalPriceListPctChange"
                        />
                        <span class="unit-suffix">%</span>
                      </div>
                    </div>
                  </div>
                </div>
              </section>

              <!-- BENTO 4: TỆP ĐÍNH KÈM & LỊCH SỬ BÁO GIÁ (CHUẨN UNIFIED FILE-ACTION PALETTE) -->
              <section class="qlhh-bento-box is-files-box">
                <div class="qlhh-bento-head is-sky is-between">
                  <div class="bento-head-title">
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>
                    <span>Tệp Đính Kèm &amp; Lịch Sử Giá</span>
                    <span class="bento-count-pill tabular-nums">{{ getProductFileHistory(formData).length }}</span>
                  </div>

                  <label
                    class="qlhh-ghost-btn is-xs is-sky-tint"
                    style="cursor: pointer;"
                    title="Tải lên chứng từ, file báo giá hoặc ảnh chụp kèm bộ giá hiện tại"
                  >
                    <input
                      type="file"
                      multiple
                      style="display: none;"
                      @change="handleAttachFileToFormData($event)"
                    />
                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
                    <span>Đính kèm file / ảnh</span>
                  </label>
                </div>

                <p class="qlhh-files-hint">
                  Mốc thời gian bên dưới lưu độc lập theo lúc tải từng tệp lên, không bị thay đổi khi chỉnh sửa thông tin hàng hóa.
                </p>

                <div v-if="!getProductFileHistory(formData).length" class="qlhh-files-empty">
                  Chưa có tệp đính kèm. Khi bạn Import Excel / Mua hàng / Đối chiếu ảnh hoặc bấm <strong>"Đính kèm file / ảnh"</strong>, tệp kèm lịch sử giá sẽ được lưu tại đây.
                </div>

                <div v-else class="qlhh-file-list">
                  <div
                    v-for="(fEntry, fIdx) in getProductFileHistory(formData)"
                    :key="fEntry.id || fIdx"
                    class="qlhh-file-card"
                  >
                    <div class="qlhh-file-card-top">
                      <div class="qlhh-file-name-wrap">
                        <span class="qlhh-file-rank tabular-nums" :class="{ 'is-latest': fIdx === 0 }">
                          {{ fIdx === 0 ? 'Mới nhất' : `#${getProductFileHistory(formData).length - fIdx}` }}
                        </span>
                        <a
                          v-if="fEntry.file_url"
                          :href="getAttachedFileViewHref(fEntry)"
                          target="_blank"
                          rel="noopener noreferrer"
                          class="qlhh-file-link"
                          :title="fEntry.file_name"
                        >
                          {{ fEntry.file_name }}
                        </a>
                        <strong v-else class="qlhh-file-plain" :title="fEntry.file_name">{{ fEntry.file_name }}</strong>
                      </div>

                      <div class="qlhh-file-acts">
                        <button
                          type="button"
                          class="qlhh-fbtn-primary"
                          title="Áp dụng lại mức Giá vốn, Giá bán và Giá nhập từ tệp này vào biểu mẫu"
                          @click="applyFileHistoryPriceToFormData(fEntry)"
                        >
                          Áp giá
                        </button>
                        <a
                          v-if="fEntry.file_url"
                          :href="getAttachedFileViewHref(fEntry)"
                          target="_blank"
                          rel="noopener noreferrer"
                          class="qlhh-fbtn-neutral"
                        >
                          {{ isExcelAttachedFile(fEntry) ? 'ViewOffice' : 'Xem' }}
                        </a>
                        <a
                          v-if="fEntry.file_url"
                          :href="fEntry.file_url"
                          target="_blank"
                          rel="noopener noreferrer"
                          download
                          class="qlhh-fbtn-neutral"
                        >
                          Tải về
                        </a>
                        <button
                          type="button"
                          class="qlhh-fbtn-delete"
                          title="Xóa tệp này khỏi lịch sử sản phẩm"
                          @click="removeFileEntryFromFormData(fIdx)"
                        >
                          ✕
                        </button>
                      </div>
                    </div>

                    <div class="qlhh-file-card-meta tabular-nums">
                      <span class="file-time-tag">
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                        <span>{{ formatLastUpdated(fEntry.file_uploaded_at) }}</span>
                        <span v-if="fEntry.ghi_chu_file" class="file-note-inline">· {{ fEntry.ghi_chu_file }}</span>
                      </span>

                      <div class="file-prices-inline">
                        <span class="fp-violet">Vốn: <strong>{{ formatCurrency(fEntry.gia_von || 0, fEntry.don_vi_tien_te || formData.Don_vi_tien_te) }}</strong></span>
                        <span class="fp-emerald">Bán: <strong>{{ formatCurrency(fEntry.don_gia || 0, fEntry.don_vi_tien_te || formData.Don_vi_tien_te) }}</strong></span>
                        <span v-if="toNum(fEntry.gia_nhap, 0) > 0" class="fp-amber">Nhập: <strong>{{ formatCurrency(fEntry.gia_nhap, fEntry.don_vi_tien_te || formData.Don_vi_tien_te) }}</strong></span>
                      </div>
                    </div>
                  </div>
                </div>
              </section>
            </div>
          </form>
        </div>

        <!-- STICKY FOOTER -->
        <footer class="qlhh-fm-foot">
          <div class="qlhh-fm-foot-left">
            <button
              v-if="isEditing"
              type="button"
              class="qlhh-fm-btn-delete"
              @click="requestDelete(formData)"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
              <span>Xóa hàng hóa</span>
            </button>
          </div>

          <div class="qlhh-fm-foot-right">
            <button type="button" class="qlhh-ghost-btn" @click="closeModal">Đóng</button>
            <button
              type="button"
              class="qlhh-btn-primary is-save-cta"
              :disabled="!isDirty || saving"
              @click="saveItem"
            >
              <span v-if="saving" class="spinner"></span>
              <svg v-else width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
              <span>{{ saving ? 'Đang lưu...' : (isEditing ? 'Lưu thay đổi' : 'Thêm hàng hóa') }}</span>
            </button>
          </div>
        </footer>
      </div>
    </div>

    <!-- =========================================================
         MODAL LỊCH SỬ TỆP ĐÍNH KÈM & BIẾN ĐỘNG GIÁ (ĐỒNG BỘ KHÔNG EMOJI)
    ========================================================== -->
    <div
      v-if="productFilesModal.show && productFilesModal.item"
      class="qlhh-modal-backdrop qlhh-hub-overlay qlhh-files-overlay"
      :class="{ 'theme-light-blue': uiTheme === 'light' }"
      @click.self="closeProductFilesModal"
    >
      <div class="qlhh-hub-modal" :class="{ 'theme-light-blue': uiTheme === 'light' }" style="max-width: 820px;">
        <div class="qlhh-hub-head">
          <div class="qlhh-hub-head-left">
            <span class="qlhh-hub-head-ico">
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>
            </span>
            <div>
              <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                <h3 class="qlhh-hub-title">Lịch sử Tệp &amp; Biến động Giá</h3>
                <span class="qlhh-code-pill is-sku tabular-nums">{{ productFilesModal.item.Ma_hang }}</span>
              </div>
              <p class="qlhh-hub-sub">{{ productFilesModal.item.Ten_hang }}</p>
            </div>
          </div>
          <button type="button" class="qlhh-hub-close" @click="closeProductFilesModal" aria-label="Đóng">✕</button>
        </div>

        <div class="qlhh-hub-body" style="display: flex; flex-direction: column; gap: 12px;">
          <div class="hub-file-slot-row" style="justify-content: space-between;">
            <div class="file-prices-inline tabular-nums">
              <span class="hub-slot-label">Giá hiện tại:</span>
              <span class="fp-violet">Vốn: <strong>{{ formatCurrency(productFilesModal.item.Gia_tieu_chuan || 0, productFilesModal.item.Don_vi_tien_te) }}</strong></span>
              <span class="fp-emerald">Bán: <strong>{{ formatCurrency(productFilesModal.item.Don_gia || 0, productFilesModal.item.Don_vi_tien_te) }}</strong></span>
              <span v-if="toNum(productFilesModal.item.gia_nhap, 0) > 0" class="fp-amber">Nhập: <strong>{{ formatCurrency(productFilesModal.item.gia_nhap, productFilesModal.item.Don_vi_tien_te) }}</strong></span>
            </div>

            <label class="qlhh-btn-primary is-sm" style="cursor: pointer;">
              <input
                type="file"
                multiple
                style="display: none;"
                @change="handleAttachFileDirectToProduct($event, productFilesModal.item)"
              />
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
              <span>Đính kèm tệp mới</span>
            </label>
          </div>

          <div v-if="!getProductFileHistory(productFilesModal.item).length" class="qlhh-files-empty">
            Sản phẩm này chưa có tệp đính kèm nào trong lịch sử. Bấm <strong>"Đính kèm tệp mới"</strong> hoặc thực hiện Import / Đối chiếu để lưu lịch sử giá.
          </div>

          <div v-else class="qlhh-file-list is-tall">
            <div
              v-for="(fEntry, fIdx) in getProductFileHistory(productFilesModal.item)"
              :key="fEntry.id || fIdx"
              class="qlhh-file-card"
            >
              <div class="qlhh-file-card-top">
                <div class="qlhh-file-name-wrap">
                  <span class="qlhh-file-rank tabular-nums" :class="{ 'is-latest': fIdx === 0 }">
                    {{ fIdx === 0 ? 'Mới nhất' : `#${getProductFileHistory(productFilesModal.item).length - fIdx}` }}
                  </span>
                  <a
                    v-if="fEntry.file_url"
                    :href="getAttachedFileViewHref(fEntry)"
                    target="_blank"
                    rel="noopener noreferrer"
                    class="qlhh-file-link"
                  >
                    {{ fEntry.file_name }}
                  </a>
                  <strong v-else class="qlhh-file-plain">{{ fEntry.file_name }}</strong>
                </div>

                <div class="qlhh-file-acts">
                  <a
                    v-if="fEntry.file_url"
                    :href="getAttachedFileViewHref(fEntry)"
                    target="_blank"
                    rel="noopener noreferrer"
                    class="qlhh-fbtn-neutral"
                  >
                    {{ isExcelAttachedFile(fEntry) ? 'ViewOffice' : 'Xem tệp' }}
                  </a>
                  <a
                    v-if="fEntry.file_url"
                    :href="fEntry.file_url"
                    target="_blank"
                    rel="noopener noreferrer"
                    download
                    class="qlhh-fbtn-neutral"
                  >
                    Tải về
                  </a>
                  <button
                    type="button"
                    class="qlhh-fbtn-delete"
                    title="Xóa bản ghi tệp này khỏi lịch sử sản phẩm"
                    @click="removeFileDirectFromProduct(productFilesModal.item, fIdx)"
                  >
                    ✕
                  </button>
                </div>
              </div>

              <div class="qlhh-file-card-meta tabular-nums">
                <span class="file-time-tag">
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                  <span>{{ formatLastUpdated(fEntry.file_uploaded_at) }}</span>
                  <span v-if="fEntry.ghi_chu_file" class="file-note-inline">· {{ fEntry.ghi_chu_file }}</span>
                </span>

                <div class="file-prices-inline">
                  <span class="fp-violet">Vốn: <strong>{{ formatCurrency(fEntry.gia_von || 0, fEntry.don_vi_tien_te || productFilesModal.item.Don_vi_tien_te) }}</strong></span>
                  <span class="fp-emerald">Bán: <strong>{{ formatCurrency(fEntry.don_gia || 0, fEntry.don_vi_tien_te || productFilesModal.item.Don_vi_tien_te) }}</strong></span>
                  <span v-if="toNum(fEntry.gia_nhap, 0) > 0" class="fp-amber">Nhập: <strong>{{ formatCurrency(fEntry.gia_nhap, fEntry.don_vi_tien_te || productFilesModal.item.Don_vi_tien_te) }}</strong></span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <footer class="qlhh-fm-foot" style="justify-content: flex-end;">
          <button type="button" class="qlhh-ghost-btn" @click="closeProductFilesModal">Đóng</button>
        </footer>
      </div>
    </div>

    <!-- IMPORT PREVIEW MODAL -->
    <div v-if="showImportModal" class="import-overlay import-overlay--fullscreen" @click.self="showImportModal = false">
      <div class="import-modal import-modal--fullscreen">
        <!-- Header -->
        <div class="import-modal__header">
          <div class="import-modal__header-left">
            <div class="import-modal__icon">
              <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg>
            </div>
            <div>
              <h2 class="import-modal__title">Import dữ liệu hàng hóa</h2>
              <p class="import-modal__subtitle">Kiểm tra và chỉnh sửa trước khi lưu vào hệ thống</p>
            </div>
          </div>
          <button class="import-modal__close" @click="showImportModal = false">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        <!-- Stats Cards -->
        <div class="import-stats">
          <div class="import-stat-card">
            <div class="import-stat-card__value">{{ importData.length }}</div>
            <div class="import-stat-card__label">Tổng sản phẩm</div>
          </div>
          <div class="import-stat-card import-stat-card--blue">
            <div class="import-stat-card__value">{{ importSheetNames.length }}</div>
            <div class="import-stat-card__label">Sheet / Nhóm</div>
          </div>
          <div class="import-stat-card import-stat-card--amber">
            <div class="import-stat-card__value">{{ filteredImportData.length }}</div>
            <div class="import-stat-card__label">Đang lọc</div>
          </div>
          <div class="import-stat-card import-stat-card--green">
            <div class="import-stat-card__value">{{ importData[0]?.Ten_nha_cung_cap || '—' }}</div>
            <div class="import-stat-card__label">Nhà cung cấp</div>
          </div>
        </div>

        <!-- Thanh công cụ Điều chỉnh Giá bán từ Giá vốn & Phân tích lại bằng AI -->
        <div
          style="display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 10px 18px; background: rgba(168, 85, 247, 0.08); border-bottom: 1px solid rgba(192, 132, 252, 0.25);"
        >
          <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
            <span style="font-size: 12.5px; color: #e9d5ff; font-weight: 700;">
              ⚡ Tính Giá bán (Đơn giá) từ Giá vốn / Giá off hãng:
            </span>
            <select
              v-model="importBulkCostMarkup.direction"
              class="pl-row-select"
              :class="importBulkCostMarkup.direction === 'decrease' ? 'down' : 'up'"
              style="height: 32px; font-size: 12px;"
            >
              <option value="increase">+ Tăng (Lãi)</option>
              <option value="decrease">- Giảm (Off)</option>
            </select>
            <select
              v-model="importBulkCostMarkup.type"
              class="pl-row-select"
              style="height: 32px; font-size: 12px;"
            >
              <option value="percent">% (Phần trăm)</option>
              <option value="amount">Số tiền cụ thể</option>
            </select>
            <div v-if="importBulkCostMarkup.type === 'percent'" style="position: relative; display: inline-flex; align-items: center;">
              <NumberInput
                v-model="importBulkCostMarkup.value"
                :decimals="2"
                style="width: 86px; height: 32px; padding: 4px 24px 4px 8px; border-radius: 6px; border: 1px solid rgba(192, 132, 252, 0.45); background: #0f172a; color: #34d399; font-weight: 700; font-size: 13px; text-align: right;"
              />
              <span style="position: absolute; right: 7px; font-size: 12px; color: #94a3b8; font-weight: 700; pointer-events: none;">%</span>
            </div>
            <div v-else style="width: 145px;">
              <NumberInput v-model="importBulkCostMarkup.value" :decimals="0" />
            </div>
            <button
              type="button"
              class="pl-mini-btn"
              style="background: rgba(16, 185, 129, 0.2); border-color: #10b981; color: #6ee7b7; font-weight: 700;"
              @click="applyImportBulkMarkupToAll"
            >
              ✓ Áp dụng cho tất cả ({{ importData.length }} SP)
            </button>
          </div>

          <div v-if="lastPurchaseUploadFile" style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
            <span style="font-size: 12px; color: #cbd5e1;">Đọc chưa chuẩn hoặc sai định dạng?</span>
            <button
              type="button"
              class="pl-mini-btn"
              style="background: linear-gradient(135deg, rgba(168, 85, 247, 0.28), rgba(59, 130, 246, 0.28)); border-color: #c084fc; color: #f3e8ff; font-weight: 700;"
              @click="runAiPurchaseFileAnalysis(lastPurchaseUploadFile)"
            >
              ✨ Dùng AI phân tích lại file này
            </button>
          </div>
        </div>

        <!-- Thanh tự động cập nhật File Gốc / Trung Gian lên Cloudinary khi Import -->
        <div
          v-if="pendingImportVendorRef"
          style="display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 10px 18px; background: rgba(56, 189, 248, 0.1); border-bottom: 1px solid rgba(56, 189, 248, 0.3);"
        >
          <label style="display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-size: 13px; color: #bae6fd; font-weight: 700;">
            <input
              type="checkbox"
              v-model="syncImportFileToCloudinaryRef"
              style="width: 16px; height: 16px; accent-color: #38bdf8; cursor: pointer;"
            />
            <span>
              ☁️ Đồng thời đẩy file <code>{{ pendingImportVendorRef.file?.name }}</code> lên <strong>Cloudinary</strong> làm File Gốc / Trung Gian chuẩn mới cho <strong>{{ pendingImportVendorRef.vendor?.toUpperCase() }}</strong> (Không còn bị dính giá file cũ khi đối chiếu)
            </span>
          </label>
        </div>

        <!-- Thanh cấu hình chuẩn hóa SOPHOS (hiển thị khi đang import dữ liệu SOPHOS) -->
        <div
          v-if="importData[0]?.Ten_nha_cung_cap === 'SOPHOS'"
          class="imp-sophos-bar"
        >
          <div class="imp-sophos-bar__top">
            <label class="imp-sophos-clear-check">
              <input
                type="checkbox"
                v-model="clearOldSophosBeforeImport"
              />
              <span>🗑️ Xóa toàn bộ hàng SOPHOS cũ trong Database trước khi lưu bộ mã mới (Chuẩn hóa <code>Ma_hang = SKU</code>)</span>
            </label>
          </div>

          <div class="imp-sophos-src-row">
            <span class="imp-sophos-src-label">Nguồn nạp theo file đối chiếu:</span>

            <!-- Nguồn 1: File Trung Gian -->
            <div class="imp-src-pill" :class="{ 'is-active is-emerald': sophosReimportMode === 'bom' }">
              <button
                type="button"
                class="imp-src-pill__main"
                @click="openSophosStandardizedReimportModal('bom')"
                :title="`Nạp ${sophosReimportSourceInfo.bomCount.toLocaleString()} mã SKU từ ${sophosReimportSourceInfo.tgFileName} (ghép thông tin từ ${sophosReimportSourceInfo.gocFileName})`"
              >
                <span class="imp-src-pill__name">{{ sophosReimportSourceInfo.tgFileName }}</span>
                <span class="imp-src-pill__badge tabular-nums">{{ sophosReimportSourceInfo.bomCount.toLocaleString() }} mã</span>
              </button>
              <a
                v-if="sophosReimportSourceInfo.tgMeta"
                :href="getVendorOfficeViewUrl(sophosReimportSourceInfo.tgMeta)"
                target="_blank"
                rel="noopener noreferrer"
                class="imp-src-pill__eye"
                :title="`Xem trước file Excel: ${sophosReimportSourceInfo.tgFileName}`"
                @click.stop="handleOpenVendorOfficeView($event, 'sophos', 'tg', sophosReimportSourceInfo.tgMeta)"
              >
                <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                <span>Xem file</span>
              </a>
            </div>

            <!-- Nguồn 2: File Trung Gian + File Gốc (CORP) -->
            <div class="imp-src-pill" :class="{ 'is-active is-amber': sophosReimportMode === 'bom_plus_skulist' }">
              <button
                type="button"
                class="imp-src-pill__main"
                @click="openSophosStandardizedReimportModal('bom_plus_skulist')"
                :title="`Nạp ${sophosReimportSourceInfo.tgFileName} + các mã CORP (New & Renewal) trong ${sophosReimportSourceInfo.gocFileName}`"
              >
                <span class="imp-src-pill__name">{{ sophosReimportSourceInfo.gocFileName }}</span>
                <span class="imp-src-pill__scope">CORP + Trung gian</span>
                <span class="imp-src-pill__badge tabular-nums">{{ sophosReimportSourceInfo.bomPlusCorpCount.toLocaleString() }} mã</span>
              </button>
              <a
                v-if="sophosReimportSourceInfo.gocMeta"
                :href="getVendorOfficeViewUrl(sophosReimportSourceInfo.gocMeta)"
                target="_blank"
                rel="noopener noreferrer"
                class="imp-src-pill__eye"
                :title="`Xem trước file Excel: ${sophosReimportSourceInfo.gocFileName}`"
                @click.stop="handleOpenVendorOfficeView($event, 'sophos', 'goc', sophosReimportSourceInfo.gocMeta)"
              >
                <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                <span>Xem file</span>
              </a>
            </div>

            <!-- Nguồn 3: Toàn bộ File Gốc / SKU_List -->
            <div class="imp-src-pill" :class="{ 'is-active is-sky': sophosReimportMode === 'all_skulist' }">
              <button
                type="button"
                class="imp-src-pill__main"
                @click="openSophosStandardizedReimportModal('all_skulist')"
                :title="`Nạp toàn bộ ${sophosReimportSourceInfo.allSkuCount.toLocaleString()} mã SKU trong ${sophosReimportSourceInfo.gocFileName}`"
              >
                <span class="imp-src-pill__name">{{ sophosReimportSourceInfo.gocFileName }}</span>
                <span class="imp-src-pill__scope">Tất cả</span>
                <span class="imp-src-pill__badge tabular-nums">{{ sophosReimportSourceInfo.allSkuCount.toLocaleString() }} mã</span>
              </button>
              <a
                v-if="sophosReimportSourceInfo.gocMeta"
                :href="getVendorOfficeViewUrl(sophosReimportSourceInfo.gocMeta)"
                target="_blank"
                rel="noopener noreferrer"
                class="imp-src-pill__eye"
                :title="`Xem trước file Excel: ${sophosReimportSourceInfo.gocFileName}`"
                @click.stop="handleOpenVendorOfficeView($event, 'sophos', 'goc', sophosReimportSourceInfo.gocMeta)"
              >
                <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                <span>Xem file</span>
              </a>
            </div>
          </div>
        </div>

        <!-- Sheet Tabs -->
        <div class="import-tabs">
          <button v-for="sheet in importSheetNames" :key="sheet"
                  @click="activeImportSheet = sheet; importDisplayLimit = 100"
                  :class="['import-tab', { 'import-tab--active': activeImportSheet === sheet }]">
            <span class="import-tab__name">{{ sheet }}</span>
            <span class="import-tab__badge">{{ importData.filter(p => p.Sheet_name === sheet).length }}</span>
          </button>
        </div>

        <!-- Table -->
        <div class="import-table-wrap">
          <table class="import-table">
            <thead>
              <tr>
                <th class="import-th--sticky-left import-th--idx">#</th>
                <th style="min-width:155px">Mã hàng</th>
                <th style="min-width:135px; color: #c4b5fd;">SKU Code</th>
                <th style="min-width:250px">Tên hàng</th>
                <th style="min-width:250px; color: #34d399;">Tên hàng báo giá</th>
                <th style="min-width:290px">Description nội bộ</th>
                <th style="min-width:520px">Diễn giải nội bộ</th>
                <th style="min-width:460px; color: #34d399;">Diễn giải báo giá</th>
                <th style="min-width:170px">Danh mục</th>
                <th style="min-width:75px">Type</th>
                <th style="min-width:125px; color: #e9d5ff;">Giá vốn / Giá off hãng</th>
                <th style="min-width:115px">Giá bán (Đơn giá)</th>
                <th style="min-width:100px">Giá nhập</th>
                <th style="min-width:70px">VAT%</th>
                <th style="min-width:70px">Tiền tệ</th>
                <th style="min-width:80px">Tỉ giá</th>
                <th style="min-width:80px">ĐVT</th>
                <th style="min-width:105px">License (months)</th>
                <th style="min-width:140px">Volume (Range Users)</th>
                <th style="min-width:105px">Trạng thái</th>
                <th style="min-width:110px">Bảo hành</th>
                <th style="min-width:100px">NCC</th>
                <th style="min-width:100px">Mã NCC</th>
                <th style="min-width:80px">% Off</th>
                <th style="min-width:140px">Mã hàng LK</th>
                <th style="min-width:140px">Tên hàng LK</th>
                <th style="min-width:120px">Ghi chú</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(row, idx) in displayedImportData" :key="row.Ma_hang + '_' + idx" class="import-row">
                <td class="import-th--sticky-left import-th--idx import-row__idx">{{ idx + 1 }}</td>
                <td><input type="text" v-model="row.Ma_hang" class="imp-input imp-input--code" /></td>
                <td><input type="text" v-model="row.sku_code" class="imp-input imp-input--code" style="color: #c4b5fd;" placeholder="SKU Code..." /></td>
                <td><textarea v-model="row.Ten_hang" class="imp-input imp-input--textarea imp-input--autofit" rows="1"></textarea></td>
                <td><textarea v-model="row.Ten_hang_bao_gia" class="imp-input imp-input--textarea imp-input--autofit" rows="1" placeholder="Tên hàng báo giá..."></textarea></td>
                <td><textarea v-model="row.Description" class="imp-input imp-input--textarea imp-input--autofit" rows="1" placeholder="Description từ file..."></textarea></td>
                <td>
                  <div class="imp-features-cell">
                    <div
                      class="imp-input imp-input--rich"
                      contenteditable="true"
                      v-html="formatFeaturesHtml(row.Features)"
                      @blur="row.Features = $event.currentTarget.innerHTML"
                    ></div>
                    <button
                      type="button"
                      class="imp-features-edit-btn"
                      title="Mở công cụ chỉnh sửa format Diễn giải nội bộ"
                      @click="openImportFeaturesEditor(row, 'Features')"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
                    </button>
                  </div>
                </td>
                <td>
                  <div class="imp-features-cell">
                    <div
                      class="imp-input imp-input--rich"
                      contenteditable="true"
                      v-html="formatFeaturesHtml(row.Dien_giai_bao_gia)"
                      @blur="row.Dien_giai_bao_gia = cleanRichHtmlOrEmpty($event.currentTarget.innerHTML)"
                    ></div>
                    <button
                      type="button"
                      class="imp-features-edit-btn"
                      title="Mở công cụ chỉnh sửa format Diễn giải báo giá"
                      @click="openImportFeaturesEditor(row, 'Dien_giai_bao_gia')"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
                    </button>
                  </div>
                </td>
                <td><textarea v-model="row.Danh_muc" class="imp-input imp-input--textarea imp-input--autofit" rows="1"></textarea></td>
                <td>
                  <input
                    type="text"
                    v-model="row.Type"
                    class="imp-input imp-input--sm"
                    :style="{ color: String(row.Type || '').toLowerCase().includes('renewal') ? '#fbbf24' : '#34d399', fontWeight: 700 }"
                  />
                </td>
                <td><NumberInput v-model="row.Gia_tieu_chuan" :decimals="String(row.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0" class="imp-input imp-input--num" style="color: #e9d5ff; font-weight: 700;" /></td>
                <td><NumberInput v-model="row.Don_gia" :decimals="String(row.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0" class="imp-input imp-input--num imp-input--green" /></td>
                <td><NumberInput v-model="row.gia_nhap" :decimals="String(row.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0" class="imp-input imp-input--num imp-input--green" /></td>
                <td><NumberInput v-model="row.Thue_VAT" :decimals="2" class="imp-input imp-input--num imp-input--green" /></td>
                <td><input type="text" v-model="row.Don_vi_tien_te" class="imp-input imp-input--sm" /></td>
                <td><NumberInput v-model="row.Ti_gia" :decimals="0" class="imp-input imp-input--num imp-input--green" /></td>
                <td><input type="text" v-model="row.DVT" class="imp-input imp-input--sm" /></td>
                <td><input type="text" v-model="row.License_duration" class="imp-input" placeholder="12 months..." /></td>
                <td><input type="text" v-model="row.volume" class="imp-input" placeholder="1-9 users..." style="color: #38bdf8; font-weight: 600;" /></td>
                <td><input type="text" v-model="row.Trang_thai" class="imp-input imp-input--sm" /></td>
                <td><input type="text" v-model="row.thoi_han_bao_hanh" class="imp-input" /></td>
                <td><input type="text" v-model="row.Ten_nha_cung_cap" class="imp-input" /></td>
                <td><input type="text" v-model="row.Ma_nha_cung_cap" class="imp-input" /></td>
                <td><NumberInput v-model="row.muc_phan_tram_off" :decimals="2" class="imp-input imp-input--num" /></td>
                <td><textarea v-model="row.Ma_hang_lien_ket" class="imp-input imp-input--textarea" rows="1"></textarea></td>
                <td><textarea v-model="row.Ten_hang_lien_ket" class="imp-input imp-input--textarea" rows="1"></textarea></td>
                <td><input type="text" v-model="row.Ghi_chu" class="imp-input" /></td>
              </tr>
            </tbody>
          </table>

          <div v-if="filteredImportData.length > importDisplayLimit" style="padding: 12px; text-align: center; background: #0f172a;">
            <button
              type="button"
              class="btn btn-outline"
              @click="importDisplayLimit += 150"
              style="font-size: 12.5px; padding: 6px 18px;"
            >
              Hiển thị thêm 150 dòng (đang hiện {{ displayedImportData.length }} / {{ filteredImportData.length }} SP trong tab này)
            </button>
          </div>
        </div>

        <!-- Footer -->
        <div class="import-modal__footer">
          <button class="btn btn-secondary" @click="showImportModal = false">
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            Hủy bỏ
          </button>
          <button class="btn import-btn-save" @click="confirmImport" :disabled="importing">
            <span v-if="importing" class="spinner"></span>
            <svg v-else xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg>
            {{ importing ? 'Đang lưu...' : `Lưu tất cả ${importData.length} sản phẩm` }}
          </button>
        </div>
      </div>
    </div>

    <!-- MODAL CHỈNH SỬA FORMAT DIỄN GIẢI NỘI BỘ / DIỄN GIẢI BÁO GIÁ TRONG BẢNG IMPORT PREVIEW -->
    <div
      v-if="importFeaturesEditRow"
      class="qlhh-modal-backdrop"
      :class="{ 'theme-light-blue': uiTheme === 'light' }"
      style="z-index: 10400;"
      @click.self="closeImportFeaturesEditor"
    >
      <div class="qlhh-hub-modal" :class="{ 'theme-light-blue': uiTheme === 'light' }" style="max-width: 820px;">
        <div class="qlhh-hub-head">
          <div class="qlhh-hub-head-left">
            <span class="qlhh-hub-head-ico">
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </span>
            <div>
              <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                <h3 class="qlhh-hub-title">
                  {{ importRichEditField === 'Dien_giai_bao_gia' ? 'Chỉnh sửa Diễn giải báo giá' : 'Chỉnh sửa Diễn giải nội bộ' }}
                </h3>
                <span class="qlhh-code-pill is-sku tabular-nums">{{ importFeaturesEditRow.Ma_hang }}</span>
              </div>
              <p class="qlhh-hub-sub">{{ importFeaturesEditRow.Ten_hang }}</p>
            </div>
          </div>
          <button type="button" class="qlhh-hub-close" @click="closeImportFeaturesEditor" aria-label="Đóng">✕</button>
        </div>
        <div class="qlhh-hub-body">
          <ExcelEditor
            v-if="importRichEditField === 'Dien_giai_bao_gia'"
            v-model="importFeaturesEditRow.Dien_giai_bao_gia"
            placeholder="Nhập diễn giải báo giá..."
            class="features-excel-editor"
          />
          <ExcelEditor
            v-else
            v-model="importFeaturesEditRow.Features"
            placeholder="Nhập diễn giải nội bộ..."
            class="features-excel-editor"
          />
        </div>
        <footer class="qlhh-fm-foot" style="justify-content: flex-end;">
          <button type="button" class="qlhh-btn-primary is-save-cta" @click="closeImportFeaturesEditor">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            <span>Hoàn tất</span>
          </button>
        </footer>
      </div>
    </div>

    <!-- CONFIRM DELETE MODAL -->
    <div
      v-if="confirmDeleteModal.show"
      class="qlhh-modal-backdrop"
      :class="{ 'theme-light-blue': uiTheme === 'light' }"
      style="z-index: 100010;"
      @click.self="confirmDeleteModal.show = false"
    >
      <div class="custom-alert-modal" :class="{ 'theme-light-blue': uiTheme === 'light' }">
        <div class="alert-icon question is-rose">
          <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"></path><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"></path><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
        </div>
        <h3 class="alert-title">Xác nhận Xóa Hàng Hóa</h3>
        <p class="alert-desc">
          Bạn có chắc muốn xóa hàng hóa<br>
          <strong class="alert-hl-rose">{{ confirmDeleteModal.item?.Ten_hang }}</strong>?
        </p>
        <div class="alert-actions">
          <button type="button" class="qlhh-ghost-btn" @click="confirmDeleteModal.show = false">Hủy</button>
          <button type="button" class="qlhh-alert-danger-btn" @click="executeDelete">Xóa ngay</button>
        </div>
      </div>
    </div>

    <!-- CONFIRM DELETE PRICE LIST MODAL -->
    <div
      v-if="confirmDeletePriceListModal.show"
      class="qlhh-modal-backdrop"
      :class="{ 'theme-light-blue': uiTheme === 'light' }"
      style="z-index: 100010;"
      @click.self="confirmDeletePriceListModal.show = false"
    >
      <div class="custom-alert-modal" :class="{ 'theme-light-blue': uiTheme === 'light' }">
        <div class="alert-icon question is-rose">
          <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"></path><line x1="7" y1="7" x2="7.01" y2="7"></line></svg>
        </div>
        <h3 class="alert-title">Xóa Bảng Giá</h3>
        <p class="alert-desc">
          Bạn có chắc muốn xóa bảng giá<br>
          <strong class="alert-hl-amber">{{ confirmDeletePriceListModal.priceList?.ten_bang_gia }}</strong>?
        </p>
        <div class="alert-actions">
          <button type="button" class="qlhh-ghost-btn" @click="confirmDeletePriceListModal.show = false">Hủy</button>
          <button type="button" class="qlhh-alert-danger-btn" @click="executeDeletePriceList">Xóa bảng giá</button>
        </div>
      </div>
    </div>

    <!-- MODAL THÔNG BÁO DÙNG AI PHÂN TÍCH KHI IMPORT FILE MUA HÀNG SAI ĐỊNH DẠNG / KHÔNG ĐỌC ĐƯỢC GIÁ VỐN -->
    <div
      v-if="aiPurchaseFallbackModal.show"
      class="qlhh-modal-backdrop"
      :class="{ 'theme-light-blue': uiTheme === 'light' }"
      style="z-index: 100010;"
      @click.self="aiPurchaseFallbackModal.show = false"
    >
      <div class="custom-alert-modal" :class="{ 'theme-light-blue': uiTheme === 'light' }" style="max-width: 520px;">
        <div class="alert-icon question is-violet">
          <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2a4 4 0 0 1 4 4v2a4 4 0 0 1-8 0V6a4 4 0 0 1 4-4z"/><path d="M16 14H8a4 4 0 0 0-4 4v2h16v-2a4 4 0 0 0-4-4z"/></svg>
        </div>
        <h3 class="alert-title">Không đọc được Giá vốn hoặc sai định dạng chuẩn</h3>
        <p class="alert-desc">
          File <strong class="alert-hl-violet">{{ aiPurchaseFallbackModal.fileName }}</strong> có bố cục khác định dạng chuẩn hoặc không nhận diện được cột Giá vốn sau thuế.<br><br>
          Bạn có muốn dùng <strong class="alert-hl-sky">AI (DeepSeek)</strong> để tự động phân tích cấu trúc file và đọc <strong>Giá vốn / Giá off hãng</strong> không?
        </p>
        <div class="alert-actions">
          <button type="button" class="qlhh-ghost-btn" @click="aiPurchaseFallbackModal.show = false">Hủy bỏ</button>
          <button type="button" class="qlhh-btn-primary is-save-cta" @click="confirmAiPurchaseFallback">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>
            <span>Dùng AI phân tích ngay</span>
          </button>
        </div>
      </div>
    </div>

    <!-- MODAL THAY ĐỔI TỈ GIÁ (DÀNH CHO USD) — ĐỒNG BỘ DUAL-THEME KHÔNG EMOJI -->
    <div
      v-if="showUsdRateModal"
      class="qlhh-modal-backdrop qlhh-hub-overlay qlhh-usd-overlay"
      :class="{ 'theme-light-blue': uiTheme === 'light' }"
      @click.self="closeUsdRateModal"
    >
      <div class="qlhh-hub-modal qlhh-usd-modal" :class="{ 'theme-light-blue': uiTheme === 'light' }">
        <div class="qlhh-hub-head">
          <div class="qlhh-hub-head-left">
            <span class="qlhh-fm-head-ico is-emerald">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
            </span>
            <div>
              <h3 class="qlhh-hub-title">Thay Đổi Tỉ Giá Hệ Thống (USD)</h3>
              <p class="qlhh-hub-sub">Cập nhật đồng loạt trường <strong>Tỉ giá (VNĐ)</strong> cho các mặt hàng USD</p>
            </div>
          </div>
          <button type="button" class="qlhh-hub-close" @click="closeUsdRateModal" aria-label="Đóng">✕</button>
        </div>

        <div class="qlhh-hub-body qlhh-usd-body">
          <!-- Thông tin hiện tại -->
          <div class="qlhh-usd-kpi-grid tabular-nums">
            <div class="qlhh-usd-kpi-box">
              <span class="usd-kpi-lbl">Tỉ giá USD hiện tại</span>
              <strong class="usd-kpi-val is-sky">{{ formatCurrency(currentSystemUsdRate, 'VND') }}</strong>
            </div>
            <div class="qlhh-usd-kpi-box">
              <span class="usd-kpi-lbl">Số sản phẩm USD</span>
              <strong class="usd-kpi-val is-emerald">
                {{ usdRateScope === 'filtered' ? filteredUsdItems.length : usdItems.length }}
                <small>sản phẩm</small>
              </strong>
            </div>
          </div>

          <!-- Phạm vi áp dụng -->
          <div class="qlhh-field">
            <label>Phạm vi áp dụng</label>
            <div class="qlhh-usd-scope-list">
              <label class="qlhh-usd-scope-opt" :class="{ active: usdRateScope === 'all' }">
                <input type="radio" v-model="usdRateScope" value="all" />
                <span>
                  Tất cả sản phẩm có đơn vị tiền tệ USD trên hệ thống
                  <strong class="is-emerald tabular-nums">({{ usdItems.length }} SP)</strong>
                </span>
              </label>

              <label
                v-if="filteredUsdItems.length > 0 && filteredUsdItems.length !== usdItems.length"
                class="qlhh-usd-scope-opt is-sky"
                :class="{ active: usdRateScope === 'filtered' }"
              >
                <input type="radio" v-model="usdRateScope" value="filtered" />
                <span>
                  Chỉ các sản phẩm USD trong danh sách đang lọc hiện tại
                  <strong class="is-sky tabular-nums">({{ filteredUsdItems.length }} SP)</strong>
                </span>
              </label>
            </div>
          </div>

          <!-- Nhập tỉ giá mới -->
          <div class="qlhh-field">
            <div class="qlhh-usd-lbl-row">
              <label>Nhập tỉ giá mới (1 USD = ? VNĐ) <span class="required">*</span></label>
              <span
                v-if="Number(newUsdExchangeRate) > 0 && Number(newUsdExchangeRate) !== currentSystemUsdRate"
                class="qlhh-usd-delta-tag tabular-nums"
                :class="Number(newUsdExchangeRate) > currentSystemUsdRate ? 'is-amber' : 'is-sky'"
              >
                {{ Number(newUsdExchangeRate) > currentSystemUsdRate ? '▲ Tăng' : '▼ Giảm' }}
                {{ formatNumberPlain(Math.abs(Number(newUsdExchangeRate) - currentSystemUsdRate)) }} ₫
              </span>
            </div>
            <NumberInput
              v-model="newUsdExchangeRate"
              :decimals="0"
              placeholder="Ví dụ: 26.200"
              class="qlhh-fm-input is-hero-num is-sell-hero tabular-nums"
            />
            <div class="qlhh-usd-presets tabular-nums">
              <span class="usd-preset-caption">Chọn nhanh:</span>
              <button type="button" class="usd-quick-step-btn" @click="newUsdExchangeRate = Math.max(1, (Number(newUsdExchangeRate) || 0) - 500)">-500</button>
              <button type="button" class="usd-quick-step-btn" @click="newUsdExchangeRate = Math.max(1, (Number(newUsdExchangeRate) || 0) - 100)">-100</button>
              <button type="button" class="usd-quick-step-btn" @click="newUsdExchangeRate = (Number(newUsdExchangeRate) || 0) + 100">+100</button>
              <button type="button" class="usd-quick-step-btn" @click="newUsdExchangeRate = (Number(newUsdExchangeRate) || 0) + 500">+500</button>
              <button type="button" class="usd-quick-step-btn preset" @click="newUsdExchangeRate = 25500">25.500</button>
              <button type="button" class="usd-quick-step-btn preset" @click="newUsdExchangeRate = 26000">26.000</button>
              <button type="button" class="usd-quick-step-btn preset" @click="newUsdExchangeRate = 26200">26.200</button>
              <button type="button" class="usd-quick-step-btn preset" @click="newUsdExchangeRate = 26500">26.500</button>
            </div>
          </div>

          <!-- Bảng quy đổi minh họa -->
          <div v-if="Number(newUsdExchangeRate) > 0" class="qlhh-usd-preview tabular-nums">
            <div class="usd-prev-head">Quy đổi tham khảo theo tỉ giá mới</div>
            <div class="usd-prev-row">
              <span>1 USD</span>
              <strong>= {{ formatCurrency(Number(newUsdExchangeRate), 'VND') }}</strong>
            </div>
            <div class="usd-prev-row">
              <span>100 USD</span>
              <strong>= {{ formatCurrency(Number(newUsdExchangeRate) * 100, 'VND') }}</strong>
            </div>
            <div class="usd-prev-row is-total">
              <span>1,000 USD</span>
              <strong>= {{ formatCurrency(Number(newUsdExchangeRate) * 1000, 'VND') }}</strong>
            </div>
          </div>
        </div>

        <footer class="qlhh-fm-foot" style="justify-content: flex-end;">
          <button type="button" class="qlhh-ghost-btn" @click="closeUsdRateModal" :disabled="updatingUsdRate">Hủy</button>
          <button
            type="button"
            class="qlhh-btn-primary is-save-cta"
            :disabled="updatingUsdRate || !(Number(newUsdExchangeRate) > 0)"
            @click="applyUsdExchangeRateUpdate"
          >
            <span v-if="updatingUsdRate" class="spinner"></span>
            <svg v-else width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            <span>Lưu &amp; Cập nhật tỉ giá ({{ usdRateScope === 'filtered' ? filteredUsdItems.length : usdItems.length }} SP)</span>
          </button>
        </footer>
      </div>
    </div>

    <!-- MODAL TẠO / CẬP NHẬT BẢNG GIÁ -->
    <div v-if="showPriceListModal" class="import-overlay" @click.self="showPriceListModal = false" style="z-index: 10060;">
      <div class="import-modal pricelist-modal">
        <!-- Header -->
        <div class="import-modal__header">
          <div class="import-modal__header-left">
            <div class="import-modal__icon is-amber-icon">
              <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"></path><line x1="7" y1="7" x2="7.01" y2="7"></line></svg>
            </div>
            <div>
              <h2 class="import-modal__title">
                {{ isEditingPriceList ? 'Cập nhật Bảng Giá' : 'Tạo Bảng Giá Mới' }}
              </h2>
              <p class="import-modal__subtitle">
                Đã chọn <strong style="color: #34d399;">{{ selectedPriceListCount }}</strong> / {{ priceListRows.length }} sản phẩm trong kho
              </p>
            </div>
          </div>
          <button class="import-modal__close" @click="showPriceListModal = false" title="Đóng">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        <!-- Khung Cấu hình Tên Bảng Giá & Khung Tăng/Giảm Giá Bán Hàng Loạt -->
        <div class="pl-config-section">
          <!-- Khung 1: Tên bảng giá, Thời gian áp dụng & Ghi chú -->
          <div class="pl-config-card">
            <div class="pl-config-card__title">
              <svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#38bdf8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg>
              1. Thông tin & Thời hạn Bảng Giá
            </div>
            <div class="pl-config-grid pl-config-grid--4">
              <div class="pl-field">
                <label>Tên bảng giá <span class="required">*</span></label>
                <input type="text" v-model="priceListForm.ten_bang_gia" placeholder="VD: Bảng giá Đại lý cấp 1..." class="pl-input" />
              </div>
              <div class="pl-field">
                <label>Thời gian bắt đầu áp dụng</label>
                <input type="date" v-model="priceListForm.ngay_bat_dau" class="pl-input" />
              </div>
              <div class="pl-field">
                <label>Thời gian kết thúc</label>
                <input type="date" v-model="priceListForm.ngay_ket_thuc" class="pl-input" />
              </div>
              <div class="pl-field">
                <label>Ghi chú / Mô tả</label>
                <input type="text" v-model="priceListForm.ghi_chu" placeholder="Ghi chú đối tượng áp dụng..." class="pl-input" />
              </div>
            </div>
            <div class="pl-autosync-box" :class="{ active: priceListForm.auto_sync_base_price }">
              <label class="pl-autosync-label">
                <input
                  type="checkbox"
                  v-model="priceListForm.auto_sync_base_price"
                  @change="onModalAutoSyncChange"
                  class="pl-autosync-checkbox"
                />
                <span class="pl-autosync-title">
                  {{ priceListForm.auto_sync_base_price ? '🔄 Tự động cập nhật khi bảng giá gốc thay đổi (Đang BẬT)' : '🔒 Giữ giá cố định — Không tự động đổi theo giá gốc (Đang TẮT)' }}
                </span>
              </label>
              <span class="pl-autosync-hint">
                {{ priceListForm.auto_sync_base_price
                  ? 'Khi giá gốc sản phẩm thay đổi (do Import Excel hoặc sửa giá gốc), bảng giá này sẽ tự động cập nhật giá bán mới theo % / số tiền đã cài đặt.'
                  : 'Bảng giá sẽ giữ cố định mức giá bán đã lưu, không bị thay đổi khi bảng giá gốc biến động.' }}
              </span>
            </div>
          </div>

          <!-- Khung 2: Khung điều chỉnh giá bán tăng / giảm theo % hoặc Số tiền -->
          <div class="pl-config-card pl-config-card--highlight">
            <div class="pl-config-card__title">
              <svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"></line><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg>
              2. Khung Điều Chỉnh Giá Bán (Tăng / Giảm theo % hoặc Số tiền)
            </div>
            <div class="pl-bulk-controls">
              <div class="pl-field" style="min-width: 135px;">
                <label>Chiều điều chỉnh</label>
                <select v-model="priceListForm.bulkDirection" @change="onBulkRuleAutoApply" class="pl-select" :class="priceListForm.bulkDirection === 'decrease' ? 'pl-select--down' : 'pl-select--up'">
                  <option value="increase">📈 Tăng giá (+)</option>
                  <option value="decrease">📉 Giảm giá (-)</option>
                </select>
              </div>
              <div class="pl-field" style="min-width: 150px;">
                <label>Đơn vị tính</label>
                <select v-model="priceListForm.bulkType" @change="onBulkRuleAutoApply" class="pl-select">
                  <option value="percent">Theo Phần trăm (%)</option>
                  <option value="amount">Theo Số tiền cố định</option>
                </select>
              </div>
              <div class="pl-field" style="flex: 1; min-width: 150px;">
                <label>
                  {{ priceListForm.bulkType === 'percent' ? 'Mức % tăng/giảm' : 'Số tiền tăng/giảm' }}
                </label>
                <div style="position: relative; display: flex; align-items: center;">
                  <NumberInput
                    v-if="priceListForm.bulkType === 'percent'"
                    v-model="priceListForm.bulkValue"
                    :decimals="2"
                    @update:modelValue="onBulkRuleAutoApply"
                    placeholder="VD: 10"
                    class="pl-input"
                    style="padding-right: 32px; font-weight: 700; color: #fbbf24;"
                  />
                  <NumberInput
                    v-else
                    v-model="priceListForm.bulkValue"
                    :decimals="0"
                    @update:modelValue="onBulkRuleAutoApply"
                    placeholder="VD: 500.000"
                    class="pl-input"
                    style="padding-right: 45px; font-weight: 700; color: #fbbf24;"
                  />
                  <span style="position: absolute; right: 10px; font-size: 12px; font-weight: 700; color: #94a3b8; pointer-events: none;">
                    {{ priceListForm.bulkType === 'percent' ? '%' : 'Tiền' }}
                  </span>
                </div>
              </div>
              <div class="pl-bulk-actions">
                <button type="button" class="pl-apply-btn pl-apply-btn--selected" @click="applyBulkRuleToSelected" title="Áp dụng mức tăng/giảm này cho tất cả sản phẩm đã tích chọn">
                  ⚡ Áp dụng cho SP đã chọn ({{ selectedPriceListCount }})
                </button>
                <button type="button" class="pl-apply-btn pl-apply-btn--filtered" @click="applyBulkRuleToFiltered" title="Tích chọn và áp dụng mức tăng/giảm này cho danh sách đang lọc bên dưới">
                  🎯 Chọn & Áp dụng SP đang lọc ({{ filteredModalProducts.length }})
                </button>
              </div>
            </div>
          </div>
        </div>

        <!-- Thanh Lọc & Chọn Sản Phẩm -->
        <div class="pl-filter-bar">
          <div class="pl-filter-group">
            <select v-model="modalBrandFilter" class="pl-filter-select">
              <option value="ALL">🏢 Tất cả Hãng ({{ priceListBrandOptions.length }})</option>
              <option v-for="b in priceListBrandOptions" :key="b" :value="b">{{ b }}</option>
            </select>

            <select v-model="modalCategoryFilter" class="pl-filter-select" style="max-width: 260px;">
              <option value="ALL">📁 Tất cả Danh mục ({{ priceListCategoryOptions.length }})</option>
              <option v-for="c in priceListCategoryOptions" :key="c" :value="c">{{ c }}</option>
            </select>

            <div style="position: relative; flex: 1; min-width: 200px; max-width: 300px;">
              <input
                type="text"
                v-model="modalSearchQuery"
                placeholder="🔍 Tìm mã hàng, tên sản phẩm..."
                class="pl-filter-input"
              />
              <button
                v-if="modalSearchQuery"
                type="button"
                @click="modalSearchQuery = ''"
                style="position: absolute; right: 8px; top: 50%; transform: translateY(-50%); background: none; border: none; color: #94a3b8; cursor: pointer; font-size: 13px;"
              >✕</button>
            </div>

            <div class="pl-view-tabs">
              <button type="button" :class="['pl-view-tab', { active: modalViewMode === 'all' }]" @click="modalViewMode = 'all'">
                Tất cả ({{ priceListRows.length }})
              </button>
              <button type="button" :class="['pl-view-tab', { active: modalViewMode === 'selected' }]" @click="modalViewMode = 'selected'">
                Đã chọn ({{ selectedPriceListCount }})
              </button>
              <button type="button" :class="['pl-view-tab', { active: modalViewMode === 'unselected' }]" @click="modalViewMode = 'unselected'">
                Chưa chọn ({{ priceListRows.length - selectedPriceListCount }})
              </button>
            </div>
          </div>

          <div class="pl-selection-btns">
            <button type="button" class="pl-mini-btn" @click="selectAllFilteredInModal">
              ☑️ Chọn tất cả đang lọc ({{ filteredModalProducts.length }})
            </button>
            <button type="button" class="pl-mini-btn pl-mini-btn--muted" @click="deselectAllFilteredInModal">
              ⬜ Bỏ chọn đang lọc
            </button>
          </div>
        </div>

        <!-- Bảng danh sách sản phẩm trong Bảng Giá -->
        <div class="import-table-wrap" style="flex: 1;">
          <table class="import-table pl-table">
            <thead>
              <tr>
                <th style="width: 42px; text-align: center;">
                  <input
                    type="checkbox"
                    :checked="isAllFilteredSelected"
                    @change="toggleAllFilteredInModal($event.target.checked)"
                    title="Chọn / Bỏ chọn tất cả sản phẩm đang lọc"
                    style="width: 16px; height: 16px; cursor: pointer; accent-color: #10b981;"
                  />
                </th>
                <th style="width: 46px;">#</th>
                <th style="min-width: 150px;">Mã hàng</th>
                <th style="min-width: 260px;">Tên hàng hóa</th>
                <th style="min-width: 110px;">Hãng</th>
                <th style="min-width: 160px;">Danh mục</th>
                <th style="width: 75px; text-align: center;">Tiền tệ</th>
                <th style="min-width: 120px; text-align: right;">Giá nhập</th>
                <th style="min-width: 140px; text-align: right;">Giá bán gốc</th>
                <th style="min-width: 250px;">Tăng / Giảm riêng</th>
                <th style="min-width: 155px; text-align: right;">Giá bán mới (Bảng giá)</th>
                <th style="min-width: 120px; text-align: right;">Chênh lệch</th>
              </tr>
            </thead>
            <tbody>
              <tr v-if="!displayedModalProducts.length">
                <td colspan="12" style="text-align: center; padding: 32px; color: #64748b;">
                  Không tìm thấy sản phẩm nào phù hợp với bộ lọc hiện tại.
                </td>
              </tr>
              <tr
                v-for="(row, idx) in displayedModalProducts"
                :key="row.Ma_hang || idx"
                :class="{ 'pl-row-selected': row.selected }"
                @click="row.selected = !row.selected"
                style="cursor: pointer;"
              >
                <td style="text-align: center;" @click.stop>
                  <input
                    type="checkbox"
                    v-model="row.selected"
                    style="width: 16px; height: 16px; cursor: pointer; accent-color: #10b981;"
                  />
                </td>
                <td class="import-row-num">{{ idx + 1 }}</td>
                <td>
                  <span style="font-family: monospace; font-weight: 600; color: #93c5fd; font-size: 12px;">{{ row.Ma_hang }}</span>
                </td>
                <td>
                  <div style="font-weight: 500; color: #f1f5f9; font-size: 12.5px; line-height: 1.35;">{{ row.Ten_hang }}</div>
                </td>
                <td>
                  <span class="brand-badge" style="font-size: 10px; padding: 2px 7px;">{{ row.Ten_nha_cung_cap || '-' }}</span>
                </td>
                <td>
                  <span style="font-size: 11px; color: #94a3b8;">{{ row.Danh_muc || '-' }}</span>
                </td>
                <td style="text-align: center; font-weight: 600; color: #cbd5e1; font-size: 12px;">
                  {{ row.Don_vi_tien_te || 'VND' }}
                </td>
                <td style="text-align: right; color: #fbbf24; font-family: monospace; font-size: 12px;">
                  {{ formatNumberPlain(row.gia_nhap) }}
                </td>
                <td style="text-align: right; color: #cbd5e1; font-weight: 600; font-family: monospace; font-size: 12.5px;">
                  <div>{{ formatNumberPlain(row.gia_goc) }}</div>
                  <div v-if="row.last_updated" style="font-size: 10px; color: #64748b; font-weight: 400; font-family: sans-serif; margin-top: 2px;">
                    CN: {{ formatLastUpdated(row.last_updated) }}
                  </div>
                </td>
                <td @click.stop>
                  <div class="pl-row-adjust">
                    <select v-model="row.direction" @change="recalcRowPrice(row, true)" class="pl-row-select" :class="row.direction === 'decrease' ? 'down' : 'up'">
                      <option value="increase">+ Tăng</option>
                      <option value="decrease">- Giảm</option>
                    </select>
                    <select v-model="row.type" @change="recalcRowPrice(row, true)" class="pl-row-select">
                      <option value="percent">%</option>
                      <option value="amount">Tiền</option>
                      <option value="custom">Tùy chỉnh</option>
                    </select>
                    <NumberInput
                      v-if="row.type === 'percent'"
                      v-model="row.value"
                      :decimals="2"
                      @update:modelValue="recalcRowPrice(row, true)"
                      class="imp-input imp-input--num"
                      style="width: 72px; min-width: 72px;"
                      placeholder="0%"
                    />
                    <NumberInput
                      v-else-if="row.type === 'amount'"
                      v-model="row.value"
                      :decimals="String(row.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0"
                      @update:modelValue="recalcRowPrice(row, true)"
                      class="imp-input imp-input--num"
                      style="width: 95px; min-width: 95px;"
                      placeholder="0"
                    />
                    <span v-else style="font-size: 11px; color: #94a3b8; padding: 0 4px;">Nhập trực tiếp</span>
                  </div>
                </td>
                <td @click.stop>
                  <NumberInput
                    v-model="row.gia_ban_moi"
                    :decimals="String(row.Don_vi_tien_te || 'VND').toUpperCase() === 'USD' ? 2 : 0"
                    @update:modelValue="onCustomRowPriceChange(row)"
                    class="imp-input imp-input--num imp-input--amber"
                    style="font-size: 13px; color: #34d399 !important; border-color: rgba(16, 185, 129, 0.35);"
                  />
                </td>
                <td style="text-align: right; font-family: monospace; font-size: 12px;">
                  <span :class="getRowDiffClass(row)">
                    {{ formatRowDiffText(row) }}
                  </span>
                </td>
              </tr>
            </tbody>
          </table>

          <div v-if="filteredModalProducts.length > modalDisplayLimit" style="padding: 12px; text-align: center; background: #0f172a;">
            <button
              type="button"
              class="btn btn-outline"
              @click="modalDisplayLimit += 100"
              style="font-size: 12.5px; padding: 6px 18px;"
            >
              Hiển thị thêm 100 sản phẩm (còn {{ filteredModalProducts.length - modalDisplayLimit }} SP)
            </button>
          </div>
        </div>

        <!-- Footer -->
        <div class="import-modal__footer" style="justify-content: space-between;">
          <div style="font-size: 13px; color: #94a3b8;">
            Tổng số SP trong bảng giá: <strong style="color: #34d399; font-size: 15px;">{{ selectedPriceListCount }}</strong> sản phẩm
          </div>
          <div style="display: flex; gap: 10px; align-items: center;">
            <button type="button" class="btn btn-secondary" @click="showPriceListModal = false">
              Hủy bỏ
            </button>
            <button type="button" class="btn btn-outline" style="border-color: rgba(56, 189, 248, 0.4); color: #38bdf8;" @click="exportDraftPriceListToExcel">
              <svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg>
              Xuất Excel
            </button>
            <button type="button" class="btn import-btn-save" @click="savePriceList" :disabled="savingPriceList">
              <span v-if="savingPriceList" class="spinner"></span>
              <svg v-else xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg>
              {{ savingPriceList ? 'Đang lưu...' : (isEditingPriceList ? `Cập nhật Bảng Giá (${selectedPriceListCount} SP)` : `Lưu Bảng Giá (${selectedPriceListCount} SP)`) }}
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- ═══ MODAL ĐỐI CHIẾU GIÁ TỪ ẢNH (BƯỚC 1 & BƯỚC 2) ═══ -->
    <div v-if="showImageCheckModal" class="import-overlay" style="z-index: 10060;" @click.self="closeImageCheckModal">
      <div class="import-modal pricelist-modal imgcheck-modal">
        <!-- Header -->
        <div class="import-modal__header">
          <div class="import-modal__header-left">
            <div class="import-modal__icon" style="background: linear-gradient(135deg, rgba(16, 185, 129, 0.25), rgba(6, 182, 212, 0.2)); border-color: rgba(16, 185, 129, 0.45); color: #34d399;">
              <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/></svg>
            </div>
            <div>
              <h2 class="import-modal__title" style="display: flex; align-items: center; gap: 10px; flex-wrap: wrap;">
                <span>Đối Chiếu Giá Từ Ảnh</span>
                <div class="imgcheck-stepper">
                  <button
                    type="button"
                    class="imgcheck-step-tab"
                    :class="{ active: imageCheckActiveStep === 1 }"
                    @click="imageCheckActiveStep = 1"
                  >
                    1. Quét &amp; Bóc tách ảnh
                  </button>
                  <span style="color: #475569;">→</span>
                  <button
                    type="button"
                    class="imgcheck-step-tab"
                    :class="{ active: imageCheckActiveStep === 2 }"
                    :disabled="!validImageCheckRowsCount"
                    @click="runImagePriceComparison"
                  >
                    2. Đối chiếu DB / File Gốc / Trung Gian
                  </button>
                </div>
              </h2>
              <p class="import-modal__sub" v-if="imageCheckActiveStep === 1">
                Tải lên hoặc nhấn <strong>Ctrl + V</strong> để dán ảnh chụp màn hình Calculator (VD: <code>anh_check.jpg</code>). Hệ thống sẽ lọc viền đỏ, quét OCR và chuẩn hóa dữ liệu.
              </p>
              <p class="import-modal__sub" v-else>
                Đối chiếu 4 chiều giữa <strong>Ảnh Check</strong> ↔ <strong>file_goc_SOPHOS</strong> ({{ sophosRefData?.version || '2026-3.0-1' }}) ↔ <strong>file_trung_gian_SOPHOS</strong> ↔ <strong>Database (hang_hoa)</strong>.
              </p>
            </div>
          </div>
          <button class="import-modal__close" @click="closeImageCheckModal" title="Đóng">✕</button>
        </div>

        <!-- Body -->
        <div class="imgcheck-body">
          <!-- ══════════════════ BƯỚC 1: QUÉT & BÓC TÁCH ẢNH ══════════════════ -->
          <template v-if="imageCheckActiveStep === 1">
            <!-- TRẠNG THÁI 1: CHƯA CHỌN ẢNH -->
            <div
              v-if="!imageCheckPreviewUrl && !imageCheckScanning"
              class="imgcheck-dropzone"
              @click="triggerImageCheckInput"
              @dragover.prevent="imageCheckDragOver = true"
              @dragleave.prevent="imageCheckDragOver = false"
              @drop.prevent="handleImageCheckDrop"
              :class="{ 'drag-over': imageCheckDragOver }"
            >
              <input ref="imageCheckFileInput" type="file" accept="image/*" style="display: none" @change="handleImageCheckFileChange" />
              <div class="imgcheck-dropzone__icon">
                <svg xmlns="http://www.w3.org/2000/svg" width="46" height="46" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
              </div>
              <div class="imgcheck-dropzone__title">Kéo thả ảnh vào đây, <span>Nhấn để chọn ảnh</span> hoặc nhấn <kbd>Ctrl + V</kbd></div>
              <div class="imgcheck-dropzone__hint">Hỗ trợ PNG, JPG, JPEG, WEBP (ảnh chụp bảng tính giá Sophos Firewall / Calculator)</div>
            </div>

            <!-- TRẠNG THÁI 2: ĐANG QUÉT OCR -->
            <div v-else-if="imageCheckScanning" class="imgcheck-scanning">
              <div class="imgcheck-scanner-box">
                <div class="imgcheck-scanner-line"></div>
                <img v-if="imageCheckPreviewUrl" :src="imageCheckPreviewUrl" class="imgcheck-scanning-img" alt="Scanning preview" />
              </div>
              <div class="imgcheck-progress-wrap">
                <div class="imgcheck-progress-label">
                  <span>{{ imageCheckStepText || 'Đang phân tích hình ảnh...' }}</span>
                  <strong>{{ Math.round(imageCheckProgress * 100) }}%</strong>
                </div>
                <div class="imgcheck-progress-bar">
                  <div class="imgcheck-progress-fill" :style="{ width: `${Math.round(imageCheckProgress * 100)}%` }"></div>
                </div>
              </div>
            </div>

            <!-- TRẠNG THÁI 3: ĐÃ QUÉT XONG -> HIỂN THỊ KẾT QUẢ BƯỚC 1 -->
            <div v-else class="imgcheck-result-grid">
              <input ref="imageCheckFileInput" type="file" accept="image/*" style="display: none" @change="handleImageCheckFileChange" />

              <!-- Cột trái: Ảnh gốc & OCR thô -->
              <div class="imgcheck-left-col">
                <div class="pl-config-card">
                  <div class="pl-config-card__title" style="justify-content: space-between;">
                    <span style="display: inline-flex; align-items: center; gap: 6px;">
                      <span>🖼️ Ảnh kiểm tra</span>
                      <small v-if="imageCheckFileName" style="color: #94a3b8; font-weight: 400;">({{ imageCheckFileName }})</small>
                    </span>
                    <div style="display: flex; gap: 6px;">
                      <button type="button" class="pl-mini-btn" @click="imageCheckZoomModal = true" title="Phóng to ảnh">
                        🔍 Phóng to
                      </button>
                      <button type="button" class="pl-mini-btn" @click="triggerImageCheckInput" title="Chọn ảnh khác">
                        🔄 Đổi ảnh
                      </button>
                    </div>
                  </div>
                  <div class="imgcheck-preview-wrap" @click="imageCheckZoomModal = true" title="Nhấn để phóng to ảnh">
                    <img :src="imageCheckPreviewUrl" class="imgcheck-preview-img" alt="Preview" />
                  </div>

                  <!-- Nút AI DeepSeek chuẩn hóa lại -->
                  <div style="margin-top: 10px; display: flex; flex-direction: column; gap: 8px;">
                    <button
                      type="button"
                      class="imgcheck-ai-btn"
                      @click="refineImageCheckWithAI"
                      :disabled="imageCheckAiLoading || !imageCheckRawOcr"
                    >
                      <span v-if="imageCheckAiLoading" class="spinner" style="width: 14px; height: 14px; border-width: 2px;"></span>
                      <span v-else>✨</span>
                      <span>{{ imageCheckAiLoading ? 'AI đang chuẩn hóa dữ liệu...' : 'Chuẩn hóa lại bằng AI (DeepSeek Pro)' }}</span>
                    </button>

                    <button
                      type="button"
                      class="pl-mini-btn"
                      style="width: 100%; justify-content: center; display: inline-flex; align-items: center; gap: 6px;"
                      @click="showRawOcrPanel = !showRawOcrPanel"
                    >
                      <span>{{ showRawOcrPanel ? '▲ Ẩn văn bản OCR thô' : '▼ Xem văn bản OCR thô' }}</span>
                    </button>
                  </div>

                  <div v-if="showRawOcrPanel" style="margin-top: 8px;">
                    <textarea
                      v-model="imageCheckRawOcr"
                      class="imp-input"
                      rows="8"
                      style="width: 100%; font-family: monospace; font-size: 11.5px; line-height: 1.45; resize: vertical; background: #090d16; color: #94a3b8;"
                      placeholder="Văn bản OCR thô..."
                    ></textarea>
                    <button
                      type="button"
                      class="pl-mini-btn"
                      style="margin-top: 6px; width: 100%;"
                      @click="reparseRawOcrText"
                    >
                      ⚡ Phân tích lại từ văn bản OCR trên
                    </button>
                  </div>
                </div>

                <div v-if="imageCheckError" class="imgcheck-error-box">
                  ⚠️ {{ imageCheckError }}
                </div>
              </div>

              <!-- Cột phải: Deal Settings & Bảng dữ liệu bóc tách -->
              <div class="imgcheck-right-col">
                <!-- Card 1: Deal Settings (Đúng chuẩn Sheet Firewall / Cover của calculate_sophos.xlsx) -->
                <div class="pl-config-card">
                  <div class="pl-config-card__title" style="justify-content: space-between; flex-wrap: wrap; gap: 8px;">
                    <span>⚙️ Cấu hình Deal Settings (Như trong <code>calculate_sophos.xlsx</code>)</span>
                    <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
                      <button
                        type="button"
                        class="pl-mini-btn"
                        style="background: rgba(20, 184, 166, 0.18); border-color: rgba(20, 184, 166, 0.55); color: #5eead4; font-weight: 700;"
                        @click="populateImageCheckRowsFromCalculator(false)"
                        title="Tự động điền & tính toàn bộ 15 hạng mục Hardware Bundles & Subscriptions theo đúng công thức trong calculate_sophos.xlsx"
                      >
                        🧮 Điền 15 hạng mục từ Calculator
                      </button>
                      <button
                        type="button"
                        class="pl-mini-btn"
                        style="background: linear-gradient(135deg, #0d9488, #0284c7); border-color: transparent; color: #fff; font-weight: 700;"
                        @click="populateImageCheckRowsFromCalculator(true)"
                        title="Tính trực tiếp từ File Calculator và mở sang màn hình Đối Chiếu ngay mà không cần quét ảnh"
                      >
                        ⚡ Tính &amp; Đối chiếu ngay →
                      </button>
                    </div>
                  </div>
                  <div class="imgcheck-settings-grid">
                    <div class="pl-field">
                      <label>Partner Level (Cover!I3)</label>
                      <select v-model="imageCheckSettings.partnerLevel" class="pl-row-select" style="width: 100%; font-weight: 700; color: #5eead4;">
                        <option v-for="pl in sophosPartnerLevelOptions" :key="pl" :value="pl">{{ pl }}</option>
                      </select>
                    </div>
                    <div class="pl-field">
                      <label>Model Thiết Bị (Firewall)</label>
                      <select v-model="imageCheckSettings.model" class="pl-row-select" style="width: 100%; font-weight: 800; color: #38bdf8;">
                        <optgroup v-for="grp in sophosCalcFirewallGroups" :key="grp.group" :label="grp.group">
                          <option v-for="m in grp.models" :key="m" :value="m">{{ m }}</option>
                        </optgroup>
                      </select>
                    </div>
                    <div class="pl-field">
                      <label>Sector (Firewall!H4)</label>
                      <select v-model="imageCheckSettings.sector" class="pl-row-select" style="width: 100%;">
                        <option v-for="sec in sophosSectorOptions" :key="sec" :value="sec">{{ sec }}</option>
                      </select>
                    </div>
                    <div class="pl-field">
                      <label>Deal Type (Firewall!V4)</label>
                      <select v-model="imageCheckSettings.dealType" class="pl-row-select" style="width: 100%;">
                        <option v-for="dt in sophosDealTypeOptions" :key="dt" :value="dt">{{ dt }}</option>
                      </select>
                    </div>
                    <div class="pl-field">
                      <label>Term (HW Bundles • D7)</label>
                      <select v-model="imageCheckSettings.termHwBundle" class="pl-row-select" style="width: 100%;">
                        <option value="">Không chọn (Chỉ tính lẻ)</option>
                        <option value="1-Year">1-Year (12 MOS)</option>
                        <option value="3-Year">3-Year (36 MOS)</option>
                        <option value="5-Year">5-Year (60 MOS)</option>
                      </select>
                    </div>
                    <div class="pl-field">
                      <label>Term (Subscriptions • D9)</label>
                      <select v-model="imageCheckSettings.termSubscription" class="pl-row-select" style="width: 100%;">
                        <option v-for="tm in sophosTermOptions" :key="tm" :value="tm">{{ tm }}</option>
                      </select>
                    </div>
                    <div class="pl-field">
                      <label>Số lượng (Qty • D11)</label>
                      <input type="number" v-model.number="imageCheckSettings.qty" class="imp-input imp-input--num" min="1" />
                    </div>
                    <div class="pl-field">
                      <label>Special Attribute (D13)</label>
                      <select v-model="imageCheckSettings.specialAttribute" class="pl-row-select" style="width: 100%; color: #fbbf24; font-weight: 700;">
                        <option v-for="ps in ['AU', 'EU', 'UK', 'US', 'CN', 'IN', 'JP']" :key="ps" :value="ps">{{ ps }}</option>
                      </select>
                    </div>
                  </div>
                  <div v-if="imageCheckSettings.description" style="margin-top: 8px; padding: 7px 10px; background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(56, 189, 248, 0.2); border-radius: 7px; font-size: 11.5px; color: #94a3b8;">
                    <strong style="color: #cbd5e1;">Hardware Features:</strong> {{ imageCheckSettings.description }}
                  </div>
                </div>

                <!-- Card 2: Bảng danh sách SKU & Giá bóc tách -->
                <div class="pl-config-card" style="flex: 1; display: flex; flex-direction: column; min-height: 0;">
                  <div class="pl-config-card__title" style="justify-content: space-between; flex-wrap: wrap; gap: 8px;">
                    <div style="display: flex; align-items: center; gap: 10px;">
                      <span>📋 Danh sách Mã SKU &amp; Giá bóc tách từ ảnh</span>
                      <span class="pricelist-rule-badge" style="background: rgba(56, 189, 248, 0.15); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.3);">
                        {{ validImageCheckRowsCount }} mã có giá / {{ imageCheckRows.length }} dòng
                      </span>
                    </div>
                    <div style="display: flex; align-items: center; gap: 8px;">
                      <label style="display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: #94a3b8; cursor: pointer; font-weight: 400;">
                        <input type="checkbox" v-model="hideUnavailableRows" style="accent-color: #10b981;" />
                        Ẩn dòng Not Available
                      </label>
                      <button type="button" class="pl-mini-btn" @click="addImageCheckRow">
                        + Thêm dòng
                      </button>
                    </div>
                  </div>

                  <div class="imgcheck-table-wrap">
                    <table class="import-table">
                      <thead>
                        <tr>
                          <th style="width: 42px; text-align: center;">#</th>
                          <th style="width: 145px;">Nhóm</th>
                          <th style="min-width: 210px;">Hạng mục (Product / Subscription)</th>
                          <th style="width: 165px;">Mã SKU</th>
                          <th style="width: 125px; text-align: right;">MSRP (USD)</th>
                          <th style="width: 95px; text-align: right;">Disc (%)</th>
                          <th style="width: 125px; text-align: right;">Buy Cost (USD)</th>
                          <th style="width: 48px; text-align: center;">Xóa</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr v-if="!displayedImageCheckRows.length">
                          <td colspan="8" style="text-align: center; padding: 28px; color: #64748b;">
                            Chưa có dòng dữ liệu nào được bóc tách. Hãy nhấn <strong>"Chuẩn hóa lại bằng AI"</strong> hoặc <strong>"+ Thêm dòng"</strong>.
                          </td>
                        </tr>
                        <tr
                          v-for="(row, idx) in displayedImageCheckRows"
                          :key="row.id"
                          :class="{ 'imgcheck-row-na': !row.available }"
                        >
                          <td style="text-align: center; color: #64748b; font-weight: 600;">{{ idx + 1 }}</td>
                          <td>
                            <select v-model="row.category" class="pl-row-select" style="width: 100%;">
                              <option value="Hardware Bundles">Hardware Bundles</option>
                              <option value="Subscriptions">Subscriptions</option>
                            </select>
                          </td>
                          <td>
                            <input type="text" v-model="row.name" class="imp-input" placeholder="Tên gói / hạng mục..." />
                          </td>
                          <td>
                            <input
                              type="text"
                              v-model="row.sku"
                              @input="row.available = Boolean(row.sku && row.sku !== 'Not Available')"
                              class="imp-input"
                              style="font-family: monospace; font-weight: 700; color: #38bdf8;"
                              placeholder="SKU..."
                            />
                            <div
                              v-if="row.available && row.sku && row.sku !== 'Not Available'"
                              style="display: flex; align-items: center; gap: 4px; margin-top: 4px; flex-wrap: wrap;"
                            >
                              <button
                                type="button"
                                class="sku-jump-chip sku-jump-chip--calc"
                                @click="openExcelNavigatorForSku(row.sku, 'calc', row.name)"
                                title="Mở calculate_sophos.xlsx và nhảy tới đúng dòng chứa mã SKU này"
                              >
                                🧮 Calculator
                              </button>
                              <button
                                type="button"
                                class="sku-jump-chip sku-jump-chip--goc"
                                @click="openExcelNavigatorForSku(row.sku, 'goc', row.name)"
                                title="Mở file_goc_SOPHOS.xlsx và nhảy tới đúng dòng chứa mã SKU này"
                              >
                                📗 File Gốc
                              </button>
                              <button
                                type="button"
                                class="sku-jump-chip sku-jump-chip--skulist"
                                @click="openExcelNavigatorForSku(row.sku, 'skulist', row.name)"
                                title="Mở sophos-pricelist-reseller_SKU_list-asean-usd-2026-3.0.xlsb (SKU_Tab) và nhảy tới đúng dòng chứa mã SKU này"
                              >
                                📙 SKU_List
                              </button>
                              <button
                                type="button"
                                class="sku-jump-chip sku-jump-chip--tg"
                                @click="openExcelNavigatorForSku(row.sku, 'tg', row.name)"
                                title="Mở file_trung_gian_SOPHOS.xlsx và nhảy tới đúng dòng chứa mã SKU này"
                              >
                                📘 File TG
                              </button>
                            </div>
                          </td>
                          <td>
                            <input
                              type="number"
                              step="0.01"
                              v-model.number="row.msrp"
                              class="imp-input imp-input--num"
                              style="color: #f8fafc; font-weight: 700;"
                              placeholder="0.00"
                            />
                          </td>
                          <td>
                            <input
                              type="number"
                              step="0.01"
                              v-model.number="row.resellerDisc"
                              class="imp-input imp-input--num"
                              style="color: #fbbf24;"
                              placeholder="0%"
                            />
                          </td>
                          <td>
                            <input
                              type="number"
                              step="0.01"
                              v-model.number="row.buyCost"
                              class="imp-input imp-input--num"
                              style="color: #34d399; font-weight: 600;"
                              placeholder="0.00"
                            />
                          </td>
                          <td style="text-align: center;">
                            <button type="button" class="btn-icon text-danger" @click="removeImageCheckRow(row.id)" title="Xóa dòng">
                              ✕
                            </button>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          </template>

          <!-- ══════════════════ BƯỚC 2: ĐỐI CHIẾU DATABASE & FILE GỐC / TRUNG GIAN ══════════════════ -->
          <template v-else>
            <!-- Thống kê tổng quan kết quả đối chiếu -->
            <div class="imgcheck-compare-stats">
              <div class="imgcheck-stat-card">
                <div class="imgcheck-stat-label">Tổng số mã kiểm tra</div>
                <div class="imgcheck-stat-val" style="color: #38bdf8;">{{ comparisonRows.length }} mã</div>
                <div class="imgcheck-stat-sub">Model: <strong>{{ imageCheckSettings.model || '-' }}</strong> ({{ imageCheckSettings.specialAttribute || 'AU' }} · {{ imageCheckSettings.termSubscription || '12 MOS' }})</div>
              </div>
              <div class="imgcheck-stat-card" style="border-color: rgba(20, 184, 166, 0.45); background: linear-gradient(180deg, rgba(20, 184, 166, 0.12), rgba(15, 23, 42, 0.84));">
                <div class="imgcheck-stat-label" style="color: #5eead4;" :title="getVendorCompareFileMeta('sophos', 'calc')?.name || 'calculate_sophos.xlsx'">
                  So với calculate_sophos (Ưu tiên)
                </div>
                <div class="imgcheck-stat-val" style="color: #2dd4bf;">
                  {{ comparisonSummary.calcMatch }} / {{ comparisonRows.length }} khớp
                </div>
                <div class="imgcheck-stat-sub">
                  <span v-if="comparisonSummary.calcDiff > 0" style="color: #fbbf24;">{{ comparisonSummary.calcDiff }} lệch giá ảnh</span>
                  <span v-else-if="comparisonSummary.calcMissing === comparisonRows.length" style="color: #f87171;">Chưa có dữ liệu Calculator</span>
                  <span v-else style="color: #99f6e4;">Khớp Calculator (v{{ sophosCalcRefData?.version || getVendorCompareFileMeta('sophos', 'calc')?.version || '2026-4.0.2-1' }})</span>
                  <span v-if="comparisonSummary.calcChangedVsGoc > 0" style="color: #fcd34d;"> · {{ comparisonSummary.calcChangedVsGoc }} đổi giá vs v3.0</span>
                </div>
              </div>
              <div class="imgcheck-stat-card">
                <div class="imgcheck-stat-label">So với file_goc_SOPHOS</div>
                <div class="imgcheck-stat-val" style="color: #34d399;">
                  {{ comparisonSummary.gocMatch }} / {{ comparisonRows.length }} khớp
                </div>
                <div class="imgcheck-stat-sub">
                  <span v-if="comparisonSummary.gocDiff > 0" style="color: #fbbf24;">{{ comparisonSummary.gocDiff }} lệch giá</span>
                  <span v-else style="color: #94a3b8;">Khớp 100% bảng giá hãng ({{ sophosRefData?.version || '2026-3.0-1' }})</span>
                </div>
              </div>
              <div class="imgcheck-stat-card" style="border-color: rgba(245, 158, 11, 0.35); background: linear-gradient(180deg, rgba(245, 158, 11, 0.08), rgba(15, 23, 42, 0.82));">
                <div class="imgcheck-stat-label" style="color: #fde68a;" title="sophos-pricelist-reseller_SKU_list-asean-usd-2026-3.0.xlsb">
                  So với Reseller_SKU_List (.xlsb)
                </div>
                <div class="imgcheck-stat-val" style="color: #fbbf24;">
                  {{ comparisonSummary.skuListMatch }} / {{ comparisonRows.length }} khớp
                </div>
                <div class="imgcheck-stat-sub">
                  <span style="color: #fcd34d;">{{ comparisonSummary.skuListPiCount }} mã có Giá cũ (PI)</span>
                  <span style="color: #94a3b8;"> · SKU_Tab &amp; HW</span>
                </div>
              </div>
              <div class="imgcheck-stat-card">
                <div class="imgcheck-stat-label">So với file_trung_gian_SOPHOS</div>
                <div class="imgcheck-stat-val" style="color: #a78bfa;">
                  {{ comparisonSummary.tgMatch }} / {{ comparisonRows.length }} khớp
                </div>
                <div class="imgcheck-stat-sub">
                  <span v-if="comparisonSummary.tgMissing > 0" style="color: #f87171;">{{ comparisonSummary.tgMissing }} mã chưa có trong BOM trung gian</span>
                  <span v-else style="color: #94a3b8;">Đầy đủ trong BOM trung gian</span>
                </div>
              </div>
              <div class="imgcheck-stat-card">
                <div class="imgcheck-stat-label">So với Database (hang_hoa)</div>
                <div class="imgcheck-stat-val" :style="{ color: comparisonSummary.dbMatch === comparisonRows.length ? '#34d399' : '#fbbf24' }">
                  {{ comparisonSummary.dbMatch }} khớp · {{ comparisonSummary.dbDiff }} lệch · {{ comparisonSummary.dbMissing }} thiếu
                </div>
                <div class="imgcheck-stat-sub">
                  <span v-if="comparisonSummary.dbDiff > 0 || comparisonSummary.dbMissing > 0" style="color: #fcd34d;">
                    Có thể đồng bộ trực tiếp vào Firebase bên dưới
                  </span>
                  <span v-else style="color: #34d399;">Database đã khớp hoàn toàn!</span>
                </div>
              </div>
            </div>

            <!-- Thanh công cụ lọc & Nạp file Excel tùy chỉnh -->
            <div class="imgcheck-compare-toolbar">
              <div class="pl-view-tabs" style="flex-wrap: wrap;">
                <button
                  type="button"
                  class="pl-view-tab"
                  :class="{ active: compareFilterMode === 'all' }"
                  @click="compareFilterMode = 'all'"
                >
                  Tất cả ({{ comparisonRows.length }})
                </button>
                <button
                  type="button"
                  class="pl-view-tab"
                  :class="{ active: compareFilterMode === 'db_issue' }"
                  @click="compareFilterMode = 'db_issue'"
                >
                  ⚠️ Cần cập nhật DB ({{ comparisonSummary.dbDiff + comparisonSummary.dbMissing }})
                </button>
                <button
                  type="button"
                  class="pl-view-tab"
                  :class="{ active: compareFilterMode === 'db_diff' }"
                  @click="compareFilterMode = 'db_diff'"
                >
                  🟡 Lệch giá DB ({{ comparisonSummary.dbDiff }})
                </button>
                <button
                  type="button"
                  class="pl-view-tab"
                  :class="{ active: compareFilterMode === 'db_missing' }"
                  @click="compareFilterMode = 'db_missing'"
                >
                  🔴 Thiếu trong DB ({{ comparisonSummary.dbMissing }})
                </button>
                <button
                  type="button"
                  class="pl-view-tab"
                  :class="{ active: compareFilterMode === 'tg_missing' }"
                  @click="compareFilterMode = 'tg_missing'"
                >
                  🟣 Thiếu ở File Trung Gian ({{ comparisonSummary.tgMissing }})
                </button>
                <button
                  type="button"
                  class="pl-view-tab"
                  :class="{ active: compareFilterMode === 'calc_issue' }"
                  @click="compareFilterMode = 'calc_issue'"
                >
                  🧮 Lệch/Thiếu ở Calculator ({{ comparisonSummary.calcDiff + comparisonSummary.calcMissing }})
                </button>
              </div>

              <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                <span v-if="vendorRefFilesMeta.sophos" style="font-size: 11.5px; color: #94a3b8; background: rgba(15,23,42,0.8); padding: 4px 10px; border-radius: 6px; border: 1px solid rgba(56,189,248,0.25); display: inline-flex; align-items: center; gap: 6px; flex-wrap: wrap;">
                  <span>☁️ Cloudinary:</span>
                  <strong style="color: #5eead4; display: inline-flex; align-items: center; gap: 4px;">
                    Calculator:
                    <template v-if="getVendorCompareFileMeta('sophos', 'calc')">
                      <a
                        :href="getVendorOfficeViewUrl(getVendorCompareFileMeta('sophos', 'calc'))"
                        target="_blank"
                        rel="noopener noreferrer"
                        style="color: #5eead4; text-decoration: underline;"
                        title="Click để mở xem trên ViewOffice (Tab mới)"
                        @click="handleOpenVendorOfficeView($event, 'sophos', 'calc', getVendorCompareFileMeta('sophos', 'calc'))"
                      >{{ getVendorCompareFileMeta('sophos', 'calc').name }}</a>
                      <span v-if="getVendorCompareFileMeta('sophos', 'calc').version" style="font-size: 10px; color: #99f6e4;">(v{{ getVendorCompareFileMeta('sophos', 'calc').version }})</span>
                      <button
                        type="button"
                        class="vendor-file-office-btn"
                        title="Mở ViewOffice trong tab mới với đầy đủ mã SKU đã tính toán của calculate_sophos"
                        @click.stop="openCompareOfficePreview({ vendor: 'sophos', role: 'calc', sheet: comparisonRows.find(r => r.calcFound)?.calcNativeSheet || 'Firewall', rowNum: comparisonRows.find(r => r.calcFound)?.calcSheetRowNum || comparisonRows.find(r => r.calcFirewallRowNum)?.calcFirewallRowNum || 29, colLetter: comparisonRows.find(r => r.calcFound)?.calcSheetColLetter || 'H', sku: comparisonRows.find(r => r.calcFound)?.calcAltSku || comparisonRows.find(r => r.calcFound)?.sku || '', itemName: comparisonRows.find(r => r.calcFound)?.name || '' })"
                      >👁️ Xem bằng ViewOffice</button>
                      <button
                        type="button"
                        class="vendor-file-download-btn"
                        title="Tải File Calculator Sophos nguyên bản về máy"
                        @click.stop="handleDownloadVendorUploadedFile('sophos', 'calc', getVendorCompareFileMeta('sophos', 'calc'))"
                      >⬇ Tải về</button>
                    </template>
                    <span v-else>Chưa có</span>
