                      <template v-if="item.dbItem">
                        <div
                          style="font-size: 13.5px; font-weight: 700;"
                          :style="{ color: item.dbStatus === 'match' ? '#34d399' : '#fbbf24' }"
                        >
                          {{ formatUsdPrice(item.dbPrice) }}
                        </div>
                        <div style="font-size: 11px; color: #94a3b8; margin-top: 2px;">
                          <span v-if="item.dbItem.gia_nhap > 0">Giá nhập: {{ formatUsdPrice(item.dbItem.gia_nhap) }}</span>
                          <span v-else>{{ item.dbItem.Don_vi_tien_te || 'USD' }}</span>
                        </div>
                      </template>
                      <template v-else>
                        <span style="color: #64748b;">—</span>
                      </template>
                    </td>

                    <!-- Cột 7: Trạng thái & Chênh lệch -->
                    <td>
                      <div v-if="item.dbStatus === 'match'" class="cmp-badge cmp-badge--match">
                        🟢 Khớp giá DB
                      </div>
                      <div v-else-if="item.dbStatus === 'diff'">
                        <span class="cmp-badge cmp-badge--diff">
                          🟡 Lệch {{ item.dbDiff > 0 ? '+' : '' }}{{ formatUsdPrice(item.dbDiff) }} ({{ item.dbDiffPct > 0 ? '+' : '' }}{{ item.dbDiffPct.toFixed(1) }}%)
                        </span>
                        <div style="font-size: 10.5px; color: #5eead4; margin-top: 3px; font-weight: 600;">
                          Chuẩn {{ item.targetPriceSource || 'Calculator' }}: {{ formatUsdPrice(item.targetPrice) }}
                        </div>
                        <div v-if="item.isOldPre10Pct" style="font-size: 11px; color: #fcd34d; margin-top: 2px;">
                          DB đang lưu giá cũ (chưa +10%)
                        </div>
                      </div>
                      <div v-else>
                        <span class="cmp-badge cmp-badge--missing">
                          🔴 Thiếu trong DB
                        </span>
                        <div style="font-size: 10.5px; color: #5eead4; margin-top: 3px; font-weight: 600;">
                          Sẽ tạo: {{ formatUsdPrice(item.targetPrice) }}
                        </div>
                      </div>
                    </td>

                    <!-- Cột 8: Thao tác đồng bộ vào DB -->
                    <td style="text-align: center;">
                      <button
                        v-if="item.dbStatus === 'diff'"
                        type="button"
                        class="cmp-action-btn cmp-action-btn--update"
                        :disabled="syncingCompareToDb"
                        @click="syncSingleCompareRowToDb(item)"
                        :title="`Cập nhật giá chuẩn (${item.targetPriceSource || 'calculate_sophos'}: ${formatUsdPrice(item.targetPrice)}) vào Database hang_hoa`"
                      >
                        🔄 Cập nhật giá
                      </button>
                      <button
                        v-else-if="item.dbStatus === 'missing'"
                        type="button"
                        class="cmp-action-btn cmp-action-btn--add"
                        :disabled="syncingCompareToDb"
                        @click="syncSingleCompareRowToDb(item)"
                        title="Thêm sản phẩm mới này vào Database hang_hoa"
                      >
                        + Thêm vào DB
                      </button>
                      <span v-else style="font-size: 12px; color: #34d399; font-weight: 600;">
                        ✓ Đã chuẩn
                      </span>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </template>
        </div>

        <!-- Footer -->
        <div class="import-modal__footer" style="justify-content: space-between;">
          <div style="display: flex; align-items: center; gap: 18px; font-size: 13px; color: #94a3b8; flex-wrap: wrap;">
            <span>Model: <strong style="color: #38bdf8;">{{ imageCheckSettings.model || '-' }}</strong></span>
            <span>Site: <strong style="color: #fbbf24;">{{ imageCheckSettings.specialAttribute || '-' }}</strong></span>
            <span>Term: <strong style="color: #e2e8f0;">{{ imageCheckSettings.termSubscription || '-' }}</strong></span>
            <span>Số mã SKU hợp lệ: <strong style="color: #34d399; font-size: 15px;">{{ validImageCheckRowsCount }}</strong></span>
          </div>

          <!-- Nút điều hướng ở Bước 1 -->
          <div v-if="imageCheckActiveStep === 1" style="display: flex; gap: 10px; align-items: center; flex-wrap: wrap;">
            <button type="button" class="btn btn-secondary" @click="closeImageCheckModal">
              Đóng
            </button>
            <button
              v-if="imageCheckPreviewUrl && !imageCheckScanning"
              type="button"
              class="btn btn-outline"
              style="border-color: rgba(56, 189, 248, 0.4); color: #38bdf8;"
              @click="resetImageCheckModal"
            >
              Quét ảnh khác
            </button>
            <button
              v-if="validImageCheckRowsCount > 0 && !imageCheckScanning"
              type="button"
              class="btn import-btn-save"
              @click="runImagePriceComparison"
            >
              <span>🔍 Sang Bước 2: Đối Chiếu Giá ({{ validImageCheckRowsCount }} mã) →</span>
            </button>
          </div>

          <!-- Nút điều hướng & Đồng bộ ở Bước 2 -->
          <div v-else style="display: flex; gap: 10px; align-items: center; flex-wrap: wrap;">
            <button type="button" class="btn btn-secondary" @click="imageCheckActiveStep = 1">
              ← Quay lại Bước 1
            </button>
            <button
              type="button"
              class="btn btn-outline"
              style="border-color: rgba(56, 189, 248, 0.4); color: #38bdf8;"
              @click="exportComparisonToExcel"
            >
              📊 Xuất Excel Đối Chiếu
            </button>
            <button
              type="button"
              class="btn import-btn-save"
              :disabled="syncingCompareToDb || selectedComparisonRowsCount === 0"
              @click="syncSelectedCompareRowsToDb"
            >
              <span v-if="syncingCompareToDb" class="spinner"></span>
              <span>⚡ Đồng bộ {{ selectedComparisonRowsCount }} mục đã chọn vào Database</span>
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- MODAL PHÓNG TO ẢNH CHECK -->
    <div v-if="imageCheckZoomModal && imageCheckPreviewUrl" class="import-overlay" style="z-index: 10100;" @click="imageCheckZoomModal = false">
      <div style="position: relative; max-width: 95vw; max-height: 92vh; display: flex; flex-direction: column; align-items: center;">
        <button
          type="button"
          class="import-modal__close"
          style="position: absolute; top: -14px; right: -14px; background: #0f172a; border: 1px solid rgba(255,255,255,0.2); z-index: 2;"
          @click.stop="imageCheckZoomModal = false"
        >✕</button>
        <img :src="imageCheckPreviewUrl" style="max-width: 95vw; max-height: 90vh; object-fit: contain; border-radius: 10px; box-shadow: 0 20px 60px rgba(0,0,0,0.85);" @click.stop />
      </div>
    </div>

    <!-- ═══════════════════════════════════════════════════════════════════════════
         MODAL ĐỐI CHIẾU GIÁ KASPERSKY TỪ ẢNH (anh_check_KAS.jpg <-> filegocKas.xlsx <-> Database)
         ═══════════════════════════════════════════════════════════════════════════ -->
    <div v-if="showKasImageCheckModal" class="import-overlay" style="z-index: 10050;" @click.self="closeKasImageCheckModal">
      <div class="import-modal" style="max-width: 1540px; width: 97vw; max-height: 94vh;">
        <!-- Header -->
        <div class="import-modal__header" style="background: linear-gradient(135deg, rgba(6, 78, 59, 0.92), rgba(15, 23, 42, 0.96)); border-bottom: 1px solid rgba(16, 185, 129, 0.3);">
          <div class="import-modal__header-left">
            <div class="import-modal__icon" style="background: rgba(16, 185, 129, 0.2); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.4);">
              🛡️
            </div>
            <div>
              <h2 class="import-modal__title" style="display: flex; align-items: center; gap: 10px;">
                <span>Đối chiếu Bảng Giá Kaspersky (Ảnh ↔ filegocKas.xlsx ↔ Database)</span>
                <span style="font-size: 11px; padding: 2px 8px; border-radius: 999px; background: rgba(16, 185, 129, 0.2); color: #6ee7b7; border: 1px solid rgba(16, 185, 129, 0.35);">
                  {{ kasCheckActiveStep === 1 ? 'Bước 1/2: Bóc tách Ảnh' : 'Bước 2/2: Đối chiếu 4 chiều' }}
                </span>
              </h2>
              <p class="import-modal__subtitle">
                Bóc tách bảng Pivot Kaspersky theo từng Band (`Band M..R`) và đối chiếu với `filegocKas.xlsx` (01/07/2026), `KASPERSKY_file_mau_import.xlsx` &amp; Firebase `hang_hoa`
              </p>
            </div>
          </div>

          <div style="display: flex; align-items: center; gap: 8px;">
            <div class="imgcheck-stepper">
              <button
                type="button"
                class="imgcheck-step-pill"
                :class="{ active: kasCheckActiveStep === 1 }"
                @click="kasCheckActiveStep = 1"
              >
                <span class="step-num">1</span>
                <span>Bóc tách Ảnh KAS</span>
              </button>
              <span style="color: #475569;">→</span>
              <button
                type="button"
                class="imgcheck-step-pill"
                :class="{ active: kasCheckActiveStep === 2 }"
                :disabled="kasCheckRows.length === 0"
                @click="runKasPriceComparison"
              >
                <span class="step-num">2</span>
                <span>Đối chiếu filegocKas &amp; DB</span>
              </button>
            </div>
            <button class="import-modal__close" @click="closeKasImageCheckModal">✕</button>
          </div>
        </div>

        <!-- Body -->
        <div class="pricelist-modal-body" style="padding: 18px 22px; overflow-y: auto; flex: 1;">
          <!-- ==================== BƯỚC 1: BÓC TÁCH ẢNH KASPERSKY ==================== -->
          <template v-if="kasCheckActiveStep === 1">
            <input ref="kasCheckFileInput" type="file" accept="image/*" style="display: none" @change="handleKasCheckFileChange" />

            <!-- Trạng thái chưa chọn ảnh -->
            <div v-if="!kasCheckPreviewUrl && !kasCheckScanning" class="imgcheck-dropzone" @click="triggerKasCheckInput" @dragover.prevent @drop.prevent="handleKasCheckDrop" style="border-color: rgba(16, 185, 129, 0.4);">
              <div class="imgcheck-dropzone__icon" style="background: rgba(16, 185, 129, 0.12); color: #34d399;">
                🛡️
              </div>
              <div class="imgcheck-dropzone__title">
                Tải lên hoặc dán (Ctrl+V) ảnh chụp bảng giá Kaspersky (VD: <code>anh_check_KAS.jpg</code>)
              </div>
              <div class="imgcheck-dropzone__sub">
                Hệ thống sẽ tự động bóc tách Product, Package, Type (Base Plus / Renewal Plus), Term (1/2/3 year), SKU và đơn giá VND theo từng cột Band
              </div>
              <div style="display: flex; gap: 12px; margin-top: 14px; flex-wrap: wrap; justify-content: center;" @click.stop>
                <button type="button" class="btn btn-primary" style="background: #10b981; border-color: #059669;" @click="triggerKasCheckInput">
                  📂 Chọn ảnh từ máy tính
                </button>
                <button
                  type="button"
                  class="btn btn-outline"
                  style="border-color: rgba(16, 185, 129, 0.55); color: #6ee7b7; background: rgba(16, 185, 129, 0.12); font-weight: 700;"
                  @click="loadSampleKasCheckData"
                >
                  ⚡ Nạp ngay dữ liệu mẫu từ anh_check_KAS.jpg (Kaspersky Next EDR Optimum)
                </button>
              </div>
            </div>

            <!-- Trạng thái đang quét OCR -->
            <div v-else-if="kasCheckScanning" class="imgcheck-scanning-box">
              <div class="spinner" style="width: 42px; height: 42px; border-width: 4px; border-top-color: #10b981;"></div>
              <h3 style="margin: 14px 0 6px; color: #f8fafc;">{{ kasCheckStepText || 'Đang nhận diện bảng giá Kaspersky...' }}</h3>
              <div style="width: 340px; max-width: 90%; background: rgba(255,255,255,0.08); height: 8px; border-radius: 999px; overflow: hidden;">
                <div :style="{ width: `${Math.round(kasCheckProgress * 100)}%`, background: 'linear-gradient(90deg, #10b981, #38bdf8)', height: '100%', transition: 'width 0.25s' }"></div>
              </div>
            </div>

            <!-- Trạng thái đã có dữ liệu Bước 1 -->
            <div v-else class="imgcheck-result-grid">
              <!-- Cột trái: Ảnh Preview -->
              <div class="imgcheck-left-col">
                <div class="pl-config-card">
                  <div class="pl-config-card__title" style="justify-content: space-between;">
                    <span>🖼️ Ảnh kiểm tra Kaspersky <small v-if="kasCheckFileName" style="color:#94a3b8;">({{ kasCheckFileName }})</small></span>
                    <div style="display: flex; gap: 6px;">
                      <button type="button" class="pl-mini-btn" @click="kasCheckZoomModal = true">🔍 Phóng to</button>
                      <button type="button" class="pl-mini-btn" @click="triggerKasCheckInput">🔄 Đổi ảnh</button>
                    </div>
                  </div>
                  <div class="imgcheck-preview-wrap" @click="kasCheckZoomModal = true" title="Nhấn để phóng to ảnh">
                    <img :src="kasCheckPreviewUrl" class="imgcheck-preview-img" alt="Kaspersky Check Preview" />
                  </div>
                  <div style="margin-top: 10px; display: flex; gap: 8px; flex-wrap: wrap;">
                    <button type="button" class="pl-mini-btn" style="flex: 1;" @click="loadSampleKasCheckData">
                      ⚡ Khôi phục chuẩn anh_check_KAS.jpg
                    </button>
                  </div>
                </div>

                <!-- Thông tin chung trên ảnh -->
                <div class="pl-config-card" style="margin-top: 12px;">
                  <div class="pl-config-card__title">⚙️ Thông tin chung trên ảnh</div>
                  <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
                    <div class="form-group" style="margin: 0; grid-column: span 2;">
                      <label style="font-size: 11px;">Product (Tên sản phẩm trên ảnh)</label>
                      <input v-model="kasCheckSettings.product" type="text" class="imp-input" style="font-weight: 700; color: #34d399;" />
                    </div>
                    <div class="form-group" style="margin: 0;">
                      <label style="font-size: 11px;">Code</label>
                      <input v-model="kasCheckSettings.code" type="text" class="imp-input" />
                    </div>
                    <div class="form-group" style="margin: 0;">
                      <label style="font-size: 11px;">Package</label>
                      <input v-model="kasCheckSettings.package" type="text" class="imp-input" />
                    </div>
                    <div class="form-group" style="margin: 0;">
                      <label style="font-size: 11px;">Effective Date</label>
                      <input v-model="kasCheckSettings.effectiveDate" type="text" class="imp-input" />
                    </div>
                    <div class="form-group" style="margin: 0;">
                      <label style="font-size: 11px;">Tiền tệ</label>
                      <input v-model="kasCheckSettings.currency" type="text" class="imp-input" />
                    </div>
                  </div>
                </div>
              </div>

              <!-- Cột phải: Bảng Pivot SKU x Band bóc tách từ ảnh -->
              <div class="imgcheck-right-col">
                <div class="pl-config-card" style="height: 100%; display: flex; flex-direction: column;">
                  <div class="pl-config-card__title" style="justify-content: space-between; flex-wrap: wrap; gap: 8px;">
                    <div style="display: flex; align-items: center; gap: 10px;">
                      <span>📋 Bảng giá Pivot bóc tách từ ảnh ({{ kasCheckRows.length }} dòng SKU × {{ kasCheckBands.length }} cột Band = {{ kasCheckRows.length * kasCheckBands.length }} mức giá)</span>
                    </div>
                    <button type="button" class="pl-mini-btn" @click="addKasCheckRow">+ Thêm dòng SKU</button>
                  </div>

                  <div class="import-table-wrap" style="max-height: 520px; border: 1px solid rgba(16, 185, 129, 0.25); border-radius: 10px;">
                    <table class="import-table">
                      <thead>
                        <tr style="background: #064e3b;">
                          <th style="width: 42px; text-align: center;">#</th>
                          <th style="min-width: 190px;">Product</th>
                          <th style="min-width: 90px;">Package</th>
                          <th style="min-width: 120px;">Type</th>
                          <th style="min-width: 85px;">Term</th>
                          <th style="min-width: 135px;">SKU</th>
                          <th v-for="band in kasCheckBands" :key="band" style="min-width: 135px; text-align: right; color: #6ee7b7;">
                            {{ band }}
                          </th>
                          <th style="width: 46px;"></th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr v-for="(row, rIdx) in kasCheckRows" :key="row.id || rIdx">
                          <td style="text-align: center; color: #64748b; font-weight: 600;">{{ rIdx + 1 }}</td>
                          <td>
                            <input v-model="row.product" type="text" class="imp-input" style="font-weight: 600;" />
                          </td>
                          <td>
                            <input v-model="row.package" type="text" class="imp-input" />
                          </td>
                          <td>
                            <input
                              v-model="row.type"
                              type="text"
                              class="imp-input"
                              :style="{ color: String(row.type).includes('Renewal') ? '#fbbf24' : '#34d399', fontWeight: '700' }"
                            />
                          </td>
                          <td>
                            <input v-model="row.term" type="text" class="imp-input" style="text-align: center;" />
                          </td>
                          <td>
                            <input v-model="row.sku" type="text" class="imp-input imp-input--code" style="font-weight: 700; color: #38bdf8;" />
                          </td>
                          <td v-for="band in kasCheckBands" :key="band">
                            <input
                              v-model.number="row.prices[band]"
                              type="number"
                              step="100"
                              class="imp-input imp-input--num"
                              style="font-weight: 700; color: #f8fafc;"
                            />
                          </td>
                          <td style="text-align: center;">
                            <button type="button" class="btn-icon text-danger" @click="kasCheckRows.splice(rIdx, 1)" title="Xóa dòng">✕</button>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>

                  <div style="margin-top: 12px; padding: 10px 14px; border-radius: 8px; background: rgba(16, 185, 129, 0.08); border: 1px solid rgba(16, 185, 129, 0.25); font-size: 12.5px; color: #cbd5e1; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px;">
                    <span>
                      💡 Trong Database <code>hang_hoa</code>, mỗi dòng SKU Kaspersky được tách theo từng cột <strong>Band</strong> (VD: <code>KL4066WA*F9 - Band M: 15-19 - Renewal Plus - 1 year - License</code>). Bấm <strong>Sang Bước 2</strong> để đối chiếu chi tiết toàn bộ {{ kasCheckRows.length * kasCheckBands.length }} mã!
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </template>

          <!-- ==================== BƯỚC 2: BẢNG ĐỐI CHIẾU 4 CHIỀU KASPERSKY ==================== -->
          <template v-else>
            <!-- 4 Card Thống kê -->
            <div class="compare-summary-grid" style="grid-template-columns: repeat(4, minmax(0, 1fr));">
              <div class="compare-stat-card compare-stat-card--goc">
                <div class="compare-stat-card__header">
                  <span>📗 So với filegocKas.xlsx (01/07/2026)</span>
                  <button
                    type="button"
                    class="excel-jump-pill excel-jump-pill--goc"
                    @click="openKasExcelNavigator({ fileType: 'kas_goc', sheet: 'SMB+Enterprise (License)', rowNum: 11, colLetter: 'I', sku: 'KL4066WA*F8', itemName: kasCheckSettings.product })"
                    title="Mở bảng Pivot SMB+Enterprise (License) của filegocKas.xlsx trong Tab mới"
                  >
                    🔍 Mở Sheet Pivot Gốc
                  </button>
                </div>
                <div class="compare-stat-card__Body">
                  <div class="stat-pill stat-pill--ok">
                    <strong>{{ kasComparisonSummary.gocMatch }}</strong> Khớp giá
                  </div>
                  <div class="stat-pill stat-pill--warn">
                    <strong>{{ kasComparisonSummary.gocDiff }}</strong> Lệch giá
                  </div>
                  <div class="stat-pill stat-pill--err">
                    <strong>{{ kasComparisonSummary.gocMissing }}</strong> Không thấy
                  </div>
                </div>
                <div class="compare-stat-card__sub">
                  Đối chiếu đồng thời trên sheet Pivot <code>SMB+Enterprise (License)</code> và <code>SaleListSMB+Enterprise</code> (6,514 dòng)
                </div>
              </div>

              <div class="compare-stat-card compare-stat-card--tg">
                <div class="compare-stat-card__header">
                  <span>📘 So với KASPERSKY_file_mau_import.xlsx</span>
                  <button
                    type="button"
                    class="excel-jump-pill excel-jump-pill--tg"
                    @click="openKasExcelNavigator({ fileType: 'kas_mau', sheet: 'SMB+Enterprise (License)', rowNum: 19, colLetter: 'I', sku: 'KL4066WA*F9', itemName: kasCheckSettings.product })"
                    title="Mở KASPERSKY_file_mau_import.xlsx trong Tab mới"
                  >
                    🔍 Mở File Mẫu Cũ
                  </button>
                </div>
                <div class="compare-stat-card__Body">
                  <div class="stat-pill stat-pill--ok">
                    <strong>{{ kasComparisonSummary.mauMatch }}</strong> Khớp giá
                  </div>
                  <div class="stat-pill stat-pill--warn">
                    <strong>{{ kasComparisonSummary.mauDiff }}</strong> Giá cũ (chưa +10%)
                  </div>
                  <div class="stat-pill stat-pill--err">
                    <strong>{{ kasComparisonSummary.mauMissingPivot }}</strong> Ẩn trên Pivot mẫu
                  </div>
                </div>
                <div class="compare-stat-card__sub">
                  File mẫu cũ đang để giá trước 01/07/2026 (thấp hơn 10%) và chỉ lọc <code>Renewal Plus</code> trên Pivot
                </div>
              </div>

              <div class="compare-stat-card compare-stat-card--db">
                <div class="compare-stat-card__header">
                  <span>🗄️ So với Database (Firebase hang_hoa)</span>
                  <span style="font-size: 11px; color: #94a3b8;">KASPERSKY</span>
                </div>
                <div class="compare-stat-card__Body">
                  <div class="stat-pill stat-pill--ok">
                    <strong>{{ kasComparisonSummary.dbMatch }}</strong> Khớp DB
                  </div>
                  <div class="stat-pill stat-pill--warn">
                    <strong>{{ kasComparisonSummary.dbDiff }}</strong> Lệch giá DB
                  </div>
                  <div class="stat-pill stat-pill--err">
                    <strong>{{ kasComparisonSummary.dbMissing }}</strong> Thiếu trong DB
                  </div>
                </div>
                <div class="compare-stat-card__sub">
                  Phát hiện <strong>{{ kasComparisonSummary.dbOldPre10Count }}</strong> mã trong DB đang lưu giá cũ trước khi tăng 10%
                </div>
              </div>

              <div class="compare-stat-card compare-stat-card--sync">
                <div class="compare-stat-card__header">
                  <span>⚡ Đồng bộ vào Database</span>
                  <button type="button" class="pl-mini-btn" @click="selectAllNeedSyncKasRows">
                    Chọn tất cả lệch/thiếu
                  </button>
                </div>
                <div style="font-size: 22px; font-weight: 800; color: #34d399; margin: 4px 0;">
                  {{ selectedKasComparisonRowsCount }} / {{ kasComparisonRows.length }} <span style="font-size: 12px; font-weight: 500; color: #94a3b8;">mục đã chọn</span>
                </div>
                <div class="compare-stat-card__sub">
                  Cập nhật giá mới (01/07/2026) cho <code>Renewal Plus</code> và bổ sung các mã <code>Base Plus</code> còn thiếu vào <code>hang_hoa</code>
                </div>
              </div>
            </div>

            <div v-if="vendorRefLoadError.kaspersky" style="margin-top: 10px; padding: 10px 14px; border-radius: 8px; background: rgba(239,68,68,0.15); border: 1px solid rgba(239,68,68,0.45); color: #fca5a5; font-size: 12.5px; font-weight: 700;">
              ⚠️ {{ vendorRefLoadError.kaspersky }}
            </div>

            <!-- Thanh thông tin File Cloudinary Kaspersky đang đối chiếu -->
            <div style="margin-top: 12px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; padding: 8px 14px; background: rgba(15, 23, 42, 0.8); border: 1px solid rgba(56, 189, 248, 0.25); border-radius: 8px;">
              <div style="font-size: 12px; color: #94a3b8; display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                <span>☁️ Đang đối chiếu theo Cloudinary:</span>
                <strong style="color: #34d399; display: inline-flex; align-items: center; gap: 5px;">
                  Gốc:
                  <template v-if="getVendorCompareFileMeta('kaspersky', 'goc')">
                    <a
                      :href="getVendorOfficeViewUrl(getVendorCompareFileMeta('kaspersky', 'goc'))"
                      target="_blank"
                      rel="noopener noreferrer"
                      style="color: #34d399; text-decoration: underline;"
                      title="Click để mở xem trên ViewOffice (Tab mới)"
                      @click="handleOpenVendorOfficeView($event, 'kaspersky', 'goc', getVendorCompareFileMeta('kaspersky', 'goc'))"
                    >{{ getVendorCompareFileMeta('kaspersky', 'goc').name }}</a>
                    <button
                      type="button"
                      class="vendor-file-office-btn"
                      title="Mở ViewOffice trong tab mới và nhảy tới sheet SMB+Enterprise (License)"
                      @click.stop="openCompareOfficePreview({ vendor: 'kaspersky', role: 'goc', sheet: 'SMB+Enterprise (License)', rowNum: 11, colLetter: 'I' })"
                    >👁️ Xem bằng ViewOffice</button>
                    <button
                      type="button"
                      class="vendor-file-download-btn"
                      title="Tải File Gốc Kaspersky về máy"
                      @click.stop="handleDownloadVendorUploadedFile('kaspersky', 'goc', getVendorCompareFileMeta('kaspersky', 'goc'))"
                    >⬇ Tải về</button>
                  </template>
                  <span v-else>Chưa có File Gốc</span>
                </strong>
                <span>·</span>
                <strong style="color: #38bdf8; display: inline-flex; align-items: center; gap: 5px;">
                  Trung gian:
                  <template v-if="getVendorCompareFileMeta('kaspersky', 'tg')">
                    <a
                      :href="getVendorOfficeViewUrl(getVendorCompareFileMeta('kaspersky', 'tg'))"
                      target="_blank"
                      rel="noopener noreferrer"
                      style="color: #38bdf8; text-decoration: underline;"
                      title="Click để mở xem trên ViewOffice (Tab mới)"
                      @click="handleOpenVendorOfficeView($event, 'kaspersky', 'mau', getVendorCompareFileMeta('kaspersky', 'tg'))"
                    >{{ getVendorCompareFileMeta('kaspersky', 'tg').name }}</a>
                    <button
                      type="button"
                      class="vendor-file-office-btn"
                      title="Mở ViewOffice trong tab mới và nhảy tới sheet SMB+Enterprise (License)"
                      @click.stop="openCompareOfficePreview({ vendor: 'kaspersky', role: 'mau', sheet: 'SMB+Enterprise (License)', rowNum: 11, colLetter: 'I' })"
                    >👁️ Xem bằng ViewOffice</button>
                    <button
                      type="button"
                      class="vendor-file-download-btn"
                      title="Tải File Trung Gian Kaspersky về máy"
                      @click.stop="handleDownloadVendorUploadedFile('kaspersky', 'mau', getVendorCompareFileMeta('kaspersky', 'tg'))"
                    >⬇ Tải về</button>
                  </template>
                  <span v-else>Chưa có File Trung Gian</span>
                </strong>
                <span v-if="vendorRefFilesMeta.kaspersky?.updated_at" style="color: #64748b;">
                  (Cập nhật: {{ formatRefTimestamp(vendorRefFilesMeta.kaspersky.updated_at) }})
                </span>
              </div>
              <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                <label class="pl-mini-btn" style="cursor: pointer; border-color: rgba(16, 185, 129, 0.45); color: #34d399;" title="Upload File Gốc Kaspersky mới lên Cloudinary">
                  <input type="file" accept=".xlsx,.xls" style="display: none;" @change="handleCustomKasExcelUpload($event, 'goc')" />
                  ☁️ Up File Gốc Kaspersky
                </label>
                <label class="pl-mini-btn" style="cursor: pointer; border-color: rgba(56, 189, 248, 0.45); color: #38bdf8;" title="Upload File Trung Gian Kaspersky mới lên Cloudinary">
                  <input type="file" accept=".xlsx,.xls" style="display: none;" @change="handleCustomKasExcelUpload($event, 'mau')" />
                  ☁️ Up File Trung Gian Kaspersky
                </label>
              </div>
            </div>

            <!-- Khung ViewOffice nhúng trực tiếp ngay trong Bảng Đối Chiếu Kaspersky -->
            <div v-if="compareOfficePreview.show && compareOfficePreview.vendor === 'kaspersky'" class="compare-office-embed-panel" style="margin-top: 10px;">
              <div class="compare-office-embed-header">
                <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                  <span style="font-weight: 800; color: #34d399;">👁️ Microsoft ViewOffice (Đối chiếu Kaspersky):</span>
                  <button
                    v-if="getVendorCompareFileMeta('kaspersky', 'goc')"
                    type="button"
                    class="compare-office-role-btn"
                    :class="{ active: compareOfficePreview.role === 'goc' }"
                    @click="openCompareOfficePreview({ vendor: 'kaspersky', role: 'goc', sheet: compareOfficePreview.sheet || 'SMB+Enterprise (License)', rowNum: compareOfficePreview.rowNum || 11, colLetter: compareOfficePreview.colLetter || 'I', sku: compareOfficePreview.sku })"
                  >📗 File Gốc ({{ getVendorCompareFileMeta('kaspersky', 'goc').name }})</button>
                  <button
                    v-if="getVendorCompareFileMeta('kaspersky', 'tg')"
                    type="button"
                    class="compare-office-role-btn"
                    :class="{ active: compareOfficePreview.role === 'mau' || compareOfficePreview.role === 'tg' }"
                    @click="openCompareOfficePreview({ vendor: 'kaspersky', role: 'mau', sheet: compareOfficePreview.sheet || 'SMB+Enterprise (License)', rowNum: compareOfficePreview.rowNum || 11, colLetter: compareOfficePreview.colLetter || 'I', sku: compareOfficePreview.sku })"
                  >📘 File Trung Gian ({{ getVendorCompareFileMeta('kaspersky', 'tg').name }})</button>
                  <span v-if="compareOfficePreview.sku" class="compare-office-target-badge">
                    SKU: <strong>{{ compareOfficePreview.sku }}</strong>
                  </span>
                  <span v-if="compareOfficePreview.sheet && compareOfficePreview.rowNum" class="compare-office-target-badge">
                    📍 Sheet <strong>{{ compareOfficePreview.sheet }}</strong> • Ô {{ compareOfficePreview.colLetter }}{{ compareOfficePreview.rowNum }} (Dòng {{ compareOfficePreview.rowNum }})
                  </span>
                  <span v-if="compareOfficePreview.copiedLabel" style="color: #34d399; font-weight: 700; font-size: 11.5px;">
                    ✓ {{ compareOfficePreview.copiedLabel }} (Bấm Ctrl+F → Ctrl+V trong bảng để tìm nhanh)
                  </span>
                </div>
                <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
                  <button
                    v-if="compareOfficePreview.sku"
                    type="button"
                    class="vendor-file-office-btn"
                    @click="copyCompareOfficeQuickText(compareOfficePreview.sku, `Đã copy SKU: ${compareOfficePreview.sku}`)"
                  >📋 Copy SKU</button>
                  <a
                    v-if="compareOfficePreview.viewUrl"
                    :href="compareOfficePreview.viewUrl"
                    target="_blank"
                    rel="noopener noreferrer"
                    class="vendor-file-office-btn"
                    style="text-decoration: none;"
                  >🌐 Mở Tab Mới</a>
                  <button
                    type="button"
                    class="vendor-file-download-btn"
                    @click="handleDownloadVendorUploadedFile('kaspersky', compareOfficePreview.role, getVendorCompareFileMeta('kaspersky', compareOfficePreview.role === 'goc' ? 'goc' : 'tg'))"
                  >⬇ Tải về</button>
                  <button type="button" class="compare-office-close-btn" @click="closeCompareOfficePreview">✕ Đóng ViewOffice</button>
                </div>
              </div>
              <div class="compare-office-embed-body">
                <div v-if="compareOfficePreview.loading" class="compare-office-loading">
                  ⏳ Đang chuẩn bị file Excel trên Microsoft ViewOffice...
                </div>
                <iframe
                  v-else-if="compareOfficePreview.embedUrl"
                  :src="compareOfficePreview.embedUrl"
                  class="compare-office-iframe"
                  allowfullscreen
                ></iframe>
              </div>
            </div>

            <!-- Thanh bộ lọc Band & Trạng thái -->
            <div class="compare-toolbar" style="margin-top: 10px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px;">
              <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
                <span style="font-size: 12px; color: #94a3b8; font-weight: 600;">Lọc trạng thái:</span>
                <button type="button" class="cmp-filter-btn" :class="{ active: kasCompareFilterMode === 'all' }" @click="kasCompareFilterMode = 'all'">
                  Tất cả ({{ kasComparisonRows.length }})
                </button>
                <button type="button" class="cmp-filter-btn" :class="{ active: kasCompareFilterMode === 'db_issue' }" @click="kasCompareFilterMode = 'db_issue'">
                  ⚠️ Cần xử lý DB ({{ kasComparisonSummary.dbDiff + kasComparisonSummary.dbMissing }})
                </button>
                <button type="button" class="cmp-filter-btn" :class="{ active: kasCompareFilterMode === 'db_diff' }" @click="kasCompareFilterMode = 'db_diff'">
                  🟡 Lệch giá DB ({{ kasComparisonSummary.dbDiff }})
                </button>
                <button type="button" class="cmp-filter-btn" :class="{ active: kasCompareFilterMode === 'db_missing' }" @click="kasCompareFilterMode = 'db_missing'">
                  🔴 Thiếu trong DB ({{ kasComparisonSummary.dbMissing }})
                </button>
              </div>

              <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
                <span style="font-size: 12px; color: #94a3b8; font-weight: 600;">Lọc theo Band:</span>
                <button type="button" class="cmp-filter-btn" :class="{ active: kasCompareBandFilter === 'ALL' }" @click="kasCompareBandFilter = 'ALL'">
                  Tất cả Band
                </button>
                <button
                  v-for="band in kasCheckBands"
                  :key="band"
                  type="button"
                  class="cmp-filter-btn"
                  :class="{ active: kasCompareBandFilter === band }"
                  @click="kasCompareBandFilter = band"
                >
                  {{ band }}
                </button>
              </div>
            </div>

            <!-- Bảng kết quả đối chiếu 4 chiều -->
            <div class="import-table-wrap" style="margin-top: 12px; max-height: 54vh; border: 1px solid rgba(148, 163, 184, 0.2); border-radius: 10px;">
              <table class="import-table">
                <thead>
                  <tr>
                    <th style="width: 42px; text-align: center;">
                      <input
                        type="checkbox"
                        :checked="allFilteredKasCompareSelected"
                        @change="toggleSelectAllFilteredKasCompare($event.target.checked)"
                      />
                    </th>
                    <th style="width: 42px; text-align: center;">#</th>
                    <th style="min-width: 240px;">Sản phẩm / Type / Term / Band</th>
                    <th style="min-width: 145px;">SKU &amp; PositionCode</th>
                    <th style="min-width: 140px; text-align: right;">Giá trên Ảnh (VND)</th>
                    <th style="min-width: 210px; text-align: right;">filegocKas.xlsx (01/07/2026)</th>
                    <th style="min-width: 210px; text-align: right;">KASPERSKY_file_mau_import</th>
                    <th style="min-width: 220px;">Sản phẩm trong Database</th>
                    <th style="min-width: 140px; text-align: right;">Giá Database</th>
                    <th style="min-width: 170px;">Trạng thái Đối chiếu DB</th>
                    <th style="min-width: 135px; text-align: center;">Thao tác</th>
                  </tr>
                </thead>
                <tbody>
                  <tr
                    v-for="(item, idx) in filteredKasComparisonRows"
                    :key="item.id"
                    :class="{
                      'cmp-row--diff': item.dbStatus === 'diff',
                      'cmp-row--missing': item.dbStatus === 'missing'
                    }"
                  >
                    <td style="text-align: center;">
                      <input type="checkbox" v-model="item.selected" />
                    </td>
                    <td style="text-align: center; color: #64748b; font-weight: 600;">{{ idx + 1 }}</td>

                    <!-- Sản phẩm / Type / Term / Band -->
                    <td>
                      <div style="font-weight: 700; color: #f8fafc; font-size: 13px;">{{ item.product }}</div>
                      <div style="display: flex; gap: 6px; align-items: center; flex-wrap: wrap; margin-top: 4px;">
                        <span
                          :style="{
                            fontSize: '10.5px',
                            fontWeight: '700',
                            padding: '1px 7px',
                            borderRadius: '999px',
                            background: item.type.includes('Renewal') ? 'rgba(245, 158, 11, 0.16)' : 'rgba(16, 185, 129, 0.16)',
                            color: item.type.includes('Renewal') ? '#fbbf24' : '#34d399',
                            border: item.type.includes('Renewal') ? '1px solid rgba(245, 158, 11, 0.35)' : '1px solid rgba(16, 185, 129, 0.35)'
                          }"
                        >
                          {{ item.type }}
                        </span>
                        <span style="font-size: 11px; color: #38bdf8; font-weight: 700; background: rgba(56, 189, 248, 0.12); padding: 1px 7px; border-radius: 6px;">
                          {{ item.term }}
                        </span>
                        <span style="font-size: 11px; color: #e2e8f0; font-weight: 600; background: rgba(255, 255, 255, 0.08); padding: 1px 7px; border-radius: 6px;">
                          {{ item.band }}
                        </span>
                      </div>
                    </td>

                    <!-- SKU & PositionCode -->
                    <td style="font-family: monospace;">
                      <div style="display: flex; flex-direction: column; gap: 4px; align-items: flex-start;">
                        <button
                          type="button"
                          class="sku-code-pill sku-code-pill--clickable"
                          @click="openKasExcelNavigator({ fileType: 'kas_goc', sheet: 'SMB+Enterprise (License)', rowNum: item.gocPivotRow || 11, colLetter: item.gocPivotColLetter || 'I', sku: item.sku, band: item.band, itemName: `${item.product} (${item.band})` })"
                          title="Click để mở filegocKas.xlsx (Sheet SMB+Enterprise (License)) tại dòng của SKU này"
                        >
                          <span>{{ item.sku }}</span>
                          <span class="sku-jump-icon">↗</span>
                        </button>
                        <span v-if="item.posCode" style="font-size: 11px; color: #94a3b8;" title="PositionCode trong sheet SaleListSMB+Enterprise">
                          Full SKU: <strong style="color: #cbd5e1;">{{ item.posCode }}</strong>
                        </span>
                      </div>
                    </td>

                    <!-- Giá trên Ảnh -->
                    <td style="text-align: right; font-family: monospace;">
                      <div style="font-size: 13.5px; font-weight: 700; color: #f8fafc;">
                        {{ formatVndPrice(item.imgPrice) }}
                      </div>
                    </td>

                    <!-- filegocKas.xlsx -->
                    <td style="text-align: right; font-family: monospace;">
                      <template v-if="item.gocFound">
                        <div style="font-size: 13.5px; font-weight: 700;" :style="{ color: item.gocStatus === 'match' ? '#34d399' : '#f87171' }">
                          {{ formatVndPrice(item.gocPrice) }}
                        </div>
                        <div style="font-size: 11px; margin-top: 2px;">
                          <span v-if="item.gocStatus === 'match'" style="color: #34d399;">✓ Khớp 100% filegocKas</span>
                          <span v-else style="color: #f87171;">Lệch: {{ formatVndPrice(item.imgPrice - item.gocPrice) }}</span>
                        </div>
                        <div style="margin-top: 4px; display: flex; gap: 4px; justify-content: flex-end; flex-wrap: wrap;">
                          <button
                            v-if="item.gocPivotRow"
                            type="button"
                            class="excel-jump-pill excel-jump-pill--goc"
                            @click="openKasExcelNavigator({ fileType: 'kas_goc', sheet: 'SMB+Enterprise (License)', rowNum: item.gocPivotRow, colLetter: item.gocPivotColLetter || 'I', sku: item.sku, band: item.band, itemName: `${item.product} (${item.band})` })"
                            title="Nhảy tới dòng trên sheet Pivot SMB+Enterprise (License) của filegocKas.xlsx"
                          >
                            📍 Pivot • Dòng {{ item.gocPivotRow }}
                          </button>
                          <button
                            v-if="item.gocSaleRow"
                            type="button"
                            class="excel-jump-pill excel-jump-pill--fw"
                            @click="openKasExcelNavigator({ fileType: 'kas_goc', sheet: 'SaleListSMB+Enterprise', rowNum: item.gocSaleRow, colLetter: 'M', sku: item.sku, band: item.band, itemName: `${item.product} (${item.band})` })"
                            title="Nhảy tới dòng chi tiết trên sheet SaleListSMB+Enterprise của filegocKas.xlsx"
                          >
                            📍 SaleList • Dòng {{ item.gocSaleRow }}
                          </button>
                          <button
                            v-if="item.gocPivotRow || item.gocSaleRow"
                            type="button"
                            class="vendor-file-office-btn"
                            style="padding: 2px 7px; font-size: 10.5px;"
                            @click="openCompareOfficePreview({ vendor: 'kaspersky', role: 'goc', sheet: item.gocPivotRow ? 'SMB+Enterprise (License)' : 'SaleListSMB+Enterprise', rowNum: item.gocPivotRow || item.gocSaleRow, colLetter: item.gocPivotRow ? (item.gocPivotColLetter || 'I') : 'M', sku: item.sku, itemName: `${item.product} (${item.band})` })"
                            :title="`Mở ViewOffice trong tab mới và nhảy trực tiếp tới ô ${item.gocPivotRow ? (item.gocPivotColLetter || 'I') + item.gocPivotRow : 'M' + item.gocSaleRow}`"
                          >
                            👁️ Xem bằng ViewOffice
                          </button>
                        </div>
                      </template>
                      <template v-else>
                        <span class="cmp-badge cmp-badge--missing">Không tìm thấy</span>
                      </template>
                    </td>

                    <!-- KASPERSKY_file_mau_import.xlsx -->
                    <td style="text-align: right; font-family: monospace;">
                      <template v-if="item.mauPrice > 0">
                        <div style="font-size: 13.5px; font-weight: 700;" :style="{ color: item.mauStatus === 'match' ? '#38bdf8' : '#fbbf24' }">
                          {{ formatVndPrice(item.mauPrice) }}
                        </div>
                        <div style="font-size: 11px; color: #fbbf24; margin-top: 2px;">
                          <span v-if="item.mauIsOldPre10">⚠️ Giá cũ chưa +10%</span>
                          <span v-else-if="!item.mauPivotRow">Ẩn trên Pivot mẫu (Có ở SaleList)</span>
                        </div>
                        <div style="margin-top: 4px; display: flex; gap: 4px; justify-content: flex-end; flex-wrap: wrap;">
                          <button
                            v-if="item.mauPivotRow"
                            type="button"
                            class="excel-jump-pill excel-jump-pill--tg"
                            @click="openKasExcelNavigator({ fileType: 'kas_mau', sheet: 'SMB+Enterprise (License)', rowNum: item.mauPivotRow, colLetter: 'I', sku: item.sku, band: item.band, itemName: `${item.product} (${item.band})` })"
                          >
                            📍 Pivot Mẫu • Dòng {{ item.mauPivotRow }}
                          </button>
                          <button
                            v-if="item.mauSaleRow"
                            type="button"
                            class="excel-jump-pill excel-jump-pill--lp"
                            @click="openKasExcelNavigator({ fileType: 'kas_mau', sheet: 'SaleListSMB+Enterprise', rowNum: item.mauSaleRow, colLetter: 'M', sku: item.sku, band: item.band, itemName: `${item.product} (${item.band})` })"
                          >
                            📍 SaleList Mẫu • Dòng {{ item.mauSaleRow }}
                          </button>
                          <button
                            v-if="item.mauPivotRow || item.mauSaleRow"
                            type="button"
                            class="vendor-file-office-btn"
                            style="padding: 2px 7px; font-size: 10.5px;"
                            @click="openCompareOfficePreview({ vendor: 'kaspersky', role: 'mau', sheet: item.mauPivotRow ? 'SMB+Enterprise (License)' : 'SaleListSMB+Enterprise', rowNum: item.mauPivotRow || item.mauSaleRow, colLetter: item.mauPivotRow ? 'I' : 'M', sku: item.sku, itemName: `${item.product} (${item.band})` })"
                            :title="`Mở ViewOffice trong tab mới và nhảy trực tiếp tới ô ${item.mauPivotRow ? 'I' + item.mauPivotRow : 'M' + item.mauSaleRow}`"
                          >
                            👁️ Xem bằng ViewOffice
                          </button>
                        </div>
                      </template>
                      <template v-else>
                        <span class="cmp-badge cmp-badge--missing">Chưa có</span>
                      </template>
                    </td>

                    <!-- Sản phẩm trong Database -->
                    <td>
                      <template v-if="item.dbItem">
                        <div style="font-weight: 600; color: #e2e8f0; font-size: 12.5px;">{{ item.dbItem.Ten_hang }}</div>
                        <div style="font-size: 11px; color: #64748b; font-family: monospace; margin-top: 2px;">
                          Mã DB: {{ item.dbItem.Ma_hang }}
                        </div>
                      </template>
                      <template v-else>
                        <span style="color: #f87171; font-size: 12px; font-weight: 600;">
                          Chưa có mã {{ item.type }} ({{ item.term }} - {{ item.band }}) trong DB
                        </span>
                      </template>
                    </td>

                    <!-- Giá Database -->
                    <td style="text-align: right; font-family: monospace;">
                      <template v-if="item.dbItem">
                        <div style="font-size: 13.5px; font-weight: 700;" :style="{ color: item.dbStatus === 'match' ? '#34d399' : '#fbbf24' }">
                          {{ formatVndPrice(item.dbPrice) }}
                        </div>
                        <div style="font-size: 11px; color: #94a3b8; margin-top: 2px;">
                          {{ item.dbItem.Don_vi_tien_te || 'VND' }}
                        </div>
                      </template>
                      <template v-else>
                        <span style="color: #64748b;">—</span>
                      </template>
                    </td>

                    <!-- Trạng thái Đối chiếu DB -->
                    <td>
                      <div v-if="item.dbStatus === 'match'" class="cmp-badge cmp-badge--match">
                        🟢 Khớp giá DB
                      </div>
                      <div v-else-if="item.dbStatus === 'diff'">
                        <span class="cmp-badge cmp-badge--diff">
                          🟡 Lệch {{ item.dbDiff > 0 ? '+' : '' }}{{ formatVndPrice(item.dbDiff) }} ({{ item.dbDiffPct > 0 ? '+' : '' }}{{ item.dbDiffPct.toFixed(1) }}%)
                        </span>
                        <div v-if="item.isOldPre10Pct" style="font-size: 11px; color: #fcd34d; margin-top: 3px;">
                          DB đang lưu giá cũ (chưa +10%)
                        </div>
                      </div>
                      <div v-else>
                        <span class="cmp-badge cmp-badge--missing">
                          🔴 Thiếu trong DB
                        </span>
                      </div>
                    </td>

                    <!-- Thao tác -->
                    <td style="text-align: center;">
                      <button
                        v-if="item.dbStatus === 'diff'"
                        type="button"
                        class="cmp-action-btn cmp-action-btn--update"
                        :disabled="syncingKasCompareToDb"
                        @click="syncSingleKasCompareRowToDb(item)"
                      >
                        🔄 Cập nhật giá
                      </button>
                      <button
                        v-else-if="item.dbStatus === 'missing'"
                        type="button"
                        class="cmp-action-btn cmp-action-btn--add"
                        :disabled="syncingKasCompareToDb"
                        @click="syncSingleKasCompareRowToDb(item)"
                      >
                        + Thêm vào DB
                      </button>
                      <span v-else style="font-size: 12px; color: #34d399; font-weight: 600;">
                        ✓ Đã chuẩn
                      </span>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </template>
        </div>

        <!-- Footer -->
        <div class="import-modal__footer" style="justify-content: space-between;">
          <div style="display: flex; align-items: center; gap: 18px; font-size: 13px; color: #94a3b8; flex-wrap: wrap;">
            <span>Product: <strong style="color: #34d399;">{{ kasCheckSettings.product || '-' }}</strong></span>
            <span>Code: <strong style="color: #fbbf24;">{{ kasCheckSettings.code || '-' }}</strong></span>
            <span>Effective: <strong style="color: #e2e8f0;">{{ kasCheckSettings.effectiveDate || '-' }}</strong></span>
            <span>Tổng mức giá (SKU × Band): <strong style="color: #38bdf8; font-size: 15px;">{{ kasCheckRows.length * kasCheckBands.length }}</strong></span>
          </div>

          <div v-if="kasCheckActiveStep === 1" style="display: flex; gap: 10px; align-items: center; flex-wrap: wrap;">
            <button type="button" class="btn btn-secondary" @click="closeKasImageCheckModal">Đóng</button>
            <button
              v-if="kasCheckPreviewUrl && !kasCheckScanning"
              type="button"
              class="btn btn-outline"
              style="border-color: rgba(16, 185, 129, 0.4); color: #34d399;"
              @click="resetKasImageCheckModal"
            >
              Quét ảnh khác
            </button>
            <button
              v-if="kasCheckRows.length > 0 && !kasCheckScanning"
              type="button"
              class="btn import-btn-save"
              style="background: linear-gradient(135deg, #10b981, #059669);"
              @click="runKasPriceComparison"
            >
              <span>🔍 Sang Bước 2: Đối Chiếu Giá ({{ kasCheckRows.length * kasCheckBands.length }} mã) →</span>
            </button>
          </div>

          <div v-else style="display: flex; gap: 10px; align-items: center; flex-wrap: wrap;">
            <button type="button" class="btn btn-secondary" @click="kasCheckActiveStep = 1">
              ← Quay lại Bước 1
            </button>
            <button
              type="button"
              class="btn btn-outline"
              style="border-color: rgba(16, 185, 129, 0.4); color: #34d399;"
              @click="exportKasComparisonToExcel"
            >
              📊 Xuất Excel Đối Chiếu KAS
            </button>
            <button
              type="button"
              class="btn import-btn-save"
              style="background: linear-gradient(135deg, #10b981, #059669);"
              :disabled="syncingKasCompareToDb || selectedKasComparisonRowsCount === 0"
              @click="syncSelectedKasCompareRowsToDb"
            >
              <span v-if="syncingKasCompareToDb" class="spinner"></span>
              <span>⚡ Đồng bộ {{ selectedKasComparisonRowsCount }} mục đã chọn vào Database</span>
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- MODAL PHÓNG TO ẢNH CHECK KASPERSKY -->
    <div v-if="kasCheckZoomModal && kasCheckPreviewUrl" class="import-overlay" style="z-index: 10150;" @click="kasCheckZoomModal = false">
      <div style="position: relative; max-width: 95vw; max-height: 92vh; display: flex; flex-direction: column; align-items: center;">
        <button
          type="button"
          class="import-modal__close"
          style="position: absolute; top: -14px; right: -14px; background: #0f172a; border: 1px solid rgba(255,255,255,0.2); z-index: 2;"
          @click.stop="kasCheckZoomModal = false"
        >✕</button>
        <img :src="kasCheckPreviewUrl" style="max-width: 95vw; max-height: 90vh; object-fit: contain; border-radius: 10px; box-shadow: 0 20px 60px rgba(0,0,0,0.85);" @click.stop />
      </div>
    </div>

    <!-- MODAL TRÌNH XEM & ĐỊNH VỊ DÒNG EXCEL (file_goc_SOPHOS & file_trung_gian_SOPHOS) -->
    <div v-if="showExcelNavModal" class="import-overlay" style="z-index: 10500;" @click.self="showExcelNavModal = false">
      <div class="import-modal excel-nav-modal">
        <!-- Header -->
        <div class="excel-nav-header">
          <div style="display: flex; align-items: center; gap: 12px; flex-wrap: wrap;">
            <div class="excel-nav-file-switcher">
              <button
                type="button"
                class="excel-nav-file-btn"
                :class="{ active: excelNavState.fileType === 'calc' }"
                @click="switchExcelNavFileType('calc')"
              >
                🧮 calculate_sophos.xlsx
              </button>
              <button
                type="button"
                class="excel-nav-file-btn"
                :class="{ active: excelNavState.fileType === 'goc' }"
                @click="switchExcelNavFileType('goc')"
              >
                📗 file_goc_SOPHOS.xlsx
              </button>
              <button
                type="button"
                class="excel-nav-file-btn"
                :class="{ active: excelNavState.fileType === 'tg' }"
                @click="switchExcelNavFileType('tg')"
              >
                📘 file_trung_gian_SOPHOS.xlsx
              </button>
            </div>

            <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
              <span class="excel-nav-sku-pill">
                SKU: <strong>{{ excelNavState.sku || '—' }}</strong>
              </span>
              <span v-if="excelNavState.itemName" style="font-size: 12.5px; color: #cbd5e1; font-weight: 600;">
                {{ excelNavState.itemName }}
              </span>
              <span class="excel-nav-coord-pill">
                📍 {{ excelNavCurrentRef }} (Dòng {{ excelNavState.targetRow }})
              </span>
            </div>
          </div>

          <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
            <button
              type="button"
              class="excel-nav-action-btn excel-nav-action-btn--copy"
              @click="copyExcelCoordToClipboard(excelNavFullRowRef)"
              title="Copy tọa độ nguyên dòng ('Sheet'!Dòng:Dòng) để khi bấm Ctrl+G -> Ctrl+V trong Excel sẽ bôi sáng toàn bộ dòng đó"
            >
              <span>{{ excelNavCopied ? '✓ Đã copy tọa độ cả dòng!' : `📋 Copy cả dòng (${excelNavFullRowRef})` }}</span>
            </button>
            <button
              type="button"
              class="excel-nav-action-btn"
              @click="scrollToExcelTargetRow"
              title="Cuộn màn hình lại đúng dòng đang định vị"
            >
              🎯 Tới Dòng #{{ excelNavState.targetRow }}
            </button>
            <button
              type="button"
              class="excel-nav-action-btn excel-nav-action-btn--excel"
              @click="openInDesktopExcel(excelNavState.fileType)"
              title="Gọi phần mềm Microsoft Excel trên máy tính mở file này và tự copy tọa độ dòng vào Clipboard"
            >
              📗 Mở App Excel Desktop
            </button>
            <button
              type="button"
              class="excel-nav-action-btn"
              title="Tải file .xlsx về máy"
              @click="handleDownloadVendorUploadedFile('sophos', excelNavState.fileType === 'calc' ? 'calc' : (excelNavState.fileType === 'tg' ? 'tg' : 'goc'), getVendorCompareFileMeta('sophos', excelNavState.fileType === 'calc' ? 'calc' : (excelNavState.fileType === 'tg' ? 'tg' : 'goc')) || { name: excelNavState.fileType === 'calc' ? 'calculate_sophos.xlsx' : (excelNavState.fileType === 'goc' ? 'file_goc_SOPHOS.xlsx' : 'file_trung_gian_SOPHOS.xlsx'), url: '' })"
            >
              ⬇️ Tải .xlsx
            </button>
            <button type="button" class="import-modal__close" @click="showExcelNavModal = false">✕</button>
          </div>
        </div>

        <!-- Thanh nhảy nhanh giữa tất cả các vị trí xuất hiện của SKU / Model này trong các file -->
        <div v-if="excelNavAllLocationsForSku.length > 0" class="excel-nav-locations-bar">
          <span style="font-size: 11.5px; color: #94a3b8; font-weight: 700; white-space: nowrap;">
            ⚡ Các vị trí của mã này:
          </span>
          <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
            <button
              v-for="(loc, idx) in excelNavAllLocationsForSku"
              :key="idx"
              type="button"
              class="excel-nav-loc-pill"
              :class="{
                active: excelNavState.fileType === loc.fileType && excelNavState.sheet === loc.sheet && excelNavState.targetRow === loc.rowNum,
                'loc-calc': loc.fileType === 'calc',
                'loc-goc': loc.fileType === 'goc',
                'loc-tg': loc.fileType === 'tg'
              }"
              @click="openExcelNavigator(loc)"
            >
              <span>{{ loc.fileType === 'calc' ? '🧮 Calculator' : (loc.fileType === 'goc' ? '📗 File Gốc' : '📘 File TG') }}:</span>
              <strong>{{ loc.sheet }}</strong>
              <span class="loc-cell">{{ loc.colLetter }}{{ loc.rowNum }} (Dòng {{ loc.rowNum }})</span>
            </button>
          </div>
        </div>

        <!-- Thanh Formula Bar chuẩn Excel (Name Box + fx + Tìm kiếm nhanh trong sheet) -->
        <div class="excel-nav-formulabar">
          <div class="excel-nav-namebox" title="Địa chỉ ô đang chọn trong Sheet">
            {{ excelNavState.colLetter || 'B' }}{{ excelNavState.targetRow || 1 }}
          </div>
          <div class="excel-nav-fx">fx</div>
          <div class="excel-nav-formulavalue">
            {{ excelNavSelectedCellText }}
          </div>
          <div class="excel-nav-searchwrap">
            <input
              type="text"
              v-model="excelNavSearchQuery"
              @keydown.enter.prevent="findAndJumpInCurrentExcelSheet"
              placeholder="Tìm SKU / Model hoặc nhập số dòng rồi Enter..."
              class="excel-nav-searchinput"
            />
            <button type="button" class="excel-nav-searchbtn" @click="findAndJumpInCurrentExcelSheet">
              Tìm &amp; Nhảy
            </button>
          </div>
        </div>

        <!-- Bảng Grid Excel (Cột A, B, C... & Số Dòng thực tế 1, 2, 3...) -->
        <div ref="excelNavGridWrapRef" class="excel-nav-grid-wrap">
          <div
            v-if="(excelNavState.fileType === 'goc' || excelNavState.fileType === 'calc') && excelNavState.sheet === 'MSRPs&BuyCost'"
            class="excel-nav-window-banner"
          >
            <span>
              Đang hiển thị vùng dữ liệu quanh <strong>Dòng #{{ excelNavState.targetRow }}</strong> (từ dòng {{ excelNavRenderedRows[1]?.rowNum || 3 }} đến {{ excelNavRenderedRows[excelNavRenderedRows.length - 1]?.rowNum || 3 }} của sheet <code>MSRPs&amp;BuyCost</code>).
            </span>
            <div style="display: flex; gap: 6px;">
              <button type="button" class="pl-mini-btn" @click="excelNavWindowRadius += 60">
                + Mở rộng thêm ±60 dòng lân cận
              </button>
            </div>
          </div>

          <table class="excel-nav-table">
            <thead>
              <tr>
                <th class="excel-col-corner">#</th>
                <th
                  v-for="(colLet, cIdx) in excelNavColLetters"
                  :key="colLet"
                  :class="{ 'excel-col-active': colLet === excelNavState.colLetter }"
                >
                  {{ colLet }}
                </th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="rObj in excelNavRenderedRows"
                :key="rObj.rowNum"
                :id="'excel-nav-row-' + rObj.rowNum"
                :class="{
                  'excel-row-target': rObj.rowNum === excelNavState.targetRow,
                  'excel-row-header': rObj.isHeader,
                  'excel-row-group': rObj.isGroup
                }"
                @click="selectExcelRowAndCell(rObj.rowNum, excelNavState.colIndex, rObj.cells)"
              >
                <td class="excel-row-num">
                  <span v-if="rObj.rowNum === excelNavState.targetRow" class="excel-target-arrow">▶</span>
                  {{ rObj.rowNum }}
                </td>
                <td
                  v-for="(colLet, cIdx) in excelNavColLetters"
                  :key="colLet"
                  :class="{
                    'excel-cell-target': rObj.rowNum === excelNavState.targetRow && cIdx === excelNavState.colIndex,
                    'excel-cell-num': isNumericOrMoneyExcelCell(rObj.cells[cIdx]),
                    'excel-cell-sku': isSkuLikeCell(rObj.cells[cIdx], excelNavState.sku)
                  }"
                  @click.stop="selectExcelRowAndCell(rObj.rowNum, cIdx, rObj.cells)"
                >
                  <div class="excel-cell-inner">{{ formatExcelCellValue(rObj.cells[cIdx], rObj.rowNum, cIdx, rObj.cells) }}</div>
                </td>
              </tr>
            </tbody>
          </table>
        </div>

        <!-- Thanh Sheet Tabs dưới đáy giống hệt Microsoft Excel -->
        <div class="excel-nav-sheetbar">
          <div class="excel-nav-sheettabs">
            <button
              v-for="sh in excelNavSheetNames"
              :key="sh"
              type="button"
              class="excel-nav-sheettab"
              :class="{
                active: excelNavState.sheet === sh,
                'has-sku': sheetContainsCurrentSku(sh)
              }"
              @click="switchExcelNavSheet(sh)"
            >
              <span v-if="sheetContainsCurrentSku(sh)" class="sheet-sku-dot" title="Sheet này có chứa mã SKU / Model đang tra cứu"></span>
              <span>{{ sh }}</span>
            </button>
            <button
              v-if="excelNavState.fileType === 'calc'"
              type="button"
              class="excel-nav-sheettab"
              style="margin-left: 6px; border-style: dashed; opacity: 0.85; font-size: 11px;"
              @click="showCalcHiddenSheets = !showCalcHiddenSheets; if (!showCalcHiddenSheets && excelNavState.sheet === 'MSRPs&BuyCost') switchExcelNavSheet('Firewall')"
              title="Trong calculate_sophos.xlsx gốc, bảng MSRPs&BuyCost được ẩn (Hidden). Bấm để hiện/ẩn khi cần dò dữ liệu thô."
            >
              {{ showCalcHiddenSheets ? '🙈 Ẩn sheet nguồn MSRPs&BuyCost' : '👁️ Hiện sheet ẩn (MSRPs&BuyCost)' }}
            </button>
          </div>
          <div class="excel-nav-statusbar">
            <span>Mẹo: Bấm <strong>Ctrl + G</strong> rồi <strong>Ctrl + V</strong> trong phần mềm Excel để nhảy &amp; bôi sáng toàn bộ dòng <code>{{ excelNavFullRowRef }}</code> (ô SKU: <code>{{ excelNavCurrentRef }}</code>)</span>
          </div>
        </div>
      </div>
    </div>

    <!-- MODAL ĐỐI CHIẾU FILE GỐC & CALCULATOR TRÊN TỪNG HÀNG HÓA (CHUẨN TEMPLATE DUAL-THEME) -->
    <div
      v-if="showCardRefCompareModal"
      class="qlhh-modal-backdrop qlhh-cmp-overlay"
      :class="{ 'theme-light-blue': uiTheme === 'light' }"
      @click.self="showCardRefCompareModal = false"
    >
      <div class="qlhh-fm-modal qlhh-cmp-modal" :class="{ 'theme-light-blue': uiTheme === 'light' }">
        <!-- Sticky Template Header -->
        <header class="qlhh-fm-head qlhh-cmp-head">
          <div class="qlhh-fm-head-left">
            <span
              class="qlhh-fm-head-ico"
              :class="cardRefCompareData?.vendor === 'sophos' ? 'is-sky' : (cardRefCompareData?.vendor === 'acronis' ? 'is-violet' : 'is-emerald')"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/></svg>
            </span>

            <div class="qlhh-fm-title-block">
              <div class="qlhh-fm-title-row">
                <span
                  class="qlhh-cmp-vendor-tag"
                  :class="`is-${cardRefCompareData?.vendor || 'sophos'}`"
                >
                  {{ (cardRefCompareData?.vendor || 'FILE GỐC').toUpperCase() }}
                </span>
                <h2>{{ cardRefCompareData?.item?.Ten_hang || 'Đối chiếu File Gốc' }}</h2>
                <span
                  v-if="cardRefCompareData?.sku || cardRefCompareData?.item?.Ma_hang"
                  class="qlhh-code-pill is-sku tabular-nums"
                >
                  {{ cardRefCompareData?.sku || cardRefCompareData?.item?.Ma_hang }}
                </span>
              </div>

              <div class="qlhh-cmp-subline tabular-nums">
                <span>{{ cardRefCompareData?.vendor === 'sophos' ? 'Đối chiếu Calculator & File Gốc' : 'Đối chiếu File Gốc Hãng' }}</span>
                <template v-if="cardRefCompareData?.vendor && vendorRefFilesMeta[cardRefCompareData.vendor]?.updated_at">
                  <span>·</span>
                  <span>Cập nhật: <strong>{{ formatRefTimestamp(vendorRefFilesMeta[cardRefCompareData.vendor].updated_at) }}</strong></span>
                </template>
              </div>
            </div>
          </div>

          <div class="qlhh-fm-head-right">
            <span
              v-if="cardRefCompareData && !cardRefCompareLoading"
              class="qlhh-cmp-status-pill tabular-nums"
              :class="cardRefCompareData.status === 'match' ? 'is-match' : (cardRefCompareData.status === 'diff' ? 'is-diff' : 'is-miss')"
            >
              <svg v-if="cardRefCompareData.status === 'match'" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
              <svg v-else-if="cardRefCompareData.status === 'diff'" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
              <svg v-else width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
              <span v-if="cardRefCompareData.status === 'match'">Khớp giá</span>
              <span v-else-if="cardRefCompareData.status === 'diff'">
                Lệch {{ cardRefCompareData.priceDiff > 0 ? '+' : '' }}{{ cardRefCompareData.vendor === 'sophos' ? formatUsdPrice(cardRefCompareData.priceDiff) : formatVndPrice(cardRefCompareData.priceDiff) }}
              </span>
              <span v-else>Chưa khớp SKU</span>
            </span>

            <button
              type="button"
              class="qlhh-fm-close"
              @click="showCardRefCompareModal = false"
              aria-label="Đóng"
            >✕</button>
          </div>
        </header>

        <!-- Scrollable Body -->
        <div class="qlhh-fm-body qlhh-cmp-body">
          <!-- Loading -->
          <div v-if="cardRefCompareLoading" class="qlhh-bento-box qlhh-cmp-loading">
            <svg class="is-spin" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>
            <span>Đang tra cứu dữ liệu đối chiếu từ File Gốc...</span>
          </div>

          <template v-else-if="cardRefCompareData">
            <!-- Lỗi tải file tham chiếu (nếu có) -->
            <div
              v-if="cardRefCompareData.vendor && vendorRefLoadError[cardRefCompareData.vendor]"
              class="qlhh-cmp-alert is-rose"
            >
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
              <span>{{ vendorRefLoadError[cardRefCompareData.vendor] }}</span>
            </div>

            <!-- 1. NGUỒN FILE THAM CHIẾU & ĐIỀU HƯỚNG ĐỐI CHIẾU -->
            <section class="qlhh-bento-box qlhh-cmp-files-card">
              <div class="qlhh-cmp-file-grid">
                <!-- Nguồn Calculator (Sophos) -->
                <div v-if="cardRefCompareData.vendor === 'sophos'" class="qlhh-cmp-file-row">
                  <div class="qlhh-cmp-file-text">
                    <span class="qlhh-cmp-file-lbl">Nguồn (Calculator):</span>
                    <a
                      v-if="getVendorCompareFileMeta('sophos', 'calc')"
                      :href="getVendorOfficeViewUrl(getVendorCompareFileMeta('sophos', 'calc'))"
                      target="_blank"
                      rel="noopener noreferrer"
                      class="qlhh-cmp-file-name"
                      @click="handleOpenVendorOfficeView($event, 'sophos', 'calc', getVendorCompareFileMeta('sophos', 'calc'))"
                    >{{ getVendorCompareFileMeta('sophos', 'calc').name }}<template v-if="getVendorCompareFileMeta('sophos', 'calc').version"> (v{{ getVendorCompareFileMeta('sophos', 'calc').version }})</template></a>
                    <span v-else class="hub-file-empty">Chưa có file</span>
                  </div>
                  <div class="qlhh-cmp-file-icons">
                    <button
                      v-if="getVendorCompareFileMeta('sophos', 'calc')"
                      type="button"
                      class="qlhh-cmp-ico-btn"
                      title="Tải file Calculator về máy"
                      aria-label="Tải file Calculator về máy"
                      @click.stop="handleDownloadVendorUploadedFile('sophos', 'calc', getVendorCompareFileMeta('sophos', 'calc'))"
                    >
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                    </button>
                    <label class="qlhh-ghost-btn is-xs qlhh-cmp-change-btn" title="Upload file Calculator mới">
                      <input type="file" accept=".xlsx,.xlsb,.xls" style="display: none;" @change="handleCustomSophosExcelUpload($event, 'calc')" />
                      <span>Đổi file</span>
                    </label>
                  </div>
                </div>

                <!-- Nguồn File Gốc (Cả 3 hãng) -->
                <div class="qlhh-cmp-file-row">
                  <div class="qlhh-cmp-file-text">
                    <span class="qlhh-cmp-file-lbl">{{ cardRefCompareData.vendor === 'acronis' ? 'Nguồn:' : 'Nguồn (File gốc):' }}</span>
                    <a
                      v-if="getVendorCompareFileMeta(cardRefCompareData.vendor, 'goc')"
                      :href="getVendorOfficeViewUrl(getVendorCompareFileMeta(cardRefCompareData.vendor, 'goc'))"
                      target="_blank"
                      rel="noopener noreferrer"
                      class="qlhh-cmp-file-name"
                      @click="handleOpenVendorOfficeView($event, cardRefCompareData.vendor, 'goc', getVendorCompareFileMeta(cardRefCompareData.vendor, 'goc'))"
                    >{{ getVendorCompareFileMeta(cardRefCompareData.vendor, 'goc').name }}</a>
                    <span v-else class="hub-file-empty">Chưa có file</span>
                  </div>
                  <div class="qlhh-cmp-file-icons">
                    <button
                      v-if="getVendorCompareFileMeta(cardRefCompareData.vendor, 'goc')"
                      type="button"
                      class="qlhh-cmp-ico-btn"
                      title="Tải File Gốc về máy"
                      aria-label="Tải File Gốc về máy"
                      @click.stop="handleDownloadVendorUploadedFile(cardRefCompareData.vendor, 'goc', getVendorCompareFileMeta(cardRefCompareData.vendor, 'goc'))"
                    >
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                    </button>
                    <label v-if="cardRefCompareData.vendor === 'sophos'" class="qlhh-ghost-btn is-xs qlhh-cmp-change-btn" title="Upload File Gốc Sophos mới">
                      <input type="file" accept=".xlsx,.xlsb,.xls" style="display: none;" @change="handleCustomSophosExcelUpload($event, 'goc')" />
                      <span>Đổi file</span>
                    </label>
                    <label v-else-if="cardRefCompareData.vendor === 'kaspersky'" class="qlhh-ghost-btn is-xs qlhh-cmp-change-btn" title="Upload File Gốc Kaspersky mới">
                      <input type="file" accept=".xlsx,.xls" style="display: none;" @change="handleCustomKasExcelUpload($event, 'goc')" />
                      <span>Đổi file</span>
                    </label>
                    <label v-else-if="cardRefCompareData.vendor === 'acronis'" class="qlhh-ghost-btn is-xs qlhh-cmp-change-btn" title="Upload File Gốc Acronis mới">
                      <input type="file" accept=".xlsx,.xls" style="display: none;" @change="handleCustomAcronisExcelUpload($event, 'both')" />
                      <span>Đổi file</span>
                    </label>
                  </div>
                </div>

                <!-- Nguồn File Trung Gian (Sophos & Kaspersky) -->
                <div v-if="cardRefCompareData.vendor !== 'acronis'" class="qlhh-cmp-file-row">
                  <div class="qlhh-cmp-file-text">
                    <span class="qlhh-cmp-file-lbl">Nguồn (File trung gian):</span>
                    <a
                      v-if="getVendorCompareFileMeta(cardRefCompareData.vendor, 'tg')"
                      :href="getVendorOfficeViewUrl(getVendorCompareFileMeta(cardRefCompareData.vendor, 'tg'))"
                      target="_blank"
                      rel="noopener noreferrer"
                      class="qlhh-cmp-file-name"
                      @click="handleOpenVendorOfficeView($event, cardRefCompareData.vendor, cardRefCompareData.vendor === 'sophos' ? 'tg' : 'mau', getVendorCompareFileMeta(cardRefCompareData.vendor, 'tg'))"
                    >{{ getVendorCompareFileMeta(cardRefCompareData.vendor, 'tg').name }}</a>
                    <span v-else class="hub-file-empty">Chưa có file</span>
                  </div>
                  <div class="qlhh-cmp-file-icons">
                    <button
                      v-if="getVendorCompareFileMeta(cardRefCompareData.vendor, 'tg')"
                      type="button"
                      class="qlhh-cmp-ico-btn"
                      title="Tải File Trung Gian về máy"
                      aria-label="Tải File Trung Gian về máy"
                      @click.stop="handleDownloadVendorUploadedFile(cardRefCompareData.vendor, cardRefCompareData.vendor === 'sophos' ? 'tg' : 'mau', getVendorCompareFileMeta(cardRefCompareData.vendor, 'tg'))"
                    >
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                    </button>
                    <label v-if="cardRefCompareData.vendor === 'sophos'" class="qlhh-ghost-btn is-xs qlhh-cmp-change-btn" title="Upload File Trung Gian Sophos mới">
                      <input type="file" accept=".xlsx,.xlsb,.xls" style="display: none;" @change="handleCustomSophosExcelUpload($event, 'tg')" />
                      <span>Đổi file</span>
                    </label>
                    <label v-else-if="cardRefCompareData.vendor === 'kaspersky'" class="qlhh-ghost-btn is-xs qlhh-cmp-change-btn" title="Upload File Mẫu Kaspersky mới">
                      <input type="file" accept=".xlsx,.xls" style="display: none;" @change="handleCustomKasExcelUpload($event, 'mau')" />
                      <span>Đổi file</span>
                    </label>
                  </div>
                </div>
              </div>

              <!-- Các nút điều hướng đối chiếu -->
              <div class="qlhh-cmp-nav-bar">
                <template v-if="cardRefCompareData.vendor === 'sophos'">
                  <button
                    type="button"
                    class="qlhh-ghost-btn is-xs is-emerald-tint"
                    @click="openExcelNavigator({ fileType: 'calc', sheet: sophosCardActiveCalcSummary.sheetName, rowNum: sophosCardActiveCalcSummary.sheetRowNum, colLetter: sophosCardActiveCalcSummary.sheetColLetter, sku: sophosCardActiveCalcSummary.sku || cardRefCompareData.sku, itemName: cardRefCompareData.item.Ten_hang })"
                  >Đối chiếu Calculator ({{ sophosCardActiveCalcSummary.sheetColLetter }}{{ sophosCardActiveCalcSummary.sheetRowNum }})</button>
                  <button
                    v-if="cardRefCompareData.gocFirewallRowNum || cardRefCompareData.gocRowNum"
                    type="button"
                    class="qlhh-ghost-btn is-xs"
                    @click="openExcelNavigator({ fileType: 'goc', sheet: cardRefCompareData.gocFirewallRowNum ? 'Firewall' : 'MSRPs&BuyCost', rowNum: cardRefCompareData.gocFirewallRowNum || cardRefCompareData.gocRowNum, colLetter: cardRefCompareData.gocFirewallRowNum ? 'H' : 'B', sku: cardRefCompareData.sku, itemName: cardRefCompareData.item.Ten_hang })"
                  >Đối chiếu File Gốc</button>
                  <button
                    v-if="cardRefCompareData.skuListRowNum"
                    type="button"
                    class="qlhh-ghost-btn is-xs"
                    @click="openExcelNavigator({ fileType: 'skulist', sheet: 'SKU_Tab', rowNum: cardRefCompareData.skuListRowNum, colLetter: 'G', sku: cardRefCompareData.sku, itemName: cardRefCompareData.item.Ten_hang })"
                  >Đối chiếu SKU_List #{{ cardRefCompareData.skuListRowNum }}</button>
                  <button
                    v-for="(loc, lIdx) in cardRefCompareData.tgLocations"
                    :key="'tg-loc-' + lIdx"
                    type="button"
                    class="qlhh-ghost-btn is-xs"
                    @click="openExcelNavigator({ fileType: 'tg', sheet: loc.sheet, rowNum: loc.rowNum, colLetter: loc.colLetter || 'B', sku: cardRefCompareData.sku, itemName: cardRefCompareData.item.Ten_hang })"
                  >Đối chiếu {{ loc.sheet }} #{{ loc.rowNum }}</button>
                  <button
                    v-if="sophosCardActiveCalcSummary.calcRowNum || cardRefCompareData.calcRowNum"
                    type="button"
                    class="qlhh-ghost-btn is-xs"
                    @click="showCalcHiddenSheets = true; openExcelNavigator({ fileType: 'calc', sheet: 'MSRPs&BuyCost', rowNum: sophosCardActiveCalcSummary.calcRowNum || cardRefCompareData.calcRowNum, colLetter: 'B', sku: sophosCardActiveCalcSummary.sku || cardRefCompareData.sku, itemName: cardRefCompareData.item.Ten_hang })"
                  >Đối chiếu MSRPs&amp;BuyCost #{{ sophosCardActiveCalcSummary.calcRowNum || cardRefCompareData.calcRowNum }}</button>
                  <button
                    v-if="getVendorCompareFileMeta('sophos', 'calc') || getVendorCompareFileMeta('sophos', 'goc')"
                    type="button"
                    class="qlhh-ghost-btn is-xs is-sky-tint"
                    :class="{ 'is-active': compareOfficePreview.show && compareOfficePreview.vendor === 'sophos' }"
                    @click.stop="openCompareOfficePreview({ vendor: 'sophos', role: getVendorCompareFileMeta('sophos', 'calc') ? 'calc' : 'goc', sheet: sophosCardActiveCalcSummary.sheetName || cardRefCompareData.calcNativeSheet || 'Firewall', rowNum: sophosCardActiveCalcSummary.sheetRowNum || cardRefCompareData.calcSheetRowNum || cardRefCompareData.calcFirewallRowNum || 29, colLetter: sophosCardActiveCalcSummary.sheetColLetter || cardRefCompareData.calcSheetColLetter || 'H', sku: sophosCardActiveCalcSummary.sku || cardRefCompareData.sku, itemName: cardRefCompareData.item?.Ten_hang })"
                  >Đối chiếu ViewOffice</button>
                </template>

                <template v-else-if="cardRefCompareData.vendor === 'kaspersky'">
                  <button
                    type="button"
                    class="qlhh-ghost-btn is-xs is-emerald-tint"
                    @click="openKasExcelNavigator({ fileType: 'kas_goc', sheet: 'SMB+Enterprise (License)', rowNum: cardRefCompareData.gocPivotRow || 11, colLetter: cardRefCompareData.gocPivotColLetter || 'I', sku: cardRefCompareData.sku, band: cardRefCompareData.band, itemName: cardRefCompareData.item.Ten_hang })"
                  >Đối chiếu File Gốc{{ cardRefCompareData.gocPivotRow ? ` (#${cardRefCompareData.gocPivotRow})` : '' }}</button>
                  <button
                    v-if="cardRefCompareData.mauPivotRow"
                    type="button"
                    class="qlhh-ghost-btn is-xs"
                    @click="openKasExcelNavigator({ fileType: 'kas_mau', sheet: 'SMB+Enterprise (License)', rowNum: cardRefCompareData.mauPivotRow, colLetter: cardRefCompareData.mauPivotColLetter, sku: cardRefCompareData.sku, band: cardRefCompareData.band, itemName: cardRefCompareData.item.Ten_hang })"
                  >Đối chiếu File Mẫu (#{{ cardRefCompareData.mauPivotRow }})</button>
                  <button
                    v-if="getVendorCompareFileMeta('kaspersky', 'goc')"
                    type="button"
                    class="qlhh-ghost-btn is-xs is-sky-tint"
                    @click.stop="openCompareOfficePreview({ vendor: 'kaspersky', role: 'goc', sheet: cardRefCompareData.gocPivotRow ? 'SMB+Enterprise (License)' : 'SaleListSMB+Enterprise', rowNum: cardRefCompareData.gocPivotRow || cardRefCompareData.gocSaleRow || 11, colLetter: cardRefCompareData.gocPivotColLetter || 'I', sku: cardRefCompareData.sku, itemName: cardRefCompareData.item?.Ten_hang })"
                  >Đối chiếu ViewOffice</button>
                </template>

                <template v-else>
                  <button
                    type="button"
                    class="qlhh-ghost-btn is-xs is-emerald-tint"
                    @click="openAcronisExcelNavigator({ fileType: 'acronis_goc', sheet: cardRefCompareData.gocRowNum ? cardRefCompareData.sheet : 'Protect Standard', rowNum: cardRefCompareData.gocRowNum || 4, colLetter: cardRefCompareData.gocRowNum ? 'D' : 'B', sku: cardRefCompareData.sku || cardRefCompareData.skuFor, itemName: cardRefCompareData.item.Ten_hang })"
                  >Đối chiếu File Gốc{{ cardRefCompareData.gocRowNum ? ` (#${cardRefCompareData.gocRowNum})` : '' }}</button>
                  <button
                    v-if="getVendorCompareFileMeta('acronis', 'goc')"
                    type="button"
                    class="qlhh-ghost-btn is-xs is-sky-tint"
                    @click.stop="openCompareOfficePreview({ vendor: 'acronis', role: 'goc', sheet: cardRefCompareData.sheet || 'Protect Standard', rowNum: cardRefCompareData.gocRowNum || 4, colLetter: 'D', sku: cardRefCompareData.sku || cardRefCompareData.skuFor, itemName: cardRefCompareData.item?.Ten_hang })"
                  >Đối chiếu ViewOffice</button>
                  <button
                    type="button"
                    class="qlhh-ghost-btn is-xs"
                    @click="showCardRefCompareModal = false; openAcronisCompareModal(cardRefCompareData.sheet, cardRefCompareData.sku || cardRefCompareData.skuFor)"
                  >Đối chiếu toàn bộ (221 mã)</button>
                </template>
              </div>
            </section>

            <!-- KHỐI VIEWOFFICE NHÚNG TRỰC TIẾP (KHI BẬT) -->
            <div
              v-if="compareOfficePreview.show && cardRefCompareData.vendor && compareOfficePreview.vendor === cardRefCompareData.vendor"
              class="compare-office-embed-panel qlhh-cmp-office"
            >
              <div class="compare-office-embed-header">
                <div class="qlhh-cmp-office-left">
                  <span class="qlhh-cmp-office-brand">Đối chiếu ViewOffice</span>
                  <button
                    v-if="cardRefCompareData.vendor === 'sophos' && getVendorCompareFileMeta('sophos', 'calc')"
                    type="button"
                    class="compare-office-role-btn"
                    :class="{ active: compareOfficePreview.role === 'calc' }"
                    @click="openCompareOfficePreview({ vendor: 'sophos', role: 'calc', sheet: sophosCardActiveCalcSummary.sheetName || cardRefCompareData.calcNativeSheet || 'Firewall', rowNum: sophosCardActiveCalcSummary.sheetRowNum || cardRefCompareData.calcSheetRowNum || cardRefCompareData.calcFirewallRowNum || 29, colLetter: sophosCardActiveCalcSummary.sheetColLetter || cardRefCompareData.calcSheetColLetter || 'H', sku: sophosCardActiveCalcSummary.sku || cardRefCompareData.sku, itemName: cardRefCompareData.item?.Ten_hang })"
                  >Calculator</button>
                  <button
                    v-if="getVendorCompareFileMeta(cardRefCompareData.vendor, 'goc')"
                    type="button"
                    class="compare-office-role-btn"
                    :class="{ active: compareOfficePreview.role === 'goc' }"
                    @click="openCompareOfficePreview({ vendor: cardRefCompareData.vendor, role: 'goc', sheet: cardRefCompareData.sheet || 'MSRPs&BuyCost', rowNum: cardRefCompareData.gocRowNum || cardRefCompareData.gocPivotRow || 4, colLetter: cardRefCompareData.gocPivotColLetter || 'B', sku: cardRefCompareData.sku || cardRefCompareData.skuFor })"
                  >File Gốc</button>
                  <button
                    v-if="cardRefCompareData.vendor !== 'acronis' && getVendorCompareFileMeta(cardRefCompareData.vendor, 'tg')"
                    type="button"
                    class="compare-office-role-btn"
                    :class="{ active: compareOfficePreview.role === 'tg' || compareOfficePreview.role === 'mau' }"
                    @click="openCompareOfficePreview({ vendor: cardRefCompareData.vendor, role: cardRefCompareData.vendor === 'sophos' ? 'tg' : 'mau', sheet: cardRefCompareData.tgSheet || 'SMB+Enterprise (License)', rowNum: cardRefCompareData.tgRowNum || cardRefCompareData.mauPivotRow || 6, colLetter: 'B', sku: cardRefCompareData.sku })"
                  >File Trung Gian</button>
                  <span v-if="compareOfficePreview.sku" class="qlhh-cmp-plain-meta tabular-nums">SKU: {{ compareOfficePreview.sku }}</span>
                  <span v-if="compareOfficePreview.sheet && compareOfficePreview.rowNum" class="qlhh-cmp-plain-meta tabular-nums">
                    {{ compareOfficePreview.sheet }} • {{ compareOfficePreview.colLetter }}{{ compareOfficePreview.rowNum }}
                  </span>
                  <span v-if="compareOfficePreview.copiedLabel" class="qlhh-cmp-copied-msg">{{ compareOfficePreview.copiedLabel }}</span>
                </div>
                <div class="qlhh-cmp-office-right">
                  <button
                    v-if="compareOfficePreview.sku"
                    type="button"
                    class="qlhh-ghost-btn is-xs"
                    @click="copyCompareOfficeQuickText(compareOfficePreview.sku, `Đã copy: ${compareOfficePreview.sku}`)"
                  >Copy SKU</button>
                  <a
                    v-if="compareOfficePreview.viewUrl"
                    :href="compareOfficePreview.viewUrl"
                    target="_blank"
                    rel="noopener noreferrer"
                    class="qlhh-ghost-btn is-xs is-sky-tint"
                    style="text-decoration: none;"
                  >Tab mới</a>
                  <button
                    type="button"
                    class="qlhh-ghost-btn is-xs"
                    @click="handleDownloadVendorUploadedFile(cardRefCompareData.vendor, compareOfficePreview.role, getVendorCompareFileMeta(cardRefCompareData.vendor, compareOfficePreview.role === 'calc' ? 'calc' : (compareOfficePreview.role === 'goc' ? 'goc' : 'tg')))"
                  >Tải về</button>
                  <button type="button" class="compare-office-close-btn" @click="closeCompareOfficePreview">Đóng</button>
                </div>
              </div>
              <div class="compare-office-embed-body">
                <div v-if="compareOfficePreview.loading" class="compare-office-loading">
                  Đang chuẩn bị ViewOffice...
                </div>
                <iframe
                  v-else-if="compareOfficePreview.embedUrl"
                  :src="compareOfficePreview.embedUrl"
                  class="compare-office-iframe"
                  allowfullscreen
                ></iframe>
              </div>
            </div>

            <!-- 2. BÊN DƯỚI LÀ CÁC KHỐI ĐỐI CHIẾU: HERO SO SÁNH + CHI TIẾT -->
            <section class="qlhh-bento-box qlhh-cmp-hero-card">
              <div class="qlhh-cmp-hero-grid">
                <!-- Cột DB -->
                <div class="qlhh-cmp-hero-side">
                  <span class="qlhh-cmp-eyebrow is-sky">Database (hang_hoa)</span>
                  <div class="qlhh-cmp-hero-price is-sky tabular-nums">
                    {{ cardRefCompareData.vendor === 'sophos' ? formatUsdPrice(cardRefCompareData.dbPrice) : formatVndPrice(cardRefCompareData.dbPrice) }}
                  </div>
                  <div class="qlhh-cmp-hero-sub tabular-nums">
                    <span>SKU: <strong>{{ cardRefCompareData.sku || cardRefCompareData.item?.Ma_hang || '-' }}</strong></span>
                    <span v-if="cardRefCompareData.vendor === 'sophos' && cardRefCompareData.dbGiaNhap > 0">
                      Giá nhập: <strong>{{ formatUsdPrice(cardRefCompareData.dbGiaNhap) }}</strong>
                    </span>
                    <span v-else-if="cardRefCompareData.vendor === 'kaspersky' && cardRefCompareData.band">
                      Band: <strong>{{ cardRefCompareData.band }}</strong>
                    </span>
                    <span v-else-if="cardRefCompareData.vendor === 'acronis' && cardRefCompareData.sheet">
                      Sheet: <strong>{{ cardRefCompareData.sheet }}</strong>
                    </span>
                  </div>
                </div>

                <!-- Trạng thái & Nút cập nhật 1-click -->
                <div class="qlhh-cmp-hero-mid">
                  <template v-if="cardRefCompareData.vendor === 'sophos' && sophosCardActiveCalcSummary.available && sophosCardActiveCalcSummary.unitMsrp > 0">
                    <span
                      v-if="Math.abs(cardRefCompareData.dbPrice - sophosCardActiveCalcSummary.unitMsrp) < 0.05"
                      class="qlhh-cmp-status-pill is-match tabular-nums"
                    >
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                      <span>Khớp Unit MSRP Calculator</span>
                    </span>
                    <template v-else>
                      <span class="qlhh-cmp-status-pill is-diff tabular-nums">
                        Lệch {{ (cardRefCompareData.dbPrice - sophosCardActiveCalcSummary.unitMsrp) > 0 ? '+' : '' }}{{ formatUsdPrice(cardRefCompareData.dbPrice - sophosCardActiveCalcSummary.unitMsrp) }}
                      </span>
                      <button
                        type="button"
                        class="qlhh-btn-primary is-sm"
                        :disabled="syncingCardRefToDb"
                        @click="syncCardFromActiveCalculator"
                      >
                        <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>
                        <span>{{ syncingCardRefToDb ? 'Đang cập nhật...' : `Cập nhật (${formatUsdPrice(sophosCardActiveCalcSummary.unitMsrp)})` }}</span>
                      </button>
                    </template>
                  </template>

                  <template v-else>
                    <span
                      class="qlhh-cmp-status-pill tabular-nums"
                      :class="cardRefCompareData.status === 'match' ? 'is-match' : (cardRefCompareData.status === 'diff' ? 'is-diff' : 'is-miss')"
                    >
                      <template v-if="cardRefCompareData.status === 'match'">Khớp File Gốc</template>
                      <template v-else-if="cardRefCompareData.status === 'diff'">
                        Lệch {{ cardRefCompareData.priceDiff > 0 ? '+' : '' }}{{ cardRefCompareData.vendor === 'sophos' ? formatUsdPrice(cardRefCompareData.priceDiff) : formatVndPrice(cardRefCompareData.priceDiff) }}
                        ({{ cardRefCompareData.priceDiffPct.toFixed(1) }}%)
                      </template>
                      <template v-else>Chưa khớp mã SKU</template>
                    </span>
                    <button
                      v-if="cardRefCompareData.refPrice > 0 && cardRefCompareData.status === 'diff'"
                      type="button"
                      class="qlhh-btn-primary is-sm"
                      :disabled="syncingCardRefToDb"
                      @click="syncCardItemWithOriginalFile"
                    >
                      <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>
                      <span>{{ syncingCardRefToDb ? 'Đang cập nhật...' : `Cập nhật (${cardRefCompareData.vendor === 'sophos' ? formatUsdPrice(cardRefCompareData.refPrice) : formatVndPrice(cardRefCompareData.refPrice)})` }}</span>
                    </button>
                  </template>
                </div>

                <!-- Cột Chuẩn Hãng -->
                <div class="qlhh-cmp-hero-side is-right">
                  <template v-if="cardRefCompareData.vendor === 'sophos'">
                    <span class="qlhh-cmp-eyebrow is-emerald">
                      Calculator <template v-if="cardRefCompareData.calcVersion">v{{ cardRefCompareData.calcVersion }}</template>
                    </span>
                    <template v-if="sophosCardActiveCalcSummary.available">
                      <div class="qlhh-cmp-hero-price is-emerald tabular-nums">
                        {{ formatUsdPrice(sophosCardActiveCalcSummary.unitMsrp) }}
                      </div>
                      <div class="qlhh-cmp-hero-sub tabular-nums">
                        <span>SKU: <strong>{{ sophosCardActiveCalcSummary.sku }}</strong></span>
                        <span>Disc: <strong>{{ sophosCardActiveCalcSummary.resellerDiscPct }}%</strong></span>
                        <span>Buy Cost: <strong class="is-emerald-txt">{{ formatUsdPrice(sophosCardActiveCalcSummary.buyCost) }}</strong></span>
                      </div>
                    </template>
                    <div v-else class="qlhh-cmp-hero-empty">
                      Không khả dụng với tùy chọn đang chọn
                    </div>
                  </template>

                  <template v-else-if="cardRefCompareData.vendor === 'kaspersky'">
                    <span class="qlhh-cmp-eyebrow is-emerald">
                      File Gốc ({{ cardRefCompareData.band || 'Chưa rõ Band' }})
                    </span>
                    <div class="qlhh-cmp-hero-price is-emerald tabular-nums">
                      {{ cardRefCompareData.gocFound ? formatVndPrice(cardRefCompareData.gocPrice) : 'Chưa tìm thấy' }}
                    </div>
                    <div v-if="cardRefCompareData.gocFound" class="qlhh-cmp-hero-sub tabular-nums">
                      <span>Pos: <strong>{{ cardRefCompareData.posCode || '-' }}</strong></span>
                      <span>Pivot #{{ cardRefCompareData.gocPivotRow || '-' }}</span>
                    </div>
                  </template>

                  <template v-else>
                    <span class="qlhh-cmp-eyebrow is-emerald">
                      File Gốc Acronis
                    </span>
                    <div class="qlhh-cmp-hero-price is-emerald tabular-nums">
                      {{ cardRefCompareData.gocFound ? formatVndPrice(cardRefCompareData.gocPrice) : 'Chưa tìm thấy' }}
                    </div>
                    <div v-if="cardRefCompareData.gocFound" class="qlhh-cmp-hero-sub tabular-nums">
                      <span>Dòng #{{ cardRefCompareData.gocRowNum || '-' }} (Ô D{{ cardRefCompareData.gocRowNum }})</span>
                    </div>
                  </template>
                </div>
              </div>
            </section>

            <!-- ==================== GIAO DIỆN ĐỐI CHIẾU SOPHOS ==================== -->
            <template v-if="cardRefCompareData.vendor === 'sophos'">
              <!-- Tabs chuyển Sheet Firewall / Universal Calculator / 4 Nguồn -->
              <div class="qlhh-hub-tabs qlhh-cmp-tabs" role="tablist">
                <button
                  type="button"
                  class="qlhh-hub-tab"
                  :class="{ active: sophosCardCalcState.activeTab === 'firewall' }"
                  @click="sophosCardCalcState.activeTab = 'firewall'; sophosCardCalcState.calcMode = 'firewall'"
                >
                  <span>Sheet Firewall</span>
                </button>
                <button
                  type="button"
                  class="qlhh-hub-tab"
                  :class="{ active: sophosCardCalcState.activeTab === 'product' }"
                  @click="sophosCardCalcState.activeTab = 'product'; sophosCardCalcState.calcMode = 'product'"
                >
                  <span>{{ sophosCardCalcState.nativeSheet && sophosCardCalcState.nativeSheet !== 'Firewall' ? sophosCardCalcState.nativeSheet : 'Universal Calculator' }}</span>
                </button>
                <button
                  type="button"
                  class="qlhh-hub-tab"
                  :class="{ active: sophosCardCalcState.activeTab === 'sources' }"
                  @click="sophosCardCalcState.activeTab = 'sources'"
                >
                  <span>So sánh 4 nguồn</span>
                </button>
              </div>

              <!-- TAB 1: SHEET FIREWALL CALCULATOR -->
              <div v-if="sophosCardCalcState.activeTab === 'firewall'" class="qlhh-cmp-stack">
                <section class="qlhh-bento-box">
                  <div class="qlhh-cmp-params-grid">
                    <div class="qlhh-field">
                      <label>Partner Level</label>
                      <select v-model="sophosCardCalcState.partnerLevel" class="qlhh-fm-select">
                        <option v-for="pl in sophosPartnerLevelOptions" :key="pl" :value="pl">{{ pl }}</option>
                      </select>
                    </div>
                    <div class="qlhh-field">
                      <label>Sector</label>
                      <select v-model="sophosCardCalcState.sector" class="qlhh-fm-select">
                        <option v-for="sec in sophosSectorOptions" :key="sec" :value="sec">{{ sec }}</option>
                      </select>
                    </div>
                    <div class="qlhh-field">
                      <label>Deal Type</label>
                      <select v-model="sophosCardCalcState.dealType" class="qlhh-fm-select">
                        <option v-for="dt in sophosDealTypeOptions" :key="dt" :value="dt">{{ dt }}</option>
                      </select>
                    </div>
                    <div class="qlhh-field">
                      <label>Term (HW Bundles)</label>
                      <select v-model="sophosCardCalcState.termHwBundle" class="qlhh-fm-select">
                        <option value="">None</option>
                        <option value="1-Year">1-Year</option>
                        <option value="3-Year">3-Year</option>
                        <option value="5-Year">5-Year</option>
                      </select>
                    </div>
                    <div class="qlhh-field">
                      <label>Term (Subscriptions)</label>
                      <select v-model="sophosCardCalcState.termSubscription" class="qlhh-fm-select">
                        <option v-for="tm in sophosTermOptions" :key="tm" :value="tm">{{ tm }}</option>
                      </select>
                    </div>
                    <div class="qlhh-field">
                      <label>Qty</label>
                      <input type="number" min="1" v-model.number="sophosCardCalcState.qty" class="qlhh-fm-input tabular-nums" />
                    </div>
                    <div class="qlhh-field">
                      <label>Special Attribute</label>
                      <select v-model="sophosCardCalcState.specialAttribute" class="qlhh-fm-select">
                        <option v-for="ps in ['AU', 'EU', 'UK', 'US', 'CN', 'IN', 'JP']" :key="ps" :value="ps">{{ ps }}</option>
                      </select>
                    </div>
                  </div>

                  <!-- Thanh chọn Model (tối đa 3 Model song song) -->
                  <div class="qlhh-cmp-model-bar">
                    <div class="qlhh-cmp-model-left">
                      <span class="qlhh-cmp-sub-label">Model:</span>
                      <select
                        :value="sophosCardCalcState.models[0]"
                        class="qlhh-fm-select qlhh-cmp-model-sel"
                        @change="setPrimarySophosCardFirewallModel($event.target.value)"
                      >
                        <optgroup v-for="grp in sophosCalcFirewallGroups" :key="'m1-' + grp.group" :label="grp.group">
                          <option v-for="m in grp.models" :key="m" :value="m">{{ m }}</option>
                        </optgroup>
                      </select>
                      <span
                        v-for="(mdl, mIdx) in sophosCardCalcState.models"
                        :key="'sel-mdl-' + mdl"
                        class="qlhh-cmp-model-chip"
                        :class="mIdx === 0 ? 'is-primary' : 'is-secondary'"
                      >
                        <span>{{ mdl }}</span>
                        <button
                          v-if="sophosCardCalcState.models.length > 1"
                          type="button"
                          class="qlhh-cmp-chip-x"
                          @click="toggleSophosCardFirewallModel(mdl)"
                          title="Bỏ cột Model này"
                        >✕</button>
                      </span>
                    </div>
                    <button
                      type="button"
                      class="qlhh-ghost-btn is-xs"
                      :class="{ 'is-sky-tint': sophosCardCalcState.showModelPicker }"
                      @click="sophosCardCalcState.showModelPicker = !sophosCardCalcState.showModelPicker"
                    >
                      <span>{{ sophosCardCalcState.showModelPicker ? 'Ẩn bảng Model' : 'So sánh thêm Model' }}</span>
                    </button>
                  </div>

                  <!-- Bảng 5 nhóm Model (khi mở) -->
                  <div v-if="sophosCardCalcState.showModelPicker" class="qlhh-cmp-model-picker">
                    <div
                      v-for="grp in sophosCalcFirewallGroups"
                      :key="grp.group"
                      class="qlhh-cmp-model-group"
                    >
                      <div class="qlhh-cmp-mg-name">{{ grp.group }}</div>
                      <div class="qlhh-cmp-mg-chips">
                        <button
                          v-for="m in grp.models"
                          :key="m"
                          type="button"
                          class="qlhh-cmp-model-btn"
                          :class="{ active: sophosCardCalcState.models.includes(m) }"
                          @click="toggleSophosCardFirewallModel(m)"
                        >{{ m }}</button>
                      </div>
                    </div>
                  </div>
                </section>

                <!-- Bảng tính 15 dòng Sheet Firewall -->
                <div class="qlhh-cmp-table-wrap">
                  <table class="qlhh-cmp-table tabular-nums">
                    <thead>
                      <tr>
                        <th style="min-width: 210px;">Hạng mục Firewall (Col C)</th>
                        <template v-for="(mdl, mIdx) in sophosCardCalcState.models" :key="'hdr-m-' + mdl">
                          <th class="col-group-sep" style="min-width: 138px;">{{ mdl }} • SKU</th>
                          <th class="text-right" style="min-width: 105px;">MSRP</th>
                          <th class="text-right" style="min-width: 74px;">Disc %</th>
                          <th v-if="mIdx === 0" class="text-right" style="width: 76px;">Promo %</th>
                          <th v-if="mIdx === 0" class="text-right" style="width: 78px;">Special %</th>
                          <th class="text-right" style="min-width: 105px;">Buy Cost</th>
                        </template>
                      </tr>
                    </thead>
                    <tbody>
                      <template v-for="(rEval, rIdx) in sophosCardFirewallEval.rows" :key="rEval.key">
                        <tr
                          v-if="rIdx === 0 || rEval.category !== sophosCardFirewallEval.rows[rIdx - 1]?.category"
                          class="qlhh-cmp-cat-row"
                        >
                          <td :colspan="1 + sophosCardCalcState.models.length * 4 + 2">
                            {{ rEval.category === 'Hardware Bundles' ? 'Hardware Bundles (Rows 25–29)' : 'Subscriptions (Rows 33–55)' }}
                          </td>
                        </tr>
                        <tr
                          class="qlhh-cmp-fw-row"
                          :class="{
                            'is-selected': sophosCardCalcState.targetFirewallRowKey === rEval.key,
                            'is-unavail': !rEval.cells[0]?.available
                          }"
                          @click="sophosCardCalcState.targetFirewallRowKey = rEval.key"
                        >
                          <td>
                            <div class="qlhh-cmp-row-title">
                              <span v-if="sophosCardCalcState.targetFirewallRowKey === rEval.key" class="qlhh-cmp-active-dot"></span>
                              <strong>{{ rEval.label }}</strong>
                            </div>
                            <div class="qlhh-cmp-row-sub">Row #{{ rEval.sheetRowNum }}</div>
                          </td>

                          <template v-for="(cEval, mIdx) in rEval.cells" :key="rEval.key + '-' + cEval.model">
                            <td class="col-group-sep">
                              <template v-if="cEval.available">
                                <code class="qlhh-cmp-sku-code">{{ cEval.sku }}</code>
                                <div v-if="cEval.note" class="qlhh-cmp-cell-note">{{ cEval.note }}</div>
                              </template>
                              <span v-else class="qlhh-cmp-muted">{{ cEval.note || 'NA' }}</span>
                            </td>
                            <td class="text-right">
                              <strong v-if="cEval.available" class="qlhh-cmp-msrp-txt">{{ formatUsdPrice(cEval.msrp) }}</strong>
                              <span v-else class="qlhh-cmp-muted">NA</span>
                            </td>
                            <td class="text-right qlhh-cmp-disc-txt">
                              {{ cEval.available ? `${cEval.resellerDiscPct}%` : '0%' }}
                            </td>
                            <td v-if="mIdx === 0" class="text-right" @click.stop>
                              <input
                                type="number"
                                min="0"
                                max="100"
                                step="0.5"
                                v-model.number="sophosCardCalcState.promoDiscByRow[rEval.key]"
                                class="qlhh-cmp-pct-input tabular-nums"
                                placeholder="0"
                              />
                            </td>
                            <td v-if="mIdx === 0" class="text-right" @click.stop>
                              <input
                                type="number"
                                min="0"
                                max="100"
                                step="0.5"
                                v-model.number="sophosCardCalcState.specialDiscByRow[rEval.key]"
                                class="qlhh-cmp-pct-input tabular-nums"
                                placeholder="0"
                              />
                            </td>
                            <td class="text-right">
                              <strong v-if="cEval.available" class="qlhh-cmp-buy-txt">{{ formatUsdPrice(cEval.buyCost) }}</strong>
                              <span v-else class="qlhh-cmp-muted">0.00$</span>
                            </td>
                          </template>
                        </tr>
                      </template>
                    </tbody>
                  </table>
                </div>

                <!-- Hardware Features & Licensing Notes -->
                <div class="qlhh-cmp-2col">
                  <div
                    v-for="mdl in sophosCardCalcState.models"
                    :key="'feat-' + mdl"
                    class="qlhh-bento-box qlhh-cmp-note-box"
                  >
                    <div class="qlhh-bento-head is-sky">{{ mdl }} — Hardware Features</div>
                    <div class="qlhh-cmp-note-text">{{ sophosCardFirewallEval.modelFeatures[mdl] || 'Virtual / Software Appliance' }}</div>
                  </div>
                  <div
                    v-if="sophosCardFirewallEval.licensingNotes"
                    class="qlhh-bento-box qlhh-cmp-note-box"
                  >
                    <div class="qlhh-bento-head is-slate">Licensing Notes</div>
                    <div class="qlhh-cmp-note-text is-pre">{{ sophosCardFirewallEval.licensingNotes }}</div>
                  </div>
                </div>
              </div>

              <!-- TAB 2: UNIVERSAL / PRODUCT CALCULATOR -->
              <div v-else-if="sophosCardCalcState.activeTab === 'product'" class="qlhh-cmp-stack">
                <section class="qlhh-bento-box">
                  <div class="qlhh-cmp-search-row">
                    <input
                      type="text"
                      v-model="sophosCardCalcState.productSearch"
                      class="qlhh-fm-input"
                      placeholder="Tìm sản phẩm hoặc SKU trên 23 Sheet (VD: Endpoint, MDR, Email, Switch, CS110, AP6...)"
                    />
                    <span class="qlhh-cmp-ver-tag">Sheet: {{ sophosCardCalcState.nativeSheet || 'Universal Calculator' }}</span>
                  </div>

                  <div v-if="sophosCardSearchMatchedProducts.length > 0" class="qlhh-cmp-search-drop">
                    <div
                      v-for="pItem in sophosCardSearchMatchedProducts"
                      :key="pItem.pc + pItem.desc"
                      class="qlhh-cmp-search-hit"
                      @click="selectSophosCardSearchedProduct(pItem)"
                    >
                      <div class="qlhh-cmp-hit-name">
                        <strong>{{ pItem.desc }}</strong>
                        <span>({{ pItem.prodType || 'Product' }})</span>
                      </div>
                      <code class="qlhh-code-pill is-sku tabular-nums">{{ pItem.pc }} • {{ pItem.partId }}</code>
                    </div>
                  </div>
                </section>

                <div class="qlhh-cmp-2col">
                  <!-- Cột Trái: Thông số đầu vào -->
                  <section class="qlhh-bento-box">
                    <div class="qlhh-bento-head is-sky">Thông số đầu vào</div>
                    <div class="qlhh-cmp-3col-fields">
                      <div class="qlhh-field">
                        <label>Partner Level</label>
                        <select v-model="sophosCardCalcState.partnerLevel" class="qlhh-fm-select">
                          <option v-for="pl in sophosPartnerLevelOptions" :key="pl" :value="pl">{{ pl }}</option>
                        </select>
                      </div>
                      <div class="qlhh-field">
                        <label>Sector</label>
                        <select v-model="sophosCardCalcState.sector" class="qlhh-fm-select">
                          <option v-for="sec in sophosSectorOptions" :key="sec" :value="sec">{{ sec }}</option>
                        </select>
                      </div>
                      <div class="qlhh-field">
                        <label>Deal Type</label>
                        <select v-model="sophosCardCalcState.dealType" class="qlhh-fm-select">
                          <option v-for="dt in sophosDealTypeOptions" :key="dt" :value="dt">{{ dt }}</option>
                        </select>
                      </div>
                    </div>

                    <div class="qlhh-field">
                      <label>Solution Family</label>
                      <select v-model="sophosCardCalcState.family" class="qlhh-fm-select" @change="handleSophosCardFamilyChange">
                        <option v-for="fam in sophosCardUniversalFamilies" :key="fam" :value="fam">{{ fam }}</option>
                      </select>
                    </div>
                    <div class="qlhh-field">
                      <label>Product Line</label>
                      <select v-model="sophosCardCalcState.productLine" class="qlhh-fm-select" @change="handleSophosCardLineChange">
                        <option v-for="ln in sophosCardUniversalLines" :key="ln" :value="ln">{{ ln }}</option>
                      </select>
                    </div>
                    <div class="qlhh-field">
                      <label>Product</label>
                      <select v-model="sophosCardCalcState.product" class="qlhh-fm-select" @change="handleSophosCardProductChange">
                        <option v-if="sophosCardCalcState.product && !sophosCardUniversalProducts.includes(sophosCardCalcState.product)" :value="sophosCardCalcState.product">
                          {{ sophosCardCalcState.product }}
                        </option>
                        <option v-for="pr in sophosCardUniversalProducts" :key="pr" :value="pr">{{ pr }}</option>
                      </select>
                    </div>

                    <div class="qlhh-cmp-3col-fields">
                      <div class="qlhh-field">
                        <label>Term</label>
                        <select
                          v-if="!sophosCardProductEval || sophosCardProductEval.isTermed && !sophosCardProductEval.fixedTermLabel"
                          v-model="sophosCardCalcState.termSubscription"
                          class="qlhh-fm-select"
                        >
                          <option v-for="tm in sophosTermOptions" :key="tm" :value="tm">{{ tm }}</option>
                        </select>
                        <div v-else class="qlhh-cmp-readonly-box">
                          {{ sophosCardProductEval.fixedTermLabel || 'One-time (00)' }}
                        </div>
                      </div>
                      <div class="qlhh-field">
                        <label>Qty</label>
                        <input type="number" min="1" v-model.number="sophosCardCalcState.qty" class="qlhh-fm-input tabular-nums" />
                      </div>
                      <div class="qlhh-field">
                        <label>Special Attribute</label>
                        <select v-model="sophosCardCalcState.specialAttribute" class="qlhh-fm-select">
                          <option
                            v-for="opt in (sophosCardProductEval?.specialAttrOptions || [{ label: 'Standard Pricing', code: 'AA' }])"
                            :key="opt.code + opt.label"
                            :value="opt.code"
                          >{{ opt.label }}</option>
                        </select>
                      </div>
                    </div>

                    <div v-if="sophosCardProductEval" class="qlhh-cmp-band-foot tabular-nums">
                      <span>
                        Band: <strong>{{ sophosCardProductEval.bandCode }}</strong>
                        <template v-if="sophosCardProductEval.bandMin !== null && sophosCardProductEval.bandCode !== 'ZZ'">
                          ({{ sophosCardProductEval.bandMin.toLocaleString() }}–{{ sophosCardProductEval.bandMax?.toLocaleString() }})
                        </template>
                      </span>
                      <span v-if="sophosCardProductEval.minQtyWarning" class="qlhh-cmp-warn-txt">{{ sophosCardProductEval.minQtyWarning }}</span>
                    </div>
                  </section>

                  <!-- Cột Phải: Kết quả tính toán -->
                  <section class="qlhh-bento-box">
                    <div class="qlhh-bento-head is-emerald is-between">
                      <span>Kết quả tính toán</span>
                      <span v-if="sophosCardProductEval?.productCode" class="qlhh-cmp-ver-tag tabular-nums">{{ sophosCardProductEval.productCode }}</span>
                    </div>

                    <template v-if="sophosCardProductEval">
                      <div class="qlhh-cmp-kv-list tabular-nums">
                        <div class="qlhh-cmp-kv-row">
                          <span>Product</span>
                          <strong>{{ sophosCardProductEval.productDesc || '-' }}</strong>
                        </div>
                        <div class="qlhh-cmp-kv-row">
                          <span>SKU (Calculated)</span>
                          <div>
                            <code v-if="sophosCardProductEval.available" class="qlhh-code-pill is-sku">{{ sophosCardProductEval.sku }}</code>
                            <span v-else class="qlhh-cmp-err-txt">Not Available ({{ sophosCardProductEval.newSku }})</span>
                          </div>
                        </div>
                        <div class="qlhh-cmp-kv-row">
                          <span>Unit MSRP</span>
                          <strong class="qlhh-cmp-price-lg is-emerald">{{ sophosCardProductEval.available ? formatUsdPrice(sophosCardProductEval.unitMsrp) : 'NA' }}</strong>
                        </div>
                        <div class="qlhh-cmp-kv-row">
                          <span>Total MSRP (×{{ sophosCardCalcState.qty }})</span>
                          <strong>{{ sophosCardProductEval.available ? formatUsdPrice(sophosCardProductEval.msrp) : 'NA' }}</strong>
                        </div>
                        <div class="qlhh-cmp-kv-row">
                          <span>Promo Disc (%)</span>
                          <input type="number" min="0" max="100" step="0.5" v-model.number="sophosCardCalcState.productPromoDisc" class="qlhh-cmp-pct-input" />
                        </div>
                        <div class="qlhh-cmp-kv-row">
                          <span>Special Disc (%)</span>
                          <input type="number" min="0" max="100" step="0.5" v-model.number="sophosCardCalcState.productSpecialDisc" class="qlhh-cmp-pct-input" />
                        </div>
                        <div class="qlhh-cmp-kv-row">
                          <span>Reseller Disc</span>
                          <strong class="qlhh-cmp-disc-txt">{{ sophosCardProductEval.available ? `${sophosCardProductEval.resellerDiscPct}%` : '0%' }}</strong>
                        </div>
                        <div class="qlhh-cmp-kv-row is-total">
                          <span>Buy Cost (USD)</span>
                          <strong class="qlhh-cmp-price-lg is-sky">{{ sophosCardProductEval.available ? formatUsdPrice(sophosCardProductEval.buyCost) : '0.00$' }}</strong>
                        </div>
                      </div>

                      <div v-if="sophosCardProductEval.features" class="qlhh-cmp-note-box">
                        <strong>Features:</strong> {{ sophosCardProductEval.features }}
                      </div>
                    </template>
                  </section>
                </div>
              </div>

              <!-- TAB 3: 4 CỘT SO SÁNH ĐA NGUỒN -->
              <div v-else class="qlhh-cmp-sources-grid is-4col">
                <!-- 1. Database -->
                <article class="qlhh-bento-box qlhh-cmp-source-card is-sky">
                  <div class="qlhh-bento-head is-sky">1. Database (hang_hoa)</div>
                  <div class="qlhh-cmp-kv-list tabular-nums">
                    <div class="qlhh-cmp-kv-row"><span>Mã hàng</span><code>{{ cardRefCompareData.item.Ma_hang }}</code></div>
                    <div class="qlhh-cmp-kv-row"><span>SKU Code</span><code>{{ cardRefCompareData.item.sku_code || '-' }}</code></div>
                    <div class="qlhh-cmp-kv-row"><span>Tên hàng</span><strong>{{ cardRefCompareData.item.Ten_hang }}</strong></div>
                    <div class="qlhh-cmp-kv-row"><span>Danh mục</span><span>{{ cardRefCompareData.item.Danh_muc || '-' }}</span></div>
                    <div class="qlhh-cmp-kv-row"><span>Description</span><span>{{ cardRefCompareData.item.Description || '-' }}</span></div>
                    <div class="qlhh-cmp-kv-row"><span>Type / Thời hạn</span><span>{{ cardRefCompareData.item.Type || '-' }} / {{ cardRefCompareData.item.License_duration || '-' }}</span></div>
                    <div class="qlhh-cmp-kv-row"><span>Volume</span><span>{{ cardRefCompareData.item.volume || '-' }}</span></div>
                    <div class="qlhh-cmp-kv-row is-total">
                      <span>Giá bán DB</span>
                      <strong class="qlhh-cmp-price-lg is-sky">{{ formatUsdPrice(cardRefCompareData.dbPrice) }}</strong>
                    </div>
                    <div class="qlhh-cmp-kv-row">
                      <span>Giá nhập / NK</span>
                      <strong>{{ formatUsdPrice(cardRefCompareData.dbGiaNhap) }}</strong>
                    </div>
                  </div>
                </article>

                <!-- 2. File Calculator -->
                <article class="qlhh-bento-box qlhh-cmp-source-card is-emerald">
                  <div class="qlhh-bento-head is-emerald is-between">
                    <span>2. File Calculator</span>
                    <span v-if="cardRefCompareData.calcVersion" class="qlhh-cmp-ver-tag">v{{ cardRefCompareData.calcVersion }}</span>
                  </div>
                  <div v-if="cardRefCompareData.calcFound" class="qlhh-cmp-kv-list tabular-nums">
                    <div class="qlhh-cmp-kv-row"><span>SKU Calculator</span><code>{{ cardRefCompareData.calcAltSku || cardRefCompareData.sku }}</code></div>
                    <div class="qlhh-cmp-kv-row"><span>Product Code</span><strong>{{ cardRefCompareData.calcEntry?.pc || '-' }}</strong></div>
                    <div class="qlhh-cmp-kv-row"><span>Description</span><span>{{ cardRefCompareData.calcEntry?.desc || '-' }}</span></div>
                    <div class="qlhh-cmp-kv-row"><span>Product Type</span><span>{{ cardRefCompareData.calcEntry?.prodType || '-' }}</span></div>
                    <div v-if="cardRefCompareData.calcEffectiveFrom" class="qlhh-cmp-kv-row">
                      <span>Effective</span><span>{{ cardRefCompareData.calcEffectiveFrom }}</span>
                    </div>
                    <div class="qlhh-cmp-kv-row">
                      <span>Dòng</span>
                      <span>
                        #{{ cardRefCompareData.calcRowNum || '-' }}
                        <template v-if="cardRefCompareData.calcFirewallRowNum"> · FW #{{ cardRefCompareData.calcFirewallRowNum }}</template>
                      </span>
                    </div>
                    <div class="qlhh-cmp-kv-row is-total">
                      <span>MSRP Calculator</span>
                      <strong class="qlhh-cmp-price-lg is-emerald">{{ formatUsdPrice(cardRefCompareData.calcMsrp) }}</strong>
                    </div>
                    <div class="qlhh-cmp-kv-row">
                      <span>Buy Cost (S/R/I)</span>
                      <span>{{ formatUsdPrice(cardRefCompareData.calcEntry?.stdAuth || 0) }} / {{ formatUsdPrice(cardRefCompareData.calcEntry?.regAuth || 0) }} / {{ formatUsdPrice(cardRefCompareData.calcEntry?.incAuth || 0) }}</span>
                    </div>
                    <div v-if="cardRefCompareData.gocFound && Math.abs(cardRefCompareData.calcVsGocDiff) >= 0.05" class="qlhh-cmp-kv-row">
                      <span>Chênh File Gốc</span>
                      <strong class="qlhh-cmp-disc-txt">{{ cardRefCompareData.calcVsGocDiff > 0 ? '+' : '' }}{{ formatUsdPrice(cardRefCompareData.calcVsGocDiff) }}</strong>
                    </div>
                  </div>
                  <div v-else class="qlhh-cmp-empty-src">Chưa tìm thấy mã SKU trong File Calculator.</div>
                </article>

                <!-- 3. File Gốc Hãng -->
                <article class="qlhh-bento-box qlhh-cmp-source-card is-emerald">
