                      type="text"
                      class="qlhh-bf-input"
                      :placeholder="bulkRules[tf.key].mode === 'find_replace' ? 'Thay bằng...' : tf.placeholder"
                      @focus="bulkRules[tf.key].enabled = true"
                    />
                    <textarea
                      v-else
                      v-model="bulkRules[tf.key].value"
                      rows="2"
                      class="qlhh-bf-textarea"
                      :placeholder="bulkRules[tf.key].mode === 'find_replace' ? 'Thay bằng...' : tf.placeholder"
