const sophosCardCalcState = ref({
  activeTab: 'firewall', // 'firewall' | 'product' | 'sources'
  calcMode: 'firewall', // 'firewall' | 'product'
  nativeSheet: 'Firewall',
  preferredSku: '',
  partnerLevel: 'Authorized',
  sector: 'Corporate',
  dealType: 'New - Standard',
  termHwBundle: '1-Year',
  termSubscription: '12 MOS',
  qty: 1,
  specialAttribute: 'AU',
  models: ['XGS 2300'],
  showModelPicker: false,
  targetFirewallRowKey: 'hw_appliance',
  family: 'Endpoint_Security',
  productLine: '',
  product: '',
  productSearch: '',
  promoDiscByRow: {},
  specialDiscByRow: {},
  productPromoDisc: 0,
  productSpecialDisc: 0
})

const sophosPartnerLevelOptions = computed(() => {
  return sophosCalcDropDowns.value?.partnerLevels || ['Authorized', 'Silver', 'Gold', 'Platinum_Titanium', 'Select']
})

const sophosSectorOptions = computed(() => {
  const arr = sophosCalcDropDowns.value?.sectors
  return Array.isArray(arr) && arr.length ? arr.map(s => s.label) : ['Corporate', 'Education', 'Government']
})

const sophosDealTypeOptions = computed(() => {
  const arr = sophosCalcDropDowns.value?.dealTypes
  return Array.isArray(arr) && arr.length ? arr.map(d => d.label) : ['New - Standard', 'New - Registered', 'Renewal']
})

const sophosTermOptions = computed(() => {
  const arr = sophosCalcDropDowns.value?.terms
  if (Array.isArray(arr) && arr.length) return arr.map(t => t.label)
  return ['1 MOS', '12 MOS', '24 MOS', '36 MOS', '48 MOS', '60 MOS']
})

const sophosCardUniversalFamilies = computed(() => {
  return sophosCalcDropDowns.value?.universalCatalog?.families || []
})

const sophosCardUniversalLines = computed(() => {
  const fam = sophosCardCalcState.value.family
  return sophosCalcDropDowns.value?.universalCatalog?.linesByFamily?.[fam] || []
})

const sophosCardUniversalProducts = computed(() => {
  const ln = sophosCardCalcState.value.productLine
  return sophosCalcDropDowns.value?.universalCatalog?.productsByLine?.[ln] || []
})

const sophosCardSearchMatchedProducts = computed(() => {
  const q = String(sophosCardCalcState.value.productSearch || '').trim().toLowerCase()
  if (!q) return []
  const pList = sophosCalcRefData.value?.engineRuntime?.product2List || []
  const calcMap = sophosCalcRefData.value?.calcSkus || {}
  const upperQ = q.toUpperCase()
  const exactSkuEntry = calcMap[upperQ]
  const exactPc = exactSkuEntry?.pc ? String(exactSkuEntry.pc).toUpperCase() : ''

  const out = []
  for (const p of pList) {
    if (
      (exactPc && p.pc.toUpperCase() === exactPc) ||
      p.desc.toLowerCase().includes(q) ||
      p.pc.toLowerCase().includes(q) ||
      p.partId.toLowerCase().includes(q)
    ) {
      out.push(p)
      if (out.length >= 40) break
    }
  }
  return out
})

const handleSophosCardFamilyChange = () => {
  const lines = sophosCardUniversalLines.value
  sophosCardCalcState.value.productLine = lines[0] || ''
  handleSophosCardLineChange()
}

const handleSophosCardLineChange = () => {
  const prods = sophosCardUniversalProducts.value
  if (prods.length && !prods.includes(sophosCardCalcState.value.product)) {
    sophosCardCalcState.value.product = prods[0]
  }
  handleSophosCardProductChange()
}

const handleSophosCardProductChange = () => {
  sophosCardCalcState.value.preferredSku = ''
  const calcObj = sophosCalcRefData.value
  if (!calcObj?.engineRuntime) return
  const pDesc = sophosCardCalcState.value.product
  const ctx = inferSophosCalculatorContext(calcObj, '', { Ten_hang: pDesc, Description: pDesc })
  if (ctx.calcType === 'product' && ctx.nativeSheet) {
    sophosCardCalcState.value.nativeSheet = ctx.nativeSheet
  }
  const ev = evaluateProductCalculator(calcObj, {
    partnerLevel: sophosCardCalcState.value.partnerLevel,
    sector: sophosCardCalcState.value.sector,
    dealType: sophosCardCalcState.value.dealType,
    product: pDesc,
    term: sophosCardCalcState.value.termSubscription,
    qty: sophosCardCalcState.value.qty,
    specialAttribute: sophosCardCalcState.value.specialAttribute
  })
  if (ev.specialAttrOptions?.length) {
    const curSpec = sophosCardCalcState.value.specialAttribute
    const ok = ev.specialAttrOptions.some(o => o.code === curSpec || o.label === curSpec)
    if (!ok) {
      sophosCardCalcState.value.specialAttribute = ev.specialAttrOptions[0].code
    }
  }
}

const selectSophosCardSearchedProduct = (prodItem) => {
  if (!prodItem) return
  sophosCardCalcState.value.preferredSku = ''
  const hier = sophosCalcRefData.value?.engineRuntime?.productToHierarchy?.[prodItem.desc]
  if (hier) {
    sophosCardCalcState.value.family = hier.family
    sophosCardCalcState.value.productLine = hier.productLine
  }
  sophosCardCalcState.value.product = prodItem.desc
  sophosCardCalcState.value.productSearch = ''
  handleSophosCardProductChange()
}

const toggleSophosCardFirewallModel = (mdl) => {
  sophosCardCalcState.value.preferredSku = ''
  const cur = [...(sophosCardCalcState.value.models || [])]
  const idx = cur.indexOf(mdl)
  if (idx !== -1) {
    if (cur.length > 1) cur.splice(idx, 1)
  } else if (cur.length < 3) {
    cur.push(mdl)
  } else {
    cur[0] = mdl
  }
  sophosCardCalcState.value.models = cur
}

const setPrimarySophosCardFirewallModel = (mdl) => {
  sophosCardCalcState.value.preferredSku = ''
  const cur = [...(sophosCardCalcState.value.models || [])].filter(m => m !== mdl)
  sophosCardCalcState.value.models = [mdl, ...cur].slice(0, 3)
}

const sophosCardFirewallEval = computed(() => {
  if (!sophosCalcRefData.value?.engineRuntime) {
    return { rows: [], modelFeatures: {}, licensingNotes: '' }
  }
  const st = sophosCardCalcState.value
  return evaluateFirewallCalculator(sophosCalcRefData.value, {
    partnerLevel: st.partnerLevel,
    sector: st.sector,
    dealType: st.dealType,
    termHwBundle: st.termHwBundle,
    termSubscription: st.termSubscription,
    qty: Math.max(1, Number(st.qty) || 1),
    specialAttribute: st.specialAttribute,
    models: st.models?.length ? st.models : ['XGS 2300'],
    promoDiscByRow: st.promoDiscByRow,
    specialDiscByRow: st.specialDiscByRow,
    preferredSku: st.preferredSku || ''
  })
})

const sophosCardProductEval = computed(() => {
  if (!sophosCalcRefData.value?.engineRuntime) return null
  const st = sophosCardCalcState.value
  return evaluateProductCalculator(sophosCalcRefData.value, {
    partnerLevel: st.partnerLevel,
    sector: st.sector,
    dealType: st.dealType,
    family: st.family,
    productLine: st.productLine,
    product: st.product,
    term: st.termSubscription,
    qty: Math.max(1, Number(st.qty) || 1),
    specialAttribute: st.specialAttribute,
    promoDiscPct: Number(st.productPromoDisc) || 0,
    specialDiscPct: Number(st.productSpecialDisc) || 0,
    preferredSku: st.preferredSku || ''
  })
})

const sophosCardActiveCalcSummary = computed(() => {
  const st = sophosCardCalcState.value
  const isProdMode = st.activeTab === 'product' || (st.activeTab === 'sources' && st.calcMode === 'product')
  if (isProdMode && sophosCardProductEval.value) {
    const ev = sophosCardProductEval.value
    const sh = st.nativeSheet && st.nativeSheet !== 'Firewall' ? st.nativeSheet : 'Universal Calculator'
    const rawSh = sophosCalcRefData.value?.calcSheetsRaw?.[sh] || []
    const ov = sophosCalcRefData.value
      ? overlayCalculatedSheetAoa(sophosCalcRefData.value, sh, rawSh, {
          sku: st.preferredSku || ev.sku || '',
          calcType: 'product',
          nativeSheet: sh,
          targetFirewallRowKey: '',
          targetFirewallSheetRow: null,
          partnerLevel: st.partnerLevel,
          sector: st.sector,
          dealType: st.dealType,
          termHwBundle: st.termHwBundle,
          termSubscription: st.termSubscription,
          qty: Math.max(1, Number(st.qty) || 1),
          specialAttribute: st.specialAttribute,
          model: st.models?.[0] || 'XGS 2300',
          models: st.models || ['XGS 2300'],
          family: st.family,
          productLine: st.productLine,
          product: st.product
        })
      : { targetRow: 16, targetColLetter: 'G' }
    return {
      mode: 'product',
      available: ev.available,
      label: ev.productDesc || st.product,
      sku: ev.sku,
      newSku: ev.newSku,
      unitMsrp: ev.unitMsrp,
      msrp: ev.msrp,
      resellerDiscPct: ev.resellerDiscPct,
      buyCost: ev.buyCost,
      calcRowNum: ev.calcRowNum,
      sheetName: sh,
      sheetRowNum: ov.targetRow,
      sheetColLetter: ov.targetColLetter
    }
  }

  const fwRows = sophosCardFirewallEval.value.rows || []
  const hitRow =
    fwRows.find(r => r.key === st.targetFirewallRowKey && r.cells?.[0]?.available) ||
    fwRows.find(r => r.cells?.[0]?.available) ||
    fwRows.find(r => r.key === st.targetFirewallRowKey) ||
    fwRows[0]
  const c0 = hitRow?.cells?.[0]
  return {
    mode: 'firewall',
    available: Boolean(c0?.available),
    label: hitRow ? `${c0?.model || st.models?.[0] || ''} — ${hitRow.label}` : '',
    sku: c0?.sku || '',
    newSku: c0?.newSku || '',
    unitMsrp: c0?.unitMsrp || 0,
    msrp: c0?.msrp || 0,
    resellerDiscPct: c0?.resellerDiscPct || 0,
    buyCost: c0?.buyCost || 0,
    calcRowNum: c0?.calcRowNum || null,
    sheetName: 'Firewall',
    sheetRowNum: hitRow?.sheetRowNum || 29,
    sheetColLetter: 'H'
  }
})

const buildActiveCalcContextForViewer = (overrideSku = '', overrideName = '') => {
  const calcObj = sophosCalcRefData.value
  const cleanOverrideSku = String(overrideSku || '').trim().toUpperCase()

  if (showCardRefCompareModal.value && cardRefCompareData.value?.vendor === 'sophos') {
    const st = sophosCardCalcState.value
    const activeSum = sophosCardActiveCalcSummary.value
    const curCardSku = String(activeSum?.sku || st.preferredSku || cardRefCompareData.value?.sku || '').trim().toUpperCase()
    if (cleanOverrideSku && curCardSku && cleanOverrideSku !== curCardSku && cleanOverrideSku !== String(activeSum?.newSku || '').toUpperCase() && calcObj) {
      return inferSophosCalculatorContext(calcObj, cleanOverrideSku, overrideName ? { Ten_hang: overrideName } : cardRefCompareData.value?.item)
    }
    const isProd = st.activeTab === 'product' || (st.activeTab === 'sources' && st.calcMode === 'product')
    const sh = isProd ? (st.nativeSheet && st.nativeSheet !== 'Firewall' ? st.nativeSheet : 'Universal Calculator') : 'Firewall'
    const fwRows = sophosCardFirewallEval.value.rows || []
    const hitFw =
      fwRows.find(r => r.key === st.targetFirewallRowKey && r.cells?.[0]?.available) ||
      fwRows.find(r => r.cells?.[0]?.available) ||
      fwRows.find(r => r.key === st.targetFirewallRowKey)
    return {
      sku: cleanOverrideSku || curCardSku,
      calcType: isProd ? 'product' : 'firewall',
      nativeSheet: sh,
      targetFirewallRowKey: hitFw?.key || st.targetFirewallRowKey || 'hw_appliance',
      targetFirewallSheetRow: hitFw?.sheetRowNum || 29,
      partnerLevel: st.partnerLevel || 'Authorized',
      sector: st.sector || 'Corporate',
      dealType: st.dealType || 'New - Standard',
      termHwBundle: st.termHwBundle !== undefined && st.termHwBundle !== null ? st.termHwBundle : '1-Year',
      termSubscription: st.termSubscription || '12 MOS',
      qty: Math.max(1, Number(st.qty) || 1),
      specialAttribute: st.specialAttribute || 'AU',
      model: st.models?.[0] || 'XGS 2300',
      models: st.models?.length ? st.models : ['XGS 2300'],
      family: st.family || 'Endpoint_Security',
      productLine: st.productLine || '',
      product: st.product || ''
    }
  }

  if (showImageCheckModal.value) {
    const s = imageCheckSettings.value
    const firstValidCmp = comparisonRows.value?.find(r => r.calcFound && r.sku)
    const firstValidImg = imageCheckRows.value?.find(r => r.available && r.sku && r.sku !== 'Not Available')
    const effSku = cleanOverrideSku || String(firstValidCmp?.calcAltSku || firstValidCmp?.sku || firstValidImg?.sku || '').trim().toUpperCase()
    const effName =
      overrideName ||
      comparisonRows.value?.find(r => r.sku === effSku || r.calcAltSku === effSku)?.name ||
      imageCheckRows.value?.find(r => r.sku === effSku)?.name ||
      ''
    if (calcObj && (effSku || effName)) {
      const inferred = inferSophosCalculatorContext(calcObj, effSku, effName ? { Ten_hang: effName } : undefined)
      const isFw = inferred.calcType === 'firewall'
      const useModel = isFw
        ? (cleanOverrideSku ? (inferred.model || s.model || 'XGS 2300') : (s.model || inferred.model || 'XGS 2300'))
        : inferred.model
      return {
        ...inferred,
        sku: effSku || inferred.sku || '',
        partnerLevel: s.partnerLevel || inferred.partnerLevel || 'Authorized',
        sector: s.sector || inferred.sector || 'Corporate',
        dealType: s.dealType || inferred.dealType || 'New - Standard',
        termHwBundle: s.termHwBundle !== undefined && s.termHwBundle !== null ? s.termHwBundle : (inferred.termHwBundle ?? '1-Year'),
        termSubscription: s.termSubscription || inferred.termSubscription || '12 MOS',
        qty: Math.max(1, Number(s.qty) || inferred.qty || 1),
        specialAttribute: isFw ? (s.specialAttribute || inferred.specialAttribute || 'AU') : inferred.specialAttribute,
        model: useModel,
        models: [useModel]
      }
    }
    const fwRow = getCalcFirewallSheetRowNumForItem(overrideName, cleanOverrideSku) || 29
    return {
      sku: cleanOverrideSku,
      calcType: 'firewall',
      nativeSheet: 'Firewall',
      targetFirewallRowKey: '',
      targetFirewallSheetRow: fwRow,
      partnerLevel: s.partnerLevel || 'Authorized',
      sector: s.sector || 'Corporate',
      dealType: s.dealType || 'New - Standard',
      termHwBundle: s.termHwBundle !== undefined && s.termHwBundle !== null ? s.termHwBundle : '1-Year',
      termSubscription: s.termSubscription || '12 MOS',
      qty: Math.max(1, Number(s.qty) || 1),
      specialAttribute: s.specialAttribute || 'AU',
      model: s.model || 'XGS 2300',
      models: [s.model || 'XGS 2300'],
      family: 'Firewall',
      productLine: '',
      product: ''
    }
  }

  if (calcObj) {
    return inferSophosCalculatorContext(calcObj, cleanOverrideSku, overrideName ? { Ten_hang: overrideName } : undefined)
  }

  return {
    sku: cleanOverrideSku,
    calcType: 'firewall',
    nativeSheet: 'Firewall',
    targetFirewallRowKey: 'hw_appliance',
    targetFirewallSheetRow: 29,
    partnerLevel: 'Authorized',
    sector: 'Corporate',
    dealType: 'New - Standard',
    termHwBundle: '1-Year',
    termSubscription: '12 MOS',
    qty: 1,
    specialAttribute: 'AU',
    model: 'XGS 2300',
    models: ['XGS 2300'],
    family: 'Firewall',
    productLine: '',
    product: ''
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// TRÌNH XEM & ĐỊNH VỊ DÒNG EXCEL (calculate_sophos.xlsx, file_goc_SOPHOS.xlsx & file_trung_gian_SOPHOS.xlsx)
// ═══════════════════════════════════════════════════════════════════════════
const showExcelNavModal = ref(false)
const showCalcHiddenSheets = ref(false)
const excelNavGridWrapRef = ref(null)
const excelNavCopied = ref(false)
const excelNavSearchQuery = ref('')
const excelNavWindowRadius = ref(45)
const excelNavState = ref({
  fileType: 'tg', // 'calc' | 'goc' | 'tg'
  sheet: 'XGS - 1U + 10%',
  targetRow: 1,
  colLetter: 'B',
  colIndex: 1,
  sku: '',
  itemName: ''
})

const letterToColIndex = (letter) => {
  const clean = String(letter || 'A').trim().toUpperCase()
  let col = 0
  for (let i = 0; i < clean.length; i++) {
    col = col * 26 + (clean.charCodeAt(i) - 64)
  }
  return Math.max(0, col - 1)
}

const colIndexToLetter = (colIdx0) => {
  let temp
  let letter = ''
  let col = colIdx0 + 1
  while (col > 0) {
    temp = (col - 1) % 26
    letter = String.fromCharCode(temp + 65) + letter
    col = (col - temp - 1) / 26
  }
  return letter
}

const excelNavCurrentRef = computed(() => {
  const sh = excelNavState.value.sheet || ''
  const cell = `${excelNavState.value.colLetter || 'B'}${excelNavState.value.targetRow || 1}`
  return `'${sh}'!${cell}`
})

const excelNavFullRowRef = computed(() => {
  const sh = excelNavState.value.sheet || ''
  const r = excelNavState.value.targetRow || 1
  return `'${sh}'!${r}:${r}`
})

/**
 * Danh sách tất cả các vị trí (Sheet + Dòng + Ô) của mã SKU hiện tại trong calculate_sophos, file_goc & file_trung_gian
 * Ưu tiên các Sheet tính toán hiển thị (Firewall, Endpoint & Server, Universal Calculator...) đúng như trong file Excel gốc!
 */
const excelNavAllLocationsForSku = computed(() => {
  const sku = String(excelNavState.value.sku || '').trim().toUpperCase()
  const itemName = excelNavState.value.itemName || ''
  const refObj = sophosRefData.value
  const calcObj = sophosCalcRefData.value
  if ((!refObj && !calcObj) || !sku) return []

  const locs = []
  if (calcObj) {
    const ctx = inferSophosCalculatorContext(calcObj, sku, itemName ? { Ten_hang: itemName } : undefined)
    const primarySheet = ctx.nativeSheet || 'Firewall'
    const rawPrimary = calcObj.calcSheetsRaw?.[primarySheet] || []
    const ov = overlayCalculatedSheetAoa(calcObj, primarySheet, rawPrimary, ctx)
    locs.push({
      fileType: 'calc',
      sheet: primarySheet,
      rowNum: ov.targetRow || 29,
      colLetter: ov.targetColLetter || 'H',
      sku,
      itemName
    })

    if (primarySheet !== 'Firewall' && primarySheet !== 'Universal Calculator' && calcObj.calcSheetsRaw?.['Universal Calculator']) {
      const ovUni = overlayCalculatedSheetAoa(calcObj, 'Universal Calculator', calcObj.calcSheetsRaw['Universal Calculator'], ctx)
      locs.push({
        fileType: 'calc',
        sheet: 'Universal Calculator',
        rowNum: ovUni.targetRow || 16,
        colLetter: ovUni.targetColLetter || 'G',
        sku,
        itemName
      })
    }

    const calcMap = calcObj.calcSkus || {}
    const calcEntry = calcMap[sku] || (sku === 'CFRAAB12ZZCAA' ? calcMap['CFRAAB12BANCAA'] : null)
    if (calcEntry && calcEntry.rowNum && (showCalcHiddenSheets.value || excelNavState.value.sheet === 'MSRPs&BuyCost')) {
      locs.push({
        fileType: 'calc',
        sheet: 'MSRPs&BuyCost',
        rowNum: calcEntry.rowNum,
        colLetter: 'B',
        sku,
        itemName
      })
    }
  }

  if (!refObj) return locs
  const gocMap = refObj.gocSkus || {}
  const gocEntry = gocMap[sku] || (sku === 'CFRAAB12ZZCAA' ? gocMap['CFRAAB12BANCAA'] : null)
  if (gocEntry && gocEntry.rowNum) {
    locs.push({
      fileType: 'goc',
      sheet: 'MSRPs&BuyCost',
      rowNum: gocEntry.rowNum,
      colLetter: 'B',
      sku,
      itemName
    })
  }
  const fwRow = getFirewallSheetRowNumForItem(itemName, sku)
  if (fwRow) {
    locs.push({
      fileType: 'goc',
      sheet: 'Firewall',
      rowNum: fwRow,
      colLetter: 'H',
      sku,
      itemName
    })
  }

  const tgLocs = (refObj.tgSkuLocations && refObj.tgSkuLocations[sku]) || []
  for (const tl of tgLocs) {
    locs.push({
      fileType: 'tg',
      sheet: tl.sheet,
      rowNum: tl.rowNum,
      colLetter: tl.colLetter || 'B',
      sku,
      itemName
    })
  }

  const modelStr = String(imageCheckSettings.value.model || '').trim().toUpperCase()
  const lpRow = (refObj.lpSophos || []).find(x => String(x.model || '').toUpperCase() === modelStr)
  if (lpRow && lpRow.rowNum) {
    locs.push({
      fileType: 'tg',
      sheet: 'LP Sophos',
      rowNum: lpRow.rowNum,
      colLetter: 'A',
      sku,
      itemName
    })
  }

  return locs
})

const excelNavSheetNames = computed(() => {
  if (excelNavState.value.fileType === 'calc') {
    const calcObj = sophosCalcRefData.value
    if (!calcObj) return ['Cover', 'Universal Calculator', 'Firewall']
    const vis = Array.isArray(calcObj.calcVisibleSheetNames) && calcObj.calcVisibleSheetNames.length
      ? [...calcObj.calcVisibleSheetNames]
      : (calcObj.calcSheetNames || ['Firewall']).filter(s => s !== 'MSRPs&BuyCost')
    if (showCalcHiddenSheets.value || excelNavState.value.sheet === 'MSRPs&BuyCost') {
      if (!vis.includes('MSRPs&BuyCost')) vis.push('MSRPs&BuyCost')
    }
    return vis
  }
  const refObj = sophosRefData.value
  if (!refObj) return []
  if (excelNavState.value.fileType === 'goc') {
    return ['MSRPs&BuyCost', 'Firewall']
  }
  const tgRaw = refObj.tgSheetsRaw || {}
  return Object.keys(tgRaw)
})

const sheetContainsCurrentSku = (sheetName) => {
  return excelNavAllLocationsForSku.value.some(
    l => l.fileType === excelNavState.value.fileType && l.sheet === sheetName
  )
}

// Danh sách SKU trong MSRPs&BuyCost đã sắp xếp theo rowNum để dựng bảng nhanh
const sortedGocMsrpRowsCache = computed(() => {
  const gocMap = sophosRefData.value?.gocSkus || {}
  const arr = []
  for (const [sku, info] of Object.entries(gocMap)) {
    if (info && info.rowNum) {
      arr.push({ sku, ...info })
    }
  }
  arr.sort((a, b) => a.rowNum - b.rowNum)
  return arr
})

const excelNavRenderedRows = computed(() => {
  const { fileType, sheet, targetRow } = excelNavState.value

  // 0. Nếu đang xem File Calculator mới (calculate_sophos.xlsx)
  if (fileType === 'calc') {
    const calcObj = sophosCalcRefData.value
    if (!calcObj) return []
    if (sheet === 'MSRPs&BuyCost') {
      const allMsrp = calcObj.sortedCalcMsrpRows || []
      const headerRow = {
        rowNum: 2,
        isHeader: true,
        isGroup: false,
        cells: [
          'Product Code',
          'SKU',
          'MSRP/RRP (USD)',
          'Std Authorized',
          'Reg Authorized',
          'Inc Authorized',
          'Std Silver',
          'Reg Silver',
          'Std Gold',
          'Reg Gold',
          'Std Platinum',
          'Reg Platinum',
          'Product Description (Product2)'
        ]
      }
      if (!allMsrp.length) return [headerRow]
      let centerIdx = allMsrp.findIndex(x => x.rowNum === targetRow)
      if (centerIdx === -1) {
        centerIdx = allMsrp.findIndex(x => x.rowNum >= targetRow)
        if (centerIdx === -1) centerIdx = 0
      }
      const radius = excelNavWindowRadius.value
      const startIdx = Math.max(0, centerIdx - radius)
      const endIdx = Math.min(allMsrp.length - 1, centerIdx + radius)
      const out = [headerRow]
      for (let i = startIdx; i <= endIdx; i++) {
        const it = allMsrp[i]
        out.push({
          rowNum: it.rowNum,
          isHeader: false,
          isGroup: false,
          cells: [
            it.pc || '',
            it.sku || '',
            it.msrp ?? '',
            it.stdAuth ?? '',
            it.regAuth ?? '',
            it.incAuth ?? '',
            it.stdSilv ?? '',
            it.regSilv ?? '',
            it.stdGold ?? '',
            it.regGold ?? '',
            it.stdPlat ?? '',
            it.regPlat ?? '',
            it.desc || ''
          ]
        })
      }
      return out
    }

    const rawSheet = (calcObj.calcSheetsRaw && calcObj.calcSheetsRaw[sheet]) || []
    const ctx = buildActiveCalcContextForViewer(excelNavState.value.sku, excelNavState.value.itemName)
    const sheetCtx = resolveSheetContextForWorkbook(calcObj, sheet, ctx, ctx.nativeSheet || sheet)
    const overlaid = overlayCalculatedSheetAoa(calcObj, sheet, rawSheet, sheetCtx)
    return overlaid.rows.map((r, idx) => ({
      rowNum: idx + 1,
      cells: r || [],
      isHeader: sheet === 'Firewall' ? idx + 1 === 20 : idx === 0,
      isGroup: sheet === 'Firewall' && (idx + 1 === 23 || idx + 1 === 31)
    }))
  }

  const refObj = sophosRefData.value
  if (!refObj) return []

  // 1. Nếu đang xem file_trung_gian_SOPHOS.xlsx
  if (fileType === 'tg') {
    const rawRows = (refObj.tgSheetsRaw && refObj.tgSheetsRaw[sheet]) || []
    const colMap = sheet === 'LP Sophos' ? null : resolveSophosTrungGianBomColumnMap(rawRows)
    const headerRowNum = sheet === 'LP Sophos' ? 2 : ((colMap && colMap.headerRowIdx >= 0 ? colMap.headerRowIdx : 3) + 1)
    const skuIdx = colMap && colMap.skuIdx >= 0 ? colMap.skuIdx : 1
    const giaIdx = colMap && colMap.giaIdx >= 0 ? colMap.giaIdx : 5
    return rawRows.map((r, idx) => {
      const rowNum = idx + 1
      const isHeader = rowNum === headerRowNum
      const isGroup = sheet !== 'LP Sophos' && rowNum > headerRowNum && Boolean(r && r[0] && !r[skuIdx] && (r[giaIdx] === null || r[giaIdx] === undefined || r[giaIdx] === ''))
      return {
        rowNum,
        cells: r || [],
        isHeader,
        isGroup
      }
    })
  }

  // 2. Nếu đang xem sheet Firewall của file_goc_SOPHOS.xlsx
  if (fileType === 'goc' && sheet === 'Firewall') {
    const rawFw = refObj.gocFirewallRaw || []
    // Đồng bộ động các dòng cấu hình theo Model đang kiểm tra trên ảnh (VD: XGS 2300)
    const cloned = rawFw.map(r => [...(r || [])])
    const s = imageCheckSettings.value
    if (cloned[3] && s.sector) cloned[3][7] = s.sector
    if (cloned[8] && s.termSubscription) cloned[8][3] = s.termSubscription
    if (cloned[10] && s.qty) cloned[10][3] = s.qty
    if (cloned[12] && s.specialAttribute) cloned[12][3] = s.specialAttribute
    if (cloned[15] && s.model) cloned[15][7] = s.model
    if (cloned[53] && s.description) cloned[53][7] = s.description

    for (const r of imageCheckRows.value) {
      const fwR = getFirewallSheetRowNumForItem(r.name, r.sku)
      if (fwR && cloned[fwR - 1]) {
        cloned[fwR - 1][7] = r.sku
        cloned[fwR - 1][9] = r.available ? r.msrp : 'NA'
        cloned[fwR - 1][11] = r.available ? `${r.resellerDisc}%` : '0%'
      }
    }

    return cloned.map((r, idx) => {
      const rowNum = idx + 1
      const isHeader = rowNum === 18
      const isGroup = rowNum === 21 || rowNum === 29
      return {
        rowNum,
        cells: r,
        isHeader,
        isGroup
      }
    })
  }

  // 3. Nếu đang xem sheet MSRPs&BuyCost của file_goc_SOPHOS.xlsx
  const allMsrp = sortedGocMsrpRowsCache.value
  const headerRow = {
    rowNum: 2,
    isHeader: true,
    isGroup: false,
    cells: [
      'Product Code',
      'SKU',
      'MSRP/RRP (USD)',
      'Std Authorized',
      'Reg Authorized',
      'Inc Authorized',
      'Std Silver',
      'Reg Silver',
      'Std Gold',
      'Reg Gold',
      'Std Platinum',
      'Reg Platinum',
      'Product Description (Product2)'
    ]
  }

  if (!allMsrp.length) return [headerRow]

  let centerIdx = allMsrp.findIndex(x => x.rowNum === targetRow)
  if (centerIdx === -1) {
    centerIdx = allMsrp.findIndex(x => x.rowNum >= targetRow)
    if (centerIdx === -1) centerIdx = 0
  }

  const radius = excelNavWindowRadius.value
  const startIdx = Math.max(0, centerIdx - radius)
  const endIdx = Math.min(allMsrp.length - 1, centerIdx + radius)

  const out = [headerRow]
  for (let i = startIdx; i <= endIdx; i++) {
    const it = allMsrp[i]
    out.push({
      rowNum: it.rowNum,
      isHeader: false,
      isGroup: false,
      cells: [
        it.pc || '',
        it.sku || '',
        it.msrp ?? '',
        it.stdAuth ?? '',
        it.regAuth ?? '',
        it.incAuth ?? '',
        it.stdSilv ?? '',
        it.regSilv ?? '',
        it.stdGold ?? '',
        it.regGold ?? '',
        it.stdPlat ?? '',
        it.regPlat ?? '',
        it.desc || ''
      ]
    })
  }
  return out
})

const excelNavColLetters = computed(() => {
  const rows = excelNavRenderedRows.value
  let maxC = 8
  for (const r of rows) {
    if (r.cells && r.cells.length > maxC) maxC = r.cells.length
  }
  const cols = []
  for (let c = 0; c < maxC; c++) {
    cols.push(colIndexToLetter(c))
  }
  return cols
})

const excelNavSelectedCellText = computed(() => {
  const rowObj = excelNavRenderedRows.value.find(r => r.rowNum === excelNavState.value.targetRow)
  if (!rowObj || !rowObj.cells) return ''
  const val = rowObj.cells[excelNavState.value.colIndex]
  return val !== null && val !== undefined ? String(val) : ''
})

const isSkuLikeCell = (cellVal, activeSku) => {
  if (!cellVal || typeof cellVal !== 'string') return false
  const s = cellVal.trim().toUpperCase()
  if (activeSku && s === String(activeSku).trim().toUpperCase()) return true
  return /^[A-Z0-9][A-Z0-9._-]{5,22}$/.test(s) && /[A-Z]/.test(s) && /\d/.test(s)
}

const isNumericOrMoneyExcelCell = (cellVal) => {
  if (typeof cellVal === 'number' && Number.isFinite(cellVal)) return true
  if (typeof cellVal !== 'string') return false
  const s = cellVal.trim()
  if (!s || s.length > 26) return false
  return /^\$?\s*-?[\d,]+(?:\.\d+)?\s*(?:%|₫|USD)?$/i.test(s)
}

const formatExcelCellValue = (val, rowNum = 0, cIdx = 0, rowCells = null) => {
  if (val === null || val === undefined || val === '') return ''
  if (typeof val === 'number') {
    if (excelNavState.value.fileType === 'calc') {
      const sh = excelNavState.value.sheet
      if (sh === 'MSRPs&BuyCost') {
        if (cIdx >= 2) {
          return '$' + val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
        }
      } else if (cIdx >= 5 && rowNum >= 11) {
        const leftLbl = Array.isArray(rowCells)
          ? String(rowCells[2] ?? rowCells[1] ?? '').trim().toLowerCase()
          : ''
        const isQtyRow =
          leftLbl.startsWith('qty') ||
          leftLbl.startsWith('quantity') ||
          leftLbl.includes('user') ||
          leftLbl.includes('server')
        if (!isQtyRow && val > 1) {
          return '$' + val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
        }
      }
    }
    return Number.isInteger(val)
      ? val.toLocaleString('en-US')
      : val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
  }
  return String(val)
}

const copyExcelCoordToClipboard = async (refStr) => {
  try {
    await navigator.clipboard.writeText(refStr)
    excelNavCopied.value = true
    setTimeout(() => {
      excelNavCopied.value = false
    }, 2600)
  } catch (_) {
    // ignore clipboard permission error
  }
}

const scrollToExcelTargetRow = () => {
  nextTick(() => {
    setTimeout(() => {
      const wrap = excelNavGridWrapRef.value
      if (!wrap) return
      const targetCell = wrap.querySelector('.excel-cell-target')
      const targetEl = targetCell || wrap.querySelector(`#excel-nav-row-${excelNavState.value.targetRow}`)
      if (targetEl) {
        targetEl.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' })
      }
    }, 50)
  })
}

/**
 * Mở Tab mới hiển thị file Excel (file_goc_SOPHOS.xlsx / file_trung_gian_SOPHOS.xlsx)
 * với định dạng màu sắc y hệt file gốc, tự cuộn tới thẳng dòng mục tiêu và highlight toàn dòng.
 */
const openExcelNavigator = (
  { fileType = 'tg', sheet = '', rowNum = 1, colLetter = 'B', sku = '', itemName = '' },
  preOpenedWin = null
) => {
  const colIndex = letterToColIndex(colLetter)
  const cleanSku = String(sku || '').trim().toUpperCase()
  const targetR = Number(rowNum) || 1
  const targetCol = colLetter || 'B'

  excelNavState.value = {
    fileType,
    sheet,
    targetRow: targetR,
    colLetter: targetCol,
    colIndex,
    sku: cleanSku,
    itemName: itemName || ''
  }

  copyExcelCoordToClipboard(`'${sheet}'!${targetR}:${targetR}`)

  try {
    localStorage.setItem(
      'sophos_excel_viewer_context',
      JSON.stringify({
        settings: imageCheckSettings.value,
        rows: imageCheckRows.value,
        calcContext: buildActiveCalcContextForViewer(cleanSku, itemName)
      })
    )
  } catch (_) {}

  const qs = new URLSearchParams({
    file: fileType,
    sheet: sheet,
    row: String(targetR),
    col: targetCol,
    sku: cleanSku,
    name: itemName || ''
  }).toString()
  const viewerUrl = `/template_excel/sophos_excel_viewer.html?${qs}`

  if (preOpenedWin && !preOpenedWin.closed) {
    preOpenedWin.location.href = viewerUrl
    return
  }
  const opened = window.open(viewerUrl, '_blank')
  if (!opened) {
    window.location.href = viewerUrl
  }
}

/**
 * Tìm vị trí trên Sheet tính toán hiển thị của calculate_sophos (Firewall, Endpoint & Server, Universal Calculator...),
 * hoặc trong file Gốc / file Trung Gian rồi mở Tab mới nhảy thẳng tới dòng đó.
 */
const openExcelNavigatorForSku = async (rawSku, preferredFileType = 'tg', itemName = '') => {
  const needsAsyncLoad =
    !sophosRefData.value || (preferredFileType === 'calc' && !sophosCalcRefData.value)
  const preWin = needsAsyncLoad ? window.open('about:blank', '_blank') : null
  if (preWin && preWin.document) {
    preWin.document.write(
      '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đang mở Bảng Sheet...</title></head><body style="margin:0;height:100vh;display:flex;align-items:center;justify-content:center;background:#0f172a;color:#e2e8f0;font-family:system-ui,sans-serif;"><div style="text-align:center;padding:20px;"><div style="font-size:16px;font-weight:700;color:#38bdf8;">⏳ Đang tải dữ liệu Sheet đối chiếu...</div></div></body></html>'
    )
    preWin.document.close()
  }

  try {
    await Promise.all([
      !sophosRefData.value ? loadSophosRefData() : Promise.resolve(),
      preferredFileType === 'calc' && !sophosCalcRefData.value ? loadSophosCalcRefData() : Promise.resolve()
    ])
  } catch (_) {}

  const sku = String(rawSku || '').trim().toUpperCase()
  const refObj = sophosRefData.value || {}
  const calcObj = sophosCalcRefData.value || {}

  if (preferredFileType === 'calc') {
    const calcMap = calcObj.calcSkus || {}
    const targetSku = sku === 'CFRAAB12ZZCAA' && !calcMap[sku] ? 'CFRAAB12BANCAA' : sku
    const ctx =
      showCardRefCompareModal.value && cardRefCompareData.value?.vendor === 'sophos'
        ? buildActiveCalcContextForViewer(targetSku, itemName)
        : inferSophosCalculatorContext(calcObj, targetSku, itemName ? { Ten_hang: itemName } : undefined)
    const targetSheet = ctx.nativeSheet || 'Firewall'
    const rawSheet = (calcObj.calcSheetsRaw && calcObj.calcSheetsRaw[targetSheet]) || []
    const ov = overlayCalculatedSheetAoa(calcObj, targetSheet, rawSheet, ctx)
    return openExcelNavigator(
      {
        fileType: 'calc',
        sheet: targetSheet,
        rowNum: ov.targetRow || 29,
        colLetter: ov.targetColLetter || 'H',
        sku: targetSku,
        itemName
      },
      preWin
    )
  }

  if (preferredFileType === 'tg') {
    const tgLocs = (refObj.tgSkuLocations && refObj.tgSkuLocations[sku]) || []
    if (tgLocs.length > 0) {
      return openExcelNavigator(
        {
          fileType: 'tg',
          sheet: tgLocs[0].sheet,
          rowNum: tgLocs[0].rowNum,
          colLetter: tgLocs[0].colLetter || 'B',
          sku,
          itemName
        },
        preWin
      )
    }
    const modelStr = String(imageCheckSettings.value.model || '').trim().toUpperCase()
    const lpRow = (refObj.lpSophos || []).find(x => String(x.model || '').toUpperCase() === modelStr)
    if (lpRow && lpRow.rowNum) {
      return openExcelNavigator(
        {
          fileType: 'tg',
          sheet: 'LP Sophos',
          rowNum: lpRow.rowNum,
          colLetter: 'A',
          sku,
          itemName
        },
        preWin
      )
    }
  }

  // Nếu chọn mở trực tiếp file sophos-pricelist-reseller_SKU_list (.xlsb)
  if (preferredFileType === 'skulist') {
    const gocMap = refObj.gocSkus || {}
    const gocEntry = gocMap[sku] || (sku === 'CFRAAB12ZZCAA' ? gocMap['CFRAAB12BANCAA'] : null)
    const targetSku = sku === 'CFRAAB12ZZCAA' && !gocMap[sku] ? 'CFRAAB12BANCAA' : sku
    if (gocEntry && gocEntry.skuTabRow) {
      return openExcelNavigator(
        {
          fileType: 'skulist',
          sheet: 'SKU_Tab',
          rowNum: gocEntry.skuTabRow,
          colLetter: 'G',
          sku: targetSku,
          itemName
        },
        preWin
      )
    }
    return openExcelNavigator(
      {
        fileType: 'skulist',
        sheet: 'SKU_Tab',
        rowNum: 8,
        colLetter: 'G',
        sku,
        itemName
      },
      preWin
    )
  }

  // Kiểm tra trong file_goc_SOPHOS
  const gocMap = refObj.gocSkus || {}
  const gocEntry = gocMap[sku] || (sku === 'CFRAAB12ZZCAA' ? gocMap['CFRAAB12BANCAA'] : null)
  if (gocEntry && gocEntry.rowNum) {
    return openExcelNavigator(
      {
        fileType: 'goc',
        sheet: 'MSRPs&BuyCost',
        rowNum: gocEntry.rowNum,
        colLetter: 'B',
        sku,
        itemName
      },
      preWin
    )
  }

  const fwRow = getFirewallSheetRowNumForItem(itemName, sku)
  if (fwRow) {
    return openExcelNavigator(
      {
        fileType: 'goc',
        sheet: 'Firewall',
        rowNum: fwRow,
        colLetter: 'H',
        sku,
        itemName
      },
      preWin
    )
  }

  // Fallback mở sheet đầu tiên
  return openExcelNavigator(
    {
      fileType: preferredFileType,
      sheet: preferredFileType === 'goc' ? 'MSRPs&BuyCost' : 'XGS - 1U + 10%',
      rowNum: 3,
      colLetter: 'B',
      sku,
      itemName
    },
    preWin
  )
}

const switchExcelNavFileType = async (newFileType) => {
  if (excelNavState.value.fileType === newFileType) return
  if (newFileType === 'calc' && !sophosCalcRefData.value) {
    await loadSophosCalcRefData()
  }
  const matchLoc = excelNavAllLocationsForSku.value.find(l => l.fileType === newFileType)
  if (matchLoc) {
    openExcelNavigator(matchLoc)
  } else {
    openExcelNavigator({
      fileType: newFileType,
      sheet: newFileType === 'calc' ? 'Firewall' : (newFileType === 'goc' ? 'MSRPs&BuyCost' : 'XGS - 1U + 10%'),
      rowNum: newFileType === 'calc' ? 29 : (newFileType === 'goc' ? 3 : 6),
      colLetter: newFileType === 'calc' ? 'H' : 'B',
      sku: excelNavState.value.sku,
      itemName: excelNavState.value.itemName
    })
  }
}

const switchExcelNavSheet = (sheetName) => {
  const matchLoc = excelNavAllLocationsForSku.value.find(
    l => l.fileType === excelNavState.value.fileType && l.sheet === sheetName
  )
  if (matchLoc) {
    openExcelNavigator(matchLoc)
    return
  }
  excelNavState.value.sheet = sheetName
  excelNavState.value.targetRow = sheetName === 'LP Sophos' ? 3 : (sheetName === 'Firewall' ? 27 : 6)
  excelNavState.value.colLetter = sheetName === 'LP Sophos' ? 'A' : (sheetName === 'Firewall' ? 'H' : 'B')
  excelNavState.value.colIndex = letterToColIndex(excelNavState.value.colLetter)
  copyExcelCoordToClipboard(excelNavCurrentRef.value)
  scrollToExcelTargetRow()
}

const selectExcelRowAndCell = (rowNum, colIdx, cells) => {
  const colLetter = colIndexToLetter(colIdx)
  excelNavState.value.targetRow = rowNum
  excelNavState.value.colIndex = colIdx
  excelNavState.value.colLetter = colLetter
  const cellVal = cells && cells[colIdx]
  if (isSkuLikeCell(cellVal, '')) {
    excelNavState.value.sku = String(cellVal).trim().toUpperCase()
  }
  copyExcelCoordToClipboard(excelNavCurrentRef.value)
}

const findAndJumpInCurrentExcelSheet = () => {
  const q = String(excelNavSearchQuery.value || '').trim().toUpperCase()
  if (!q) return

  // Nếu nhập số dòng (VD: "57" hoặc "58214")
  if (/^\d+$/.test(q)) {
    const rNum = Number(q)
    excelNavState.value.targetRow = rNum
    scrollToExcelTargetRow()
    return
  }

  // Nếu đang ở MSRPs&BuyCost -> tìm trong toàn bộ mã SKU của gocSkus hoặc calcSkus
  if ((excelNavState.value.fileType === 'goc' || excelNavState.value.fileType === 'calc') && excelNavState.value.sheet === 'MSRPs&BuyCost') {
    const sourceRows = excelNavState.value.fileType === 'calc'
      ? (sophosCalcRefData.value?.sortedCalcMsrpRows || [])
      : sortedGocMsrpRowsCache.value
    const found = sourceRows.find(
      x => x.sku.includes(q) || String(x.pc || '').toUpperCase().includes(q) || String(x.desc || '').toUpperCase().includes(q)
    )
    if (found) {
      excelNavState.value.sku = found.sku
      excelNavState.value.targetRow = found.rowNum
      excelNavState.value.colLetter = 'B'
      excelNavState.value.colIndex = 1
      copyExcelCoordToClipboard(excelNavCurrentRef.value)
      scrollToExcelTargetRow()
    }
    return
  }

  // Tìm trong sheet hiện tại
  for (const rObj of excelNavRenderedRows.value) {
    const cIdx = (rObj.cells || []).findIndex(c => c !== null && c !== undefined && String(c).toUpperCase().includes(q))
    if (cIdx !== -1) {
      selectExcelRowAndCell(rObj.rowNum, cIdx, rObj.cells)
      scrollToExcelTargetRow()
      return
    }
  }
}

const openInDesktopExcel = (fileType) => {
  copyExcelCoordToClipboard(excelNavCurrentRef.value)
  const relPath = fileType === 'goc'
    ? '/template_excel/file_goc_SOPHOS.xlsx'
    : '/template_excel/file_trung_gian_SOPHOS.xlsx'
  const fullUrl = `${window.location.origin}${relPath}`
  window.location.href = `ms-excel:ofe|u|${fullUrl}`
}

const comparisonSummary = computed(() => {
  const rows = comparisonRows.value
  return {
    calcMatch: rows.filter(r => r.calcStatus === 'match').length,
    calcDiff: rows.filter(r => r.calcStatus === 'diff').length,
    calcMissing: rows.filter(r => r.calcStatus === 'missing').length,
    calcChangedVsGoc: rows.filter(r => r.calcFound && r.gocFound && Math.abs(r.calcVsGocDiff) >= 0.05).length,
    gocMatch: rows.filter(r => r.gocStatus === 'match').length,
    gocDiff: rows.filter(r => r.gocStatus === 'diff').length,
    gocMissing: rows.filter(r => r.gocStatus === 'missing').length,
    skuListMatch: rows.filter(r => r.skuListRowNum && r.gocStatus === 'match').length,
    skuListPiCount: rows.filter(r => r.skuListPrevPrice > 0).length,
    tgMatch: rows.filter(r => r.tgStatus === 'match').length,
    tgDiff: rows.filter(r => r.tgStatus === 'diff').length,
    tgMissing: rows.filter(r => r.tgStatus === 'missing').length,
    dbMatch: rows.filter(r => r.dbStatus === 'match').length,
    dbDiff: rows.filter(r => r.dbStatus === 'diff').length,
    dbMissing: rows.filter(r => r.dbStatus === 'missing').length
  }
})

const filteredComparisonRows = computed(() => {
  const mode = compareFilterMode.value
  const rows = comparisonRows.value
  if (mode === 'db_issue') return rows.filter(r => r.dbStatus === 'diff' || r.dbStatus === 'missing')
  if (mode === 'db_diff') return rows.filter(r => r.dbStatus === 'diff')
  if (mode === 'db_missing') return rows.filter(r => r.dbStatus === 'missing')
  if (mode === 'tg_missing') return rows.filter(r => !r.tgFound)
  if (mode === 'calc_issue') return rows.filter(r => !r.calcFound || r.calcStatus === 'diff')
  return rows
})

const selectedComparisonRowsCount = computed(() => {
  return comparisonRows.value.filter(r => r.selected).length
})

const allFilteredCompareSelected = computed(() => {
  const list = filteredComparisonRows.value
  return list.length > 0 && list.every(r => r.selected)
})

const toggleSelectAllFilteredCompare = (checked) => {
  filteredComparisonRows.value.forEach(r => {
    r.selected = checked
  })
}

const selectAllNeedSyncRows = () => {
  comparisonRows.value.forEach(r => {
    r.selected = r.dbStatus !== 'match'
  })
}

const resolveSophosCompareFileMeta = async () => {
  if (imageCheckCurrentFileMeta.value) {
    let url = ''
    if (imageCheckCurrentFileMeta.value.uploadPromise) {
      try {
        url = (await imageCheckCurrentFileMeta.value.uploadPromise) || ''
      } catch (_) {}
    }
    return {
      file_name: imageCheckCurrentFileMeta.value.file_name,
      file_url: url,
      file_type: 'image_check',
      file_uploaded_at: imageCheckCurrentFileMeta.value.file_uploaded_at || new Date().toISOString(),
      ghi_chu_file: 'Ảnh Check Giá Sophos'
    }
  }
  const sMeta = vendorRefFilesMeta.value?.sophos
  if (sMeta && (sMeta.calc_file_name || sMeta.goc_file_name || sMeta.import_file_name)) {
    const fName = sMeta.calc_file_name || sMeta.goc_file_name || sMeta.import_file_name
    const fUrl = sMeta.calc_file_url || sMeta.goc_file_url || sMeta.import_file_url || ''
    const ts = sMeta.calc_updated_at || sMeta.goc_updated_at || sMeta.import_updated_at || sMeta.updated_at
    return {
      file_name: fName,
      file_url: fUrl,
      file_type: 'excel_import',
      file_uploaded_at: ts ? new Date(ts).toISOString() : new Date().toISOString(),
      ghi_chu_file: sMeta.calc_file_name ? `Đồng bộ Đối chiếu Sophos (${sMeta.calc_file_name}${sMeta.calc_version ? ' v' + sMeta.calc_version : ''})` : 'Đồng bộ Đối chiếu Sophos'
    }
  }
  return null
}

/**
 * Xây dựng dữ liệu sản phẩm chuẩn Sophos để thêm mới hoặc cập nhật vào Firebase node `hang_hoa`
 * Chuẩn hóa: Ma_hang = SKU, có cột Description, volume (tách từ range users), License_duration (months), Trang_thai (New/Renewal)
 */
const buildHangHoaPayloadFromCompareRow = (cmpRow, resolvedFileMeta = null) => {
  const modelStr = String(imageCheckSettings.value.model || 'XGS').trim().toUpperCase()
  const danhMuc = modelStr.startsWith('SOPHOS') ? modelStr : `SOPHOS ${modelStr}`
  const isHw = cmpRow.category === 'Hardware Bundles' || cmpRow.sku.startsWith('XG')

  const gocMap = sophosRefData.value?.gocSkus || {}
  const gocEntry = gocMap[cmpRow.sku] || (cmpRow.sku === 'CFRAAB12ZZCAA' ? gocMap['CFRAAB12BANCAA'] : null)
  const calcMap = sophosCalcRefData.value?.calcSkus || {}
  const calcEntry = calcMap[cmpRow.sku] || (cmpRow.sku === 'CFRAAB12ZZCAA' ? calcMap['CFRAAB12BANCAA'] : null)
  const rawDescFromSkuList = calcEntry?.desc || gocEntry?.desc || cmpRow.calcDesc || ''
  const rawTermFromSkuList = gocEntry?.term || imageCheckSettings.value.termSubscription || (isHw ? '' : '12 MOS')
  const rawTransType = gocEntry?.transType || ''

  const parsedMeta = parseSophosDescriptionMetadata(
    rawDescFromSkuList || cmpRow.name,
    rawTermFromSkuList,
    rawTransType,
    isHw
  )

  let payload
  // Nếu đã có trong Database -> giữ nguyên Ma_hang (hoặc chuẩn hóa nếu cần), cập nhật giá + Description + volume + License_duration + Trang_thai
  if (cmpRow.dbItem) {
    const existing = cmpRow.dbItem
    const noteSku = `SKU: ${cmpRow.sku}`
    const oldNote = String(existing.Ghi_chu || '').trim()
    const newNote = oldNote.includes(cmpRow.sku) ? oldNote : [oldNote, noteSku].filter(Boolean).join(' | ')

    payload = buildFirebaseHangHoaPayload({
      ...existing,
      sku_code: cmpRow.sku || existing.sku_code || '',
      Description: parsedMeta.description || existing.Description || '',
      License_duration: parsedMeta.licenseDuration || existing.License_duration || '',
      volume: parsedMeta.volume || existing.volume || '',
      Trang_thai: existing.Trang_thai && existing.Trang_thai !== 'New' && existing.Trang_thai !== 'Renewal' ? existing.Trang_thai : 'Còn hàng',
      Type: parsedMeta.trangThai || existing.Type || 'New',
      Gia_tieu_chuan: cmpRow.targetPrice,
      Don_gia: cmpRow.targetPrice,
      gia_nhap: cmpRow.tgNhapKhau > 0 ? cmpRow.tgNhapKhau : (existing.gia_nhap || 0),
      Ghi_chu: newNote
    })
  } else {
    // Nếu chưa có trong Database -> Tạo mới với Ma_hang = SKU theo chuẩn mới
    let tenHang = ''
    let featuresText = ''

    if (cmpRow.tgMoTa) {
      const lines = String(cmpRow.tgMoTa).trim().split('\n')
      tenHang = lines[0].trim().replace(/:$/, '')
      featuresText = formatFeaturesHtml(cmpRow.tgMoTa)
    } else if (rawDescFromSkuList) {
      tenHang = rawDescFromSkuList
      featuresText = formatFeaturesHtml(`${rawDescFromSkuList}\nSKU: ${cmpRow.sku}`)
    } else if (isHw) {
      tenHang = `Sophos ${modelStr} Hardware Appliance`
      const desc = imageCheckSettings.value.description || `${modelStr} Security Appliance`
      featuresText = formatFeaturesHtml(`${tenHang}:\n${desc}`)
    } else {
      const termStr = imageCheckSettings.value.termSubscription || '12 MOS'
      const years = termStr.includes('12') ? '1-Year' : (termStr.includes('24') ? '2-Year' : (termStr.includes('36') ? '3-Year' : termStr))
      tenHang = `${years} ${cmpRow.name} Subscription for ${modelStr}`
      featuresText = formatFeaturesHtml(`${tenHang}\nSKU: ${cmpRow.sku}`)
    }

    payload = buildFirebaseHangHoaPayload({
      Ma_hang: cmpRow.sku,
      sku_code: cmpRow.sku,
      Ten_hang: tenHang,
      Description: parsedMeta.description || tenHang,
      Main_img: '',
      Ma_nha_cung_cap: 'SOPHOS',
      Ten_nha_cung_cap: 'SOPHOS',
      Mo_ta_chung: '',
      Mo_ta_chi_tiet: '',
      Features: featuresText,
      Danh_muc: danhMuc,
      License_duration: parsedMeta.licenseDuration || (isHw ? '' : '12 months'),
      DVT: isHw ? 'Thiết bị' : 'Gói',
      Gia_tieu_chuan: cmpRow.targetPrice,
      Don_gia: cmpRow.targetPrice,
      Trang_thai: 'Còn hàng',
      Don_vi_tien_te: 'USD',
      Ti_gia: currentSystemUsdRate.value || sophosRefData.value?.tiGiaTrungGian || 26200,
      Thue_VAT: 10,
      Ma_hang_lien_ket: '',
      Ten_hang_lien_ket: '',
      Ghi_chu: `SKU: ${cmpRow.sku}`,
      gia_hardware: 0,
      gia_nhap: cmpRow.tgNhapKhau || 0,
      muc_phan_tram_off: cmpRow.imgDisc || 0,
      Type: parsedMeta.trangThai || 'New',
      thoi_han_bao_hanh: isHw ? '12 months' : '',
      volume: parsedMeta.volume || ''
    })
  }

  if (resolvedFileMeta && resolvedFileMeta.file_name) {
    payload.danh_sach_file = appendFileEntryToProductHistory(
      cmpRow.dbItem?.danh_sach_file || [],
      resolvedFileMeta,
      {
        gia_von: payload.Gia_tieu_chuan,
        don_gia: payload.Don_gia,
        gia_nhap: payload.gia_nhap,
        don_vi_tien_te: payload.Don_vi_tien_te
      }
    )
  }

  return payload
}

/**
 * Đồng bộ 1 dòng đối chiếu vào Firebase (node hang_hoa)
 */
const syncSingleCompareRowToDb = async (cmpRow) => {
  if (!cmpRow) return
  syncingCompareToDb.value = true
  try {
    const resolvedFileMeta = await resolveSophosCompareFileMeta()
    const payload = buildHangHoaPayloadFromCompareRow(cmpRow, resolvedFileMeta)
    if (cmpRow.dbItem && cmpRow.dbItem._firebaseKey) {
      await update(dbRef(database, `hang_hoa/${cmpRow.dbItem._firebaseKey}`), payload)
      showAsyncSuccess('Đã cập nhật giá Database!', `${payload.Ten_hang} → ${formatUsdPrice(payload.Don_gia)}`)
    } else {
      const newRef = push(dbRef(database, 'hang_hoa'))
      await set(newRef, payload)
      if (payload.Danh_muc) {
        await rebuildCategoryLinksFirebase(payload.Danh_muc)
      }
      showAsyncSuccess('Đã thêm vào Database!', `${payload.Ten_hang} (${cmpRow.sku}) → ${formatUsdPrice(payload.Don_gia)}`)
    }
    await fetchData()
    await syncAutoUpdatePriceListsInFirebase()
    await runImagePriceComparison()
  } catch (err) {
    console.error('Lỗi đồng bộ vào Database:', err)
    showAsyncError('Lỗi đồng bộ Firebase', err.message)
  } finally {
    syncingCompareToDb.value = false
  }
}

/**
 * Đồng bộ hàng loạt tất cả các dòng được tick chọn vào Firebase (node hang_hoa)
 */
const syncSelectedCompareRowsToDb = async () => {
  const selectedList = comparisonRows.value.filter(r => r.selected)
  if (!selectedList.length) return

  syncingCompareToDb.value = true
  showAsyncLoading('Đang đồng bộ vào Database...', `Đang xử lý ${selectedList.length} sản phẩm...`)
  try {
    const resolvedFileMeta = await resolveSophosCompareFileMeta()
    const batchUpdates = {}
    const touchedCategories = new Set()
    let updatedCount = 0
    let addedCount = 0

    for (const cmpRow of selectedList) {
      const payload = buildHangHoaPayloadFromCompareRow(cmpRow, resolvedFileMeta)
      if (payload.Danh_muc) touchedCategories.add(payload.Danh_muc)

      if (cmpRow.dbItem && cmpRow.dbItem._firebaseKey) {
        batchUpdates[cmpRow.dbItem._firebaseKey] = payload
        updatedCount++
      } else {
        const newKey = push(dbRef(database, 'hang_hoa')).key
        batchUpdates[newKey] = payload
        addedCount++
      }
    }

    await update(dbRef(database, 'hang_hoa'), batchUpdates)

    for (const cat of touchedCategories) {
      await rebuildCategoryLinksFirebase(cat)
    }

    await fetchData()
    await syncAutoUpdatePriceListsInFirebase()
    await runImagePriceComparison()

    showAsyncSuccess(
      'Đồng bộ Database thành công!',
      `Đã cập nhật: ${updatedCount} SP · Thêm mới: ${addedCount} SP.`
    )
  } catch (err) {
    console.error('Lỗi đồng bộ hàng loạt:', err)
    showAsyncError('Lỗi đồng bộ Database', err.message)
  } finally {
    syncingCompareToDb.value = false
  }
}

/**
 * Xuất bảng kết quả đối chiếu 4 chiều ra file Excel (.xlsx)
 */
const exportComparisonToExcel = () => {
  if (!comparisonRows.value.length) return
  const modelName = imageCheckSettings.value.model || 'SOPHOS'
  const header = [
    'STT',
    'Nhóm',
    'Hạng mục (Ảnh)',
    'Mã SKU',
    'Giá Ảnh (USD)',
    'Discount Ảnh (%)',
