// ═══════════════════════════════════════════════════════════════════════════
// ĐỐI CHIẾU TOÀN BỘ BẢNG GIÁ GỐC ACRONIS (file_goc_acronis.xlsx ⇄ ACRONIS_file_mau_import.xlsx ⇄ DATABASE)
// ═══════════════════════════════════════════════════════════════════════════
const showAcronisCompareModal = ref(false)
const acronisRefData = ref(null)
const loadingAcronisRef = ref(false)
const acronisComparisonRows = ref([])
const acronisCompareSheetFilter = ref('ALL')
const acronisCompareFilterMode = ref('all') // 'all' | 'db_issue' | 'db_diff' | 'db_missing'
const acronisCompareSearch = ref('')
const syncingAcronisCompareToDb = ref(false)

const loadAcronisRefData = async (forceReload = false) => {
  if (!forceReload && (acronisRefData.value || loadingAcronisRef.value)) return acronisRefData.value
  loadingAcronisRef.value = true
  vendorRefLoadError.value.acronis = ''
  try {
    const allMeta = await fetchVendorRefFilesMeta(forceReload)
    const meta = allMeta?.acronis
    if (!meta || !meta.index_url) {
      acronisRefData.value = null
      vendorRefLoadError.value.acronis = 'Chưa có File Gốc Acronis trên Cloudinary. Vui lòng bấm Upload File Mới lên Cloudinary để đối chiếu!'
      return null
    }
    const res = await fetch(meta.index_url)
    if (!res.ok) {
      throw new Error(`Không tải được dữ liệu Acronis từ Cloudinary (HTTP ${res.status})`)
    }
    const raw = await res.json()
    acronisRefData.value = hydrateAcronisRefData(raw)
  } catch (err) {
    console.error('Lỗi tải dữ liệu tham chiếu Acronis từ Cloudinary:', err)
    acronisRefData.value = null
    vendorRefLoadError.value.acronis = err.message || 'Không thể tải dữ liệu tham chiếu Acronis từ Cloudinary.'
  } finally {
    loadingAcronisRef.value = false
  }
  return acronisRefData.value
}

const acronisSheetNames = computed(() => {
  const refObj = acronisRefData.value
  if (refObj && Array.isArray(refObj.sheetNames) && refObj.sheetNames.length) {
    return refObj.sheetNames
  }
  return [...new Set(acronisComparisonRows.value.map(r => r.sheet).filter(Boolean))]
})

const openAcronisExcelNavigator = ({ fileType = 'acronis_goc', sheet = 'Protect Standard', rowNum = 4, colLetter = 'D', sku = '', itemName = '' }) => {
  const qs = new URLSearchParams({
    file: fileType,
    sheet: sheet || 'Protect Standard',
    row: String(rowNum || 4),
    col: colLetter || 'D',
    sku: String(sku || '').trim().toUpperCase(),
    name: itemName || ''
  }).toString()
  window.open(`/template_excel/sophos_excel_viewer.html?${qs}`, '_blank')
}

const matchDatabaseItemForAcronisRow = (entry) => {
  if (!entry) return null
  const maHangUpper = String(entry.maHang || '').trim().toUpperCase()
  const skuUpper = String(entry.sku || '').trim().toUpperCase()
  const skuForUpper = String(entry.skuFor || '').trim().toUpperCase()
  const moTaLower = String(entry.moTa || '').trim().toLowerCase()

  // 1. Khớp chính xác theo Ma_hang = "${skuFor} - ${sku}" hoặc "${sku}"
  if (maHangUpper) {
    const exactMa = items.value.find(it => String(it.Ma_hang || '').trim().toUpperCase() === maHangUpper)
    if (exactMa) return exactMa
  }

  // 2. Khớp theo cả skuFor + sku nằm trong Ma_hang
  if (skuUpper && skuForUpper) {
    const bothMatch = items.value.find(it => {
      const mh = String(it.Ma_hang || '').trim().toUpperCase()
      return mh.includes(skuForUpper) && mh.includes(skuUpper)
    })
    if (bothMatch) return bothMatch
  }

  // 3. Khớp theo SKU đơn lẻ trong Ma_hang hoặc Ghi_chu của các sản phẩm Acronis
  if (skuUpper) {
    const skuMatch = items.value.find(it => {
      const ncc = String(it.Ten_nha_cung_cap || it.Ma_nha_cung_cap || '').toUpperCase()
      const mh = String(it.Ma_hang || '').trim().toUpperCase()
      const gc = String(it.Ghi_chu || '').toUpperCase()
      const tokens = mh.split(/[\s\-|]+/).map(s => s.trim())
      return tokens.includes(skuUpper) || (ncc.includes('ACRONIS') && gc.includes(skuUpper))
    })
    if (skuMatch) return skuMatch
  }

  // 4. Khớp chính xác theo Tên hàng (Mô tả sản phẩm) thuộc NCC Acronis
  if (moTaLower) {
    const nameMatch = items.value.find(it => {
      const ncc = String(it.Ten_nha_cung_cap || it.Ma_nha_cung_cap || '').toUpperCase()
      return ncc.includes('ACRONIS') && String(it.Ten_hang || '').trim().toLowerCase() === moTaLower
    })
    if (nameMatch) return nameMatch
  }

  return null
}

const runAcronisPriceComparison = async () => {
  await loadAcronisRefData()
  if (!items.value.length) {
    await fetchData()
  }

  const refObj = acronisRefData.value || {}
  const gocItems = refObj.gocItems || []
  const mauByMaHang = refObj.mauByMaHang || {}
  const mauBySku = refObj.mauBySku || {}
  const results = []

  for (const g of gocItems) {
    const maKey = String(g.maHang || '').trim().toUpperCase()
    const skuKey = String(g.sku || '').trim().toUpperCase()
    const mauEntry = (maKey && mauByMaHang[maKey]) || (skuKey && mauBySku[skuKey]) || null
    const mauFound = Boolean(mauEntry)
    const mauPrice = mauEntry ? (Number(mauEntry.price) || 0) : 0
    const mauRowNum = mauEntry?.rowNum || null
    const mauSheet = mauEntry?.sheet || g.sheet
    const gocPrice = Number(g.price) || 0

    const mauStatus = !mauFound
      ? 'missing'
      : (Math.abs(gocPrice - mauPrice) < 1 ? 'match' : 'diff')

    const dbItem = matchDatabaseItemForAcronisRow(g)
    let dbStatus = 'missing'
    let dbPrice = 0
    let dbDiff = 0
    let dbDiffPct = 0

    if (dbItem) {
      dbPrice = Number(dbItem.Don_gia) || 0
      dbDiff = dbPrice - gocPrice
      dbDiffPct = gocPrice > 0 ? (dbDiff / gocPrice) * 100 : 0
      dbStatus = Math.abs(dbDiff) < 1 ? 'match' : 'diff'
    }

    results.push({
      id: `${g.sheet}-${g.rowNum}-${g.maHang}`,
      sheet: g.sheet,
      gocRowNum: g.rowNum,
      category: g.category || g.sheet,
      subType: g.subType || '',
      skuFor: g.skuFor || '',
      sku: g.sku || '',
      maHang: g.maHang || '',
      moTa: g.moTa || '',
      features: g.features || '',
      licenseDuration: g.licenseDuration || '',
      type: g.type || '',
      volume: g.volume || '',
      gocPrice,
      mauFound,
      mauEntry,
      mauPrice,
      mauRowNum,
      mauSheet,
      mauStatus,
      dbItem,
      dbPrice,
      dbStatus,
      dbDiff,
      dbDiffPct,
      targetPrice: gocPrice,
      selected: dbStatus !== 'match'
    })
  }

  acronisComparisonRows.value = results
}

const openAcronisCompareModal = async (initialSheet = 'ALL', initialSearch = '') => {
  showAcronisCompareModal.value = true
  acronisCompareSheetFilter.value = initialSheet && typeof initialSheet === 'string' ? initialSheet : 'ALL'
  acronisCompareSearch.value = typeof initialSearch === 'string' ? initialSearch : ''
  acronisCompareFilterMode.value = 'all'
  await runAcronisPriceComparison()
}

const handleCustomAcronisExcelUpload = (e, role = 'goc') => {
  const file = e.target.files && e.target.files[0]
  if (!file) return
  showAsyncLoading('☁️ Đang đọc & đẩy file Acronis lên Cloudinary...', `File: ${file.name}`)
  const reader = new FileReader()
  reader.onload = (evt) => {
    setTimeout(async () => {
      try {
        const data = new Uint8Array(evt.target.result)
        const wb = XLSX.read(data, { type: 'array', cellStyles: true })
        const res = await uploadAndPersistVendorRefWorkbook('acronis', file, wb, role)
        await runAcronisPriceComparison()
        if (showCardRefCompareModal.value && cardRefCompareData.value?.vendor === 'acronis' && cardRefCompareData.value?.item) {
          cardRefCompareData.value = await resolveAcronisCardCompare(cardRefCompareData.value.item)
        }
        showAsyncSuccess('☁️ Đã cập nhật Acronis lên Cloudinary!', res.summaryText)
      } catch (err) {
        console.error('Lỗi upload file Acronis lên Cloudinary:', err)
        showAsyncError('Lỗi cập nhật Cloudinary', err.message)
      }
    }, 50)
  }
  reader.readAsArrayBuffer(file)
  e.target.value = ''
}

const acronisComparisonSummary = computed(() => {
  const rows = acronisComparisonRows.value
  return {
    mauMatch: rows.filter(r => r.mauStatus === 'match').length,
    mauDiff: rows.filter(r => r.mauStatus === 'diff').length,
    mauMissing: rows.filter(r => r.mauStatus === 'missing').length,
    dbMatch: rows.filter(r => r.dbStatus === 'match').length,
    dbDiff: rows.filter(r => r.dbStatus === 'diff').length,
    dbMissing: rows.filter(r => r.dbStatus === 'missing').length
  }
})

const filteredAcronisComparisonRows = computed(() => {
  let list = acronisComparisonRows.value
  if (acronisCompareSheetFilter.value !== 'ALL') {
    list = list.filter(r => r.sheet === acronisCompareSheetFilter.value)
  }
  const mode = acronisCompareFilterMode.value
  if (mode === 'db_issue') list = list.filter(r => r.dbStatus === 'diff' || r.dbStatus === 'missing')
  else if (mode === 'db_diff') list = list.filter(r => r.dbStatus === 'diff')
  else if (mode === 'db_missing') list = list.filter(r => r.dbStatus === 'missing')

  const kw = acronisCompareSearch.value.trim().toLowerCase()
  if (kw) {
    list = list.filter(r =>
      String(r.sku || '').toLowerCase().includes(kw) ||
      String(r.skuFor || '').toLowerCase().includes(kw) ||
      String(r.maHang || '').toLowerCase().includes(kw) ||
      String(r.moTa || '').toLowerCase().includes(kw) ||
      String(r.category || '').toLowerCase().includes(kw)
    )
  }
  return list
})

const selectedAcronisComparisonRowsCount = computed(() => {
  return acronisComparisonRows.value.filter(r => r.selected).length
})

const allFilteredAcronisCompareSelected = computed(() => {
  const list = filteredAcronisComparisonRows.value
  return list.length > 0 && list.every(r => r.selected)
})

const toggleSelectAllFilteredAcronisCompare = (checked) => {
  filteredAcronisComparisonRows.value.forEach(r => {
    r.selected = checked
  })
}

const selectAllNeedSyncAcronisRows = () => {
  acronisComparisonRows.value.forEach(r => {
    r.selected = r.dbStatus !== 'match'
  })
}

const resolveAcronisCompareFileMeta = () => {
  const aMeta = vendorRefFilesMeta.value?.acronis
  if (aMeta && (aMeta.goc_file_name || aMeta.import_file_name || aMeta.mau_file_name)) {
    const fName = aMeta.goc_file_name || aMeta.import_file_name || aMeta.mau_file_name
    const fUrl = aMeta.goc_file_url || aMeta.import_file_url || aMeta.mau_file_url || ''
    const ts = aMeta.goc_updated_at || aMeta.import_updated_at || aMeta.mau_updated_at || aMeta.updated_at
    return {
      file_name: fName,
      file_url: fUrl,
      file_type: 'excel_import',
      file_uploaded_at: ts ? new Date(ts).toISOString() : new Date().toISOString(),
      ghi_chu_file: 'Đồng bộ Đối chiếu Acronis'
    }
  }
  return null
}

const buildHangHoaPayloadFromAcronisCompareRow = (cmpRow, resolvedFileMeta = null) => {
  const maHang = String(cmpRow.maHang || `${cmpRow.skuFor} - ${cmpRow.sku}`).trim()
  const danhMuc = String(cmpRow.category || cmpRow.sheet || 'ACRONIS').trim().toUpperCase()
  const noteParts = []
  if (cmpRow.skuFor && cmpRow.sku && cmpRow.skuFor !== cmpRow.sku) {
    noteParts.push(`SKU For: ${cmpRow.skuFor} | SKU: ${cmpRow.sku}`)
  }
  if (cmpRow.subType) noteParts.push(cmpRow.subType)

  let payload
  if (cmpRow.dbItem) {
    payload = buildFirebaseHangHoaPayload({
      ...cmpRow.dbItem,
      Ma_hang: cmpRow.dbItem.Ma_hang || maHang,
      sku_code: cmpRow.sku || cmpRow.skuFor || cmpRow.dbItem.sku_code || '',
      Ten_hang: cmpRow.moTa || cmpRow.dbItem.Ten_hang,
      Don_gia: cmpRow.targetPrice,
      Gia_tieu_chuan: cmpRow.targetPrice,
      Trang_thai: 'Còn hàng',
      Type: cmpRow.type || cmpRow.dbItem.Type || '',
      License_duration: cmpRow.licenseDuration || cmpRow.dbItem.License_duration || '',
      volume: cmpRow.volume || cmpRow.dbItem.volume || ''
    })
  } else {
    payload = buildFirebaseHangHoaPayload({
      Ma_hang: maHang,
      sku_code: cmpRow.sku || cmpRow.skuFor || '',
      Ten_hang: cmpRow.moTa,
      Description: cmpRow.moTa,
      Main_img: '',
      Ma_nha_cung_cap: 'ACRONIS',
      Ten_nha_cung_cap: 'ACRONIS',
      Mo_ta_chung: '',
      Mo_ta_chi_tiet: '',
      Features: cmpRow.features ? formatFeaturesHtml(cmpRow.features) : '',
      Danh_muc: danhMuc,
      License_duration: cmpRow.licenseDuration || '',
      DVT: 'License',
      Gia_tieu_chuan: cmpRow.targetPrice,
      Don_gia: cmpRow.targetPrice,
      Trang_thai: 'Còn hàng',
      Don_vi_tien_te: 'VND',
      Ti_gia: 1,
      Thue_VAT: 0,
      Ma_hang_lien_ket: '',
      Ten_hang_lien_ket: '',
      Ghi_chu: noteParts.join(' | '),
      gia_hardware: 0,
      gia_nhap: 0,
      muc_phan_tram_off: 0,
      Type: cmpRow.type || '',
      thoi_han_bao_hanh: '',
      volume: cmpRow.volume || ''
    })
  }

  if (resolvedFileMeta && resolvedFileMeta.file_name) {
    payload.danh_sach_file = appendFileEntryToProductHistory(
      cmpRow.dbItem?.danh_sach_file || [],
      resolvedFileMeta,
      {
        gia_von: payload.Gia_tieu_chuan,
        don_gia: payload.Don_gia,
        gia_nhap: payload.gia_nhap,
        don_vi_tien_te: payload.Don_vi_tien_te
      }
    )
  }

  return payload
}

const syncSingleAcronisCompareRowToDb = async (cmpRow) => {
  if (!cmpRow) return
  syncingAcronisCompareToDb.value = true
  try {
    const resolvedFileMeta = resolveAcronisCompareFileMeta()
    const payload = buildHangHoaPayloadFromAcronisCompareRow(cmpRow, resolvedFileMeta)
    if (cmpRow.dbItem && cmpRow.dbItem._firebaseKey) {
      await update(dbRef(database, `hang_hoa/${cmpRow.dbItem._firebaseKey}`), payload)
      showAsyncSuccess('Đã cập nhật giá Acronis!', `${payload.Ten_hang} → ${formatVndPrice(payload.Don_gia)}`)
    } else {
      const newRef = push(dbRef(database, 'hang_hoa'))
      await set(newRef, payload)
      if (payload.Danh_muc) {
        await rebuildCategoryLinksFirebase(payload.Danh_muc)
      }
      showAsyncSuccess('Đã thêm mã Acronis vào DB!', `${payload.Ten_hang} → ${formatVndPrice(payload.Don_gia)}`)
    }
    await fetchData()
    await syncAutoUpdatePriceListsInFirebase()
    await runAcronisPriceComparison()
  } catch (err) {
    console.error('Lỗi đồng bộ Acronis vào Database:', err)
    showAsyncError('Lỗi đồng bộ Firebase', err.message)
  } finally {
    syncingAcronisCompareToDb.value = false
  }
}

const syncSelectedAcronisCompareRowsToDb = async () => {
  const selectedList = acronisComparisonRows.value.filter(r => r.selected)
  if (!selectedList.length) return

  syncingAcronisCompareToDb.value = true
  showAsyncLoading('Đang đồng bộ Acronis vào Database...', `Đang xử lý ${selectedList.length} sản phẩm...`)
  try {
    const resolvedFileMeta = resolveAcronisCompareFileMeta()
    const batchUpdates = {}
    const touchedCategories = new Set()
    let updatedCount = 0
    let addedCount = 0

    for (const cmpRow of selectedList) {
      const payload = buildHangHoaPayloadFromAcronisCompareRow(cmpRow, resolvedFileMeta)
      if (payload.Danh_muc) touchedCategories.add(payload.Danh_muc)

      if (cmpRow.dbItem && cmpRow.dbItem._firebaseKey) {
        batchUpdates[cmpRow.dbItem._firebaseKey] = payload
        updatedCount++
      } else {
        const newKey = push(dbRef(database, 'hang_hoa')).key
        batchUpdates[newKey] = payload
        addedCount++
      }
    }

    await update(dbRef(database, 'hang_hoa'), batchUpdates)

    for (const cat of touchedCategories) {
      await rebuildCategoryLinksFirebase(cat)
    }

    await fetchData()
    await syncAutoUpdatePriceListsInFirebase()
    await runAcronisPriceComparison()

    showAsyncSuccess(
      'Đồng bộ Acronis thành công!',
      `Đã cập nhật: ${updatedCount} mã · Thêm mới: ${addedCount} mã.`
    )
  } catch (err) {
    console.error('Lỗi đồng bộ hàng loạt Acronis:', err)
    showAsyncError('Lỗi đồng bộ Database', err.message)
  } finally {
    syncingAcronisCompareToDb.value = false
  }
}

const exportAcronisComparisonToExcel = () => {
  if (!acronisComparisonRows.value.length) return
  const header = [
    'STT',
    'Sheet',
    'Danh mục',
    'SKU For',
    'SKU',
    'Mô tả sản phẩm',
    'Thời hạn',
    'Type',
    'Volume',
    'Giá file_goc_acronis.xlsx (VNĐ)',
    'Dòng file_goc_acronis',
    'Giá ACRONIS_file_mau_import.xlsx (VNĐ)',
    'Dòng ACRONIS_file_mau',
    'Mã Hàng Trong Database',
    'Giá Database (VNĐ)',
    'Chênh Lệch DB (VNĐ)',
    'Trạng Thái Đối Chiếu DB'
  ]

  const rowsData = filteredAcronisComparisonRows.value.map((r, idx) => [
    idx + 1,
    r.sheet,
    r.category,
    r.skuFor,
    r.sku,
    r.moTa,
    r.licenseDuration,
    r.type,
    r.volume,
    r.gocPrice,
    r.gocRowNum,
    r.mauFound ? r.mauPrice : 'Chưa có',
    r.mauRowNum || '',
    r.dbItem ? r.dbItem.Ma_hang : 'Chưa có trong DB',
    r.dbItem ? r.dbPrice : '',
    r.dbItem ? Math.round(r.dbDiff) : '',
    r.dbStatus === 'match'
      ? 'Khớp giá DB'
      : (r.dbStatus === 'diff'
          ? `Lệch ${r.dbDiff > 0 ? '+' : ''}${Math.round(r.dbDiff).toLocaleString('vi-VN')} ₫ (${r.dbDiffPct.toFixed(1)}%)`
          : 'Thiếu trong DB')
  ])

  const ws = XLSX.utils.aoa_to_sheet([
    ['BÁO CÁO ĐỐI CHIẾU BẢNG GIÁ GỐC ACRONIS (file_goc_acronis.xlsx ⇄ ACRONIS_file_mau_import.xlsx ⇄ Database)'],
    [],
    header,
    ...rowsData
  ])
  ws['!cols'] = [
    { wch: 6 }, { wch: 22 }, { wch: 32 }, { wch: 16 },
    { wch: 16 }, { wch: 52 }, { wch: 14 }, { wch: 14 },
    { wch: 16 }, { wch: 22 }, { wch: 16 }, { wch: 24 },
    { wch: 16 }, { wch: 28 }, { wch: 18 }, { wch: 18 }, { wch: 28 }
  ]

  const wb = XLSX.utils.book_new()
  XLSX.utils.book_append_sheet(wb, ws, 'Doi_Chieu_Acronis')
  XLSX.writeFile(wb, 'Doi_Chieu_Gia_Acronis_file_goc_acronis.xlsx')
}

// ═══════════════════════════════════════════════════════════════════════════
// ĐỐI CHIẾU TRỰC TIẾP TRÊN CARD HÀNG HÓA (SOPHOS / KASPERSKY / ACRONIS) VỚI FILE GỐC
// ═══════════════════════════════════════════════════════════════════════════
const showCardRefCompareModal = ref(false)
const cardRefCompareLoading = ref(false)
const cardRefCompareData = ref(null)
const syncingCardRefToDb = ref(false)

/**
 * Xác định một Card hàng hóa có thuộc SOPHOS, KASPERSKY hoặc ACRONIS không
 * @returns {'sophos' | 'kaspersky' | 'acronis' | null}
 */
const getCardVendorType = (item) => {
  if (!item) return null
  const ncc = String(item.Ten_nha_cung_cap || item.Ma_nha_cung_cap || '').trim().toUpperCase()
  const dm = String(item.Danh_muc || '').trim().toUpperCase()
  const th = String(item.Ten_hang || '').trim().toUpperCase()
  const mh = String(item.Ma_hang || '').trim().toUpperCase()

  if (ncc.includes('KASPERSKY') || dm.includes('KASPERSKY') || th.startsWith('KASPERSKY') || /^KL\d{4}/i.test(mh)) {
    return 'kaspersky'
  }
  if (ncc.includes('ACRONIS') || dm.includes('ACRONIS') || th.includes('ACRONIS')) {
    return 'acronis'
  }
  if (
    ncc.includes('SOPHOS') ||
    dm.includes('SOPHOS') ||
    th.includes('SOPHOS') ||
    mh.includes('SOPHOS') ||
    /\b(XGS?\s*\d{2,4}W?|SFV[\s-]*(?:UNLIMITED|\d+C\d+)|XRP\d+|SD-RED\s*\d+|CS(?:101|110|210|1010)|AP6\s*\d{3}|CZTNA|MDRNDU)\b/i.test(`${th} ${mh}`)
  ) {
    return 'sophos'
  }
  return null
}

const resolveSophosCardCompare = async (item) => {
  await fetchVendorRefFilesMeta()
  await Promise.all([
    loadSophosRefData(),
    loadSophosCalcRefData()
  ])
  const sRef = sophosRefData.value || { gocSkus: {}, trungGianItems: [], lpSophos: [], tgSkuLocations: {} }
  const gocMap = sRef.gocSkus || {}
  const calcMap = sophosCalcRefData.value?.calcSkus || {}
  const calcDd = sophosCalcRefData.value?.engineRuntime?.dropDowns
  const tgList = sRef.trungGianItems || []
  const lpList = sRef.lpSophos || []
  const tgLocMap = sRef.tgSkuLocations || {}

  const mh = String(item.Ma_hang || '').trim().toUpperCase()
  const itemSkuCode = String(item.sku_code || '').trim().toUpperCase()
  const gc = String(item.Ghi_chu || '')
  const skuFromNote = ((gc.match(/SKU:\s*([A-Z0-9]+)/i) || [])[1] || '').toUpperCase()
  const embeddedCalcSku = sophosCalcRefData.value ? extractValidatedEmbeddedCalcSku(item, sophosCalcRefData.value) : ''
  const itemVolRange = extractVolumeRangeFromSophosItem(item)

  let sku = ''
  if (itemSkuCode && (calcMap[itemSkuCode] || gocMap[itemSkuCode])) sku = itemSkuCode
  else if (calcMap[mh] || gocMap[mh]) sku = mh
  else if (skuFromNote && (calcMap[skuFromNote] || gocMap[skuFromNote])) sku = skuFromNote
  else if (embeddedCalcSku) sku = embeddedCalcSku
  else if (itemSkuCode) sku = itemSkuCode

  const matchesTgVolRange = (t) => {
    if (!itemVolRange) return true
    const tSku = String(t?.sku || '').trim().toUpperCase()
    const tText = `${t?.description || ''} ${t?.moTa || ''}`
    if (tText.includes(`${itemVolRange.min}-${itemVolRange.max}`)) return true
    const mappedNew = (tSku && calcDd?.newSkuByOldSku?.[tSku]) || (tSku.length === 14 ? tSku : '')
    if (mappedNew.length === 14 && calcDd?.volBandTables) {
      const bCode = mappedNew.slice(8, 10)
      if (bCode !== 'ZZ') {
        const tbl = calcDd.volBandTables[bCode[0]] || []
        const hitBand = tbl.find(b => b[2] === bCode)
        if (hitBand) {
          return itemVolRange.min >= hitBand[0] && itemVolRange.min <= hitBand[1]
        }
      }
    }
    return false
  }

  const itemModelMatch = `${item.Ma_hang || ''} ${item.Ten_hang || ''} ${item.Danh_muc || ''}`.match(/\b(XGS?\s*\d{2,4}w?)\b/i)
  const itemModelNorm = itemModelMatch ? itemModelMatch[1].replace(/\s+/g, '').toUpperCase() : ''
  const matchesTgModel = (t) => {
    if (!itemModelNorm) return true
    const tText = `${t?.group || ''} ${t?.model || ''} ${t?.description || ''} ${t?.moTa || ''}`
    const m = tText.match(/\b(XGS?\s*\d{2,4}w?)\b/i)
    if (!m) return true
    return m[1].replace(/\s+/g, '').toUpperCase() === itemModelNorm
  }

  // Tìm trong file_trung_gian_SOPHOS (có kiểm tra đúng dải số lượng Volume Band & Model Firewall nếu có)
  let tgEntry = tgList.find(t => (sku && t.sku === sku) || t.sku === mh || (skuFromNote && t.sku === skuFromNote)) || null
  if (!tgEntry) {
    const dmLower = String(item.Danh_muc || '').trim().toLowerCase()
    const thLower = String(item.Ten_hang || '').trim().replace(/:$/, '').toLowerCase()
    // 1. Khớp chính xác group + dòng đầu moTa + đúng Volume Band
    tgEntry = tgList.find(t => {
      const grp = String(t.group || '').trim().toLowerCase()
      const firstLine = String(t.moTa || '').split('\n')[0].trim().replace(/:$/, '').toLowerCase()
      return grp === dmLower && firstLine === thLower && matchesTgVolRange(t) && matchesTgModel(t)
    }) || null
    // 2. Khớp group + moTa chứa Ten_hang + đúng Volume Band
    if (!tgEntry && dmLower && thLower) {
      tgEntry = tgList.find(t => {
        const grp = String(t.group || '').trim().toLowerCase()
        return grp === dmLower && String(t.moTa || '').toLowerCase().includes(thLower) && matchesTgVolRange(t) && matchesTgModel(t)
      }) || null
    }
    // 3. Khớp dòng đầu moTa trên toàn bộ danh sách + đúng Volume Band + đúng Model Firewall
    if (!tgEntry && thLower) {
      tgEntry = tgList.find(t => {
        const firstLine = String(t.moTa || '').split('\n')[0].trim().replace(/:$/, '').toLowerCase()
        return firstLine === thLower && matchesTgVolRange(t) && matchesTgModel(t)
      }) || null
    }
  }

  if (tgEntry && !sku) {
    sku = String(tgEntry.sku || '').trim().toUpperCase()
  }
  if (!sku && /^[A-Z0-9]{8,16}$/.test(mh) && /\d/.test(mh)) {
    sku = mh
  }

  // Khởi tạo ngữ cảnh Calculator đúng y như khi người dùng chọn cấu hình trên file calculate_sophos.xlsx
  let calcNativeSheet = 'Firewall'
  let calcSheetRowNum = null
  let calcSheetColLetter = 'H'
  if (sophosCalcRefData.value?.engineRuntime) {
    const inferredCtx = inferSophosCalculatorContext(sophosCalcRefData.value, sku, item)
    sophosCardCalcState.value = {
      activeTab: inferredCtx.calcType === 'firewall' ? 'firewall' : 'product',
      calcMode: inferredCtx.calcType === 'firewall' ? 'firewall' : 'product',
      nativeSheet: inferredCtx.nativeSheet || 'Firewall',
      preferredSku: inferredCtx.sku || sku || '',
      partnerLevel: inferredCtx.partnerLevel || 'Authorized',
      sector: inferredCtx.sector || 'Corporate',
      dealType: inferredCtx.dealType || 'New - Standard',
      termHwBundle: inferredCtx.termHwBundle || '1-Year',
      termSubscription: inferredCtx.termSubscription || '12 MOS',
      qty: inferredCtx.qty || 1,
      specialAttribute: inferredCtx.specialAttribute || 'AU',
      models: inferredCtx.models?.length ? inferredCtx.models : [inferredCtx.model || 'XGS 2300'],
      showModelPicker: false,
      targetFirewallRowKey: inferredCtx.targetFirewallRowKey || 'hw_appliance',
      family: inferredCtx.family || 'Endpoint_Security',
      productLine: inferredCtx.productLine || '',
      product: inferredCtx.product || '',
      productSearch: '',
      promoDiscByRow: {},
      specialDiscByRow: {},
      productPromoDisc: 0,
      productSpecialDisc: 0
    }
    const activeSum = sophosCardActiveCalcSummary.value
    if (activeSum) {
      calcNativeSheet = activeSum.sheetName || inferredCtx.nativeSheet || 'Firewall'
      calcSheetRowNum = activeSum.sheetRowNum || null
      calcSheetColLetter = activeSum.sheetColLetter || 'H'
      if (activeSum.available && activeSum.sku && activeSum.sku !== 'Not Available') {
        if (!sku || (!calcMap[sku] && calcMap[activeSum.sku])) {
          sku = String(activeSum.sku).trim().toUpperCase()
        }
      }
    }
  }

  // Tra cứu trong File Calculator mới (calculate_sophos)
  const calcEntry = (sku && calcMap[sku])
    ? calcMap[sku]
    : (sku === 'CFRAAB12ZZCAA' ? calcMap['CFRAAB12BANCAA'] : null)
  const calcAltSku = (sku === 'CFRAAB12ZZCAA' && !calcMap[sku] && calcMap['CFRAAB12BANCAA']) ? 'CFRAAB12BANCAA' : ''
  const calcFound = Boolean(calcEntry)
  const calcMsrp = calcEntry ? (Number(calcEntry.msrp) || 0) : 0
  const calcRowNum = calcEntry?.rowNum || null
  const calcFirewallRowNum = getCalcFirewallSheetRowNumForItem(item.Ten_hang, sku)
  const calcVersion = sophosCalcRefData.value?.version || vendorRefFilesMeta.value?.sophos?.calc_version || ''
  const calcEffectiveFrom = sophosCalcRefData.value?.effectiveFrom || vendorRefFilesMeta.value?.sophos?.calc_effective_from || ''

  const gocEntry = (sku && gocMap[sku])
    ? gocMap[sku]
    : (sku === 'CFRAAB12ZZCAA' ? gocMap['CFRAAB12BANCAA'] : null)
  const gocFound = Boolean(gocEntry)
  const gocMsrp = gocEntry ? (Number(gocEntry.msrp) || 0) : 0
  const gocRowNum = gocEntry?.rowNum || null
  const skuListRowNum = gocEntry?.skuTabRow || null
  const skuListHwRowNum = gocEntry?.hwRow || null
  const calcVsGocDiff = (calcFound && gocFound) ? Number((calcMsrp - gocMsrp).toFixed(2)) : 0

  const tgLocations = (sku && tgLocMap[sku])
    ? [...tgLocMap[sku]]
    : (tgEntry && tgEntry.rowNum
        ? [{ sheet: tgEntry.sheet, rowNum: tgEntry.rowNum, colIndex: 1, colLetter: 'B', cell: tgEntry.cell || `B${tgEntry.rowNum}` }]
        : [])
  const tgFound = Boolean(tgEntry || tgLocations.length > 0)
  const tgMsrp = tgEntry ? (Number(tgEntry.msrp) || 0) : 0
  const tgSheet = tgEntry?.sheet || tgLocations[0]?.sheet || ''
  const tgRowNum = tgEntry?.rowNum || tgLocations[0]?.rowNum || null
  const tgGroup = tgEntry?.group || ''

  // Suy luận model XGS để lấy LP Sophos & Firewall Row
  const combinedModelText = `${item.Danh_muc || ''} ${tgGroup || ''} ${item.Ten_hang || ''}`
  const modelMatch = combinedModelText.match(/\b(XGS?\s*\d{2,4}w?)\b/i)
  const modelStr = modelMatch ? modelMatch[1].toUpperCase().replace(/\bXGS(\d)/i, 'XGS $1').replace(/\s+/g, ' ') : ''
  const lpRow = modelStr ? lpList.find(x => String(x.model || '').toUpperCase() === modelStr) : null
  const lpRowNum = lpRow?.rowNum || null
  let lpOldUsd = 0
  const thLower = String(item.Ten_hang || '').toLowerCase()
  if (lpRow) {
    if (sku.startsWith('XG') || thLower.includes('hardware appliance')) lpOldUsd = Number(lpRow.oldHwUsd) || 0
    else if (sku.startsWith('XS') || thLower.includes('xstream protection')) lpOldUsd = Number(lpRow.oldXstream1YUsd) || 0
    else if (sku.startsWith('SP') || thLower.includes('standard protection')) lpOldUsd = Number(lpRow.oldStd1YUsd) || 0
  }
  if (!lpOldUsd && gocEntry?.prevPrice) {
    lpOldUsd = Number(gocEntry.prevPrice) || 0
  }

  const tgNhapKhau = tgEntry
    ? (Number(tgEntry.nhapKhau) || 0)
    : (lpRow && sku.startsWith('XG') ? (Number(lpRow.nhapKhauUsd) || 0) : 0)

  const gocFirewallRowNum = getFirewallSheetRowNumForItem(item.Ten_hang, sku)

  const dbPrice = Number(item.Don_gia) || 0
  const dbGiaNhap = Number(item.gia_nhap) || 0
  // Ưu tiên lấy giá chuẩn từ calculate_sophos (nếu tìm thấy mã), fallback về file_goc_SOPHOS rồi file_trung_gian
  const refPrice = (calcFound && calcMsrp > 0)
    ? calcMsrp
    : ((gocFound && gocMsrp > 0) ? gocMsrp : (tgFound && tgMsrp > 0 ? tgMsrp : 0))
  const refSourceLabel = (calcFound && calcMsrp > 0)
    ? 'calculate_sophos'
    : ((gocFound && gocMsrp > 0) ? 'file_goc_SOPHOS' : (tgFound && tgMsrp > 0 ? 'file_trung_gian' : 'File Gốc'))
  const priceDiff = refPrice > 0 ? (dbPrice - refPrice) : 0
  const priceDiffPct = refPrice > 0 ? (priceDiff / refPrice) * 100 : 0

  let status = 'not_found'
  if (calcFound || gocFound || tgFound) {
    status = Math.abs(priceDiff) < 0.05 ? 'match' : 'diff'
  }

  return {
    vendor: 'sophos',
    item,
    sku,
    calcFound,
    calcEntry,
    calcAltSku,
    calcMsrp,
    calcRowNum,
    calcFirewallRowNum,
    calcNativeSheet,
    calcSheetRowNum,
    calcSheetColLetter,
    calcVersion,
    calcEffectiveFrom,
    calcVsGocDiff,
    gocFound,
    gocEntry,
    gocMsrp,
    gocRowNum,
    skuListRowNum,
    skuListHwRowNum,
    gocFirewallRowNum,
    tgFound,
    tgEntry,
    tgMsrp,
    tgNhapKhau,
    tgSheet,
    tgRowNum,
    tgGroup,
    tgLocations,
    lpRowNum,
    lpOldUsd,
    dbPrice,
    dbGiaNhap,
    refPrice,
    refSourceLabel,
    priceDiff,
    priceDiffPct,
    status
  }
}

const resolveKasperskyCardCompare = async (item) => {
  await loadKasRefData()
  const kRef = kasRefData.value || {}
  const gocPivotMap = kRef.gocPivotBySku || {}
  const mauPivotMap = kRef.mauPivotBySku || {}
  const gocSaleMap = kRef.gocSaleBySkuBand || {}
  const mauSaleMap = kRef.mauSaleBySkuBand || {}

  const mh = String(item.Ma_hang || '').trim()
  const itemSkuCode = String(item.sku_code || '').trim().toUpperCase()
  const gc = String(item.Ghi_chu || '').trim()
  const klTokens = [
    ...(itemSkuCode ? [itemSkuCode] : []),
    ...(mh.match(/KL\d{4}[A-Z0-9*]+/gi) || []),
    ...(gc.match(/KL\d{4}[A-Z0-9*]+/gi) || [])
  ].map(s => s.toUpperCase())

  let sku = klTokens.find(t => t.includes('*') && gocPivotMap[t])
    || klTokens.find(t => gocPivotMap[t])
    || klTokens.find(t => t.includes('*'))
    || klTokens[0]
    || ''

  let band = String(item.volume || '').trim()
  if (!band) {
    const bandMatch = mh.match(/(Band\s+[A-Z0-9]+:\s*\d+(?:-\d+|\+)?)/i)
      || String(item.Ten_hang || '').match(/(Band\s+[A-Z0-9]+:\s*\d+(?:-\d+|\+)?)/i)
    if (bandMatch) band = bandMatch[1].trim()
  }

  const gocPivotEntry = (sku && gocPivotMap[sku]) || null
  const mauPivotEntry = (sku && mauPivotMap[sku]) || null
  const skuBandKey = `${sku}||${band}`
  const gocSaleEntry = gocSaleMap[skuBandKey] || null
  const mauSaleEntry = mauSaleMap[skuBandKey] || null

  const posCode = gocSaleEntry?.posCode
    || mauSaleEntry?.posCode
    || klTokens.find(t => !t.includes('*') && t !== sku)
    || ''

  const gocPivotRow = gocPivotEntry?.rowNum || null
  const gocPivotColIdx = (gocPivotEntry?.bandCols && gocPivotEntry.bandCols[band] !== undefined)
    ? gocPivotEntry.bandCols[band]
    : 9
  const gocPivotColLetter = colIndexToLetter(gocPivotColIdx)
  const gocSaleRow = gocSaleEntry?.rowNum || null
  const gocPrice = Number(gocPivotEntry?.prices?.[band] ?? gocSaleEntry?.price ?? 0)
  const gocFound = Boolean(gocPivotEntry || gocSaleEntry)

  const mauPivotRow = mauPivotEntry?.rowNum || null
  const mauPivotColIdx = (mauPivotEntry?.bandCols && mauPivotEntry.bandCols[band] !== undefined)
    ? mauPivotEntry.bandCols[band]
    : gocPivotColIdx
  const mauPivotColLetter = colIndexToLetter(mauPivotColIdx)
  const mauSaleRow = mauSaleEntry?.rowNum || null
  const mauPrice = Number(mauPivotEntry?.prices?.[band] ?? mauSaleEntry?.price ?? 0)
  const mauFound = Boolean(mauPivotEntry || mauSaleEntry)

  const dbPrice = Number(item.Don_gia) || 0
  const refPrice = gocFound && gocPrice > 0 ? gocPrice : (mauFound && mauPrice > 0 ? mauPrice : 0)
  const priceDiff = refPrice > 0 ? (dbPrice - refPrice) : 0
  const priceDiffPct = refPrice > 0 ? (priceDiff / refPrice) * 100 : 0
  const mauIsOldPre10 = mauPrice > 0 && refPrice > 0 && Math.abs(mauPrice * 1.1 - refPrice) / refPrice < 0.015

  let status = 'not_found'
  if (gocFound || mauFound) {
    status = Math.abs(priceDiff) < 1 ? 'match' : 'diff'
  }

  return {
    vendor: 'kaspersky',
    item,
    sku,
    posCode,
    band,
    gocFound,
    gocPivotEntry,
    gocSaleEntry,
    gocPivotRow,
    gocPivotColLetter,
    gocSaleRow,
    gocPrice,
    mauFound,
    mauPivotRow,
    mauPivotColLetter,
    mauSaleRow,
    mauPrice,
    mauIsOldPre10,
    dbPrice,
    refPrice,
    priceDiff,
    priceDiffPct,
    status
  }
}

const resolveAcronisCardCompare = async (item) => {
  await loadAcronisRefData()
  const aRef = acronisRefData.value || {}
  const gocByMaHang = aRef.gocByMaHang || {}
  const gocBySku = aRef.gocBySku || {}
  const gocBySkuFor = aRef.gocBySkuFor || {}
  const gocItems = aRef.gocItems || []
  const mauByMaHang = aRef.mauByMaHang || {}
  const mauBySku = aRef.mauBySku || {}
  const mauBySkuFor = aRef.mauBySkuFor || {}

  const mh = String(item.Ma_hang || '').trim().toUpperCase()
  const itemSkuCode = String(item.sku_code || '').trim().toUpperCase()
  const thLower = String(item.Ten_hang || '').trim().toLowerCase()
  const parts = mh.split('-').map(s => s.trim()).filter(Boolean)

  let gocEntry = gocByMaHang[mh] || null
  if (!gocEntry && itemSkuCode) {
    gocEntry = gocBySku[itemSkuCode] || gocBySkuFor[itemSkuCode] || null
  }
  if (!gocEntry && parts.length >= 2) {
    gocEntry = gocBySku[parts[1]] || gocBySkuFor[parts[0]] || null
  }
  if (!gocEntry && parts.length === 1) {
    gocEntry = gocBySku[parts[0]] || gocBySkuFor[parts[0]] || null
  }
  if (!gocEntry && thLower) {
    gocEntry = gocItems.find(x => String(x.moTa || '').trim().toLowerCase() === thLower) || null
  }

  const sku = gocEntry?.sku || (parts.length >= 2 ? parts[1] : (parts[0] || ''))
  const skuFor = gocEntry?.skuFor || (parts.length >= 2 ? parts[0] : '')
  const maKey = gocEntry?.maHang ? String(gocEntry.maHang).toUpperCase() : mh

  const mauEntry = mauByMaHang[maKey]
    || (sku && mauBySku[sku.toUpperCase()])
    || (skuFor && mauBySkuFor[skuFor.toUpperCase()])
    || null

  const gocFound = Boolean(gocEntry)
  const gocPrice = gocEntry ? (Number(gocEntry.price) || 0) : 0
  const gocRowNum = gocEntry?.rowNum || null
  const sheet = gocEntry?.sheet || mauEntry?.sheet || 'Protect Standard'

  const mauFound = Boolean(mauEntry)
  const mauPrice = mauEntry ? (Number(mauEntry.price) || 0) : 0
  const mauRowNum = mauEntry?.rowNum || null
  const mauSheet = mauEntry?.sheet || sheet

  const dbPrice = Number(item.Don_gia) || 0
  const refPrice = gocFound && gocPrice > 0 ? gocPrice : (mauFound && mauPrice > 0 ? mauPrice : 0)
  const priceDiff = refPrice > 0 ? (dbPrice - refPrice) : 0
  const priceDiffPct = refPrice > 0 ? (priceDiff / refPrice) * 100 : 0

  let status = 'not_found'
  if (gocFound || mauFound) {
    status = Math.abs(priceDiff) < 1 ? 'match' : 'diff'
  }

  const catLower = String(gocEntry?.category || item.Danh_muc || '').trim().toLowerCase()
  const relatedItems = catLower
    ? gocItems.filter(x => String(x.category || '').trim().toLowerCase() === catLower)
    : []

  return {
    vendor: 'acronis',
    item,
    sku,
    skuFor,
    sheet,
    gocFound,
    gocEntry,
    gocRowNum,
    gocPrice,
    mauFound,
    mauEntry,
    mauRowNum,
    mauSheet,
    mauPrice,
    relatedItems,
    dbPrice,
    refPrice,
    priceDiff,
    priceDiffPct,
    status
  }
}

/**
 * Mở Modal Đối Chiếu File Gốc cho Card hàng hóa Sophos, Kaspersky hoặc Acronis
 */
const openCardOriginalFileCompare = async (item) => {
  const vendor = getCardVendorType(item)
  if (!vendor) return
  showCardRefCompareModal.value = true
  cardRefCompareLoading.value = true
  cardRefCompareData.value = { vendor, item, status: 'loading' }
  try {
    if (vendor === 'sophos') {
      cardRefCompareData.value = await resolveSophosCardCompare(item)
    } else if (vendor === 'acronis') {
      cardRefCompareData.value = await resolveAcronisCardCompare(item)
    } else {
      cardRefCompareData.value = await resolveKasperskyCardCompare(item)
    }
  } catch (err) {
    console.error('Lỗi đối chiếu file gốc trên card:', err)
  } finally {
    cardRefCompareLoading.value = false
  }
}

/**
 * Đồng bộ trực tiếp Card đang đối chiếu theo Giá chuẩn File Gốc vào Firebase `hang_hoa`
 */
const syncCardItemWithOriginalFile = async () => {
  const data = cardRefCompareData.value
  if (!data || !data.item || !data.item._firebaseKey || !(data.refPrice > 0)) return
  syncingCardRefToDb.value = true
  try {
    const existing = data.item
    const updatedFields = {
      ...existing,
      sku_code: data.sku || existing.sku_code || '',
      Don_gia: data.refPrice,
      Gia_tieu_chuan: data.refPrice
    }
    if (data.vendor === 'sophos') {
      if (data.tgNhapKhau > 0) {
        updatedFields.gia_nhap = data.tgNhapKhau
      }
      const bestDesc = data.calcEntry?.desc || data.gocEntry?.desc || ''
      if (bestDesc && !existing.Description) {
        updatedFields.Description = bestDesc
      }
      if (data.sku && !String(existing.Ghi_chu || '').includes(data.sku)) {
        updatedFields.Ghi_chu = [existing.Ghi_chu, `SKU: ${data.sku}`].filter(Boolean).join(' | ')
      }
    }
    const payload = buildFirebaseHangHoaPayload(updatedFields)
    await update(dbRef(database, `hang_hoa/${existing._firebaseKey}`), payload)
    await fetchData()
    await syncAutoUpdatePriceListsInFirebase()

    const refreshedItem = items.value.find(x => x._firebaseKey === existing._firebaseKey) || { ...existing, ...payload }
    if (data.vendor === 'sophos') {
      cardRefCompareData.value = await resolveSophosCardCompare(refreshedItem)
    } else if (data.vendor === 'acronis') {
      cardRefCompareData.value = await resolveAcronisCardCompare(refreshedItem)
    } else {
      cardRefCompareData.value = await resolveKasperskyCardCompare(refreshedItem)
    }
    showAsyncSuccess(
      `Đã cập nhật Card theo ${data.refSourceLabel || 'File Gốc'}!`,
      `${refreshedItem.Ten_hang} → ${data.vendor === 'sophos' ? formatUsdPrice(data.refPrice) : formatVndPrice(data.refPrice)}`
    )
  } catch (err) {
    console.error('Lỗi cập nhật Card theo File Gốc:', err)
    showAsyncError('Lỗi cập nhật Database', err.message)
  } finally {
    syncingCardRefToDb.value = false
  }
}

/**
 * Đồng bộ trực tiếp Card đang mở theo đúng dòng / sản phẩm đang được chọn & tính toán trên giao diện Sophos Calculator
 */
const syncCardFromActiveCalculator = async () => {
  const data = cardRefCompareData.value
  const activeSum = sophosCardActiveCalcSummary.value
  if (!data?.item?._firebaseKey || !activeSum?.available || !(activeSum.unitMsrp > 0)) return
  syncingCardRefToDb.value = true
  try {
    const existing = data.item
    const newSku = String(activeSum.sku || data.sku || '').trim().toUpperCase()
    const newUnitPrice = Number(activeSum.unitMsrp) || 0
    const updatedFields = {
      ...existing,
      sku_code: newSku || existing.sku_code || '',
      Don_gia: newUnitPrice,
      Gia_tieu_chuan: newUnitPrice
    }
    if (data.tgNhapKhau > 0) {
      updatedFields.gia_nhap = data.tgNhapKhau
    }
    if (activeSum.label && !existing.Description) {
      updatedFields.Description = activeSum.label
    }
    if (newSku && !String(existing.Ghi_chu || '').includes(newSku)) {
      updatedFields.Ghi_chu = [existing.Ghi_chu, `SKU: ${newSku}`].filter(Boolean).join(' | ')
    }
    const payload = buildFirebaseHangHoaPayload(updatedFields)
    await update(dbRef(database, `hang_hoa/${existing._firebaseKey}`), payload)
    await fetchData()
    await syncAutoUpdatePriceListsInFirebase()

    const refreshedItem = items.value.find(x => x._firebaseKey === existing._firebaseKey) || { ...existing, ...payload }
    cardRefCompareData.value = await resolveSophosCardCompare(refreshedItem)
    showAsyncSuccess(
      'Đã cập nhật Card theo kết quả tính từ File Calculator!',
      `${refreshedItem.Ten_hang} → SKU ${newSku} • ${formatUsdPrice(newUnitPrice)}`
    )
  } catch (err) {
    console.error('Lỗi đồng bộ từ Sophos Calculator:', err)
    showAsyncError('Lỗi cập nhật Database', err.message)
  } finally {
    syncingCardRefToDb.value = false
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// ĐỒNG BỘ HÀNG LOẠT THEO FILE CALCULATOR SOPHOS:
//   1. Đồng bộ List Price hàng Sophos trong Database (hang_hoa) theo File Calculator
//   2. Đồng bộ Giá tham khảo (Cột F) của File Trung Gian theo File Calculator
// ═══════════════════════════════════════════════════════════════════════════
const showSophosDbSyncModal = ref(false)
const sophosDbSyncLoading = ref(false)
const syncingSophosDbFromCalc = ref(false)
const sophosDbSyncRows = ref([])
const sophosDbSyncFilter = ref('need_sync')
const sophosDbSyncSearch = ref('')
const sophosDbSyncUpdateSku2026 = ref(true)

const showSophosTgSyncModal = ref(false)
const sophosTgSyncLoading = ref(false)
const syncingSophosTgFromCalc = ref(false)
const exportingSophosTgFromCalc = ref(false)
const sophosTgLoadedWorkbook = ref(null)
const sophosTgSyncFileName = ref('file_trung_gian_SOPHOS.xlsx')
const sophosTgBomSheetList = ref([])
const sophosTgSyncRows = ref([])
const sophosTgSyncSheetFilter = ref('ALL')
const sophosTgSyncFilter = ref('need_sync')
const sophosTgSyncSearch = ref('')
const sophosTgSyncUpdateSku2026 = ref(true)
const sophosTgAutoDownloadAfterSync = ref(false)

/**
 * Tra cứu chuẩn xác SKU & Giá MSRP trong File Calculator (calculate_sophos.xlsx)
 * cho 1 mặt hàng trong Database hoặc 1 dòng BOM trong File Trung Gian (Không gán nhầm fallback).
 */
const resolveSophosItemAgainstCalculator = (calcObj, rawCandidates = [], pseudoItem = null, tgList = []) => {
  const calcMap = calcObj?.calcSkus || {}
  const runtime = calcObj?.engineRuntime || null
  const calcDd = runtime?.dropDowns || null
  const newByOld = calcDd?.newSkuByOldSku || {}

  const normalizedCands = Array.from(
    new Set(
      (rawCandidates || [])
        .map(x => String(x || '').trim().toUpperCase())
        .filter(Boolean)
    )
  )

  // 1. Khớp trực tiếp mã SKU 2026 hoặc qua bảng ánh xạ OldSKU -> NewSKU chính thức của Calculator
  for (const cand of normalizedCands) {
    if (calcMap[cand]) {
      return {
        found: true,
        resolvedSku: cand,
        matchedFromSku: cand,
        matchSource: 'exact',
        msrp: Number(calcMap[cand].msrp) || 0,
        rowNum: calcMap[cand].rowNum || null,
        desc: calcMap[cand].desc || ''
      }
    }
    const mappedNew = newByOld[cand] || (cand === 'CFRAAB12ZZCAA' ? 'CFRAAB12BANCAA' : '')
    if (mappedNew && calcMap[mappedNew]) {
      return {
        found: true,
        resolvedSku: mappedNew,
        matchedFromSku: cand,
        matchSource: 'mapped_2026',
        msrp: Number(calcMap[mappedNew].msrp) || 0,
        rowNum: calcMap[mappedNew].rowNum || null,
        desc: calcMap[mappedNew].desc || ''
      }
    }
  }

  // 2. Thử trích xuất mã SKU nhúng hợp lệ trong tên / mô tả / ghi chú
  if (pseudoItem && calcObj) {
    const embedded = extractValidatedEmbeddedCalcSku(pseudoItem, calcObj)
    if (embedded && calcMap[embedded]) {
      return {
        found: true,
        resolvedSku: embedded,
        matchedFromSku: normalizedCands[0] || '',
        matchSource: 'embedded_sku',
        msrp: Number(calcMap[embedded].msrp) || 0,
        rowNum: calcMap[embedded].rowNum || null,
        desc: calcMap[embedded].desc || ''
      }
    }
  }

  // 3. Đối với hàng DB có mã nội bộ riêng: dò qua BOM File Trung Gian (kiểm tra chặt Model & Volume Band)
  if (pseudoItem && Array.isArray(tgList) && tgList.length > 0) {
    const itemVolRange = extractVolumeRangeFromSophosItem(pseudoItem)
    const matchesTgVol = (t) => {
      if (!itemVolRange) return true
      const tSku = String(t?.sku || '').trim().toUpperCase()
      const tText = `${t?.description || ''} ${t?.moTa || ''}`
      if (tText.includes(`${itemVolRange.min}-${itemVolRange.max}`)) return true
      const mapped = (tSku && newByOld[tSku]) || (tSku.length === 14 ? tSku : '')
      if (mapped.length === 14 && calcDd?.volBandTables) {
        const bCode = mapped.slice(8, 10)
        if (bCode !== 'ZZ') {
          const tbl = calcDd.volBandTables[bCode[0]] || []
          const hitBand = tbl.find(b => b[2] === bCode)
          if (hitBand) return itemVolRange.min >= hitBand[0] && itemVolRange.min <= hitBand[1]
        }
      }
      return false
    }
    const modelMatch = `${pseudoItem.Ma_hang || ''} ${pseudoItem.Ten_hang || ''} ${pseudoItem.Danh_muc || ''}`.match(/\b(XGS?\s*\d{2,4}w?)\b/i)
    const itemModelNorm = modelMatch ? modelMatch[1].replace(/\s+/g, '').toUpperCase() : ''
    const matchesTgModel = (t) => {
      if (!itemModelNorm) return true
      const tText = `${t?.group || ''} ${t?.model || ''} ${t?.description || ''} ${t?.moTa || ''}`
      const m = tText.match(/\b(XGS?\s*\d{2,4}w?)\b/i)
      if (!m) return true
      return m[1].replace(/\s+/g, '').toUpperCase() === itemModelNorm
    }

    const dmLower = String(pseudoItem.Danh_muc || '').trim().toLowerCase()
    const thLower = String(pseudoItem.Ten_hang || '').trim().replace(/:$/, '').toLowerCase()
    let tgHit = null
    if (thLower) {
      tgHit =
        tgList.find(t => {
          const grp = String(t.group || '').trim().toLowerCase()
          const firstLine = String(t.moTa || '').split('\n')[0].trim().replace(/:$/, '').toLowerCase()
          return grp === dmLower && firstLine === thLower && matchesTgVol(t) && matchesTgModel(t)
        }) ||
        tgList.find(t => {
          const firstLine = String(t.moTa || '').split('\n')[0].trim().replace(/:$/, '').toLowerCase()
          return firstLine === thLower && matchesTgVol(t) && matchesTgModel(t)
        }) ||
        null
    }
    if (tgHit?.sku) {
      const tgSku = String(tgHit.sku).trim().toUpperCase()
      const resolvedTgSku = calcMap[tgSku]
        ? tgSku
        : ((newByOld[tgSku] && calcMap[newByOld[tgSku]]) ? newByOld[tgSku] : '')
      if (resolvedTgSku && calcMap[resolvedTgSku]) {
        return {
          found: true,
          resolvedSku: resolvedTgSku,
          matchedFromSku: tgSku,
          matchSource: 'tg_bom',
          msrp: Number(calcMap[resolvedTgSku].msrp) || 0,
          rowNum: calcMap[resolvedTgSku].rowNum || null,
          desc: calcMap[resolvedTgSku].desc || ''
        }
      }
    }
  }

  // 4. Suy luận qua Engine của Calculator (chỉ chấp nhận khi khớp thật sự Model Firewall hoặc Product2 cụ thể, tuyệt đối không nhận fallback Endpoint mặc định)
  if (pseudoItem && runtime) {
    const primaryRaw = normalizedCands[0] || ''
    const combinedText = `${pseudoItem.Ma_hang || ''} ${pseudoItem.Ten_hang || ''} ${pseudoItem.Description || ''} ${pseudoItem.Danh_muc || ''}`
    if (!/\butm\s*\d+\b/i.test(combinedText)) {
      const ctx = inferSophosCalculatorContext(calcObj, primaryRaw, pseudoItem)
      const ctxSku = String(ctx?.sku || '').trim().toUpperCase()
      if (ctxSku && calcMap[ctxSku]) {
        const hasExplicitPartPrefix =
          primaryRaw.length >= 6 &&
          (Boolean(runtime.partIdToProducts?.[primaryRaw.slice(0, 6)]) ||
            primaryRaw.startsWith('CZTNA') ||
            primaryRaw.startsWith('MDRNDU'))
        const isFirewallGenuine =
          ctx.calcType === 'firewall' &&
          (/\b(XGS?\s*\d{2,4}w?|SFv[\s-]*(?:Unlimited|\d+C\d+)|central\s+firewall\s+reporting)\b/i.test(combinedText) ||
            primaryRaw.startsWith('CFR'))
        const isProductGenuine =
          ctx.calcType === 'product' &&
          (hasExplicitPartPrefix ||
            (ctx.product && ctx.product !== 'Sophos Endpoint - User') ||
            /\bendpoint\b/i.test(combinedText))

        if (isFirewallGenuine || isProductGenuine) {
          return {
            found: true,
            resolvedSku: ctxSku,
            matchedFromSku: primaryRaw,
            matchSource: 'calc_engine',
            msrp: Number(calcMap[ctxSku].msrp) || 0,
            rowNum: calcMap[ctxSku].rowNum || null,
            desc: calcMap[ctxSku].desc || ctx.product || ''
          }
        }
      }
    }
  }

  return {
    found: false,
    resolvedSku: '',
    matchedFromSku: normalizedCands[0] || '',
    matchSource: 'none',
    msrp: 0,
    rowNum: null,
    desc: ''
  }
}

// ---------------------------------------------------------------------------
// TÍNH NĂNG 1: ĐỒNG BỘ LIST PRICE HÀNG SOPHOS TRONG DB THEO FILE CALCULATOR
// ---------------------------------------------------------------------------
const rowNeedsDbSync = (row) => {
  if (!row || !row.calcFound || !(row.newPrice > 0)) return false
  if (row.hasPriceDiff) return true
  if (sophosDbSyncUpdateSku2026.value && row.hasSkuUpgrade) return true
  return false
}

const buildSophosDbSyncPreviewRows = () => {
  const calcObj = sophosCalcRefData.value
  const tgList = sophosRefData.value?.trungGianItems || []
  const sophosItems = (items.value || []).filter(it => getCardVendorType(it) === 'sophos')

  const built = sophosItems.map((it, idx) => {
    const currentSku = String(it.sku_code || '').trim().toUpperCase()
    const maHang = String(it.Ma_hang || '').trim()
    const mhUpper = maHang.toUpperCase()
    const skuFromNote = ((String(it.Ghi_chu || '').match(/SKU:\s*([A-Z0-9]+)/i) || [])[1] || '').toUpperCase()

    const cands = [
      currentSku,
      /^[A-Z0-9]{8,16}$/.test(mhUpper) && /\d/.test(mhUpper) ? mhUpper : '',
      skuFromNote
    ].filter(Boolean)

    const match = resolveSophosItemAgainstCalculator(calcObj, cands, it, tgList)
    const oldCurrency = String(it.Don_vi_tien_te || 'USD').trim().toUpperCase()
    const oldPrice = Number(it.Don_gia) || 0
    const oldStdCost = Number(it.Gia_tieu_chuan) || 0
    const newPrice = match.found ? Number(match.msrp.toFixed(2)) : 0

    const hasPriceDiff =
      match.found &&
      newPrice > 0 &&
      (oldCurrency !== 'USD' || Math.abs(newPrice - oldPrice) >= 0.01)

    const diffUsd = match.found
      ? (oldCurrency === 'USD' ? Number((newPrice - oldPrice).toFixed(2)) : newPrice)
      : 0
    const diffPct = match.found && oldCurrency === 'USD' && oldPrice > 0
      ? ((newPrice - oldPrice) / oldPrice) * 100
      : 0

    const hasSkuUpgrade = Boolean(match.found && match.resolvedSku && currentSku !== match.resolvedSku)
    const preserveCustomCost =
      oldCurrency === 'USD' &&
      oldStdCost > 0 &&
      Math.abs(oldStdCost - oldPrice) >= 0.01

    const displaySku = match.resolvedSku || currentSku || skuFromNote || (/^[A-Z0-9]{8,16}$/.test(mhUpper) ? mhUpper : '')
    const needsSync = hasPriceDiff || (sophosDbSyncUpdateSku2026.value && hasSkuUpgrade)

    return {
      id: it._firebaseKey || `db-sophos-${idx}`,
      dbItem: it,
      maHang,
      currentSku,
      displaySku,
      resolvedSku: match.resolvedSku,
      matchSource: match.matchSource,
      calcFound: match.found,
      calcRowNum: match.rowNum,
      calcDesc: match.desc,
      name: String(it.Ten_hang || '').trim() || maHang,
      category: String(it.Danh_muc || '').trim(),
      oldCurrency,
      oldPrice,
      oldStdCost,
      preserveCustomCost,
      newPrice,
      diffUsd,
      diffPct,
      hasPriceDiff,
      hasSkuUpgrade,
      selected: Boolean(match.found && newPrice > 0 && needsSync)
    }
  })

  // Ưu tiên hiển thị các dòng lệch giá lên đầu, tiếp đến là đổi SKU, khớp giá, và không tìm thấy
  built.sort((a, b) => {
    const score = (r) => {
      if (!r.calcFound) return 3
      if (r.hasPriceDiff) return 0
      if (r.hasSkuUpgrade) return 1
      return 2
    }
    const diffScore = score(a) - score(b)
    if (diffScore !== 0) return diffScore
    return Math.abs(b.diffUsd) - Math.abs(a.diffUsd)
  })

  sophosDbSyncRows.value = built
}

watch(sophosDbSyncUpdateSku2026, (enableSkuUpdate) => {
  sophosDbSyncRows.value.forEach(r => {
    if (r.calcFound && r.newPrice > 0 && !r.hasPriceDiff && r.hasSkuUpgrade) {
      r.selected = Boolean(enableSkuUpdate)
    }
  })
})

const sophosDbSyncSummary = computed(() => {
  const rows = sophosDbSyncRows.value
  const total = rows.length
  const notFound = rows.filter(r => !r.calcFound).length
  const priceDiff = rows.filter(r => r.calcFound && r.hasPriceDiff).length
  const skuDiff = rows.filter(r => r.calcFound && r.hasSkuUpgrade).length
  const needSync = rows.filter(r => rowNeedsDbSync(r)).length
  const matched = rows.filter(r => r.calcFound && !rowNeedsDbSync(r)).length
  return { total, needSync, priceDiff, skuDiff, matched, notFound }
})

const filteredSophosDbSyncRows = computed(() => {
  let list = sophosDbSyncRows.value
  const mode = sophosDbSyncFilter.value
  if (mode === 'need_sync') list = list.filter(r => rowNeedsDbSync(r))
  else if (mode === 'price_diff') list = list.filter(r => r.calcFound && r.hasPriceDiff)
  else if (mode === 'sku_diff') list = list.filter(r => r.calcFound && r.hasSkuUpgrade)
  else if (mode === 'matched') list = list.filter(r => r.calcFound && !rowNeedsDbSync(r))
  else if (mode === 'not_found') list = list.filter(r => !r.calcFound)

  const q = String(sophosDbSyncSearch.value || '').trim().toLowerCase()
  if (q) {
    list = list.filter(r =>
      String(r.displaySku || '').toLowerCase().includes(q) ||
      String(r.currentSku || '').toLowerCase().includes(q) ||
      String(r.resolvedSku || '').toLowerCase().includes(q) ||
      String(r.maHang || '').toLowerCase().includes(q) ||
      String(r.name || '').toLowerCase().includes(q) ||
      String(r.category || '').toLowerCase().includes(q)
    )
  }
  return list
})

const selectableFilteredSophosDbRows = computed(() =>
  filteredSophosDbSyncRows.value.filter(r => r.calcFound && r.newPrice > 0)
)

const allFilteredSophosDbSelected = computed(() => {
  const selectable = selectableFilteredSophosDbRows.value
  return selectable.length > 0 && selectable.every(r => r.selected)
})

const selectedSophosDbSyncCount = computed(() =>
  sophosDbSyncRows.value.filter(r => r.selected && r.calcFound && r.newPrice > 0).length
)

const toggleSelectAllFilteredSophosDb = (checked) => {
  selectableFilteredSophosDbRows.value.forEach(r => {
    r.selected = Boolean(checked)
  })
}

const selectAllNeedSyncSophosDbRows = () => {
  sophosDbSyncRows.value.forEach(r => {
    r.selected = rowNeedsDbSync(r)
  })
}

const refreshSophosDbSyncModal = async () => {
  sophosDbSyncLoading.value = true
  try {
    await fetchVendorRefFilesMeta(true)
    if (!items.value.length) {
      await fetchData()
    }
    await Promise.all([
      loadSophosCalcRefData(),
      loadSophosRefData().catch(() => null)
    ])
    if (!sophosCalcRefData.value?.calcSkus || !Object.keys(sophosCalcRefData.value.calcSkus).length) {
      showAsyncError(
        'Chưa có dữ liệu File Calculator Sophos',
        'Vui lòng upload file calculate_sophos.xlsx lên Cloudinary tại mục ☁️ File Calculator trước khi đồng bộ!'
      )
      return
    }
    buildSophosDbSyncPreviewRows()
    sophosDbSyncFilter.value = sophosDbSyncSummary.value.needSync > 0 ? 'need_sync' : 'all'
  } catch (err) {
    console.error('Lỗi quét dữ liệu đồng bộ ListPrice Sophos:', err)
    showAsyncError('Lỗi tải dữ liệu đối chiếu', err.message)
  } finally {
    sophosDbSyncLoading.value = false
  }
}

const openSophosDbListPriceSyncModal = async () => {
  sophosDbSyncSearch.value = ''
  showSophosDbSyncModal.value = true
  await refreshSophosDbSyncModal()
}

const buildUpdatedHangHoaPayloadForSophosCalcSync = (row, calcFileMeta) => {
  const existing = row.dbItem || {}
  const newPrice = Number(row.newPrice.toFixed(2))
  const oldPrice = Number(existing.Don_gia) || 0
  const oldStd = Number(existing.Gia_tieu_chuan) || 0
  const oldCurrency = String(existing.Don_vi_tien_te || 'USD').trim().toUpperCase()

  // Quy tắc A1 đã chốt: nếu Gia_tieu_chuan trước đó đang bằng Don_gia cũ (hoặc <= 0) thì cập nhật theo Giá mới;
  // nếu mặt hàng đã có Giá vốn riêng khác Don_gia cũ thì giữ nguyên hoàn toàn Gia_tieu_chuan.
  const preserveCost = oldCurrency === 'USD' && oldStd > 0 && Math.abs(oldStd - oldPrice) >= 0.01
  const nextGiaTieuChuan = preserveCost ? oldStd : newPrice

  let nextSkuCode = String(existing.sku_code || '').trim()
  let nextNote = String(existing.Ghi_chu || '').trim()
  if (sophosDbSyncUpdateSku2026.value && row.resolvedSku) {
    nextSkuCode = row.resolvedSku
    if (!nextNote) {
      nextNote = `SKU: ${row.resolvedSku}`
    } else if (!nextNote.toUpperCase().includes(row.resolvedSku)) {
      if (/SKU:\s*[A-Z0-9]+/i.test(nextNote)) {
        nextNote = nextNote.replace(/SKU:\s*([A-Z0-9]+)/i, (_, oldCode) =>
          oldCode.toUpperCase() === row.resolvedSku
            ? `SKU: ${row.resolvedSku}`
            : `SKU: ${row.resolvedSku} (SKU cũ: ${oldCode.toUpperCase()})`
        )
      } else {
        nextNote = `${nextNote} | SKU: ${row.resolvedSku}`
      }
    }
  }

  const nextRate = Number(existing.Ti_gia) > 1
    ? Number(existing.Ti_gia)
    : (currentSystemUsdRate.value || sophosRefData.value?.tiGiaTrungGian || 26200)

  const payload = buildFirebaseHangHoaPayload({
    ...existing,
    Ma_hang: existing.Ma_hang,
    sku_code: nextSkuCode,
    Description: existing.Description || row.calcDesc || '',
    Don_gia: newPrice,
    Gia_tieu_chuan: nextGiaTieuChuan,
    Don_vi_tien_te: 'USD',
    Ti_gia: nextRate,
    Ghi_chu: nextNote
  })

  if (calcFileMeta && calcFileMeta.file_name) {
    payload.danh_sach_file = appendFileEntryToProductHistory(
      existing.danh_sach_file || [],
      calcFileMeta,
      {
        gia_von: payload.Gia_tieu_chuan,
        don_gia: payload.Don_gia,
        gia_nhap: payload.gia_nhap,
        don_vi_tien_te: payload.Don_vi_tien_te
      }
    )
  }

  return payload
}

const getActiveCalcHistoryFileMeta = () => {
  const sMeta = vendorRefFilesMeta.value?.sophos || {}
  const fName = sMeta.calc_file_name || sophosCalcRefData.value?.fileName || 'calculate_sophos.xlsx'
  return {
    file_name: fName,
    file_url: sMeta.calc_file_url || '',
    file_type: 'sophos_calculator_sync',
    file_uploaded_at: sMeta.calc_updated_at
      ? new Date(sMeta.calc_updated_at).toISOString()
      : new Date().toISOString(),
    ghi_chu_file: `Đồng bộ List Price từ File Calculator Sophos${sMeta.calc_version ? ' (v' + sMeta.calc_version + ')' : ''}`
  }
}

const syncSingleSophosDbRow = async (row) => {
  if (!row?.dbItem?._firebaseKey || !row.calcFound || !(row.newPrice > 0)) return
  syncingSophosDbFromCalc.value = true
  try {
    const calcFileMeta = getActiveCalcHistoryFileMeta()
    const payload = buildUpdatedHangHoaPayloadForSophosCalcSync(row, calcFileMeta)
    await update(dbRef(database, `hang_hoa/${row.dbItem._firebaseKey}`), payload)
    await fetchData()
    await syncAutoUpdatePriceListsInFirebase()
    buildSophosDbSyncPreviewRows()
    showAsyncSuccess(
      'Đã đồng bộ List Price vào DB!',
      `${row.name} → ${formatUsdPrice(payload.Don_gia)}`
    )
  } catch (err) {
    console.error('Lỗi đồng bộ dòng Sophos vào DB:', err)
    showAsyncError('Lỗi đồng bộ Database', err.message)
  } finally {
    syncingSophosDbFromCalc.value = false
  }
}

const applySophosDbListPriceSync = async () => {
  const selectedRows = sophosDbSyncRows.value.filter(
    r => r.selected && r.calcFound && r.newPrice > 0 && r.dbItem?._firebaseKey
  )
  if (!selectedRows.length) return

  syncingSophosDbFromCalc.value = true
  showAsyncLoading(
    'Đang đồng bộ List Price hàng Sophos vào Database...',
    `Đang cập nhật ${selectedRows.length} mặt hàng theo File Calculator...`
  )
  try {
    const calcFileMeta = getActiveCalcHistoryFileMeta()
    const CHUNK_SIZE = 250
    for (let i = 0; i < selectedRows.length; i += CHUNK_SIZE) {
      const chunk = selectedRows.slice(i, i + CHUNK_SIZE)
      const batchUpdates = {}
      for (const row of chunk) {
        batchUpdates[row.dbItem._firebaseKey] = buildUpdatedHangHoaPayloadForSophosCalcSync(row, calcFileMeta)
      }
      await update(dbRef(database, 'hang_hoa'), batchUpdates)
    }

    await fetchData()
    await syncAutoUpdatePriceListsInFirebase()
    buildSophosDbSyncPreviewRows()
    if (sophosDbSyncSummary.value.needSync === 0) {
      sophosDbSyncFilter.value = 'all'
    }

    showAsyncSuccess(
      'Đồng bộ List Price Sophos vào DB thành công!',
      `Đã cập nhật ${selectedRows.length} mặt hàng Sophos theo File Calculator${vendorRefFilesMeta.value.sophos?.calc_version ? ' (v' + vendorRefFilesMeta.value.sophos.calc_version + ')' : ''}.`
    )
  } catch (err) {
    console.error('Lỗi đồng bộ hàng loạt List Price Sophos vào DB:', err)
    showAsyncError('Lỗi đồng bộ Database', err.message)
  } finally {
    syncingSophosDbFromCalc.value = false
  }
}

// ---------------------------------------------------------------------------
// TÍNH NĂNG 2: ĐỒNG BỘ GIÁ FILE TRUNG GIAN SOPHOS THEO FILE CALCULATOR
// ---------------------------------------------------------------------------
const rowNeedsTgSync = (row) => {
  if (!row || !row.calcFound || !(row.newPrice > 0)) return false
  if (row.hasPriceDiff) return true
  if (sophosTgSyncUpdateSku2026.value && row.hasSkuUpgrade) return true
  return false
}

const loadCurrentSophosTrungGianWorkbook = async () => {
  const tgMeta = getVendorCompareFileMeta('sophos', 'tg')
  const fName = tgMeta?.name || vendorRefFilesMeta.value?.sophos?.tg_file_name || 'file_trung_gian_SOPHOS.xlsx'
  sophosTgSyncFileName.value = fName.replace(/\.(xlsb|xls)$/i, '.xlsx')

  const candidateUrls = []
  const rawUrl = String(tgMeta?.url || vendorRefFilesMeta.value?.sophos?.tg_file_url || '').trim()
  if (rawUrl && !rawUrl.toLowerCase().endsWith('.json')) {
    candidateUrls.push(`${rawUrl}${rawUrl.includes('?') ? '&' : '?'}_t=${Date.now()}`)
  }
  candidateUrls.push(`/template_excel/file_trung_gian_SOPHOS.xlsx?_t=${Date.now()}`)

  for (const url of candidateUrls) {
    try {
      const res = await fetch(url, { cache: 'no-store' })
      if (res.ok) {
        const buf = await res.arrayBuffer()
        if (buf && buf.byteLength > 200) {
          return XLSX.read(buf, {
            type: 'array',
            cellStyles: true,
            cellFormula: true,
            cellNF: true,
            cellDates: true
          })
        }
      }
    } catch (err) {
      console.warn('Không tải trực tiếp được binary File Trung Gian từ URL, thử nguồn dự phòng:', url, err)
    }
  }

  return await buildVendorRefWorkbookFromCloudinary('sophos', 'tg', sophosTgSyncFileName.value)
}

const getExcelJsCellPlainVal = (cell) => {
  if (!cell) return null
  const v = cell.value
  if (v === null || v === undefined) return null
  if (typeof v === 'object') {
    if (Array.isArray(v.richText)) {
      return v.richText.map(rt => rt?.text || '').join('')
    }
    if ('result' in v && v.result !== undefined) return v.result
    if ('text' in v && typeof v.text === 'string') return v.text
    return null
  }
  return v
}

const loadSophosTrungGianExcelJsWorkbook = async () => {
  const tgMeta = getVendorCompareFileMeta('sophos', 'tg')
  const fName = (tgMeta?.name || vendorRefFilesMeta.value?.sophos?.tg_file_name || 'file_trung_gian_SOPHOS.xlsx')
    .replace(/\.(xlsb|xls)$/i, '.xlsx')
  sophosTgSyncFileName.value = fName

  const candidateUrls = []
  const rawUrl = String(tgMeta?.url || vendorRefFilesMeta.value?.sophos?.tg_file_url || '').trim()
  if (rawUrl && !rawUrl.toLowerCase().endsWith('.json')) {
    candidateUrls.push(`${rawUrl}${rawUrl.includes('?') ? '&' : '?'}_t=${Date.now()}`)
  }
  candidateUrls.push(`/template_excel/file_trung_gian_SOPHOS.xlsx?_t=${Date.now()}`)

  for (const url of candidateUrls) {
    try {
      const res = await fetch(url, { cache: 'no-store' })
      if (!res.ok) continue
      const buf = await res.arrayBuffer()
      if (!buf || buf.byteLength < 200) continue
      const exWb = new ExcelJS.Workbook()
      await exWb.xlsx.load(buf)
      if (exWb.worksheets && exWb.worksheets.length > 0) {
        return { exWb, fileName: fName }
      }
    } catch (err) {
      console.warn('Không nạp được workbook ExcelJS từ URL, chuyển sang nguồn kế tiếp:', url, err)
    }
  }

  const fallbackSheetJsWb = await buildVendorRefWorkbookFromCloudinary('sophos', 'tg', fName)
  const fallbackArr = XLSX.write(fallbackSheetJsWb, { bookType: 'xlsx', type: 'array', compression: true })
  const exWb = new ExcelJS.Workbook()
  await exWb.xlsx.load(fallbackArr)
  return { exWb, fileName: fName }
}

/**
 * Cập nhật bảng giá gốc USD (cột T..Z & các hằng số USD cột C/D/F/G) trong sheet "LP Sophos"
 * theo File Calculator, đồng thời tính lại giá trị hiển thị (.result) của toàn bộ công thức VNĐ
 * mà vẫn bảo toàn 100% chuỗi công thức Excel gốc (sharedFormula / formula) và màu sắc/định dạng.
 */
const updateSophosLpSheetWithCalc = (exWb, calcObj) => {
  const wsLp = exWb?.getWorksheet('LP Sophos')
  if (!wsLp || !calcObj) {
    return { updatedModels: 0, updatedUsdCells: 0 }
  }

  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100
  const lpRate = Number(getExcelJsCellPlainVal(wsLp.getCell('H19'))) || 26600

  const setFormulaCachedResult = (cell, nextResult) => {
    if (!cell || !Number.isFinite(nextResult)) return
    const cur = cell.value
    if (cur && typeof cur === 'object' && ('formula' in cur || 'sharedFormula' in cur)) {
      cell.value = { ...cur, result: nextResult }
    }
  }

  const updateDirectUsdRateFormula = (cell, newUsd) => {
    if (!cell || !(newUsd > 0)) return false
    const cur = cell.value
    if (!cur || typeof cur !== 'object' || !('formula' in cur) || typeof cur.formula !== 'string') return false
    const m = cur.formula.trim().match(/^([\d.]+)\s*\*\s*(\$?H\$?19)$/i)
    if (!m) return false
    const rateToken = m[2]
    const cleanUsd = round2(newUsd)
    cell.value = {
      ...cur,
      formula: `${cleanUsd}*${rateToken}`,
      result: round2(cleanUsd * lpRate)
    }
    return true
  }

  const extractEvalRowMsrp = (evalRes, key) => {
    const foundRow = evalRes?.rows?.find(x => x.key === key)
    const c0 = foundRow?.cells?.[0]
    if (!c0 || !c0.available) return 0
    const v = Number(c0.unitMsrp ?? c0.msrp) || 0
    return v > 0 ? round2(v) : 0
  }

  const resolveFallbackDescMsrp = (descText) => {
    const hit = resolveSophosItemAgainstCalculator(
      calcObj,
      [],
      { Ten_hang: descText, Description: descText },
      []
    )
    return hit.found && hit.msrp > 0 ? round2(hit.msrp) : 0
  }

  let updatedModels = 0
  let updatedUsdCells = 0

  for (let r = 3; r <= wsLp.rowCount; r++) {
    const modelName = String(getExcelJsCellPlainVal(wsLp.getCell(r, 1)) || '').trim()
    if (!/^(?:XGS|XG|SFV)\s*\d+/i.test(modelName)) continue

    let hwUsd = 0
    let std1Y = 0
    let std3Y = 0
    let std5Y = 0
    let xst1Y = 0
    let xst3Y = 0
    let xst5Y = 0
    let net1Y = 0
    let enh1Y = 0
    let webSrv1Y = 0
    let email1Y = 0

    if (calcObj.engineRuntime) {
      const baseCfg = {
        partnerLevel: 'Authorized',
        sector: 'Corporate',
        dealType: 'New - Standard',
        models: [modelName],
        qty: 1,
        specialAttribute: 'AU'
      }
      const eval1Y = evaluateFirewallCalculator(calcObj, {
        ...baseCfg,
        termHwBundle: '1-Year',
        termSubscription: '12 MOS'
      })
      const eval3Y = evaluateFirewallCalculator(calcObj, {
        ...baseCfg,
        termHwBundle: '3-Year',
        termSubscription: '36 MOS'
      })
      const eval5Y = evaluateFirewallCalculator(calcObj, {
        ...baseCfg,
        termHwBundle: '5-Year',
        termSubscription: '60 MOS'
      })

      hwUsd = extractEvalRowMsrp(eval1Y, 'hw_appliance')
      std1Y = extractEvalRowMsrp(eval1Y, 'std_prot')
      std3Y = extractEvalRowMsrp(eval3Y, 'std_prot')
      std5Y = extractEvalRowMsrp(eval5Y, 'std_prot')
      xst1Y = extractEvalRowMsrp(eval1Y, 'xstream_prot')
      xst3Y = extractEvalRowMsrp(eval3Y, 'xstream_prot')
      xst5Y = extractEvalRowMsrp(eval5Y, 'xstream_prot')
      net1Y = extractEvalRowMsrp(eval1Y, 'net_prot')
      enh1Y = extractEvalRowMsrp(eval1Y, 'enhanced_sup')
      webSrv1Y = extractEvalRowMsrp(eval1Y, 'webserver_prot')
      email1Y = extractEvalRowMsrp(eval1Y, 'email_prot')
    } else {
      hwUsd = resolveFallbackDescMsrp(`${modelName} Security Appliance - AU power cord`)
      std1Y = resolveFallbackDescMsrp(`${modelName} Standard Protection - 12 MOS`)
      std3Y = resolveFallbackDescMsrp(`${modelName} Standard Protection - 36 MOS`)
      std5Y = resolveFallbackDescMsrp(`${modelName} Standard Protection - 60 MOS`)
      xst1Y = resolveFallbackDescMsrp(`${modelName} Xstream Protection - 12 MOS`)
      xst3Y = resolveFallbackDescMsrp(`${modelName} Xstream Protection - 36 MOS`)
      xst5Y = resolveFallbackDescMsrp(`${modelName} Xstream Protection - 60 MOS`)
    }

    let rowTouched = false
    const cellS = wsLp.getCell(r, 19)
    if (getExcelJsCellPlainVal(cellS)) {
      cellS.value = modelName
    }

    const usdColsToWrite = [
      [20, hwUsd],   // T: HW
      [21, std1Y],   // U: License 1Y Standard
      [22, std3Y],   // V: License 3Y Standard
      [23, std5Y],   // W: License 5Y Standard
      [24, xst1Y],   // X: License 1Y Xstream
      [25, xst3Y],   // Y: License 3Y Xstream
      [26, xst5Y]    // Z: License 5Y Xstream
    ]

    for (const [colIdx, nextUsd] of usdColsToWrite) {
      if (nextUsd > 0) {
        const cObj = wsLp.getCell(r, colIdx)
        const prevNum = Number(getExcelJsCellPlainVal(cObj)) || 0
        cObj.value = nextUsd
        if (Math.abs(prevNum - nextUsd) >= 0.01) {
          updatedUsdCells++
        }
        rowTouched = true
      }
    }

    if (updateDirectUsdRateFormula(wsLp.getCell(r, 3), webSrv1Y)) updatedUsdCells++
    if (updateDirectUsdRateFormula(wsLp.getCell(r, 4), email1Y)) updatedUsdCells++
    if (updateDirectUsdRateFormula(wsLp.getCell(r, 6), net1Y)) updatedUsdCells++
    if (updateDirectUsdRateFormula(wsLp.getCell(r, 7), enh1Y)) updatedUsdCells++

    if (rowTouched) updatedModels++

    // Cập nhật giá trị hiển thị (.result) của các cột công thức VNĐ trên dòng r
    const valT = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 20))) || 0
    const valU = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 21))) || 0
    const valV = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 22))) || 0
    const valW = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 23))) || 0
    const valX = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 24))) || 0
    const valY = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 25))) || 0
    const valZ = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 26))) || 0
    const valR = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 18))) || 0

    const resB = round2(valT * lpRate)
    const resH = round2(valU * lpRate)
    const resI = round2(valV * lpRate)
    const resJ = round2(valW * lpRate)
    const resK = round2(valX * lpRate)
    const resL = round2(valY * lpRate)
    const resM = round2(valZ * lpRate)
    const resO = round2(valR * lpRate)

    setFormulaCachedResult(wsLp.getCell(r, 2), resB)  // B: HW (VND)
    setFormulaCachedResult(wsLp.getCell(r, 8), resH)  // H: 1Y Std
    setFormulaCachedResult(wsLp.getCell(r, 9), resI)  // I: 3Y Std
    setFormulaCachedResult(wsLp.getCell(r, 10), resJ) // J: 5Y Std
    setFormulaCachedResult(wsLp.getCell(r, 11), resK) // K: 1Y Xstream
    setFormulaCachedResult(wsLp.getCell(r, 12), resL) // L: 3Y Xstream
    setFormulaCachedResult(wsLp.getCell(r, 13), resM) // M: 5Y Xstream
    setFormulaCachedResult(wsLp.getCell(r, 15), resO) // O: Giá nhập thiết bị
    setFormulaCachedResult(wsLp.getCell(r, 16), round2(resB + resO)) // P: HW+nhap
    setFormulaCachedResult(wsLp.getCell(r, 17), round2(resO + resH + resB)) // Q: HW+nhap+Lic STD 1Y

    const valF = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 6))) || 0
    const valG = Number(getExcelJsCellPlainVal(wsLp.getCell(r, 7))) || 0
    if (valF > 0 || valG > 0) {
      setFormulaCachedResult(wsLp.getCell(r, 5), round2(valF + valG)) // E: F+G
    }
  }

  // Cập nhật các ô công thức tham chiếu chéo cuối bảng LP Sophos (nếu có)
  const valI7 = Number(getExcelJsCellPlainVal(wsLp.getCell('I7'))) || 0
  const valL7 = Number(getExcelJsCellPlainVal(wsLp.getCell('L7'))) || 0
  if (valI7 > 0) {
    setFormulaCachedResult(wsLp.getCell('I19'), valL7 / valI7)
    setFormulaCachedResult(wsLp.getCell('I20'), round2(valI7 * 0.85))
  }
  const valB8 = Number(getExcelJsCellPlainVal(wsLp.getCell('B8'))) || 0
  const valH8 = Number(getExcelJsCellPlainVal(wsLp.getCell('H8'))) || 0
  if (valB8 > 0 || valH8 > 0) {
    setFormulaCachedResult(wsLp.getCell('B20'), round2(valB8 + valH8))
  }
  const valF9 = Number(getExcelJsCellPlainVal(wsLp.getCell('F9'))) || 0
  const valG9 = Number(getExcelJsCellPlainVal(wsLp.getCell('G9'))) || 0
  if (valF9 > 0 || valG9 > 0) {
    setFormulaCachedResult(wsLp.getCell('F23'), round2(valF9 + valG9))
  }

  return { updatedModels, updatedUsdCells }
}

/**
 * Dựng buffer .xlsx của File Trung Gian đã cập nhật theo File Calculator bằng ExcelJS
 * (giữ nguyên 100% màu sắc, đường viền, độ rộng cột, richText mô tả sản phẩm, cột Nhập khẩu và toàn bộ công thức).
 */
const buildUpdatedSophosTrungGianExcelJs = async ({ selectedRowMap = null, updateSku2026 = true } = {}) => {
  const calcObj = sophosCalcRefData.value
  const { exWb, fileName } = await loadSophosTrungGianExcelJsWorkbook()

  let updatedPriceCells = 0
  let updatedSkuCells = 0

  for (const ws of exWb.worksheets) {
    const headerSample = []
    const sampleLimit = Math.min(ws.rowCount || 0, 15)
    for (let r = 1; r <= sampleLimit; r++) {
      const row = ws.getRow(r)
      const arr = []
      for (let c = 1; c <= 14; c++) {
        arr.push(getExcelJsCellPlainVal(row.getCell(c)))
      }
      headerSample.push(arr)
    }

    if (!isSophosTrungGianBomSheet(ws.name, headerSample)) continue

    const colMap = resolveSophosTrungGianBomColumnMap(headerSample)
    const sttCol = (colMap.sttIdx >= 0 ? colMap.sttIdx : 0) + 1
    const skuCol = (colMap.skuIdx >= 0 ? colMap.skuIdx : 1) + 1
    const modelCol = (colMap.modelIdx >= 0 ? colMap.modelIdx : 2) + 1
    const descCol = (colMap.descIdx >= 0 ? colMap.descIdx : 3) + 1
    const moTaCol = (colMap.moTaIdx >= 0 ? colMap.moTaIdx : 4) + 1
    const giaCol = (colMap.giaIdx >= 0 ? colMap.giaIdx : 5) + 1
    const startRowNum = (colMap.headerRowIdx >= 0 ? colMap.headerRowIdx : 3) + 2

    let currentGroup = ''
    for (let r = startRowNum; r <= ws.rowCount; r++) {
      const row = ws.getRow(r)
      const colA = getExcelJsCellPlainVal(row.getCell(sttCol))
      const colB = getExcelJsCellPlainVal(row.getCell(skuCol))
      const colGia = getExcelJsCellPlainVal(row.getCell(giaCol))

      if (colA && !colB && (colGia === null || colGia === '')) {
        currentGroup = String(colA).trim()
        continue
      }
      if (!colB || colGia === null || colGia === '') continue

      const rowId = `${ws.name}::R${r}`
      const rawSku = String(colB).trim().toUpperCase()
      const oldPrice = Number(colGia) || 0

      if (selectedRowMap) {
        const picked = selectedRowMap.get(rowId)
        if (!picked || !(picked.newPrice > 0)) continue

        const cellGia = row.getCell(giaCol)
        cellGia.value = Number(picked.newPrice.toFixed(2))
        if (!cellGia.numFmt) {
          cellGia.numFmt = '_(* #,##0.00_);_(* \\(#,##0.00\\);_(* "-"??_);_(@_)'
        }
        updatedPriceCells++

        if (updateSku2026 && picked.hasSkuUpgrade && picked.resolvedSku) {
          row.getCell(skuCol).value = picked.resolvedSku
          updatedSkuCells++
        }
      } else {
        const modelText = String(getExcelJsCellPlainVal(row.getCell(modelCol)) || '').trim()
        const descText = String(getExcelJsCellPlainVal(row.getCell(descCol)) || '').trim()
        const moTaText = String(getExcelJsCellPlainVal(row.getCell(moTaCol)) || '').trim()
        const pseudoItem = {
          Ma_hang: rawSku,
          sku_code: rawSku,
          Ten_hang: modelText || descText,
          Description: descText,
          Danh_muc: currentGroup,
          Ghi_chu: moTaText
        }
        const match = resolveSophosItemAgainstCalculator(calcObj, [rawSku], pseudoItem, [])
        if (!match.found || !(match.msrp > 0)) continue

        const newPrice = Number(match.msrp.toFixed(2))
        const cellGia = row.getCell(giaCol)
        cellGia.value = newPrice
        if (!cellGia.numFmt) {
          cellGia.numFmt = '_(* #,##0.00_);_(* \\(#,##0.00\\);_(* "-"??_);_(@_)'
        }
        if (Math.abs(newPrice - oldPrice) >= 0.01) {
          updatedPriceCells++
        }

        if (updateSku2026 && match.resolvedSku && match.resolvedSku !== rawSku) {
          row.getCell(skuCol).value = match.resolvedSku
          updatedSkuCells++
        }
      }
    }
  }

  const lpStats = updateSophosLpSheetWithCalc(exWb, calcObj)
  exWb.calcProperties.fullCalcOnLoad = true

  const outBuffer = await exWb.xlsx.writeBuffer()
  return {
    outBuffer,
    baseFileName: fileName,
    updatedPriceCells,
    updatedSkuCells,
    updatedLpModels: lpStats.updatedModels,
    updatedLpUsdCells: lpStats.updatedUsdCells
  }
}

const triggerExcelArrayBufferDownload = (buffer, fileName) => {
  const blob = new Blob([buffer], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = fileName
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  setTimeout(() => URL.revokeObjectURL(url), 6000)
}

/**
 * Nút "Xuất File Trung Gian (Calc)": lấy File Trung Gian hiện tại làm khung,
 * cập nhật toàn bộ 5 sheet BOM + sheet LP Sophos theo File Calculator rồi tải .xlsx về máy (không ghi đè Cloudinary).
 */
const exportSophosTrungGianFromCalc = async ({ onlySelectedFromModal = false } = {}) => {
  if (exportingSophosTgFromCalc.value) return
  exportingSophosTgFromCalc.value = true
  showAsyncLoading(
    '📥 Đang xuất File Trung Gian theo File Calculator...',
    'Đang giữ nguyên định dạng/công thức gốc và cập nhật giá MSRP, mã SKU 2026 cho 5 sheet BOM + sheet LP Sophos...'
  )
  try {
    await fetchVendorRefFilesMeta(true)
    await Promise.all([
      loadSophosCalcRefData(),
      loadSophosRefData().catch(() => null)
    ])
    if (!sophosCalcRefData.value?.calcSkus || !Object.keys(sophosCalcRefData.value.calcSkus).length) {
      showAsyncError(
        'Chưa có dữ liệu File Calculator Sophos',
        'Vui lòng upload file calculate_sophos.xlsx lên Cloudinary tại mục ☁️ File Calculator trước khi xuất File Trung Gian!'
      )
      return
    }

    let selectedMap = null
    let useSkuUpgrade = true
    if (onlySelectedFromModal && showSophosTgSyncModal.value && sophosTgSyncRows.value.length > 0) {
      useSkuUpgrade = Boolean(sophosTgSyncUpdateSku2026.value)
      const activeRows = sophosTgSyncRows.value.filter(r => r.selected && r.calcFound && r.newPrice > 0)
      if (activeRows.length > 0) {
        selectedMap = new Map(activeRows.map(r => [r.id, r]))
      }
    }

    const {
      outBuffer,
      baseFileName,
      updatedPriceCells,
      updatedSkuCells,
      updatedLpModels
    } = await buildUpdatedSophosTrungGianExcelJs({
      selectedRowMap: selectedMap,
      updateSku2026: useSkuUpgrade
    })

    const calcVer = String(
      vendorRefFilesMeta.value?.sophos?.calc_version || sophosCalcRefData.value?.version || ''
    ).trim()
    const cleanVer = calcVer ? `_v${calcVer.replace(/[^a-zA-Z0-9._-]+/g, '_')}` : ''
    const stem = String(baseFileName || 'file_trung_gian_SOPHOS.xlsx').replace(/\.(xlsx|xlsb|xls)$/i, '')
    const exportFileName = `${stem}_theo_Calc${cleanVer}.xlsx`

    triggerExcelArrayBufferDownload(outBuffer, exportFileName)

    showAsyncSuccess(
      '📥 Đã xuất File Trung Gian theo File Calculator!',
      `Đã tải "${exportFileName}" về máy • Cập nhật ${updatedPriceCells} ô giá BOM${updatedSkuCells > 0 ? `, ${updatedSkuCells} mã SKU 2026` : ''} và ${updatedLpModels} dòng Model trong sheet LP Sophos.`
    )
  } catch (err) {
    console.error('Lỗi xuất File Trung Gian theo File Calculator:', err)
    showAsyncError('Lỗi xuất File Trung Gian', err.message || String(err))
  } finally {
    exportingSophosTgFromCalc.value = false
  }
}

const buildSophosTgSyncPreviewRowsFromWorkbook = (wb) => {
  const calcObj = sophosCalcRefData.value
  if (!wb || !Array.isArray(wb.SheetNames)) {
    sophosTgBomSheetList.value = []
    sophosTgSyncRows.value = []
    return
  }

  const sheetRowsMap = {}
  for (const s of wb.SheetNames) {
    sheetRowsMap[s] = XLSX.utils.sheet_to_json(wb.Sheets[s], { header: 1, defval: null })
  }

  // Quy tắc A4 đã chốt: chỉ quét đúng 5 sheet BOM chuẩn, giữ nguyên các sheet tính nháp/công thức khác
  const bomSheets = wb.SheetNames.filter(s => isSophosTrungGianBomSheet(s, sheetRowsMap[s]))
  sophosTgBomSheetList.value = bomSheets

  const previewRows = []
  for (const s of bomSheets) {
    const rows = sheetRowsMap[s] || []
    const colMap = resolveSophosTrungGianBomColumnMap(rows)
    const sttIdx = colMap.sttIdx >= 0 ? colMap.sttIdx : 0
    const skuIdx = colMap.skuIdx >= 0 ? colMap.skuIdx : 1
    const modelIdx = colMap.modelIdx >= 0 ? colMap.modelIdx : 2
    const descIdx = colMap.descIdx >= 0 ? colMap.descIdx : 3
    const moTaIdx = colMap.moTaIdx >= 0 ? colMap.moTaIdx : 4
    const giaIdx = colMap.giaIdx >= 0 ? colMap.giaIdx : 5
    const nhapIdx = colMap.nhapKhauIdx >= 0 ? colMap.nhapKhauIdx : 6
    const startIdx = (colMap.headerRowIdx >= 0 ? colMap.headerRowIdx : 3) + 1
    let currentGroup = ''
    for (let i = startIdx; i < rows.length; i++) {
      const r = rows[i]
      if (!r || !r.some(x => x !== null && x !== '')) continue
      if (r[sttIdx] && !r[skuIdx] && (r[giaIdx] === null || r[giaIdx] === undefined || r[giaIdx] === '')) {
        currentGroup = String(r[sttIdx]).trim()
        continue
      }
      if (r[skuIdx] && r[giaIdx] !== null && r[giaIdx] !== undefined && r[giaIdx] !== '') {
        const rowNum = i + 1
        const rawSku = String(r[skuIdx]).trim().toUpperCase()
        const modelText = String(r[modelIdx] || '').trim()
        const descText = descIdx >= 0 ? String(r[descIdx] || '').trim() : ''
        const moTaText = moTaIdx >= 0 ? String(r[moTaIdx] || '').trim() : ''
        const oldPrice = Number(r[giaIdx]) || 0
        const nhapKhau = nhapIdx >= 0 && r[nhapIdx] !== null && r[nhapIdx] !== undefined && r[nhapIdx] !== ''
          ? (Number(r[nhapIdx]) || 0)
          : 0

        const pseudoItem = {
          Ma_hang: rawSku,
          sku_code: rawSku,
          Ten_hang: modelText || descText,
          Description: descText,
          Danh_muc: currentGroup,
          Ghi_chu: moTaText
        }
        const match = resolveSophosItemAgainstCalculator(calcObj, [rawSku], pseudoItem, [])
        const newPrice = match.found ? Number(match.msrp.toFixed(2)) : 0
        const hasPriceDiff = match.found && newPrice > 0 && Math.abs(newPrice - oldPrice) >= 0.01
        const diffUsd = match.found ? Number((newPrice - oldPrice).toFixed(2)) : 0
        const diffPct = match.found && oldPrice > 0 ? ((newPrice - oldPrice) / oldPrice) * 100 : 0
        const hasSkuUpgrade = Boolean(match.found && match.resolvedSku && match.resolvedSku !== rawSku)
        const needsSync = hasPriceDiff || (sophosTgSyncUpdateSku2026.value && hasSkuUpgrade)

        previewRows.push({
          id: `${s}::R${rowNum}`,
          sheet: s,
          rowNum,
          group: currentGroup,
          rawSku,
          resolvedSku: match.resolvedSku,
          calcFound: match.found,
          calcRowNum: match.rowNum,
          name: modelText || (moTaText.split('\n')[0] || '').trim() || rawSku,
          description: descText,
          nhapKhau,
          oldPrice,
          newPrice,
          diffUsd,
          diffPct,
          hasPriceDiff,
          hasSkuUpgrade,
          selected: Boolean(match.found && newPrice > 0 && needsSync)
        })
      }
    }
  }

  sophosTgSyncRows.value = previewRows
}

watch(sophosTgSyncUpdateSku2026, (enableSkuUpdate) => {
  sophosTgSyncRows.value.forEach(r => {
    if (r.calcFound && r.newPrice > 0 && !r.hasPriceDiff && r.hasSkuUpgrade) {
      r.selected = Boolean(enableSkuUpdate)
    }
  })
})

const sophosTgSyncSummary = computed(() => {
  const rows = sophosTgSyncRows.value
  const total = rows.length
  const notFound = rows.filter(r => !r.calcFound).length
  const priceDiff = rows.filter(r => r.calcFound && r.hasPriceDiff).length
  const skuDiff = rows.filter(r => r.calcFound && r.hasSkuUpgrade).length
  const needSync = rows.filter(r => rowNeedsTgSync(r)).length
  const matched = rows.filter(r => r.calcFound && !rowNeedsTgSync(r)).length
  return { total, needSync, priceDiff, skuDiff, matched, notFound }
})

const filteredSophosTgSyncRows = computed(() => {
  let list = sophosTgSyncRows.value
  if (sophosTgSyncSheetFilter.value !== 'ALL') {
    list = list.filter(r => r.sheet === sophosTgSyncSheetFilter.value)
  }
  const mode = sophosTgSyncFilter.value
  if (mode === 'need_sync') list = list.filter(r => rowNeedsTgSync(r))
  else if (mode === 'matched') list = list.filter(r => r.calcFound && !rowNeedsTgSync(r))
  else if (mode === 'not_found') list = list.filter(r => !r.calcFound)

  const q = String(sophosTgSyncSearch.value || '').trim().toLowerCase()
  if (q) {
    list = list.filter(r =>
      String(r.rawSku || '').toLowerCase().includes(q) ||
      String(r.resolvedSku || '').toLowerCase().includes(q) ||
      String(r.name || '').toLowerCase().includes(q) ||
      String(r.description || '').toLowerCase().includes(q) ||
      String(r.group || '').toLowerCase().includes(q) ||
      String(r.sheet || '').toLowerCase().includes(q)
    )
  }
  return list
})

const selectableFilteredSophosTgRows = computed(() =>
  filteredSophosTgSyncRows.value.filter(r => r.calcFound && r.newPrice > 0)
)

const allFilteredSophosTgSelected = computed(() => {
  const selectable = selectableFilteredSophosTgRows.value
  return selectable.length > 0 && selectable.every(r => r.selected)
})

const selectedSophosTgSyncCount = computed(() =>
  sophosTgSyncRows.value.filter(r => r.selected && r.calcFound && r.newPrice > 0).length
)

const toggleSelectAllFilteredSophosTg = (checked) => {
  selectableFilteredSophosTgRows.value.forEach(r => {
    r.selected = Boolean(checked)
  })
}

const selectAllNeedSyncSophosTgRows = () => {
  sophosTgSyncRows.value.forEach(r => {
    r.selected = rowNeedsTgSync(r)
  })
}

const refreshSophosTgSyncModal = async () => {
  sophosTgSyncLoading.value = true
  try {
    await fetchVendorRefFilesMeta(true)
    await Promise.all([
      loadSophosCalcRefData(),
      loadSophosRefData().catch(() => null)
    ])
    if (!sophosCalcRefData.value?.calcSkus || !Object.keys(sophosCalcRefData.value.calcSkus).length) {
      showAsyncError(
        'Chưa có dữ liệu File Calculator Sophos',
        'Vui lòng upload file calculate_sophos.xlsx lên Cloudinary tại mục ☁️ File Calculator trước khi đồng bộ!'
      )
      return
    }
    const wb = await loadCurrentSophosTrungGianWorkbook()
    sophosTgLoadedWorkbook.value = wb
    buildSophosTgSyncPreviewRowsFromWorkbook(wb)
    sophosTgSyncFilter.value = sophosTgSyncSummary.value.needSync > 0 ? 'need_sync' : 'all'
  } catch (err) {
    console.error('Lỗi tải File Trung Gian Sophos để đối chiếu với Calculator:', err)
    showAsyncError('Lỗi đọc File Trung Gian Sophos', err.message)
  } finally {
    sophosTgSyncLoading.value = false
  }
}

const openSophosTrungGianCalcSyncModal = async () => {
  sophosTgSyncSearch.value = ''
  sophosTgSyncSheetFilter.value = 'ALL'
  showSophosTgSyncModal.value = true
  await refreshSophosTgSyncModal()
}

const downloadWorkbookBufferAsFile = (wb, fileName) => {
  const outArray = XLSX.write(wb, { bookType: 'xlsx', type: 'array', compression: true })
  const blob = new Blob([outArray], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = fileName
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  setTimeout(() => URL.revokeObjectURL(url), 6000)
}

const downloadCurrentLoadedSophosTgWorkbook = () => {
  if (!sophosTgLoadedWorkbook.value) return
  downloadWorkbookBufferAsFile(sophosTgLoadedWorkbook.value, sophosTgSyncFileName.value)
}

const applySophosTrungGianCalcSync = async () => {
  const wb = sophosTgLoadedWorkbook.value
  const selectedRows = sophosTgSyncRows.value.filter(r => r.selected && r.calcFound && r.newPrice > 0)
  if (!wb || !selectedRows.length) return

  syncingSophosTgFromCalc.value = true
  showAsyncLoading(
    '☁️ Đang đồng bộ giá vào File Trung Gian Sophos...',
    `Đang ghi ${selectedRows.length} dòng BOM + bảng LP Sophos và đẩy lên Cloudinary...`
  )
  try {
    const selectedMap = new Map(selectedRows.map(r => [r.id, r]))
    const {
      outBuffer,
      baseFileName,
      updatedPriceCells,
      updatedSkuCells,
      updatedLpModels
    } = await buildUpdatedSophosTrungGianExcelJs({
      selectedRowMap: selectedMap,
      updateSku2026: Boolean(sophosTgSyncUpdateSku2026.value)
    })

    const targetFileName = sophosTgSyncFileName.value || baseFileName || 'file_trung_gian_SOPHOS.xlsx'
    const syncedFile = new File([outBuffer], targetFileName, {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    })
    const updatedSheetJsWb = XLSX.read(outBuffer, {
      type: 'array',
      cellStyles: true,
      cellFormula: true,
      cellNF: true,
      cellDates: true
    })
    sophosTgLoadedWorkbook.value = updatedSheetJsWb

    await uploadAndPersistVendorRefWorkbook('sophos', syncedFile, updatedSheetJsWb, 'tg')

    if (sophosTgAutoDownloadAfterSync.value) {
      triggerExcelArrayBufferDownload(outBuffer, targetFileName)
    }

    buildSophosTgSyncPreviewRowsFromWorkbook(updatedSheetJsWb)
    if (sophosTgSyncSummary.value.needSync === 0) {
      sophosTgSyncFilter.value = 'all'
    }

    // Cập nhật luôn bảng đối chiếu ảnh hoặc card nếu đang mở
    await runImagePriceComparison().catch(() => {})
    if (showCardRefCompareModal.value && cardRefCompareData.value?.vendor === 'sophos' && cardRefCompareData.value?.item) {
      cardRefCompareData.value = await resolveSophosCardCompare(cardRefCompareData.value.item)
    }

    showAsyncSuccess(
      '☁️ Đồng bộ File Trung Gian thành công!',
      `Đã cập nhật ${updatedPriceCells} ô Giá BOM${updatedSkuCells > 0 ? `, ${updatedSkuCells} mã SKU 2026` : ''} và ${updatedLpModels} dòng Model trong LP Sophos lên Cloudinary ("${targetFileName}").`
    )
  } catch (err) {
    console.error('Lỗi đồng bộ File Trung Gian theo File Calculator:', err)
    showAsyncError('Lỗi đồng bộ File Trung Gian', err.message)
  } finally {
    syncingSophosTgFromCalc.value = false
  }
}

// ═══ THAY ĐỔI TỈ GIÁ (DÀNH CHO USD) ═══
const showUsdRateModal = ref(false)
const newUsdExchangeRate = ref(26200)
const usdRateScope = ref('all') // 'all' | 'filtered'
const updatingUsdRate = ref(false)
const customDefaultUsdRate = ref(
  typeof localStorage !== 'undefined' && Number(localStorage.getItem('custom_usd_exchange_rate')) > 1
    ? Number(localStorage.getItem('custom_usd_exchange_rate'))
    : 0
)

const isUsdCurrencyItem = (item) => {
  return String(item?.Don_vi_tien_te || '').trim().toUpperCase() === 'USD'
}

const usdItems = computed(() => {
  return items.value.filter(isUsdCurrencyItem)
})

const filteredUsdItems = computed(() => {
  return filteredItems.value.filter(isUsdCurrencyItem)
})

const currentSystemUsdRate = computed(() => {
  if (customDefaultUsdRate.value > 1) return customDefaultUsdRate.value
  // Tìm tỉ giá phổ biến nhất trong các sản phẩm USD hiện có
  const freq = new Map()
  let bestRate = 0
  let bestCount = 0
  for (const it of usdItems.value) {
    const r = Number(it.Ti_gia) || 0
    if (r > 1) {
      const c = (freq.get(r) || 0) + 1
      freq.set(r, c)
      if (c > bestCount) {
        bestCount = c
        bestRate = r
      }
    }
  }
  if (bestRate > 1) return bestRate
  return Number(sophosRefData.value?.tiGiaTrungGian) || 26200
})

const openUsdRateModal = () => {
  newUsdExchangeRate.value = currentSystemUsdRate.value || 26200
  usdRateScope.value = 'all'
  showUsdRateModal.value = true
}

const closeUsdRateModal = () => {
  if (updatingUsdRate.value) return
  showUsdRateModal.value = false
}

const applyUsdExchangeRateUpdate = async () => {
  const rate = Math.round(Number(newUsdExchangeRate.value) || 0)
  if (!(rate > 0)) {
    showAsyncError('Tỉ giá không hợp lệ', 'Vui lòng nhập tỉ giá USD lớn hơn 0.')
    return
  }

  const targetList = usdRateScope.value === 'filtered' ? filteredUsdItems.value : usdItems.value
  updatingUsdRate.value = true
  showAsyncLoading('Đang cập nhật tỉ giá USD...', `Áp dụng mức ${formatCurrency(rate, 'VND')} cho ${targetList.length} sản phẩm USD`)

  try {
    customDefaultUsdRate.value = rate
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem('custom_usd_exchange_rate', String(rate))
    }
    if (sophosRefData.value && typeof sophosRefData.value === 'object') {
      sophosRefData.value.tiGiaTrungGian = rate
    }

    const validTargets = targetList.filter(item => item && item._firebaseKey)
    const nowIso = new Date().toISOString()
    const CHUNK_SIZE = 400
    for (let i = 0; i < validTargets.length; i += CHUNK_SIZE) {
      const chunk = validTargets.slice(i, i + CHUNK_SIZE)
      const updatesObj = {}
      chunk.forEach(item => {
        updatesObj[`hang_hoa/${item._firebaseKey}/Ti_gia`] = rate
        updatesObj[`hang_hoa/${item._firebaseKey}/last_updated`] = nowIso
      })
      await update(dbRef(database), updatesObj)
    }

    // Cập nhật ngay trên state local để UI phản hồi tức thì
    const updatedKeys = new Set(validTargets.map(x => x._firebaseKey))
    items.value.forEach(item => {
      if (updatedKeys.has(item._firebaseKey)) {
        item.Ti_gia = rate
        item.last_updated = nowIso
      }
    })

    // Nếu người dùng đang mở sẵn dữ liệu import preview có dòng USD, cập nhật luôn tỉ giá USD trong bảng preview
    if (Array.isArray(importData.value) && importData.value.length > 0) {
      importData.value.forEach(row => {
        if (String(row.Don_vi_tien_te || '').trim().toUpperCase() === 'USD') {
          row.Ti_gia = rate
        }
      })
    }

    showUsdRateModal.value = false
    showAsyncSuccess(
      'Đã cập nhật tỉ giá USD thành công!',
      `Tỉ giá mới: ${formatCurrency(rate, 'VND')} • Đã áp dụng cho ${validTargets.length} sản phẩm USD.`
    )
  } catch (err) {
    console.error('Lỗi cập nhật tỉ giá USD:', err)
    showAsyncError('Lỗi cập nhật tỉ giá USD', err.message || 'Không thể lưu tỉ giá mới lên Firebase.')
  } finally {
    updatingUsdRate.value = false
  }
}

// =========================================================================
// GIỎ HÀNG BÁO GIÁ & CHUYỂN TÍNH TOÁN SANG TRANG BÁO GIÁ (ĐA TAB)
// =========================================================================
const router = useRouter()
const QUOTE_CART_STORAGE_KEY = 'nts_hanghoa_quote_cart_v1'
const quoteCart = ref([])
const showQuoteCartDrawer = ref(false)

const getCartItemKey = (item) => {
  if (!item || typeof item !== 'object') return ''
  return String(item._firebaseKey || item.Ma_hang || item.sku_code || item.Ten_hang || '').trim()
}

const saveQuoteCartToStorage = () => {
  try {
    if (!quoteCart.value.length) {
      localStorage.removeItem(QUOTE_CART_STORAGE_KEY)
    } else {
      localStorage.setItem(QUOTE_CART_STORAGE_KEY, JSON.stringify(quoteCart.value))
    }
  } catch (err) {
    console.warn('Không thể lưu giỏ hàng báo giá vào localStorage:', err)
  }
}

const restoreQuoteCartFromStorage = () => {
  try {
    const raw = localStorage.getItem(QUOTE_CART_STORAGE_KEY)
    if (!raw) return
    const parsed = JSON.parse(raw)
    if (Array.isArray(parsed)) {
      quoteCart.value = parsed.filter(x => x && x.key && Number(x.qty) > 0)
      if (quoteCart.value.length > 0 && (typeof window === 'undefined' || window.innerWidth > 1100)) {
        showQuoteCartDrawer.value = true
      }
    }
  } catch (err) {
    console.warn('Không thể khôi phục giỏ hàng báo giá:', err)
  }
}

const getCartEntryByItem = (item) => {
  const key = getCartItemKey(item)
  if (!key) return null
  return quoteCart.value.find(e => e.key === key) || null
}

const isInQuoteCart = (item) => {
  const entry = getCartEntryByItem(item)
  return Boolean(entry && Number(entry.qty) > 0)
}

const getCartItemQty = (item) => {
  const entry = getCartEntryByItem(item)
  return entry ? Math.max(1, Number(entry.qty) || 1) : 0
}

const addToQuoteCart = (item) => {
  if (!item) return
  const key = getCartItemKey(item)
  if (!key) return
  const existing = quoteCart.value.find(e => e.key === key)
  if (existing) {
    existing.qty = Math.max(1, Number(existing.qty) || 1) + 1
    existing.itemSnapshot = JSON.parse(JSON.stringify(item))
  } else {
    quoteCart.value.push({
      key,
      qty: 1,
      itemSnapshot: JSON.parse(JSON.stringify(item))
    })
  }
  if (typeof window === 'undefined' || window.innerWidth > 1100) {
    showQuoteCartDrawer.value = true
  }
  saveQuoteCartToStorage()
}

const removeFromQuoteCart = (item) => {
  const key = getCartItemKey(item)
  if (!key) return
  const idx = quoteCart.value.findIndex(e => e.key === key)
  if (idx !== -1) {
    quoteCart.value.splice(idx, 1)
    if (!quoteCart.value.length) {
      showQuoteCartDrawer.value = false
    }
    saveQuoteCartToStorage()
  }
}

const updateQuoteCartQty = (item, deltaOrVal, isAbsolute = false) => {
  const key = getCartItemKey(item)
  if (!key) return
  const entry = quoteCart.value.find(e => e.key === key)
  if (!entry) return

  const nextQty = isAbsolute
    ? Math.floor(Number(deltaOrVal) || 0)
    : Math.floor((Number(entry.qty) || 1) + Number(deltaOrVal))

  if (nextQty <= 0) {
    removeFromQuoteCart(item)
    return
  }

  entry.qty = nextQty
  entry.itemSnapshot = JSON.parse(JSON.stringify(item))
  saveQuoteCartToStorage()
}

const onCardCartQtyInputChange = (item, event) => {
  const rawVal = Number(event?.target?.value)
  if (!Number.isFinite(rawVal) || rawVal <= 0) {
    removeFromQuoteCart(item)
    return
  }
  updateQuoteCartQty(item, Math.max(1, Math.floor(rawVal)), true)
}

const clearQuoteCart = () => {
  quoteCart.value = []
  showQuoteCartDrawer.value = false
  saveQuoteCartToStorage()
}

const resolveLatestCartItem = (entry) => {
  if (!entry) return null
  const found = items.value.find(it => getCartItemKey(it) === entry.key)
  return found || entry.itemSnapshot || null
}

const getEffectiveItemUnitPrice = (item) => {
  if (!item) return 0
  const plEntry = activePriceList.value ? getPriceListEntry(item) : null
  if (plEntry && plEntry.gia_ban_moi !== undefined && plEntry.gia_ban_moi !== null) {
    return toNum(plEntry.gia_ban_moi, toNum(item.Don_gia, 0))
  }
  return toNum(item.Don_gia, 0)
}

const quoteCartEnrichedList = computed(() => {
  return quoteCart.value
    .map(entry => {
      const item = resolveLatestCartItem(entry)
      if (!item) return null
      const qty = Math.max(1, Number(entry.qty) || 1)
      const effectiveUnitPrice = getEffectiveItemUnitPrice(item)
      const tiGia = String(item.Don_vi_tien_te || '').trim().toUpperCase() === 'USD'
        ? Math.max(1, toNum(item.Ti_gia, 1))
        : 1
      const unitPriceVnd = Math.round(effectiveUnitPrice * tiGia)
      const lineTotalVnd = unitPriceVnd * qty
      const vatPct = Math.max(0, toNum(item.Thue_VAT, 0))
      const lineAfterTaxVnd = Math.round(lineTotalVnd * (1 + vatPct / 100))
      return {
        key: entry.key,
        qty,
        item,
        effectiveUnitPrice,
        unitPriceVnd,
        lineTotalVnd,
        lineAfterTaxVnd
      }
    })
    .filter(Boolean)
})

const quoteCartTotalQty = computed(() => {
  return quoteCartEnrichedList.value.reduce((sum, e) => sum + e.qty, 0)
})

const quoteCartTotalBeforeTaxVnd = computed(() => {
  return quoteCartEnrichedList.value.reduce((sum, e) => sum + e.lineTotalVnd, 0)
})

const quoteCartTotalAfterTaxVnd = computed(() => {
  return quoteCartEnrichedList.value.reduce((sum, e) => sum + e.lineAfterTaxVnd, 0)
})

const proceedToCalculateQuote = () => {
  if (!quoteCartEnrichedList.value.length) return

  const payloadItems = quoteCartEnrichedList.value.map(entry => {
    const p = entry.item
    const effectiveDonGia = entry.effectiveUnitPrice
    const giaTC = toNum(p.Gia_tieu_chuan, 0)
    const tiGia = toNum(p.Ti_gia, 1) || 1
    const vat = toNum(p.Thue_VAT, 0)
    const giaHw = toNum(p.gia_hardware, 0)
    const giaNhap = toNum(p.gia_nhap, 0)
    const mucOff = toNum(p.muc_phan_tram_off, 0)

    return {
      Ma_hang: String(p.Ma_hang ?? '').trim(),
      sku_code: String(p.sku_code ?? '').trim(),
      Ten_hang: String(p.Ten_hang ?? ''),
      Ten_hang_bao_gia: String(p.Ten_hang_bao_gia ?? ''),
      Description: String(p.Description ?? ''),
      Main_img: String(p.Main_img ?? ''),
      Ma_nha_cung_cap: String(p.Ma_nha_cung_cap ?? ''),
      Ten_nha_cung_cap: String(p.Ten_nha_cung_cap ?? ''),
      Mo_ta_chung: String(p.Mo_ta_chung ?? ''),
      Mo_ta_chi_tiet: String(p.Mo_ta_chi_tiet ?? ''),
      Features: String(p.Features ?? ''),
      Dien_giai_bao_gia: String(p.Dien_giai_bao_gia ?? ''),
      Danh_muc: String(p.Danh_muc ?? '').toUpperCase(),
      License_duration: String(p.License_duration ?? ''),
      DVT: String(p.DVT ?? ''),
      Gia_tieu_chuan: giaTC,
      Don_gia: effectiveDonGia,
      Trang_thai: String(p.Trang_thai ?? ''),
      Don_vi_tien_te: String(p.Don_vi_tien_te || 'VND'),
      Ti_gia: tiGia,
      Thue_VAT: vat,
      Ma_hang_lien_ket: String(p.Ma_hang_lien_ket ?? ''),
      Ten_hang_lien_ket: String(p.Ten_hang_lien_ket ?? ''),
      Ghi_chu: String(p.Ghi_chu ?? ''),
      gia_hardware: giaHw,
      gia_nhap: giaNhap,
      muc_phan_tram_off: mucOff,
      Type: String(p.Type ?? '').trim(),
      thoi_han_bao_hanh: String(p.thoi_han_bao_hanh ?? ''),
      volume: String(p.volume ?? ''),
      So_luong: entry.qty,
      _Don_gia_goc: effectiveDonGia,
      _Gia_tieu_chuan_goc: giaTC,
      _Ti_gia_goc: tiGia,
      _Thue_VAT_goc: vat,
      _gia_hardware_goc: giaHw,
      _gia_nhap_goc: giaNhap,
      _muc_phan_tram_off_goc: mucOff
    }
  })

  try {
    localStorage.setItem('cloneQuoteProducts', JSON.stringify(payloadItems))
    if (selectedPriceListId.value) {
      localStorage.setItem('cloneQuotePriceListId', String(selectedPriceListId.value))
    } else {
      localStorage.removeItem('cloneQuotePriceListId')
    }
  } catch (err) {
    console.error('Lỗi lưu danh sách sản phẩm chuyển sang báo giá:', err)
  }

  // Làm trống giỏ hàng ngay sau khi đẩy sang tab báo giá
  clearQuoteCart()

  // Điều hướng sang trang Báo giá Firebase
  router.push('/baogiafirebase')
}

