  try {
    localStorage.setItem(QLHH_VIEW_MODE_STORAGE_KEY, viewMode.value)
  } catch {}
}

const allCategoriesTotalCount = computed(() => {
  const setCats = new Set()
  items.value.forEach(item => {
    setCats.add(getItemCategory(item))
  })
  return setCats.size
})

const brandKpiCounts = computed(() => {
  let sophos = 0
  let kaspersky = 0
  let acronis = 0
  let others = 0
  items.value.forEach(item => {
    const b = getItemBrand(item)
    if (b === 'SOPHOS') sophos++
    else if (b === 'KASPERSKY') kaspersky++
    else if (b === 'ACRONIS') acronis++
    else others++
  })
  return { sophos, kaspersky, acronis, others }
})

const toggleBrandQuickFilter = (brandKey) => {
  selectedBrandFilter.value = selectedBrandFilter.value === brandKey ? '' : brandKey
}

const selectedBrandBtnLabel = computed(() => {
  if (!selectedBrandFilter.value) {
    return `Hãng (${brandFilterOptions.value.length})`
  }
  if (selectedBrandFilter.value === '__OTHER_BRANDS__') {
    return 'Hãng: Khác'
  }
  return `Hãng: ${selectedBrandFilter.value}`
})

const sortOrderLabel = computed(() => {
  if (sortOrder.value === 'newest') return 'Mới → Cũ'
  if (sortOrder.value === 'oldest') return 'Cũ → Mới'
  return 'Sắp xếp'
})

const showImportHubModal = ref(false)
const activeImportHubTab = ref('sophos')
const showCompareHubModal = ref(false)
const activeCompareHubTab = ref('sophos')

const resolvePreferredVendorHubTab = (tab = '', fallback = 'sophos') => {
  if (tab) return tab
  if (selectedBrandFilter.value === 'KASPERSKY') return 'kaspersky'
  if (selectedBrandFilter.value === 'ACRONIS') return 'acronis'
  if (selectedBrandFilter.value === 'SOPHOS') return 'sophos'
  return fallback
}

const openImportHub = (tab = '') => {
  activeImportHubTab.value = resolvePreferredVendorHubTab(tab, activeImportHubTab.value || 'sophos')
  showCompareHubModal.value = false
  showImportHubModal.value = true
}

const openCompareHub = (tab = '') => {
  const resolved = resolvePreferredVendorHubTab(tab, activeCompareHubTab.value || 'sophos')
  activeCompareHubTab.value = resolved === 'cost_pricing' ? 'sophos' : resolved
  showImportHubModal.value = false
  showCompareHubModal.value = true
}

const openVendorToolsHub = (tab = '') => {
  openImportHub(tab)
}

watch(
