    showImportModal,
    showImageCheckModal,
    showKasImageCheckModal,
    showAcronisCompareModal,
    showSophosDbSyncModal,
    showSophosTgSyncModal,
    showUsdRateModal,
    showPriceListModal
  ],
  (vals) => {
    if (vals.some(Boolean)) {
      if (showImportHubModal.value) showImportHubModal.value = false
      if (showCompareHubModal.value) showCompareHubModal.value = false
    }
  }
)

