  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.2s;
}
.pricelist-action-btn.edit {
  background: rgba(56, 189, 248, 0.15);
  color: #38bdf8;
  border-color: rgba(56, 189, 248, 0.3);
}
.pricelist-action-btn.edit:hover {
  background: rgba(56, 189, 248, 0.25);
}
.pricelist-action-btn.export {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.3);
}
.pricelist-action-btn.export:hover {
  background: rgba(16, 185, 129, 0.25);
}
.pricelist-action-btn.delete {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
  border-color: rgba(239, 68, 68, 0.3);
  padding: 5px 8px;
}
.pricelist-action-btn.delete:hover {
  background: rgba(239, 68, 68, 0.25);
}

.pl-card-diff-badge {
  display: inline-flex;
  align-items: center;
  padding: 1px 7px;
  border-radius: 99px;
  font-size: 10.5px;
  font-weight: 700;
}
.pl-card-diff-badge.up {
  background: rgba(16, 185, 129, 0.18);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.35);
}
.pl-card-diff-badge.down {
  background: rgba(245, 158, 11, 0.18);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.35);
}
.pl-card-diff-badge.neutral {
  background: rgba(148, 163, 184, 0.15);
  color: #94a3b8;
}

.pricelist-modal {
  max-width: 96vw !important;
  width: 1500px !important;
  height: 92vh !important;
}

.pl-config-section {
  display: grid;
  grid-template-columns: 1.25fr 1.25fr;
  gap: 14px;
  padding: 14px 20px;
  background: #0b1120;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}
@media (max-width: 1100px) {
  .pl-config-section {
    grid-template-columns: 1fr;
  }
}

.pl-config-card {
  background: rgba(30, 41, 59, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 12px 16px;
}
.pl-config-card--highlight {
  background: linear-gradient(135deg, rgba(245, 158, 11, 0.08), rgba(15, 23, 42, 0.75));
  border-color: rgba(245, 158, 11, 0.3);
}

.pl-config-card__title {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  font-weight: 700;
  color: #e2e8f0;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 10px;
}

.pl-config-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 10px;
}
.pl-config-grid--4 {
  grid-template-columns: 1.3fr 1fr 1fr 1.2fr;
}
@media (max-width: 900px) {
  .pl-config-grid--4 {
    grid-template-columns: 1fr 1fr;
  }
}

.pl-bulk-controls {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.pl-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.pl-field label {
  font-size: 11.5px;
  color: #94a3b8;
  font-weight: 600;
}

.pl-input, .pl-select {
  background: #0f172a;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 7px;
  color: #f8fafc;
  padding: 7px 10px;
  font-size: 13px;
  outline: none;
  width: 100%;
  box-sizing: border-box;
}
.pl-input:focus, .pl-select:focus {
  border-color: #f59e0b;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.15);
}
.pl-select--up {
  color: #34d399;
  font-weight: 700;
}
.pl-select--down {
  color: #fbbf24;
  font-weight: 700;
}

.pl-bulk-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.pl-apply-btn {
  padding: 8px 13px;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
}
.pl-apply-btn--selected {
  background: linear-gradient(135deg, #f59e0b, #d97706);
  color: #fff;
  box-shadow: 0 3px 10px rgba(245, 158, 11, 0.25);
}
.pl-apply-btn--selected:hover {
  background: linear-gradient(135deg, #fbbf24, #f59e0b);
  transform: translateY(-1px);
}
.pl-apply-btn--filtered {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.35);
}
.pl-apply-btn--filtered:hover {
  background: rgba(16, 185, 129, 0.25);
}

.pl-filter-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 10px 20px;
  background: #111827;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.pl-filter-group {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  flex: 1;
}

.pl-filter-select, .pl-filter-input {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 7px;
  color: #f8fafc;
  padding: 6px 11px;
  font-size: 12.5px;
  outline: none;
}
.pl-filter-input {
  width: 100%;
  padding-right: 28px;
  box-sizing: border-box;
}
.pl-filter-select:focus, .pl-filter-input:focus {
  border-color: #38bdf8;
}

.pl-view-tabs {
  display: inline-flex;
  background: #0f172a;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 7px;
  padding: 2px;
}
.pl-view-tab {
  background: transparent;
  border: none;
  color: #94a3b8;
  font-size: 11.5px;
  font-weight: 600;
  padding: 5px 10px;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.15s;
}
.pl-view-tab.active {
  background: rgba(56, 189, 248, 0.2);
  color: #38bdf8;
}

.pl-selection-btns {
  display: flex;
  gap: 8px;
}
.pl-mini-btn {
  background: rgba(59, 130, 246, 0.15);
  border: 1px solid rgba(59, 130, 246, 0.35);
  color: #60a5fa;
  padding: 5px 11px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
}
.pl-mini-btn:hover {
  background: rgba(59, 130, 246, 0.25);
}
.pl-mini-btn--muted {
  background: rgba(148, 163, 184, 0.1);
  border-color: rgba(148, 163, 184, 0.25);
  color: #94a3b8;
}
.pl-mini-btn--muted:hover {
  background: rgba(148, 163, 184, 0.2);
  color: #e2e8f0;
}

.pl-row-selected {
  background: rgba(16, 185, 129, 0.05) !important;
}

.pl-row-adjust {
  display: flex;
  align-items: center;
  gap: 5px;
}

.pl-row-select {
  background: #0f172a;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 5px;
  color: #e2e8f0;
  padding: 4px 6px;
  font-size: 11.5px;
  font-weight: 600;
  outline: none;
}
.pl-row-select.up {
  color: #34d399;
}
.pl-row-select.down {
  color: #fbbf24;
}

.pl-diff-up {
  color: #34d399;
  font-weight: 700;
}
.pl-diff-down {
  color: #fbbf24;
  font-weight: 700;
}
.pl-diff-zero {
  color: #64748b;
}

.pricelist-autosync-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 99px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
  border: 1px solid transparent;
}
.pricelist-autosync-btn.on {
  background: rgba(16, 185, 129, 0.16);
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.4);
}
.pricelist-autosync-btn.on:hover {
  background: rgba(16, 185, 129, 0.26);
}
.pricelist-autosync-btn.off {
  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
  border-color: rgba(148, 163, 184, 0.35);
}
.pricelist-autosync-btn.off:hover {
  background: rgba(148, 163, 184, 0.24);
}

.pl-autosync-box {
  margin-top: 10px;
  padding: 9px 12px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.75);
  border: 1px dashed rgba(148, 163, 184, 0.3);
  display: flex;
  flex-direction: column;
  gap: 3px;
  transition: all 0.2s;
}
.pl-autosync-box.active {
  background: rgba(16, 185, 129, 0.08);
  border: 1px solid rgba(16, 185, 129, 0.35);
}
.pl-autosync-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  user-select: none;
}
.pl-autosync-checkbox {
  width: 16px;
  height: 16px;
  accent-color: #10b981;
  cursor: pointer;
}
.pl-autosync-title {
  font-size: 12.5px;
  font-weight: 700;
  color: #e2e8f0;
}
.pl-autosync-box.active .pl-autosync-title {
  color: #34d399;
}
.pl-autosync-hint {
  font-size: 11px;
  color: #94a3b8;
  padding-left: 24px;
}

/* ═══ MOBILE RESPONSIVE & SCROLL FIX FOR PRICE LIST & IMPORT MODALS ═══ */
@media (max-width: 900px) {
  .import-overlay,
  .modal-overlay {
    z-index: 10050;
    padding: 6px;
    box-sizing: border-box;
  }

  .import-modal,
  .pricelist-modal {
    width: 98vw !important;
    max-width: 98vw !important;
    height: auto !important;
    max-height: calc(100dvh - 16px) !important;
    display: block !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch !important;
    overscroll-behavior: contain;
    touch-action: pan-y pan-x;
    border-radius: 14px;
  }

  .import-modal__header {
    position: sticky;
    top: 0;
    z-index: 40;
    background: rgba(15, 23, 42, 0.98);
    backdrop-filter: blur(12px);
    padding: 12px 14px;
  }

  .import-stats {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
    padding: 12px 14px;
  }

  .import-tabs {
    padding: 0 14px 12px;
  }

  .pl-config-section {
    padding: 12px;
    gap: 10px;
  }

  .pl-config-card {
    padding: 10px 12px;
  }

  .pl-filter-bar {
    padding: 10px 12px;
    gap: 10px;
  }

  .pl-filter-group {
    width: 100%;
  }

  .pl-filter-select {
    flex: 1 1 140px;
    max-width: 100% !important;
  }

  .pl-view-tabs {
    width: 100%;
    display: flex;
  }

  .pl-view-tab {
    flex: 1;
    text-align: center;
  }

  .pl-selection-btns {
    width: 100%;
    flex-wrap: wrap;
  }

  .pl-mini-btn {
    flex: 1 1 auto;
    text-align: center;
  }

  .import-modal .import-table-wrap,
  .pricelist-modal .import-table-wrap {
    flex: none !important;
    height: auto !important;
    min-height: 280px;
    max-height: 62dvh;
    margin: 10px 12px !important;
    overflow: auto !important;
    -webkit-overflow-scrolling: touch !important;
    touch-action: pan-x pan-y;
  }

  .import-modal__footer {
    flex-wrap: wrap;
    gap: 10px;
    padding: 12px 14px calc(16px + env(safe-area-inset-bottom, 0px)) 14px;
    background: rgba(15, 23, 42, 0.98);
  }
}

@media (max-width: 640px) {
  .pl-config-grid--4 {
    grid-template-columns: 1fr;
  }

  .pl-bulk-controls > .pl-field {
    width: 100%;
    flex: 1 1 100% !important;
  }

  .pl-bulk-actions {
    width: 100%;
  }

  .pl-apply-btn {
    flex: 1 1 100%;
    text-align: center;
    white-space: normal;
  }
}

/* ═══ BUTTON & MODAL ĐỐI CHIẾU GIÁ TỪ ẢNH (BƯỚC 1) ═══ */
.btn-image-check {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.18), rgba(6, 182, 212, 0.16));
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.45);
  font-weight: 600;
  box-shadow: 0 2px 10px rgba(16, 185, 129, 0.15);
}
.btn-image-check:hover {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.3), rgba(6, 182, 212, 0.25));
  border-color: #34d399;
  color: #ecfdf5;
  transform: translateY(-1px);
}

.imgcheck-modal {
  max-width: 1360px !important;
  width: 96vw !important;
  max-height: 92vh !important;
}

.imgcheck-step-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 99px;
  font-size: 12px;
  font-weight: 700;
  background: rgba(16, 185, 129, 0.18);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.4);
}

.imgcheck-body {
  flex: 1;
  overflow-y: auto;
  padding: 18px 22px;
  display: flex;
  flex-direction: column;
  min-height: 360px;
}

.imgcheck-dropzone {
  flex: 1;
  min-height: 320px;
  border: 2px dashed rgba(56, 189, 248, 0.35);
  border-radius: 14px;
  background: rgba(15, 23, 42, 0.65);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 36px 24px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
}
.imgcheck-dropzone:hover,
.imgcheck-dropzone.drag-over {
  border-color: #34d399;
  background: rgba(16, 185, 129, 0.08);
}
.imgcheck-dropzone__icon {
  width: 78px;
  height: 78px;
  border-radius: 50%;
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
  display: flex;
  align-items: center;
  justify-content: center;
}
.imgcheck-dropzone__title {
  font-size: 16px;
  color: #e2e8f0;
  font-weight: 500;
}
.imgcheck-dropzone__title span {
  color: #34d399;
  font-weight: 700;
  text-decoration: underline;
}
.imgcheck-dropzone__title kbd {
  background: #1e293b;
  border: 1px solid rgba(148, 163, 184, 0.35);
  border-radius: 6px;
  padding: 2px 8px;
  font-size: 13px;
  color: #38bdf8;
  font-weight: 700;
}
.imgcheck-dropzone__hint {
  font-size: 13px;
  color: #64748b;
}

.imgcheck-scanning {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 24px;
}
.imgcheck-scanner-box {
  position: relative;
  max-width: 560px;
  max-height: 300px;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(56, 189, 248, 0.4);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.5);
}
.imgcheck-scanning-img {
  display: block;
  max-width: 100%;
  max-height: 300px;
  object-fit: contain;
  opacity: 0.75;
}
.imgcheck-scanner-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent, #34d399, #38bdf8, transparent);
  box-shadow: 0 0 14px #34d399;
  animation: imgcheck-scan 2s ease-in-out infinite;
  z-index: 2;
}
@keyframes imgcheck-scan {
  0%, 100% { top: 4%; }
  50% { top: 94%; }
}
.imgcheck-progress-wrap {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.imgcheck-progress-label {
  display: flex;
  justify-content: space-between;
  font-size: 13.5px;
  color: #cbd5e1;
}
.imgcheck-progress-bar {
  width: 100%;
  height: 8px;
  border-radius: 99px;
  background: rgba(30, 41, 59, 0.9);
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.2);
}
.imgcheck-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #10b981, #38bdf8);
  transition: width 0.25s ease;
}

.imgcheck-result-grid {
  display: grid;
  grid-template-columns: 340px 1fr;
  gap: 16px;
  align-items: start;
}
.imgcheck-left-col {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.imgcheck-right-col {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}
.imgcheck-preview-wrap {
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: #090d16;
  cursor: zoom-in;
  max-height: 240px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.imgcheck-preview-img {
  width: 100%;
  max-height: 240px;
  object-fit: contain;
  display: block;
}
.imgcheck-ai-btn {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 14px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid rgba(167, 139, 250, 0.5);
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.25), rgba(59, 130, 246, 0.22));
  color: #e9d5ff;
  transition: all 0.2s;
}
.imgcheck-ai-btn:hover:not(:disabled) {
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.4), rgba(59, 130, 246, 0.35));
  border-color: #c084fc;
}
.imgcheck-ai-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
.imgcheck-error-box {
  padding: 10px 12px;
  border-radius: 8px;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.35);
  color: #fca5a5;
  font-size: 12.5px;
}
.imgcheck-settings-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}
.imgcheck-table-wrap {
  max-height: 360px;
  overflow: auto;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.16);
}
.imgcheck-row-na {
  opacity: 0.52;
}

/* Step 2: 4-way Price Reconciliation Styles */
.imgcheck-stepper {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.85);
  border: 1px solid rgba(148, 163, 184, 0.2);
}
.imgcheck-step-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 7px;
  border: 1px solid transparent;
  background: transparent;
  color: #94a3b8;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
}
.imgcheck-step-tab:hover:not(:disabled) {
  color: #e2e8f0;
  background: rgba(51, 65, 85, 0.45);
}
.imgcheck-step-tab.active {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.22), rgba(59, 130, 246, 0.22));
  border-color: rgba(16, 185, 129, 0.45);
  color: #6ee7b7;
}
.imgcheck-step-tab:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.imgcheck-step-num {
  width: 20px;
  height: 20px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.2);
  color: #e2e8f0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
}
.imgcheck-step-tab.active .imgcheck-step-num {
  background: #10b981;
  color: #052e16;
}
.imgcheck-step-badge {
  padding: 1px 7px;
  border-radius: 999px;
  background: rgba(59, 130, 246, 0.25);
  color: #93c5fd;
  font-size: 11px;
  font-weight: 800;
}

.imgcheck-compare-container {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.imgcheck-compare-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(195px, 1fr));
  gap: 10px;
}
.imgcheck-stat-card {
  padding: 12px 14px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.18);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.imgcheck-stat-label {
  font-size: 11.5px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.imgcheck-stat-value {
  font-size: 22px;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1.15;
}
.imgcheck-stat-sub {
  font-size: 11.5px;
  color: #cbd5e1;
}
.imgcheck-stat-ok {
  border-color: rgba(16, 185, 129, 0.35);
  background: linear-gradient(180deg, rgba(16, 185, 129, 0.1), rgba(15, 23, 42, 0.8));
}
.imgcheck-stat-ok .imgcheck-stat-value {
  color: #34d399;
}
.imgcheck-stat-info {
  border-color: rgba(59, 130, 246, 0.35);
  background: linear-gradient(180deg, rgba(59, 130, 246, 0.1), rgba(15, 23, 42, 0.8));
}
.imgcheck-stat-info .imgcheck-stat-value {
  color: #60a5fa;
}
.imgcheck-stat-warn {
  border-color: rgba(245, 158, 11, 0.4);
  background: linear-gradient(180deg, rgba(245, 158, 11, 0.12), rgba(15, 23, 42, 0.8));
}
.imgcheck-stat-warn .imgcheck-stat-value {
  color: #fbbf24;
}
.imgcheck-stat-danger {
  border-color: rgba(244, 63, 94, 0.4);
  background: linear-gradient(180deg, rgba(244, 63, 94, 0.12), rgba(15, 23, 42, 0.8));
}
.imgcheck-stat-danger .imgcheck-stat-value {
  color: #fb7185;
}

.imgcheck-compare-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 10px 14px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid rgba(148, 163, 184, 0.16);
}
.imgcheck-filter-pills {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.imgcheck-pill {
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  color: #cbd5e1;
  background: rgba(30, 41, 59, 0.75);
  border: 1px solid rgba(148, 163, 184, 0.2);
  cursor: pointer;
  transition: all 0.18s;
}
.imgcheck-pill:hover {
  border-color: rgba(148, 163, 184, 0.45);
  color: #ffffff;
}
.imgcheck-pill.active {
  background: rgba(59, 130, 246, 0.25);
  border-color: #60a5fa;
  color: #93c5fd;
}
.imgcheck-pill-warn.active {
  background: rgba(245, 158, 11, 0.22);
  border-color: #fbbf24;
  color: #fde68a;
}
.imgcheck-pill-danger.active {
  background: rgba(244, 63, 94, 0.22);
  border-color: #fb7185;
  color: #fecdd3;
}
.imgcheck-pill-info.active {
  background: rgba(139, 92, 246, 0.22);
  border-color: #a78bfa;
  color: #ddd6fe;
}
.imgcheck-upload-ref-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 11px;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 600;
  color: #cbd5e1;
  background: rgba(30, 41, 59, 0.85);
  border: 1px dashed rgba(148, 163, 184, 0.35);
  cursor: pointer;
  transition: all 0.2s;
}
.imgcheck-upload-ref-btn:hover {
  border-color: #38bdf8;
  color: #bae6fd;
}

.imgcheck-compare-table-wrap {
  max-height: 470px;
  overflow: auto;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(15, 23, 42, 0.7);
}
.imgcheck-compare-table th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: #0f172a;
  font-size: 11.5px;
  white-space: nowrap;
}
.imgcheck-compare-table td {
  vertical-align: middle;
  padding: 9px 10px;
}
.cmp-row-warning {
  background: rgba(245, 158, 11, 0.05);
}
.cmp-row-missing {
  background: rgba(244, 63, 94, 0.05);
}
.cmp-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}
.cmp-badge-ok {
  background: rgba(16, 185, 129, 0.16);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.35);
}
.cmp-badge-warn {
  background: rgba(245, 158, 11, 0.16);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.35);
}
.cmp-badge-danger {
  background: rgba(244, 63, 94, 0.16);
  color: #fb7185;
  border: 1px solid rgba(244, 63, 94, 0.35);
}
.cmp-badge-info {
  background: rgba(59, 130, 246, 0.16);
  color: #93c5fd;
  border: 1px solid rgba(59, 130, 246, 0.35);
}
.cmp-badge-muted {
  background: rgba(148, 163, 184, 0.12);
  color: #94a3b8;
  border: 1px solid rgba(148, 163, 184, 0.22);
}
.cmp-mini-dot {
  width: 20px;
  height: 20px;
  border-radius: 5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 800;
}
.cmp-dot-ok {
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.4);
}
.cmp-dot-warn {
  background: rgba(245, 158, 11, 0.2);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.4);
}
.cmp-dot-miss {
  background: rgba(244, 63, 94, 0.2);
  color: #fb7185;
  border: 1px solid rgba(244, 63, 94, 0.4);
}
.cmp-action-btn {
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s;
  white-space: nowrap;
}
.cmp-action-update {
  background: rgba(245, 158, 11, 0.2);
  border: 1px solid rgba(245, 158, 11, 0.45);
  color: #fde68a;
}
.cmp-action-update:hover:not(:disabled) {
  background: rgba(245, 158, 11, 0.35);
}
.cmp-action-insert {
  background: rgba(59, 130, 246, 0.2);
  border: 1px solid rgba(59, 130, 246, 0.45);
  color: #bfdbfe;
}
.cmp-action-insert:hover:not(:disabled) {
  background: rgba(59, 130, 246, 0.35);
}
.cmp-action-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Clickable SKU & Excel Row Navigation Chips */
.sku-clickable-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: monospace;
  font-weight: 700;
  color: #38bdf8;
  font-size: 12px;
  background: rgba(56, 189, 248, 0.14);
  border: 1px solid rgba(56, 189, 248, 0.35);
  padding: 2px 8px;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.18s;
}
.sku-clickable-badge:hover {
  background: rgba(56, 189, 248, 0.28);
  border-color: #38bdf8;
  color: #e0f2fe;
  transform: translateY(-1px);
}
.sku-jump-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 5px;
  font-size: 10.5px;
  font-weight: 700;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  transition: all 0.16s;
  white-space: nowrap;
}
.sku-jump-chip--calc {
  background: rgba(20, 184, 166, 0.18);
  border: 1px solid rgba(20, 184, 166, 0.5);
  color: #5eead4;
}
.sku-jump-chip--calc:hover {
  background: rgba(20, 184, 166, 0.32);
  border-color: #2dd4bf;
  color: #f0fdfa;
}
.sku-jump-chip--calc-sub {
  background: rgba(6, 182, 212, 0.14);
  border: 1px dashed rgba(6, 182, 212, 0.45);
  color: #67e8f9;
}
.sku-jump-chip--calc-sub:hover {
  background: rgba(6, 182, 212, 0.28);
  border-color: #22d3ee;
  color: #ecfeff;
}
.excel-jump-chip--calc {
  background: rgba(20, 184, 166, 0.18);
  border: 1px solid rgba(20, 184, 166, 0.5);
  color: #5eead4;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
}
.excel-jump-chip--calc:hover {
  background: rgba(20, 184, 166, 0.32);
  border-color: #2dd4bf;
  color: #f0fdfa;
}
.sku-jump-chip--goc {
  background: rgba(16, 185, 129, 0.14);
  border: 1px solid rgba(16, 185, 129, 0.38);
  color: #6ee7b7;
}
.sku-jump-chip--goc:hover {
  background: rgba(16, 185, 129, 0.28);
  border-color: #10b981;
  color: #ecfdf5;
}
.sku-jump-chip--goc-sub {
  background: rgba(20, 184, 166, 0.12);
  border: 1px dashed rgba(20, 184, 166, 0.38);
  color: #5eead4;
}
.sku-jump-chip--goc-sub:hover {
  background: rgba(20, 184, 166, 0.26);
  border-color: #14b8a6;
}
.sku-jump-chip--tg {
  background: rgba(168, 85, 247, 0.15);
  border: 1px solid rgba(168, 85, 247, 0.4);
  color: #d8b4fe;
}
.sku-jump-chip--tg:hover {
  background: rgba(168, 85, 247, 0.3);
  border-color: #a855f7;
  color: #faf5ff;
}
.sku-jump-chip--tg-lp {
  background: rgba(59, 130, 246, 0.14);
  border: 1px dashed rgba(59, 130, 246, 0.38);
  color: #93c5fd;
}
.sku-jump-chip--tg-lp:hover {
  background: rgba(59, 130, 246, 0.28);
  border-color: #3b82f6;
}
.sku-jump-chip--skulist {
  background: rgba(245, 158, 11, 0.16);
  border: 1px solid rgba(245, 158, 11, 0.45);
  color: #fde68a;
}
.sku-jump-chip--skulist:hover {
  background: rgba(245, 158, 11, 0.32);
  border-color: #f59e0b;
  color: #fffbeb;
}
.sku-jump-chip--skulist-hw {
  background: rgba(234, 88, 12, 0.15);
  border: 1px dashed rgba(249, 115, 22, 0.45);
  color: #fdba74;
}
.sku-jump-chip--skulist-hw:hover {
  background: rgba(234, 88, 12, 0.3);
  border-color: #f97316;
  color: #ffedd5;
}

/* Excel Sheet Navigator Modal */
.excel-nav-modal {
  max-width: 1420px;
  width: 97vw;
  height: 90vh;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
  background: #0b1120;
  border: 1px solid rgba(56, 189, 248, 0.3);
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.85);
}
.excel-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  background: linear-gradient(90deg, #0f172a, #1e293b);
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  flex-wrap: wrap;
}
.excel-nav-file-switcher {
  display: inline-flex;
  background: #090d16;
  padding: 3px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  gap: 4px;
}
.excel-nav-file-btn {
  padding: 5px 11px;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: #94a3b8;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s;
}
.excel-nav-file-btn.active {
  background: rgba(16, 185, 129, 0.22);
  color: #6ee7b7;
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.45);
}
.excel-nav-sku-pill {
  padding: 4px 10px;
  border-radius: 6px;
  background: rgba(56, 189, 248, 0.15);
  border: 1px solid rgba(56, 189, 248, 0.35);
  color: #bae6fd;
  font-family: monospace;
  font-size: 12.5px;
}
.excel-nav-coord-pill {
  padding: 4px 10px;
  border-radius: 6px;
  background: rgba(245, 158, 11, 0.18);
  border: 1px solid rgba(245, 158, 11, 0.45);
  color: #fde68a;
  font-family: monospace;
  font-weight: 700;
  font-size: 12.5px;
}
.excel-nav-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 11px;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
  background: rgba(30, 41, 59, 0.9);
  border: 1px solid rgba(148, 163, 184, 0.3);
  color: #e2e8f0;
  cursor: pointer;
  transition: all 0.18s;
}
.excel-nav-action-btn:hover {
  border-color: #38bdf8;
  color: #ffffff;
  background: rgba(51, 65, 85, 0.9);
}
.excel-nav-action-btn--copy {
  background: rgba(16, 185, 129, 0.18);
  border-color: rgba(16, 185, 129, 0.45);
  color: #6ee7b7;
}
.excel-nav-action-btn--excel {
  background: rgba(22, 163, 74, 0.22);
  border-color: rgba(34, 197, 94, 0.5);
  color: #86efac;
}
.excel-nav-locations-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  background: #0f172a;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  flex-wrap: wrap;
}
.excel-nav-loc-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(148, 163, 184, 0.25);
  color: #cbd5e1;
  cursor: pointer;
  transition: all 0.16s;
}
.excel-nav-loc-pill:hover {
  border-color: #38bdf8;
  color: #fff;
}
.excel-nav-loc-pill.active {
  background: rgba(245, 158, 11, 0.22);
  border-color: #fbbf24;
  color: #fef08a;
  box-shadow: 0 0 12px rgba(245, 158, 11, 0.25);
}
.excel-nav-loc-pill .loc-cell {
  font-family: monospace;
  font-weight: 700;
  color: #38bdf8;
}
.excel-nav-loc-pill.active .loc-cell {
  color: #fde047;
}
.excel-nav-formulabar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: #111827;
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
}
.excel-nav-namebox {
  min-width: 74px;
  padding: 4px 10px;
  border-radius: 5px;
  background: #090d16;
  border: 1px solid rgba(148, 163, 184, 0.28);
  color: #fbbf24;
  font-family: monospace;
  font-weight: 800;
  font-size: 12.5px;
  text-align: center;
}
.excel-nav-fx {
  font-family: Georgia, serif;
  font-style: italic;
  font-weight: 700;
  color: #94a3b8;
  padding: 0 4px;
}
.excel-nav-formulavalue {
  flex: 1;
  min-width: 0;
  padding: 4px 10px;
  border-radius: 5px;
  background: #090d16;
  border: 1px solid rgba(148, 163, 184, 0.2);
  color: #f1f5f9;
  font-family: monospace;
  font-size: 12.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.excel-nav-searchwrap {
  display: flex;
  align-items: center;
  gap: 5px;
}
.excel-nav-searchinput {
  width: 250px;
  padding: 4px 10px;
  border-radius: 5px;
  background: #090d16;
  border: 1px solid rgba(148, 163, 184, 0.28);
  color: #f8fafc;
  font-size: 12px;
}
.excel-nav-searchbtn {
  padding: 4px 10px;
  border-radius: 5px;
  background: rgba(56, 189, 248, 0.2);
  border: 1px solid rgba(56, 189, 248, 0.4);
  color: #bae6fd;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}
.excel-nav-window-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 14px;
  background: rgba(30, 58, 138, 0.35);
  border-bottom: 1px solid rgba(59, 130, 246, 0.3);
  font-size: 12px;
  color: #bfdbfe;
}
.excel-nav-grid-wrap {
  flex: 1;
  overflow: auto;
  background: #090d16;
  position: relative;
}
.excel-nav-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}
.excel-nav-table thead th {
  position: sticky;
  top: 0;
  z-index: 3;
  background: #1e293b;
  color: #94a3b8;
  font-weight: 700;
  font-family: monospace;
  text-align: center;
  padding: 5px 8px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  min-width: 90px;
}
.excel-nav-table thead th.excel-col-corner {
  min-width: 54px;
  width: 54px;
  left: 0;
  z-index: 4;
  background: #0f172a;
}
.excel-nav-table thead th.excel-col-active {
  background: rgba(245, 158, 11, 0.25);
  color: #fde047;
  border-bottom: 2px solid #fbbf24;
}
.excel-nav-table tbody td {
  border: 1px solid rgba(148, 163, 184, 0.14);
  padding: 5px 8px;
  color: #e2e8f0;
  vertical-align: top;
  max-width: 340px;
  cursor: cell;
}
.excel-nav-table tbody td.excel-row-num {
  position: sticky;
  left: 0;
  z-index: 2;
  background: #1e293b;
  color: #94a3b8;
  font-family: monospace;
  font-weight: 700;
  text-align: right;
  padding-right: 8px;
  user-select: none;
  min-width: 54px;
}
.excel-cell-inner {
  max-height: 64px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: pre-wrap;
  line-height: 1.35;
}
.excel-cell-num {
  text-align: right;
  font-family: 'JetBrains Mono', Consolas, monospace;
  font-variant-numeric: tabular-nums;
  color: #34d399;
  white-space: nowrap !important;
  max-width: none !important;
}
.excel-cell-sku {
  font-family: 'JetBrains Mono', Consolas, monospace;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  color: #38bdf8;
  white-space: nowrap !important;
  max-width: none !important;
}
.excel-cell-num .excel-cell-inner,
.excel-cell-sku .excel-cell-inner {
  white-space: nowrap !important;
  word-break: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  max-height: none !important;
}
.excel-row-header td {
  background: rgba(30, 41, 59, 0.92);
  font-weight: 800;
  color: #f8fafc;
}
.excel-row-group td {
  background: rgba(59, 130, 246, 0.14);
  font-weight: 700;
  color: #93c5fd;
}
@keyframes excel-row-glow-pulse {
  0%, 100% {
    box-shadow: inset 0 0 18px rgba(245, 158, 11, 0.28);
  }
  50% {
    box-shadow: inset 0 0 28px rgba(16, 185, 129, 0.42);
  }
}
.excel-row-target {
  animation: excel-row-glow-pulse 2.2s infinite ease-in-out;
  position: relative;
}
.excel-row-target td {
  background: linear-gradient(90deg, rgba(245, 158, 11, 0.34), rgba(16, 185, 129, 0.26)) !important;
  border-top: 2px solid #fbbf24 !important;
  border-bottom: 2px solid #fbbf24 !important;
  color: #ffffff !important;
  font-weight: 700 !important;
}
.excel-row-target td .excel-cell-inner {
  max-height: none;
  color: #fef08a;
  font-weight: 700;
}
.excel-row-target td.excel-cell-num .excel-cell-inner {
  color: #6ee7b7;
  font-size: 13px;
  font-weight: 800;
}
.excel-row-target td.excel-row-num {
  background: linear-gradient(135deg, #f59e0b, #10b981) !important;
  color: #052e16 !important;
  font-weight: 900 !important;
  border-left: 3px solid #fde047 !important;
}
.excel-target-arrow {
  margin-right: 3px;
  font-size: 10px;
}
.excel-cell-target {
  outline: 2.5px solid #34d399 !important;
  outline-offset: -2px;
  background: rgba(16, 185, 129, 0.4) !important;
  color: #ffffff !important;
  font-weight: 800;
}
.cmp-row--active-sku td {
  background: linear-gradient(90deg, rgba(245, 158, 11, 0.2), rgba(56, 189, 248, 0.16)) !important;
  border-top: 1.5px solid #fbbf24 !important;
  border-bottom: 1.5px solid #fbbf24 !important;
}
.excel-nav-sheetbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 12px;
  background: #0f172a;
  border-top: 1px solid rgba(148, 163, 184, 0.24);
  flex-wrap: wrap;
}
.excel-nav-sheettabs {
  display: flex;
  align-items: center;
  gap: 4px;
  overflow-x: auto;
  max-width: 100%;
  padding-bottom: 2px;
}
.excel-nav-sheettab {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 11px;
  border-radius: 6px 6px 0 0;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: #1e293b;
  color: #94a3b8;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.16s;
}
.excel-nav-sheettab:hover {
  color: #f8fafc;
  background: #334155;
}
.excel-nav-sheettab.active {
  background: #090d16;
  color: #34d399;
  border-color: #10b981;
  border-bottom-color: #090d16;
}
.excel-nav-sheettab.has-sku {
  border-color: rgba(245, 158, 11, 0.5);
}
.sheet-sku-dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: #fbbf24;
  box-shadow: 0 0 6px #fbbf24;
}
.excel-nav-statusbar {
  font-size: 11.5px;
  color: #94a3b8;
}
.excel-nav-table {
  width: max-content;
  min-width: 100%;
}
@media (max-width: 768px) {
  .excel-nav-modal {
    width: 100vw;
    max-width: 100vw;
    height: 100dvh;
    max-height: 100dvh;
    border-radius: 0;
  }
  .excel-nav-header {
    padding: 8px 10px;
    gap: 6px;
  }
  .excel-nav-file-switcher {
    overflow-x: auto;
    max-width: 100%;
  }
  .excel-nav-file-btn {
    white-space: nowrap;
    padding: 4px 8px;
    font-size: 11px;
  }
  .excel-nav-locations-bar {
    flex-wrap: nowrap;
    overflow-x: auto;
    padding: 5px 10px;
  }
  .excel-nav-locations-bar > div {
    flex-wrap: nowrap !important;
  }
  .excel-nav-loc-pill {
    white-space: nowrap;
    flex-shrink: 0;
  }
  .excel-nav-formulabar {
    padding: 5px 8px;
    gap: 5px;
  }
  .excel-nav-searchinput {
    width: 130px;
  }
  .excel-nav-grid-wrap {
    flex: 1 1 auto;
    min-height: 55dvh;
    -webkit-overflow-scrolling: touch;
  }
  .excel-nav-statusbar {
    display: none;
  }
}

.card-ref-compare-btn {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 12px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
}
.card-ref-compare-btn--sophos {
  background: rgba(56, 189, 248, 0.13);
  border: 1px solid rgba(56, 189, 248, 0.42);
  color: #38bdf8;
}
.card-ref-compare-btn--sophos:hover {
  background: rgba(56, 189, 248, 0.25);
  border-color: #38bdf8;
  color: #e0f2fe;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(56, 189, 248, 0.22);
}
.card-ref-compare-btn--kas {
  background: rgba(16, 185, 129, 0.13);
  border: 1px solid rgba(16, 185, 129, 0.42);
  color: #34d399;
}
.card-ref-compare-btn--kas:hover {
  background: rgba(16, 185, 129, 0.25);
  border-color: #10b981;
  color: #ecfdf5;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.22);
}
.card-ref-compare-btn--acronis {
  background: rgba(99, 102, 241, 0.15);
  border: 1px solid rgba(129, 140, 248, 0.45);
  color: #a5b4fc;
}
.card-ref-compare-btn--acronis:hover {
  background: rgba(99, 102, 241, 0.28);
  border-color: #818cf8;
  color: #e0e7ff;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.25);
}

/* Bộ lọc Sắp xếp & Dropdown Hãng / Danh mục / Nhà cung cấp (Lazy Loading) */
.hh-filter-sort-group {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.hh-filter-select {
  height: 40px;
  padding: 0 14px;
  border-radius: 99px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(15, 23, 42, 0.72);
  color: #f8fafc;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  outline: none;
  transition: all 0.2s ease;
}
.hh-filter-select:hover,
.hh-filter-select:focus {
  border-color: rgba(56, 189, 248, 0.5);
  background: rgba(15, 23, 42, 0.92);
}

.hh-lazy-dropdown {
  position: relative;
}

.hh-lazy-dropdown__trigger {
  height: 40px;
  padding: 0 14px;
  border-radius: 99px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(15, 23, 42, 0.72);
  color: #e2e8f0;
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.hh-lazy-dropdown__trigger:hover {
  border-color: rgba(20, 184, 166, 0.5);
  background: rgba(15, 23, 42, 0.92);
}
.hh-lazy-dropdown__trigger.active {
  border-color: rgba(20, 184, 166, 0.65);
  background: rgba(20, 184, 166, 0.16);
  color: #5eead4;
}
.hh-lazy-dropdown__caret {
  font-size: 11px;
  color: #94a3b8;
}

.hh-lazy-dropdown__menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  min-width: 250px;
  max-width: 340px;
  background: #0f172a;
  border: 1px solid rgba(56, 189, 248, 0.35);
  border-radius: 12px;
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.65);
  z-index: 120;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.hh-lazy-dropdown__menu--wide {
  min-width: 310px;
  max-width: 420px;
}

.hh-lazy-dropdown__search-wrap {
  padding: 8px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(15, 23, 42, 0.95);
}

.hh-lazy-dropdown__search {
  width: 100%;
  padding: 7px 10px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(30, 41, 59, 0.8);
  color: #f8fafc;
  font-size: 12.5px;
  outline: none;
  box-sizing: border-box;
}
.hh-lazy-dropdown__search:focus {
  border-color: #38bdf8;
}

.hh-lazy-dropdown__list {
  max-height: 280px;
  overflow-y: auto;
  padding: 4px 0;
}
.hh-lazy-dropdown__list::-webkit-scrollbar {
  width: 6px;
}
.hh-lazy-dropdown__list::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.3);
  border-radius: 3px;
}

.hh-lazy-dropdown__item {
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 12.5px;
  color: #cbd5e1;
  cursor: pointer;
  transition: background 0.15s ease;
}
.hh-lazy-dropdown__item span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hh-lazy-dropdown__item:hover {
  background: rgba(56, 189, 248, 0.12);
  color: #f8fafc;
}
.hh-lazy-dropdown__item.selected {
  background: rgba(20, 184, 166, 0.2);
  color: #5eead4;
  font-weight: 700;
}

.hh-lazy-dropdown__count {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.08);
  color: #94a3b8;
  flex-shrink: 0;
}

.hh-lazy-dropdown__empty {
  padding: 14px 12px;
  text-align: center;
  font-size: 12px;
  color: #64748b;
}

.hh-lazy-dropdown__more {
  padding: 8px 12px;
  text-align: center;
  font-size: 11.5px;
  font-weight: 600;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.08);
  cursor: pointer;
  border-top: 1px dashed rgba(56, 189, 248, 0.25);
}
.hh-lazy-dropdown__more:hover {
  background: rgba(56, 189, 248, 0.16);
}

.hh-clear-filter-btn {
  height: 40px;
  padding: 0 14px;
  border-radius: 99px;
  border: 1px solid rgba(239, 68, 68, 0.45);
  background: rgba(239, 68, 68, 0.14);
  color: #fca5a5;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
}
.hh-clear-filter-btn:hover {
  background: rgba(239, 68, 68, 0.26);
  color: #fee2e2;
}

@media (max-width: 1024px) {
  .imgcheck-result-grid {
    grid-template-columns: 1fr;
  }
  .imgcheck-settings-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .imgcheck-compare-stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* =========================================================
   GIỎ HÀNG BÁO GIÁ TRÊN CARD & THANH TÍNH TOÁN NỔI
   ========================================================= */
.product-card.in-quote-cart {
  border-color: rgba(16, 185, 129, 0.7) !important;
  box-shadow: 0 0 0 1px rgba(16, 185, 129, 0.35), 0 10px 25px -5px rgba(16, 185, 129, 0.18) !important;
}

.card-cart-action-box {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed rgba(255, 255, 255, 0.1);
}

.card-add-cart-btn {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid rgba(16, 185, 129, 0.45);
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.18) 0%, rgba(5, 150, 105, 0.24) 100%);
  color: #34d399;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.card-add-cart-btn:hover {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
  border-color: #10b981;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.35);
  transform: translateY(-1px);
}

.card-cart-qty-cluster {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 8px;
  border-radius: 8px;
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.45);
}

.card-cart-selected-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 700;
  color: #34d399;
  white-space: nowrap;
}

.card-cart-stepper {
  display: inline-flex;
  align-items: center;
  background: rgba(15, 23, 42, 0.85);
  border: 1px solid rgba(51, 65, 85, 0.85);
  border-radius: 6px;
  overflow: hidden;
}

.card-cart-step-btn {
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  color: #cbd5e1;
  cursor: pointer;
  transition: all 0.15s ease;
  padding: 0;
}

.card-cart-step-btn:hover {
  background: rgba(16, 185, 129, 0.25);
  color: #34d399;
}

.card-cart-qty-input {
  width: 42px;
  height: 26px;
  border: none;
  border-left: 1px solid rgba(51, 65, 85, 0.7);
  border-right: 1px solid rgba(51, 65, 85, 0.7);
  background: transparent;
  color: #ffffff;
  font-size: 12.5px;
  font-weight: 800;
  text-align: center;
  outline: none;
  padding: 0 2px;
