}

.card-cart-qty-input::-webkit-outer-spin-button,
.card-cart-qty-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.card-cart-remove-btn {
  width: 26px;
  height: 26px;
  border-radius: 6px;
  border: 1px solid rgba(239, 68, 68, 0.35);
  background: rgba(239, 68, 68, 0.14);
  color: #f87171;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
  flex-shrink: 0;
  transition: all 0.15s ease;
}

.card-cart-remove-btn:hover {
  background: rgba(239, 68, 68, 0.3);
  color: #fee2e2;
}

.quote-cart-right-Launcher {
  position: fixed;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  z-index: 9500;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px 10px 12px;
  border-radius: 14px 0 0 14px;
  border: 1px solid rgba(16, 185, 129, 0.55);
  border-right: none;
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.98) 0%, rgba(30, 41, 59, 0.98) 100%);
  color: #f8fafc;
  cursor: pointer;
  box-shadow: -8px 10px 30px rgba(0, 0, 0, 0.55);
  transition: all 0.25s cubic-bezier(0.22, 1, 0.36, 1);
}

.quote-cart-right-Launcher:hover {
  padding-right: 18px;
  border-color: #10b981;
  box-shadow: -10px 12px 34px rgba(16, 185, 129, 0.28);
}

.quote-cart-launcher__icon {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  color: #34d399;
}

.quote-cart-launcher__meta {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.quote-cart-launcher__label {
  font-size: 11.5px;
  font-weight: 700;
  color: #e2e8f0;
  white-space: nowrap;
}

.quote-cart-launcher__total {
  font-size: 12px;
  font-weight: 800;
  color: #fbbf24;
  white-space: nowrap;
}

.quote-cart-right-sidebar {
  position: fixed;
  top: 0;
  right: 0;
  width: min(410px, 92vw);
  height: 100vh;
  z-index: 9550;
  display: flex;
  flex-direction: column;
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.99) 0%, rgba(9, 13, 24, 0.99) 100%);
  border-left: 1px solid rgba(16, 185, 129, 0.45);
  box-shadow: -18px 0 45px rgba(0, 0, 0, 0.68);
  backdrop-filter: blur(14px);
  transform: translateX(102%);
  transition: transform 0.34s cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
}

.quote-cart-right-sidebar.open {
  transform: translateX(0);
  pointer-events: auto;
}

.quote-cart-sidebar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  background: rgba(30, 41, 59, 0.85);
  border-bottom: 1px solid rgba(51, 65, 85, 0.85);
  flex-shrink: 0;
}

.quote-cart-sidebar__title-group {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.quote-cart-sidebar__heading {
  margin: 0;
  font-size: 15px;
  font-weight: 800;
  color: #f8fafc;
  letter-spacing: 0.2px;
}

.quote-cart-sidebar__sub {
  margin: 2px 0 0;
  font-size: 12px;
  color: #94a3b8;
}

.quote-cart-sidebar__sub strong {
  color: #34d399;
}

.quote-cart-sidebar__collapse-btn {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  background: rgba(255, 255, 255, 0.05);
  color: #cbd5e1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.18s ease;
}

.quote-cart-sidebar__collapse-btn:hover {
  background: rgba(16, 185, 129, 0.2);
  border-color: rgba(16, 185, 129, 0.5);
  color: #34d399;
}

.quote-cart-sidebar__body {
  flex: 1;
  overflow-y: auto;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.quote-cart-sidebar__body::-webkit-scrollbar {
  width: 5px;
}

.quote-cart-sidebar__body::-webkit-scrollbar-thumb {
  background: rgba(100, 116, 139, 0.45);
  border-radius: 99px;
}

.quote-cart-sidebar__item {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 11px 12px;
  border-radius: 10px;
  background: rgba(30, 41, 59, 0.65);
  border: 1px solid rgba(51, 65, 85, 0.75);
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease;
}

.quote-cart-sidebar__item:hover {
  background: rgba(30, 41, 59, 0.92);
  border-color: rgba(16, 185, 129, 0.55);
}

.quote-cart-sidebar__item-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.quote-cart-item-index {
  font-size: 11px;
  font-weight: 800;
  color: #64748b;
}

.quote-cart-drawer__codes {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.quote-cart-code-sku {
  font-family: monospace;
  font-size: 11px;
  font-weight: 700;
  color: #c4b5fd;
  background: rgba(139, 92, 246, 0.16);
  padding: 1px 6px;
  border-radius: 4px;
}

.quote-cart-code-ma {
  font-family: monospace;
  font-size: 11px;
  font-weight: 700;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.14);
  padding: 1px 6px;
  border-radius: 4px;
}

.quote-cart-drawer__name {
  font-size: 13px;
  font-weight: 700;
  color: #f8fafc;
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.quote-cart-drawer__price {
  font-size: 11.5px;
  color: #94a3b8;
}

.quote-cart-drawer__price strong {
  color: #34d399;
}

.quote-cart-drawer__vnd {
  color: #64748b;
  margin-left: 4px;
}

.quote-cart-sidebar__item-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 2px;
  padding-top: 6px;
  border-top: 1px dashed rgba(255, 255, 255, 0.08);
}

.quote-cart-drawer__subtotal {
  text-align: right;
  font-size: 13px;
  font-weight: 800;
  color: #f8fafc;
}

.quote-cart-sidebar__footer {
  padding: 14px 16px 18px;
  background: rgba(15, 23, 42, 0.98);
  border-top: 1px solid rgba(51, 65, 85, 0.9);
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex-shrink: 0;
}

.quote-cart-sidebar__totals {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 9px;
  background: rgba(30, 41, 59, 0.6);
  border: 1px solid rgba(51, 65, 85, 0.7);
}

.quote-cart-total-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12.5px;
  color: #cbd5e1;
}

.quote-cart-total-row.after-tax {
  padding-top: 5px;
  border-top: 1px dashed rgba(148, 163, 184, 0.2);
  font-size: 13px;
  font-weight: 700;
}

.quote-cart-icon-badge {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: rgba(16, 185, 129, 0.18);
  border: 1px solid rgba(16, 185, 129, 0.45);
  color: #34d399;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.quote-cart-count-pill {
  position: absolute;
  top: -6px;
  right: -6px;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 999px;
  background: #10b981;
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
}

.quote-cart-total-highlight {
  color: #fbbf24;
  font-size: 14px;
  font-weight: 800;
}

.quote-cart-sidebar__actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.quote-cart-btn-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 13px;
  border-radius: 10px;
  border: 1px solid rgba(239, 68, 68, 0.4);
  background: rgba(239, 68, 68, 0.14);
  color: #fca5a5;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}

.quote-cart-btn-clear:hover {
  background: rgba(239, 68, 68, 0.28);
  color: #fee2e2;
}

.quote-cart-btn-calculate {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 18px;
  border-radius: 10px;
  border: 1px solid rgba(52, 211, 153, 0.5);
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
  font-size: 13.5px;
  font-weight: 800;
  letter-spacing: 0.2px;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.4);
  transition: all 0.2s ease;
}

.quote-cart-btn-calculate:hover {
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
  box-shadow: 0 6px 20px rgba(16, 185, 129, 0.55);
  transform: translateY(-1px);
}

/* =========================================================
   NÚT & MODAL ĐỒNG BỘ LISTPRICE SOPHOS (DB & FILE TRUNG GIAN)
   ========================================================= */
.vendor-ref-sync-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: auto;
  margin: 0;
  padding: 5px 10px;
  border-radius: 7px;
  font-size: 11.5px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.18s ease;
}

.vendor-ref-sync-btn--calc-db {
  border: 1px solid rgba(16, 185, 129, 0.55);
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.2), rgba(13, 148, 136, 0.28));
  color: #6ee7b7;
}

.vendor-ref-sync-btn--calc-db:hover {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.36), rgba(13, 148, 136, 0.45));
  border-color: #34d399;
  color: #ecfdf5;
  transform: translateY(-1px);
}

.vendor-ref-sync-btn--tg-calc {
  border: 1px solid rgba(192, 132, 252, 0.55);
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.22), rgba(107, 33, 168, 0.3));
  color: #e9d5ff;
}

.vendor-ref-sync-btn--tg-calc:hover {
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.38), rgba(126, 34, 206, 0.46));
  border-color: #c084fc;
  color: #faf5ff;
  transform: translateY(-1px);
}

.vendor-ref-sync-btn--tg-export {
  border: 1px solid rgba(56, 189, 248, 0.58);
  background: linear-gradient(135deg, rgba(14, 165, 233, 0.24), rgba(2, 132, 199, 0.34));
  color: #bae6fd;
}

.vendor-ref-sync-btn--tg-export:hover:not(:disabled) {
  background: linear-gradient(135deg, rgba(14, 165, 233, 0.42), rgba(3, 105, 161, 0.52));
  border-color: #38bdf8;
  color: #f0f9ff;
  transform: translateY(-1px);
}

.vendor-ref-sync-btn:disabled {
  opacity: 0.58;
  cursor: wait;
  transform: none;
}

.sophos-sync-pill {
  display: inline-flex;
  align-items: center;
  padding: 4px 11px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 800;
  white-space: nowrap;
}

.sophos-sync-pill--db {
  background: rgba(16, 185, 129, 0.2);
  color: #6ee7b7;
  border: 1px solid rgba(16, 185, 129, 0.45);
}

.sophos-sync-pill--tg {
  background: rgba(168, 85, 247, 0.22);
  color: #e9d5ff;
  border: 1px solid rgba(192, 132, 252, 0.48);
}

.sophos-sync-ver-badge {
  padding: 2px 7px;
  border-radius: 5px;
  background: rgba(20, 184, 166, 0.2);
  border: 1px solid rgba(20, 184, 166, 0.4);
  color: #5eead4;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.sophos-sync-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.sophos-sync-kpi-card {
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.72);
  min-width: 0;
}

.sophos-sync-kpi-card--slate {
  border-color: rgba(56, 189, 248, 0.32);
  background: rgba(14, 116, 144, 0.14);
}

.sophos-sync-kpi-card--violet {
  border-color: rgba(192, 132, 252, 0.35);
  background: rgba(107, 33, 168, 0.16);
}

.sophos-sync-kpi-card--amber {
  border-color: rgba(245, 158, 11, 0.38);
  background: rgba(245, 158, 11, 0.1);
}

.sophos-sync-kpi-card--emerald {
  border-color: rgba(16, 185, 129, 0.36);
  background: rgba(16, 185, 129, 0.1);
}

.sophos-sync-kpi-card--rose {
  border-color: rgba(244, 63, 94, 0.32);
  background: rgba(244, 63, 94, 0.08);
}

.sophos-sync-kpi-label {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: #cbd5e1;
}

.sophos-sync-kpi-val {
  margin-top: 3px;
  font-size: 20px;
  font-weight: 800;
  color: #f8fafc;
  font-variant-numeric: tabular-nums;
}

.sophos-sync-kpi-card--amber .sophos-sync-kpi-val {
  color: #fbbf24;
}

.sophos-sync-kpi-card--emerald .sophos-sync-kpi-val {
  color: #34d399;
}

.sophos-sync-kpi-card--rose .sophos-sync-kpi-val {
  color: #fb7185;
}

.sophos-sync-kpi-sub {
  margin-top: 2px;
  font-size: 11.5px;
  color: #94a3b8;
  font-variant-numeric: tabular-nums;
}

.sophos-sync-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.2);
}

.sophos-sync-filter-tabs {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 3px;
  border-radius: 8px;
  background: rgba(30, 41, 59, 0.85);
  border: 1px solid rgba(148, 163, 184, 0.2);
}

.sophos-sync-tab-btn {
  width: auto;
  margin: 0;
  padding: 5px 10px;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: #94a3b8;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  font-variant-numeric: tabular-nums;
  transition: all 0.16s ease;
}

.sophos-sync-tab-btn:hover {
  color: #f1f5f9;
  background: rgba(148, 163, 184, 0.12);
}

.sophos-sync-tab-btn.active {
  background: rgba(20, 184, 166, 0.25);
  color: #5eead4;
  box-shadow: inset 0 0 0 1px rgba(20, 184, 166, 0.45);
}

.sophos-sync-sheet-select {
  height: 34px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid rgba(192, 132, 252, 0.42);
  background: rgba(30, 41, 59, 0.92);
  color: #f3e8ff;
  font-size: 12px;
  font-weight: 700;
}

.sophos-sync-search-input {
  height: 34px;
  min-width: 220px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  background: rgba(9, 13, 22, 0.88);
  color: #f8fafc;
  font-size: 12.5px;
}

.sophos-sync-search-input:focus {
  outline: none;
  border-color: #2dd4bf;
  box-shadow: 0 0 0 2px rgba(45, 212, 191, 0.18);
}

.sophos-sync-check-opt {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 7px;
  background: rgba(30, 41, 59, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.24);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}

.sophos-sync-check-opt input[type='checkbox'] {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: #14b8a6;
}

.sophos-sync-btn-tg-submit {
  background: linear-gradient(135deg, #7c3aed, #6d28d9) !important;
  box-shadow: 0 4px 12px rgba(124, 58, 237, 0.32) !important;
}

.sophos-sync-btn-tg-submit:hover:not(:disabled) {
  background: linear-gradient(135deg, #8b5cf6, #7c3aed) !important;
}

.sophos-sync-rule-note {
  padding: 8px 12px;
  border-radius: 8px;
  background: rgba(14, 116, 144, 0.14);
  border: 1px solid rgba(56, 189, 248, 0.25);
  color: #bae6fd;
  font-size: 12px;
  line-height: 1.45;
}

.sophos-sync-rule-note--tg {
  background: rgba(107, 33, 168, 0.14);
  border-color: rgba(192, 132, 252, 0.28);
  color: #e9d5ff;
}

.sophos-sync-loading-box {
  padding: 36px 20px;
  text-align: center;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px dashed rgba(148, 163, 184, 0.28);
  color: #5eead4;
  font-size: 13.5px;
  font-weight: 700;
}

.sophos-sync-table-wrap {
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 10px;
  overflow: auto;
  max-height: 52vh;
  background: rgba(9, 13, 22, 0.55);
}

.sophos-sync-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

.sophos-sync-table thead {
  position: sticky;
  top: 0;
  z-index: 5;
  background: #0f172a;
  border-bottom: 1px solid rgba(148, 163, 184, 0.26);
}

.sophos-sync-table th {
  padding: 10px 10px;
  color: #94a3b8;
  font-size: 11.5px;
  font-weight: 800;
  white-space: nowrap;
}

.sophos-sync-table td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.11);
  vertical-align: middle;
}

.sophos-sync-row--diff {
  background: rgba(245, 158, 11, 0.055);
}

.sophos-sync-row--miss {
  background: rgba(244, 63, 94, 0.045);
}

.sophos-sync-num {
  font-variant-numeric: tabular-nums;
  font-family: 'JetBrains Mono', 'Consolas', monospace;
}

.sophos-sync-sku-code {
  font-family: 'JetBrains Mono', 'Consolas', monospace;
  font-size: 12px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.sophos-sync-sku-upgrade-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border-radius: 4px;
  background: rgba(56, 189, 248, 0.14);
  border: 1px solid rgba(56, 189, 248, 0.35);
  color: #bae6fd;
  font-family: 'JetBrains Mono', 'Consolas', monospace;
  font-size: 10.5px;
}

.sophos-sync-meta-tag {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}

.sophos-sync-meta-tag--cat {
  background: rgba(56, 189, 248, 0.12);
  color: #7dd3fc;
}

.sophos-sync-meta-tag--cost {
  background: rgba(139, 92, 246, 0.16);
  border: 1px solid rgba(167, 139, 250, 0.35);
  color: #ddd6fe;
  font-weight: 700;
}

.sophos-sync-meta-tag--nk {
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.3);
  color: #6ee7b7;
  font-weight: 600;
}

@media (max-width: 960px) {
  .sophos-sync-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* ==========================================================================
   PHƯƠNG ÁN A — ĐỒNG BỘ HỆ THỐNG GIAO DIỆN CHUẨN BAOGIA / QUANLYBAOGIA
   Dual-Theme (Dark Navy & Light Blue), 3-Card Bento KPI, Rounded Search,
   Collapsible Category Groups, 4-Tier Cards ↔ Data Table, Vendor Hub & Dock
========================================================================== */
.qlhh-page,
.qlhh-modal-backdrop,
.qlhh-hub-overlay,
.qlhh-fm-overlay {
  --font-sans: 'Inter', 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  /* Dark Navy Default */
  --bg-canvas: radial-gradient(ellipse 80% 50% at 10% 0%, rgba(14, 165, 233, 0.11) 0%, transparent 52%),
    radial-gradient(ellipse 60% 40% at 90% 100%, rgba(16, 185, 129, 0.07) 0%, transparent 52%), #09090b;
  --bg-surface: #0f172a;
  --bg-card: rgba(15, 23, 42, 0.78);
  --bg-card-hover: rgba(20, 31, 56, 0.94);
  --bg-well: rgba(2, 6, 23, 0.52);
  --bg-input: #0b1324;
  --bg-modal: #0b1322;
  --bg-modal-head: #0f172a;
  --bg-table-head: #0d1629;
  --bg-row-hover: rgba(56, 189, 248, 0.06);

  --border-subtle: rgba(148, 163, 184, 0.16);
  --border-control: rgba(148, 163, 184, 0.24);
  --border-strong: rgba(56, 189, 248, 0.38);

  --ink-primary: #f8fafc;
  --ink-strong: #ffffff;
  --ink-secondary: #cbd5e1;
  --ink-muted: #94a3b8;
  --ink-faint: #64748b;

  --sky-text: #38bdf8;
  --sky-bg: rgba(14, 165, 233, 0.15);
  --sky-border: rgba(56, 189, 248, 0.38);

  --emerald-text: #34d399;
  --emerald-bg: rgba(16, 185, 129, 0.14);
  --emerald-border: rgba(16, 185, 129, 0.36);

  --amber-text: #fbbf24;
  --amber-bg: rgba(245, 158, 11, 0.13);
  --amber-border: rgba(245, 158, 11, 0.35);

  --rose-text: #f87171;
  --rose-bg: rgba(239, 68, 68, 0.14);
  --rose-border: rgba(239, 68, 68, 0.35);

  --violet-text: #c4b5fd;
  --violet-bg: rgba(139, 92, 246, 0.14);
  --violet-border: rgba(167, 139, 250, 0.36);

  --slate-text: #cbd5e1;
  --slate-bg: rgba(148, 163, 184, 0.12);
  --slate-border: rgba(148, 163, 184, 0.24);

  --shadow-card: 0 10px 28px -10px rgba(0, 0, 0, 0.55);
  --shadow-modal: 0 26px 60px -12px rgba(0, 0, 0, 0.78);
}

/* Enterprise Light Blue Theme */
.qlhh-page.theme-light-blue,
.qlhh-modal-backdrop.theme-light-blue,
.qlhh-hub-overlay.theme-light-blue,
.qlhh-fm-overlay.theme-light-blue,
.qlhh-cmp-overlay.theme-light-blue {
  --bg-canvas: linear-gradient(180deg, #eef4fb 0%, #e2ecf8 100%);
  --bg-surface: #ffffff;
  --bg-card: #ffffff;
  --bg-card-hover: #f8fbff;
  --bg-well: #f1f5f9;
  --bg-input: #f8fafc;
  --bg-modal: #ffffff;
  --bg-modal-head: #f8fbff;
  --bg-table-head: #eff6ff;
  --bg-row-hover: #eff6ff;

  --border-subtle: #dbeafe;
  --border-control: #cbd5e1;
  --border-strong: #60a5fa;

  --ink-primary: #0f172a;
  --ink-strong: #020617;
  --ink-secondary: #334155;
  --ink-muted: #475569;
  --ink-faint: #64748b;

  --sky-text: #0284c7;
  --sky-bg: #eff6ff;
  --sky-border: #93c5fd;

  --emerald-text: #059669;
  --emerald-bg: #ecfdf5;
  --emerald-border: #6ee7b7;

  --amber-text: #d97706;
  --amber-bg: #fffbeb;
  --amber-border: #fcd34d;

  --rose-text: #dc2626;
  --rose-bg: #fef2f2;
  --rose-border: #fecaca;

  --violet-text: #6d28d9;
  --violet-bg: #f5f3ff;
  --violet-border: #c4b5fd;

  --slate-text: #334155;
  --slate-bg: #f1f5f9;
  --slate-border: #cbd5e1;

  --shadow-card: 0 8px 24px -8px rgba(15, 23, 42, 0.08);
  --shadow-modal: 0 24px 52px -12px rgba(15, 23, 42, 0.22);
}

.quan-ly-hang-hoa.qlhh-page {
  max-width: 100%;
  min-height: 100vh;
  margin: 0;
  padding: 14px 18px 44px;
  background: var(--bg-canvas);
  color: var(--ink-primary);
  font-family: var(--font-sans);
  font-size: 13px;
  line-height: 1.48;
  box-sizing: border-box;
}

.qlhh-page *,
.qlhh-page .qlhh-modal-backdrop *,
.qlhh-page .import-overlay *,
.qlhh-page .quote-cart-right-sidebar * {
  box-sizing: border-box;
  font-family: var(--font-sans);
}

/* Reset global style.css `code` & `h2` collisions inside QuanLyHangHoaFirebase */
.qlhh-page code,
.qlhh-modal-backdrop code {
  display: inline;
  padding: 1px 6px;
  border-radius: 5px;
  font-family: var(--font-mono) !important;
  font-size: 11.5px;
  line-height: 1.35;
  font-weight: 700;
  background: var(--sky-bg);
  color: var(--sky-text);
  border: 1px solid var(--sky-border);
}
.qlhh-page .import-overlay code {
  display: inline;
  padding: 1px 6px;
  border-radius: 5px;
  font-family: var(--font-mono) !important;
  font-size: 11.5px;
  line-height: 1.35;
  font-weight: 700;
  background: rgba(56, 189, 248, 0.14);
  color: #7dd3fc;
  border: 1px solid rgba(56, 189, 248, 0.3);
}

/* Fix Import / PriceList / ImageCheck modal header flex & Amber icon */
.import-modal__title-group {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}
.import-modal__icon.is-amber-icon {
  background: rgba(245, 158, 11, 0.16);
  border: 1px solid rgba(245, 158, 11, 0.42);
  color: #fbbf24;
  box-shadow: 0 6px 18px -6px rgba(245, 158, 11, 0.4);
}
.import-overlay {
  z-index: 10065;
}

/* Collision-free Modal Backdrop (100% isolated from baogiaFirebase / BaoGia / style.css) */
.qlhh-modal-backdrop {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  padding: 16px;
  background: rgba(2, 6, 23, 0.72);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10060;
  box-sizing: border-box;
  overscroll-behavior: contain;
}
.qlhh-modal-backdrop.theme-light-blue {
  background: rgba(15, 23, 42, 0.46);
}

.tabular-nums {
  font-variant-numeric: tabular-nums;
}
.text-right {
  text-align: right !important;
}
.text-center {
  text-align: center !important;
}

:deep(mark.qlhh-hl) {
  background: rgba(250, 204, 21, 0.28);
  color: inherit;
  padding: 0 2px;
  border-radius: 3px;
  font-weight: 700;
}
.theme-light-blue :deep(mark.qlhh-hl) {
  background: #fef08a;
  color: #0f172a;
}

@keyframes qlhhSpin {
  to {
    transform: rotate(360deg);
  }
}
.is-spin {
  animation: qlhhSpin 0.85s linear infinite;
}

/* ==========================================================================
   1. BENTO KPI GRID (3 THẺ ĐỒNG BỘ QUANLYBAOGIAFIREBASE)
========================================================================== */
.qlhh-kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.qlhh-kpi-card {
  width: 100%;
  margin: 0;
  padding: 14px 16px 13px;
  border-radius: 14px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-card);
  color: var(--ink-primary);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 9px;
  min-width: 0;
  transition: all 0.18s ease;
  user-select: none;
}

.qlhh-kpi-card:hover {
  transform: translateY(-1px);
}
.qlhh-kpi-card:not(.active):hover {
  background: var(--bg-card-hover);
}

.kpi-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.kpi-label {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -0.005em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.kpi-icon {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.kpi-icon.is-sky {
  background: var(--sky-bg);
  color: var(--sky-text);
}
.kpi-icon.is-emerald {
  background: var(--emerald-bg);
  color: var(--emerald-text);
}
.kpi-icon.is-amber {
  background: var(--amber-bg);
  color: var(--amber-text);
}

.qlhh-kpi-card.is-sky .kpi-label {
  color: #bae6fd;
}
.qlhh-kpi-card.is-sky:not(.active):hover {
  border-color: #38bdf8;
}
.qlhh-kpi-card.is-sky.active {
  background: linear-gradient(155deg, #0369a1 0%, #075985 55%, #0c4a6e 100%);
  border-color: #7dd3fc;
  box-shadow: inset 3px 0 0 #38bdf8, 0 8px 22px -8px rgba(14, 165, 233, 0.45);
}

.qlhh-kpi-card.is-emerald .kpi-label {
  color: #a7f3d0;
}
.qlhh-kpi-card.is-emerald:not(.active):hover {
  border-color: #6ee7b7;
}
.qlhh-kpi-card.is-emerald.active {
  background: linear-gradient(155deg, #047857 0%, #065f46 58%, #064e3b 100%);
  border-color: #6ee7b7;
  box-shadow: inset 3px 0 0 #34d399, 0 8px 22px -8px rgba(16, 185, 129, 0.45);
}

.qlhh-kpi-card.is-amber .kpi-label {
  color: #fde68a;
}
.qlhh-kpi-card.is-amber:not(.active):hover {
  border-color: #fbbf24;
}
.qlhh-kpi-card.is-amber.active {
  background: linear-gradient(155deg, #b45309 0%, #92400e 58%, #78350f 100%);
  border-color: #fde68a;
  box-shadow: inset 3px 0 0 #fbbf24, 0 8px 22px -8px rgba(245, 158, 11, 0.45);
}

.qlhh-kpi-card.active .kpi-icon {
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
}
.qlhh-kpi-card.active .kpi-label,
.qlhh-kpi-card.active .kpi-val,
.qlhh-kpi-card.active .kpi-pl-name {
  color: #ffffff;
}

.qlhh-page.theme-light-blue .qlhh-kpi-card.is-sky .kpi-label {
  color: #0369a1;
}
.qlhh-page.theme-light-blue .qlhh-kpi-card.is-emerald .kpi-label {
  color: #047857;
}
.qlhh-page.theme-light-blue .qlhh-kpi-card.is-amber .kpi-label {
  color: #b45309;
}
.qlhh-page.theme-light-blue .qlhh-kpi-card.is-sky.active {
  background: linear-gradient(155deg, #0284c7 0%, #0369a1 58%, #075985 100%);
  border-color: #0284c7;
}
.qlhh-page.theme-light-blue .qlhh-kpi-card.is-emerald.active {
  background: linear-gradient(155deg, #059669 0%, #047857 58%, #065f46 100%);
  border-color: #047857;
}
.qlhh-page.theme-light-blue .qlhh-kpi-card.is-amber.active {
  background: linear-gradient(155deg, #d97706 0%, #b45309 58%, #92400e 100%);
  border-color: #b45309;
}
.qlhh-page.theme-light-blue .qlhh-kpi-card.active .kpi-label,
.qlhh-page.theme-light-blue .qlhh-kpi-card.active .kpi-val,
.qlhh-page.theme-light-blue .qlhh-kpi-card.active .kpi-pl-name {
  color: #ffffff;
}

.kpi-main-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.kpi-val {
  font-size: 23px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--ink-strong);
  letter-spacing: -0.02em;
}
.kpi-unit {
  font-size: 12px;
  font-weight: 700;
  opacity: 0.78;
  margin-left: 3px;
}

.kpi-pl-name {
  font-size: 15px;
  font-weight: 800;
  color: var(--ink-strong);
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.kpi-sub-pills {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.kpi-mini-pill {
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.12);
  color: inherit;
  border: 1px solid rgba(255, 255, 255, 0.18);
  white-space: nowrap;
}
.qlhh-kpi-card:not(.active) .kpi-mini-pill {
  background: var(--slate-bg);
  color: var(--ink-secondary);
  border-color: var(--border-subtle);
}

.kpi-brand-chips {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.kpi-brand-chip {
  margin: 0;
  padding: 5px 7px;
  border-radius: 8px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--ink-secondary);
  font-size: 11.5px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  cursor: pointer;
  transition: all 0.15s ease;
  min-width: 0;
}
.kpi-brand-chip span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kpi-brand-chip strong {
  color: var(--ink-strong);
  font-weight: 800;
}
.kpi-brand-chip:hover {
  border-color: var(--emerald-border);
  color: var(--ink-strong);
}
.kpi-brand-chip.active {
  background: #ffffff;
  color: #064e3b;
  border-color: #ffffff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.18);
}
.kpi-brand-chip.active strong {
  color: #047857;
}
.qlhh-kpi-card.is-emerald.active .kpi-brand-chip:not(.active) {
  background: rgba(0, 0, 0, 0.24);
  border-color: rgba(255, 255, 255, 0.22);
  color: #d1fae5;
}
.qlhh-kpi-card.is-emerald.active .kpi-brand-chip:not(.active) strong {
  color: #ffffff;
}

.kpi-action-pill {
  margin: 0;
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
.kpi-action-pill.is-amber {
  background: var(--amber-bg);
  border: 1px solid var(--amber-border);
  color: var(--amber-text);
}
.kpi-action-pill.is-sky {
  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
}
.qlhh-kpi-card.active .kpi-action-pill {
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.36);
  color: #ffffff;
}
.kpi-action-pill:hover {
  filter: brightness(1.1);
}

/* ==========================================================================
   2. UNIFIED SMART FILTER & SEARCH BAR
========================================================================== */
.qlhh-filter-bar {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 14px;
}

.qlhh-filter-row-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.qlhh-filter-left,
.qlhh-filter-right {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
  min-width: 0;
}

.qlhh-picker-root {
  position: relative;
}

.qlhh-picker-btn {
  width: auto;
  margin: 0;
  height: 36px;
  max-width: 205px;
  padding: 0 10px;
  border-radius: 9px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-primary);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}
.qlhh-picker-btn:hover {
  border-color: var(--sky-border);
}
.qlhh-picker-btn.is-active,
.qlhh-picker-btn.is-open {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
}

.picker-btn-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.picker-chev {
  opacity: 0.65;
  flex-shrink: 0;
}

.picker-clear-dot {
  width: 17px;
  height: 17px;
  padding: 0;
  margin: 0;
  border-radius: 999px;
  border: none;
  background: rgba(148, 163, 184, 0.24);
  color: inherit;
  font-size: 10px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
}
.picker-clear-dot:hover {
  background: var(--rose-bg);
  color: var(--rose-text);
}

.qlhh-vol-pill {
  height: 36px;
  padding: 0 9px;
  border-radius: 9px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-muted);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.15s ease;
}
.qlhh-vol-pill:focus-within,
.qlhh-vol-pill.is-active {
  border-color: var(--sky-border);
  color: var(--sky-text);
}
.qlhh-vol-input {
  width: 98px;
  border: none;
  outline: none;
  background: transparent;
  color: var(--ink-primary);
  font-size: 12.5px;
  font-weight: 600;
}
.qlhh-vol-input::placeholder {
  color: var(--ink-faint);
}

.qlhh-reset-btn {
  height: 36px;
  padding: 0 10px;
  border-radius: 9px;
  border: 1px solid var(--rose-border);
  background: var(--rose-bg);
  color: var(--rose-text);
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  cursor: pointer;
  white-space: nowrap;
}
.qlhh-reset-btn:hover {
  filter: brightness(1.08);
}

/* Rounded Search Capsule with Soft Blue Border */
.qlhh-search-box {
  flex: 1 1 250px;
  min-width: 190px;
  height: 38px;
  padding: 0 14px;
  background: var(--bg-card);
  border: 1.5px solid var(--sky-border);
  border-radius: 999px;
  box-shadow: 0 2px 10px -4px rgba(14, 165, 233, 0.18);
  display: flex;
  align-items: center;
  gap: 8px;
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}
.qlhh-search-box:focus-within {
  border-color: var(--border-strong);
  box-shadow: 0 0 0 3px rgba(14, 165, 233, 0.16);
}
.qlhh-search-ico {
  color: var(--sky-text);
  opacity: 0.88;
  flex-shrink: 0;
}
.qlhh-search-input {
  flex: 1 1 auto;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  color: var(--ink-primary);
  font-size: 13px;
}
.qlhh-search-input::placeholder {
  color: var(--ink-faint);
}
.qlhh-search-count {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--sky-bg);
  color: var(--sky-text);
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}
.qlhh-search-clear {
  padding: 3px 9px;
  border-radius: 999px;
  border: 1px solid var(--border-control);
  background: var(--slate-bg);
  color: var(--ink-secondary);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}
.qlhh-search-clear:hover {
  color: var(--rose-text);
  border-color: var(--rose-border);
  background: var(--rose-bg);
}
.qlhh-search-sep {
  width: 1px;
  height: 20px;
  background: var(--border-control);
  flex-shrink: 0;
  opacity: 0.85;
}
.qlhh-search-vol {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 7px;
  border-radius: 999px;
  color: var(--ink-muted);
  background: transparent;
  border: 1px solid transparent;
  flex-shrink: 0;
  transition: all 0.15s ease;
}
.qlhh-search-vol:focus-within,
.qlhh-search-vol.is-active {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
}
.qlhh-search-vol-input {
  width: 64px;
  border: none;
  outline: none;
  background: transparent;
  color: var(--ink-primary);
  font-size: 12.5px;
  font-weight: 700;
  -moz-appearance: textfield;
}
.qlhh-search-vol-input::-webkit-outer-spin-button,
.qlhh-search-vol-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
.qlhh-search-vol-input::placeholder {
  color: var(--ink-faint);
  font-weight: 500;
}

.qlhh-display-btn {
  max-width: none;
  white-space: nowrap;
}

/* Right Action Cluster */
.qlhh-view-seg {
  display: inline-flex;
  align-items: center;
  padding: 3px;
  border-radius: 9px;
  background: var(--bg-card);
  border: 1px solid var(--border-control);
  gap: 2px;
}
.qlhh-view-seg-btn {
  height: 28px;
  padding: 0 9px;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: var(--ink-muted);
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
.qlhh-view-seg-btn.active {
  background: var(--sky-bg);
  color: var(--sky-text);
  box-shadow: inset 0 0 0 1px var(--sky-border);
}

.qlhh-icon-btn {
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: 9px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-secondary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}
.qlhh-icon-btn:hover:not(:disabled) {
  border-color: var(--sky-border);
  color: var(--sky-text);
}

.qlhh-ghost-btn {
  height: 36px;
  padding: 0 12px;
  border-radius: 9px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-primary);
  font-size: 12.5px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
.qlhh-ghost-btn:hover:not(:disabled) {
  border-color: var(--sky-border);
  color: var(--sky-text);
}
.qlhh-ghost-btn.is-hub-btn {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
}
.qlhh-ghost-btn.is-sm {
  height: 32px;
  padding: 0 10px;
  font-size: 12px;
}
.qlhh-ghost-btn.is-xs {
  height: 28px;
  padding: 0 9px;
  font-size: 11.5px;
  border-radius: 7px;
}
.qlhh-ghost-btn.is-amber-tint {
  background: var(--amber-bg);
  border-color: var(--amber-border);
  color: var(--amber-text);
}
.qlhh-ghost-btn.is-emerald-tint {
  background: var(--emerald-bg);
  border-color: var(--emerald-border);
  color: var(--emerald-text);
}
.qlhh-ghost-btn.is-sky-tint {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
}

.qlhh-btn-primary {
  height: 36px;
  padding: 0 14px;
  border-radius: 9px;
  border: 1px solid rgba(52, 211, 153, 0.48);
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
  font-size: 12.5px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  white-space: nowrap;
  box-shadow: 0 4px 12px -4px rgba(16, 185, 129, 0.45);
  transition: all 0.16s ease;
}
.qlhh-btn-primary:hover {
  filter: brightness(1.06);
  transform: translateY(-1px);
}
.qlhh-page.theme-light-blue .qlhh-btn-primary,
.qlhh-hub-modal.theme-light-blue .qlhh-btn-primary,
.qlhh-fm-modal.theme-light-blue .qlhh-btn-primary {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  border-color: #38bdf8;
  box-shadow: 0 4px 12px -4px rgba(2, 132, 199, 0.35);
}
.qlhh-btn-primary.is-sm {
  height: 32px;
  padding: 0 11px;
  font-size: 12px;
}

/* Adaptive Popover Menu (PC Popover ↔ Mobile Bottom Sheet) */
.qlhh-pop-backdrop {
  display: none;
}
.mob-sheet-grabber {
  display: none;
}

.qlhh-pop-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  width: 265px;
  z-index: 1200;
  background: var(--bg-modal);
  border: 1px solid var(--border-strong);
  border-radius: 13px;
  box-shadow: var(--shadow-modal);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.qlhh-pop-menu.is-wide {
  width: 340px;
}
.qlhh-pop-menu.is-align-right {
  left: auto;
  right: 0;
}
.qlhh-pop-menu.is-display-pop {
  width: 270px;
}
.qlhh-display-pop-body {
  padding: 10px 12px 12px;
  display: flex;
  flex-direction: column;
  gap: 11px;
}
.qlhh-display-sec {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.qlhh-display-sec-lbl {
  font-size: 10.5px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink-muted);
}
.qlhh-display-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
.qlhh-display-opt {
  height: 36px;
  width: 100%;
  margin: 0;
  padding: 0 9px;
  border-radius: 9px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--ink-secondary);
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
.qlhh-display-opt:hover:not(.active) {
  border-color: var(--sky-border);
  color: var(--ink-strong);
}
.qlhh-display-opt.active {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
  font-weight: 800;
  box-shadow: 0 2px 8px -4px rgba(14, 165, 233, 0.35);
}

.qlhh-pop-head {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12.5px;
  font-weight: 800;
  color: var(--ink-strong);
}
.qlhh-pop-close {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--ink-muted);
  font-size: 11px;
  cursor: pointer;
}

.qlhh-pop-search-wrap {
  padding: 8px 10px;
  border-bottom: 1px solid var(--border-subtle);
}
.qlhh-pop-search {
  width: 100%;
  height: 32px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--ink-primary);
  font-size: 12.5px;
}
.qlhh-pop-search:focus {
  outline: none;
  border-color: var(--sky-border);
}

.qlhh-pop-list {
  max-height: 290px;
  overflow-y: auto;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.qlhh-pop-item {
  width: 100%;
  padding: 8px 10px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--ink-primary);
  font-size: 12.5px;
  font-weight: 600;
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  cursor: pointer;
}
.qlhh-pop-item span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.qlhh-pop-item:hover {
  background: var(--bg-row-hover);
}
.qlhh-pop-item.active {
  background: var(--sky-bg);
  color: var(--sky-text);
  font-weight: 700;
}
.qlhh-pop-count {
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--slate-bg);
  color: var(--ink-muted);
  font-size: 11px;
  font-weight: 700;
  flex-shrink: 0;
}
.qlhh-pop-check {
  color: var(--sky-text);
  font-weight: 800;
}
.qlhh-pop-empty {
  padding: 16px 10px;
  text-align: center;
  color: var(--ink-faint);
  font-size: 12px;
}
.qlhh-pop-more {
  margin-top: 4px;
  padding: 7px 10px;
  border-radius: 7px;
  border: 1px dashed var(--sky-border);
  background: var(--sky-bg);
  color: var(--sky-text);
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
}
.qlhh-pop-foot {
  padding: 8px 10px;
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-modal-head);
}
.qlhh-pop-create-btn {
  width: 100%;
  height: 32px;
  border-radius: 8px;
  border: 1px dashed var(--sky-border);
  background: var(--sky-bg);
  color: var(--sky-text);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

/* Price List Context Sub-Bar */
.qlhh-pricelist-context-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 11px;
  background: var(--bg-card);
  border: 1px solid var(--amber-border);
}
.pl-ctx-left,
.pl-ctx-right {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}
.pl-ctx-title {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--amber-text);
  font-size: 12.5px;
}

/* ==========================================================================
   3. SKELETON, EMPTY STATE & COLLAPSIBLE CATEGORY GROUPS
========================================================================== */
.qlhh-skeleton-wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.qlhh-skeleton-bar {
  height: 44px;
  border-radius: 12px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
}
.qlhh-skeleton-card {
  padding: 14px;
  border-radius: 13px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 9px;
}
.sk-row-top,
.sk-chips,
.sk-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.sk-pill {
  width: 85px;
  height: 18px;
  border-radius: 999px;
}
.sk-pill.w60 {
  width: 60px;
}
.sk-code {
  width: 45%;
  height: 16px;
  border-radius: 5px;
}
.sk-title {
  width: 92%;
  height: 16px;
  border-radius: 5px;
}
.sk-title.w70 {
  width: 68%;
}
.sk-chip {
  width: 78px;
  height: 20px;
  border-radius: 6px;
}
.sk-price {
  width: 110px;
  height: 24px;
  border-radius: 6px;
}
.sk-btn {
  width: 68px;
  height: 28px;
  border-radius: 999px;
}

.qlhh-empty-state {
  padding: 44px 20px;
  border-radius: 14px;
  background: var(--bg-card);
  border: 1px dashed var(--border-control);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.qlhh-empty-state .empty-ico {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: var(--sky-bg);
  color: var(--sky-text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.qlhh-empty-state h3 {
  margin: 4px 0 0;
  font-size: 16px;
  font-weight: 800;
  color: var(--ink-strong);
}
.qlhh-empty-state p {
  margin: 0;
  color: var(--ink-muted);
  font-size: 13px;
}
.qlhh-empty-state .empty-actions {
  margin-top: 8px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}

.qlhh-groups-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.qlhh-group-block {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-left: 3px solid #0ea5e9;
  border-radius: 14px;
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.qlhh-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 15px;
  background: linear-gradient(90deg, rgba(3, 105, 161, 0.36) 0%, rgba(15, 23, 42, 0.65) 65%, rgba(15, 23, 42, 0.45) 100%);
  border-bottom: 1px solid var(--border-subtle);
  cursor: pointer;
  user-select: none;
  transition: background 0.15s ease;
}
.qlhh-group-block.is-collapsed .qlhh-group-header {
  border-bottom: none;
}
.qlhh-group-header:hover {
  background: linear-gradient(90deg, rgba(2, 132, 199, 0.48) 0%, rgba(15, 23, 42, 0.72) 65%, rgba(15, 23, 42, 0.52) 100%);
}
.qlhh-page.theme-light-blue .qlhh-group-header {
  background: linear-gradient(90deg, #e0f2fe 0%, #eff6ff 65%, #f8fbff 100%);
  border-bottom-color: #bae6fd;
}
.qlhh-page.theme-light-blue .qlhh-group-header:hover {
  background: linear-gradient(90deg, #bae6fd 0%, #e0f2fe 65%, #eff6ff 100%);
}

.qlhh-group-header .gh-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1 1 auto;
}
.qlhh-group-header .gh-folder-ico {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.qlhh-group-header .gh-title-wrap {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
  min-width: 0;
}
.qlhh-group-header .gh-title {
  margin: 0;
  font-size: 13.5px;
  font-weight: 800;
  color: var(--ink-strong);
  letter-spacing: 0.01em;
}
.qlhh-group-header .gh-sub-hint {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--ink-muted);
}
.qlhh-group-header .gh-right {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.qlhh-group-header .gh-count-pill {
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
  font-size: 11.5px;
  font-weight: 800;
  white-space: nowrap;
}
.qlhh-group-header .gh-toggle-btn {
  width: 28px;
  height: 28px;
  padding: 0;
  border-radius: 7px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-secondary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.qlhh-group-header .gh-chevron {
  transition: transform 0.2s ease;
}
.qlhh-group-header .gh-chevron.is-collapsed {
  transform: rotate(-90deg);
}

/* ==========================================================================
   4. COMPACT 4-TIER PRODUCT CARDS (.qlhh-card)
========================================================================== */
.qlhh-cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(295px, 1fr));
  gap: 12px;
}
.qlhh-cards-grid.is-inside-group {
  padding: 12px;
}

.qlhh-card {
  padding: 13px 14px;
  border-radius: 13px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 9px;
  cursor: pointer;
  transition: transform 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
  min-width: 0;
}
.qlhh-card:hover {
  transform: translateY(-2px);
  border-color: var(--sky-border);
  background: var(--bg-card-hover);
  box-shadow: 0 10px 24px -10px rgba(14, 165, 233, 0.25);
}
.qlhh-page.theme-light-blue .qlhh-card {
  background: #ffffff;
  border: 1px solid #dbeafe;
  border-left: 3px solid #2563eb;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.05);
}
.qlhh-page.theme-light-blue .qlhh-card:hover {
  background: #f8fbff;
  border-color: #60a5fa;
  border-left-color: #1d4ed8;
}

.qlhh-card.in-quote-cart {
  border-color: var(--emerald-border);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.25);
}
.qlhh-page.theme-light-blue .qlhh-card.in-quote-cart {
  background: linear-gradient(180deg, #ffffff 0%, #ecfdf5 100%);
  border-color: #34d399;
  border-left: 3.5px solid #059669;
}

.qlhh-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}
.qlhh-card-badges {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  min-width: 0;
}

.qlhh-brand-tag {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.qlhh-type-tag {
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  white-space: nowrap;
}
.qlhh-type-tag.is-emerald {
  background: var(--emerald-bg);
  border: 1px solid var(--emerald-border);
  color: var(--emerald-text);
}
.qlhh-type-tag.is-amber {
  background: var(--amber-bg);
  border: 1px solid var(--amber-border);
  color: var(--amber-text);
}

.qlhh-selected-tag {
  padding: 2px 7px;
  border-radius: 999px;
  background: var(--emerald-bg);
  border: 1px solid var(--emerald-border);
  color: var(--emerald-text);
  font-size: 10.5px;
  font-weight: 800;
  white-space: nowrap;
}

.qlhh-row-icons {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.qlhh-ico-act {
  position: relative;
  width: 27px;
  height: 27px;
  padding: 0;
  margin: 0;
  border-radius: 7px;
  border: 1px solid var(--border-subtle);
  background: var(--slate-bg);
  color: var(--ink-muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}
.qlhh-ico-act:hover {
  color: var(--ink-strong);
  border-color: var(--border-control);
}
.qlhh-ico-act.is-sky,
.qlhh-ico-act.has-files {
  color: var(--sky-text);
  border-color: var(--sky-border);
  background: var(--sky-bg);
}
.qlhh-ico-act.is-edit:hover {
  color: var(--sky-text);
  border-color: var(--sky-border);
  background: var(--sky-bg);
}
.qlhh-ico-act.is-del:hover {
  color: var(--rose-text);
  border-color: var(--rose-border);
  background: var(--rose-bg);
}
.ico-mini-dot {
  position: absolute;
  top: -5px;
  right: -5px;
  min-width: 15px;
  height: 15px;
  padding: 0 3px;
  border-radius: 999px;
  background: #0ea5e9;
  color: #ffffff;
  font-size: 9px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.qlhh-card-identity {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.qlhh-code-row {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.qlhh-code-pill {
  font-family: var(--font-mono) !important;
  font-size: 11px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 5px;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.qlhh-code-pill.is-sku {
  background: var(--violet-bg);
  border: 1px solid var(--violet-border);
  color: var(--violet-text);
}
.qlhh-code-pill.is-ma {
  background: var(--slate-bg);
  border: 1px solid var(--border-control);
  color: var(--ink-secondary);
}

.qlhh-card-title {
  margin: 0;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.38;
  color: var(--ink-strong);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.qlhh-card-sku-line {
  display: flex;
  align-items: baseline;
  gap: 5px;
  font-size: 12px;
  line-height: 1.35;
  color: var(--ink-secondary);
  min-width: 0;
}
.qlhh-card-sku-lbl {
  color: var(--ink-muted);
  font-weight: 600;
  flex-shrink: 0;
}
.qlhh-card-sku-val {
  font-weight: 700;
  color: var(--ink-secondary);
  word-break: break-word;
}

.qlhh-spec-row {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}
.qlhh-spec-chip {
  padding: 2px 8px;
  border-radius: 6px;
  background: var(--slate-bg);
  border: 1px solid var(--border-subtle);
  color: var(--ink-secondary);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.qlhh-spec-chip.is-sky {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
}
.qlhh-spec-chip.is-cur {
  background: var(--amber-bg);
  border-color: var(--amber-border);
  color: var(--amber-text);
}

.qlhh-card-footer {
  margin-top: auto;
  padding-top: 9px;
  border-top: 1px dashed var(--border-control);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.qlhh-card-price-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
}

.qlhh-card-bottom-bar {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  padding-top: 8px;
  border-top: 1px solid var(--border-subtle);
}

.qlhh-card-bottom-bar .qlhh-ico-act {
  width: 100%;
  min-width: 0;
  height: 31px;
  padding: 0 8px;
  gap: 5px;
  border-radius: 8px;
  font-size: 11.5px;
  font-weight: 700;
  white-space: nowrap;
}
.qlhh-card-bottom-bar.is-3btn .qlhh-ico-act.is-doc-btn {
  grid-column: span 2;
}
.qlhh-card-bottom-bar .qlhh-ico-act svg {
  flex-shrink: 0;
}

.qlhh-price-stack {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.qlhh-cost-line {
  font-size: 11.5px;
  color: var(--ink-muted);
  display: flex;
  align-items: center;
  gap: 5px;
}
.qlhh-cost-val {
  color: var(--violet-text);
  font-weight: 700;
}
.qlhh-price-lbl-row {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}
.qlhh-price-list-lbl {
  font-size: 11px;
  font-weight: 700;
  color: var(--ink-muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  line-height: 1.2;
}
.qlhh-cur-switch {
  display: inline-flex;
  align-items: center;
  padding: 1.5px;
  margin: 0;
  border-radius: 999px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  cursor: pointer;
  gap: 1px;
  transition: border-color 0.15s ease;
}
.qlhh-cur-switch:hover {
  border-color: var(--sky-border);
}
.qlhh-cur-switch .cur-sw-opt {
  padding: 1.5px 6px;
  border-radius: 999px;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.03em;
  line-height: 1.25;
  color: var(--ink-muted);
  transition: all 0.14s ease;
}
.qlhh-cur-switch .cur-sw-opt.active {
  background: #0284c7;
  color: #ffffff;
}
.qlhh-cur-switch.is-vnd .cur-sw-opt.active {
  background: #059669;
  color: #ffffff;
}
.qlhh-usd-rate-txt {
  font-size: 11px;
  font-weight: 600;
  color: var(--ink-muted);
  white-space: nowrap;
}
.qlhh-price-strike {
  font-size: 11px;
  color: var(--ink-faint);
  text-decoration: line-through;
}
.qlhh-price-main-line {
  display: flex;
  align-items: baseline;
  gap: 5px;
  flex-wrap: wrap;
}
.qlhh-price-main-line.is-right {
  justify-content: flex-end;
}
.qlhh-sell-val {
  font-size: 15.5px;
  font-weight: 800;
  color: var(--emerald-text);
  letter-spacing: -0.01em;
}
.qlhh-page.theme-light-blue .qlhh-sell-val {
  color: #1d4ed8;
}
.qlhh-sell-dvt {
  font-size: 11px;
  font-weight: 600;
  color: var(--ink-muted);
}

/* Add Cart Button & Signature Circular Capsule Stepper */
.qlhh-add-cart-btn {
  height: 30px;
  padding: 0 11px;
  border-radius: 999px;
  border: 1px solid var(--emerald-border);
  background: var(--emerald-bg);
  color: var(--emerald-text);
  font-size: 12px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
.qlhh-add-cart-btn:hover {
  background: #10b981;
  border-color: #10b981;
  color: #ffffff;
}
.qlhh-add-cart-btn.is-compact {
  height: 27px;
  padding: 0 9px;
  font-size: 11.5px;
}
.qlhh-add-cart-btn.is-icon-only {
  width: 30px;
  height: 30px;
  padding: 0;
  justify-content: center;
  border-radius: 50%;
  flex-shrink: 0;
}

.qlhh-capsule-stepper {
  height: 30px;
  padding: 2px;
  border-radius: 999px;
  background: var(--bg-input);
  border: 1px solid var(--border-control);
  display: inline-flex;
  align-items: center;
  gap: 2px;
}
.qlhh-capsule-stepper .step-cir {
  width: 24px;
  height: 24px;
  padding: 0;
  margin: 0;
  border-radius: 999px;
  border: none;
  font-size: 14px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.qlhh-capsule-stepper .step-cir.minus {
  background: var(--slate-bg);
  color: var(--ink-primary);
}
.qlhh-capsule-stepper .step-cir.plus {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
}
.qlhh-capsule-stepper .step-num {
  width: 32px;
  border: none;
  outline: none;
  background: transparent;
  color: var(--ink-strong);
  font-size: 13px;
  font-weight: 800;
  text-align: center;
  -moz-appearance: textfield;
}
.qlhh-capsule-stepper .step-num::-webkit-outer-spin-button,
.qlhh-capsule-stepper .step-num::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

/* ==========================================================================
   5. HIGH-DENSITY DATA TABLE VIEW (.qlhh-data-table)
========================================================================== */
.qlhh-table-wrap {
  width: 100%;
  overflow-x: auto;
}

.qlhh-data-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 12.5px;
}

.qlhh-data-table thead th {
  padding: 9px 12px;
  background: var(--bg-table-head);
  color: var(--ink-muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  text-align: left;
  border-bottom: 1px solid var(--border-subtle);
  white-space: nowrap;
}
.qlhh-data-table .col-code {
  width: 165px;
}
.qlhh-data-table .col-spec {
  width: 165px;
}
.qlhh-data-table .col-cur {
  width: 92px;
}
.qlhh-data-table .col-cost {
  width: 135px;
}
.qlhh-data-table .col-price {
  width: 165px;
}
.qlhh-data-table .col-act {
  width: 215px;
}

.qlhh-table-row {
  border-bottom: 1px solid var(--border-subtle);
  cursor: pointer;
  transition: background 0.12s ease;
}
.qlhh-table-row:last-child {
  border-bottom: none;
}
.qlhh-table-row:hover {
  background: var(--bg-row-hover);
}
.qlhh-table-row.in-quote-cart {
  background: rgba(16, 185, 129, 0.06);
}
.qlhh-data-table td {
  padding: 9px 12px;
  vertical-align: middle;
}

.tbl-code-stack,
.tbl-spec-stack {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.tbl-name-main {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink-strong);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.tbl-name-badges {
  margin-top: 4px;
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}
.qlhh-dvt-tag {
  font-size: 11px;
  color: var(--ink-muted);
  font-weight: 600;
}

.qlhh-cur-pill {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 999px;
  background: var(--slate-bg);
  border: 1px solid var(--border-subtle);
  color: var(--ink-secondary);
  font-size: 11px;
  font-weight: 700;
}
.tbl-rate-sub {
  margin-top: 2px;
  font-size: 10.5px;
  color: var(--amber-text);
  font-weight: 600;
}

.tbl-act-cluster {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

/* Lazy Footer */
.qlhh-lazy-footer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px 0 8px;
}
.qlhh-lazy-status {
  font-size: 12.5px;
  color: var(--ink-muted);
  font-weight: 600;
}
.qlhh-lazy-status strong {
  color: var(--sky-text);
}
.qlhh-load-more-btn {
  width: 100%;
  max-width: 560px;
  padding: 10px 16px;
  border-radius: 10px;
  border: 1px dashed var(--sky-border);
  background: var(--sky-bg);
  color: var(--sky-text);
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.16s ease;
}
.qlhh-load-more-btn:hover {
  filter: brightness(1.08);
}

/* ==========================================================================
   6. BENTO VENDOR IMPORT & COMPARE HUB MODAL (.qlhh-hub-modal)
========================================================================== */
.qlhh-hub-overlay {
  z-index: 10045;
}
.qlhh-files-overlay,
.qlhh-usd-overlay {
  z-index: 10065;
}

.qlhh-hub-modal {
  width: min(860px, 100%);
  max-width: 860px;
  max-height: min(88vh, calc(100dvh - 32px));
  background: var(--bg-modal);
  border: 1px solid var(--border-strong);
  border-radius: 16px;
  box-shadow: var(--shadow-modal);
  color: var(--ink-primary);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.qlhh-hub-head {
  padding: 15px 18px;
  background: var(--bg-modal-head);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.qlhh-hub-head.is-import-hub {
  background: linear-gradient(135deg, #0c4a6e 0%, #0369a1 55%, #1d4ed8 100%);
  border-bottom: 1.5px solid rgba(56, 189, 248, 0.45);
  color: #ffffff;
}
.qlhh-hub-head.is-compare-hub {
  background: linear-gradient(135deg, #065f46 0%, #047857 55%, #0f766e 100%);
  border-bottom: 1.5px solid rgba(52, 211, 153, 0.45);
  color: #ffffff;
}
.qlhh-hub-head.is-import-hub .qlhh-hub-head-ico,
.qlhh-hub-head.is-compare-hub .qlhh-hub-head-ico {
