}
.qlhh-ghost-btn.is-pricelist-btn {
  border-color: var(--violet-border);
  background: var(--violet-bg);
  color: var(--violet-text);
}
.qlhh-ghost-btn.is-pricelist-btn:hover {
  filter: brightness(1.06);
}
.qlhh-hub-head-left {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}
.qlhh-hub-head-ico {
  width: 36px;
  height: 36px;
