  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.qlhh-hub-title {
  margin: 0;
  font-size: 15.5px;
