}
.hub-choice-text > span {
  font-size: 11.5px;
  color: var(--ink-muted);
  line-height: 1.4;
}

/* ==========================================================================
   7. LIGHT-BLUE PARITY & COLLISION-FREE MODAL DIALOGS (USD, ALERTS, EXCEL EDITOR, CART)
========================================================================== */
/* ExcelEditor Dual-Theme Parity without needing polluted global .page class */
.qlhh-page.theme-light-blue .features-excel-editor:deep(.excel-editor),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.excel-editor),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.excel-editor) {
  background: #ffffff;
  border-color: #cbd5e1;
}
.qlhh-page.theme-light-blue .features-excel-editor:deep(.excel-toolbar),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.excel-toolbar),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.excel-toolbar) {
  background: #f1f5f9;
  border-bottom-color: #cbd5e1;
}
.qlhh-page.theme-light-blue .features-excel-editor:deep(.toolbar-divider),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.toolbar-divider),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.toolbar-divider) {
  background: #cbd5e1;
}
.qlhh-page.theme-light-blue .features-excel-editor:deep(.toolbar-select),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.toolbar-select),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.toolbar-select) {
  background-color: #ffffff;
  color: #0f172a;
  border-color: #cbd5e1;
}
.qlhh-page.theme-light-blue .features-excel-editor:deep(.toolbar-btn),
.qlhh-page.theme-light-blue .features-excel-editor:deep(.color-btn),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.toolbar-btn),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.color-btn),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.toolbar-btn),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.color-btn) {
  color: #1e293b;
  border-color: transparent;
}
.qlhh-page.theme-light-blue .features-excel-editor:deep(.toolbar-btn:hover),
.qlhh-page.theme-light-blue .features-excel-editor:deep(.color-btn:hover),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.toolbar-btn:hover),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.color-btn:hover),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.toolbar-btn:hover),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.color-btn:hover) {
  background: #e2e8f0;
  border-color: #94a3b8;
}
.qlhh-page.theme-light-blue .features-excel-editor:deep(.editor-content),
.qlhh-fm-modal.theme-light-blue .features-excel-editor:deep(.editor-content),
.qlhh-hub-modal.theme-light-blue .features-excel-editor:deep(.editor-content) {
  background: #ffffff;
  color: #0f172a;
}

/* Custom Alert Modals (Confirm Delete / Delete PriceList / AI Fallback) Dual-Theme */
.custom-alert-modal {
  width: min(440px, 100%);
  padding: 28px 26px 24px;
  border-radius: 18px;
  background: var(--bg-modal);
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow-modal);
  color: var(--ink-primary);
  text-align: center;
}
.alert-icon.is-rose {
  color: var(--rose-text);
  background: var(--rose-bg);
  border: 1px solid var(--rose-border);
}
.alert-icon.is-violet {
  color: var(--violet-text);
  background: var(--violet-bg);
  border: 1px solid var(--violet-border);
}
.custom-alert-modal .alert-title {
  margin: 12px 0 8px;
  font-size: 17px;
  font-weight: 800;
  color: var(--ink-strong);
}
.custom-alert-modal .alert-desc {
  margin: 0 0 22px;
  font-size: 13.5px;
  line-height: 1.55;
  color: var(--ink-muted);
}
.custom-alert-modal .alert-hl-rose {
  color: var(--rose-text);
  font-weight: 700;
}
.custom-alert-modal .alert-hl-amber {
  color: var(--amber-text);
  font-weight: 700;
}
.custom-alert-modal .alert-hl-violet {
  color: var(--violet-text);
  font-weight: 700;
}
.custom-alert-modal .alert-hl-sky {
  color: var(--sky-text);
  font-weight: 700;
}
.custom-alert-modal .alert-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
}
.qlhh-alert-danger-btn {
  height: 36px;
  padding: 0 16px;
  border-radius: 9px;
  border: 1px solid #dc2626;
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
  color: #ffffff;
  font-size: 12.5px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 4px 12px -3px rgba(239, 68, 68, 0.45);
  transition: all 0.15s ease;
}
.qlhh-alert-danger-btn:hover {
  filter: brightness(1.06);
  transform: translateY(-1px);
}

/* Async Result Modal Dual-Theme Parity */
.qlhh-page.theme-light-blue .async-card {
  background: #ffffff;
  border-color: #cbd5e1;
  box-shadow: var(--shadow-modal);
}
.qlhh-page.theme-light-blue .async-title {
  color: #0f172a;
}
.qlhh-page.theme-light-blue .async-subtitle {
  color: #475569;
}

/* USD Exchange Rate Modal (.qlhh-usd-modal) Dual-Theme */
.qlhh-usd-modal {
  width: min(540px, 100%);
  max-width: 540px;
}
.qlhh-usd-body {
  display: flex;
  flex-direction: column;
  gap: 15px;
}
.qlhh-usd-kpi-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.qlhh-usd-kpi-box {
  padding: 11px 13px;
  border-radius: 11px;
  background: var(--bg-well);
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.usd-kpi-lbl {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--ink-muted);
}
.usd-kpi-val {
  font-size: 17.5px;
  font-weight: 800;
}
.usd-kpi-val.is-sky {
  color: var(--sky-text);
}
.usd-kpi-val.is-emerald {
  color: var(--emerald-text);
}
.usd-kpi-val small {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-muted);
}
.qlhh-usd-scope-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.qlhh-usd-scope-opt {
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border-control);
  background: var(--bg-well);
  color: var(--ink-secondary);
  font-size: 12.5px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 9px;
  cursor: pointer;
  transition: all 0.15s ease;
}
.qlhh-usd-scope-opt input[type='radio'] {
  width: 16px;
  height: 16px;
  accent-color: #10b981;
  flex-shrink: 0;
}
.qlhh-usd-scope-opt.active {
  background: var(--emerald-bg);
  border-color: var(--emerald-border);
  color: var(--ink-strong);
}
.qlhh-usd-scope-opt.is-sky.active {
  background: var(--sky-bg);
  border-color: var(--sky-border);
}
.qlhh-usd-scope-opt strong.is-emerald {
  color: var(--emerald-text);
}
.qlhh-usd-scope-opt strong.is-sky {
  color: var(--sky-text);
}
.qlhh-usd-lbl-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}
.qlhh-usd-delta-tag {
  font-size: 11.5px;
  font-weight: 800;
}
.qlhh-usd-delta-tag.is-amber {
  color: var(--amber-text);
}
.qlhh-usd-delta-tag.is-sky {
  color: var(--sky-text);
}
.qlhh-usd-presets {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 3px;
}
.usd-preset-caption {
  font-size: 11.5px;
  color: var(--ink-muted);
  margin-right: 2px;
}
.qlhh-usd-modal.theme-light-blue .usd-quick-step-btn {
  background: #f1f5f9;
  border-color: #cbd5e1;
  color: #334155;
}
.qlhh-usd-modal.theme-light-blue .usd-quick-step-btn.preset {
  background: #ecfdf5;
  border-color: #6ee7b7;
  color: #047857;
}
.qlhh-usd-preview {
  padding: 11px 14px;
  border-radius: 11px;
  background: var(--emerald-bg);
  border: 1px dashed var(--emerald-border);
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12.5px;
  color: var(--ink-secondary);
}
.usd-prev-head {
  font-weight: 800;
  color: var(--emerald-text);
  margin-bottom: 3px;
}
.usd-prev-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 3px 0;
  border-bottom: 1px solid var(--border-subtle);
}
.usd-prev-row.is-total {
  border-bottom: none;
}
.usd-prev-row strong {
  color: var(--ink-strong);
  font-weight: 800;
}
.usd-prev-row.is-total strong {
  color: var(--emerald-text);
}

.qlhh-page.theme-light-blue .btn-secondary {
  background: #f1f5f9;
  border-color: #cbd5e1;
  color: #334155;
}
.qlhh-page.theme-light-blue .quote-cart-right-sidebar {
  background: #ffffff;
  border-left-color: #cbd5e1;
  color: #0f172a;
}
.qlhh-page.theme-light-blue .quote-cart-sidebar__header,
.qlhh-page.theme-light-blue .quote-cart-sidebar__footer {
  background: #f8fbff;
  border-color: #e2e8f0;
}
.qlhh-page.theme-light-blue .quote-cart-sidebar__heading,
.qlhh-page.theme-light-blue .quote-cart-drawer__name,
.qlhh-page.theme-light-blue .quote-cart-drawer__subtotal {
  color: #0f172a;
}
.qlhh-page.theme-light-blue .quote-cart-sidebar__item,
.qlhh-page.theme-light-blue .quote-cart-sidebar__totals {
  background: #f8fafc;
  border-color: #dbeafe;
}
.qlhh-page.theme-light-blue .quote-cart-total-row {
  color: #334155;
}

/* ==========================================================================
   8. RESPONSIVE MOBILE SHELL, BOTTOM SHEETS & FLOATING SUB-DOCK (<= 1100px)
========================================================================== */
@media (max-width: 1100px) {
  .quan-ly-hang-hoa.qlhh-page {
    padding: 10px 10px calc(148px + env(safe-area-inset-bottom, 0px));
  }

  .hide-mob-dock,
  .quote-cart-right-Launcher {
    display: none !important;
  }

  .qlhh-kpi-grid {
    grid-template-columns: 1fr;
    gap: 8px;
  }
  .qlhh-kpi-card {
    padding: 11px 13px;
  }

  .qlhh-filter-row-main {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
  }
  .qlhh-search-box {
    order: -1;
    flex: 1 1 auto;
    width: 100%;
    padding: 0 10px 0 12px;
    gap: 6px;
  }
  .qlhh-search-vol {
    padding: 2px 6px;
  }
  .qlhh-search-vol-input {
    width: 52px;
  }
  .qlhh-filter-left {
    width: 100%;
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 2px;
  }
  .qlhh-picker-btn,
  .qlhh-vol-pill,
  .qlhh-reset-btn {
    flex-shrink: 0;
  }

  /* Adaptive Pickers become Bottom Sheets on Mobile */
  .qlhh-pop-backdrop {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 10025;
    background: rgba(2, 6, 23, 0.62);
    backdrop-filter: blur(4px);
  }
  .qlhh-pop-menu,
  .qlhh-pop-menu.is-wide {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    top: auto;
    width: 100%;
    max-height: 82dvh;
    z-index: 10030;
    border-radius: 18px 18px 0 0;
    border-bottom: none;
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }
  .mob-sheet-grabber {
    display: block;
    width: 40px;
    height: 4px;
    border-radius: 999px;
    background: var(--border-control);
    margin: 8px auto 2px;
    flex-shrink: 0;
  }

  /* Prevent iOS Safari Auto-Zoom on Inputs */
  .qlhh-capsule-stepper .step-num {
    font-size: 16px !important;
  }
  .form-grid-2col,
  .hub-choice-grid {
    grid-template-columns: 1fr;
  }

  /* Floating Glass Bottom Sub-Dock (.bg-mobile-dock — Đồng bộ App.vue & QuanLyBaoGiaFirebase) */
  .bg-mob-popover-backdrop {
    position: fixed;
    inset: 0;
    z-index: 970;
    background: rgba(2, 6, 23, 0.35);
  }

  .bg-mobile-dock {
    position: fixed;
    left: 10px;
    right: 10px;
    bottom: calc(74px + env(safe-area-inset-bottom, 0px));
    width: auto;
    max-width: 430px;
    margin: 0 auto;
    z-index: 955;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    align-items: stretch;
    gap: 5px;
    padding: 6px;
    border-radius: 20px;
    background: rgba(15, 23, 42, 0.92);
    border: 1px solid rgba(148, 163, 184, 0.28);
    box-shadow: 0 14px 36px rgba(2, 6, 23, 0.62), inset 0 1px 0 rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(22px) saturate(165%);
    -webkit-backdrop-filter: blur(22px) saturate(165%);
    transform: translate3d(0, 0, 0);
    transition: bottom 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      transform 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.24s cubic-bezier(0.22, 1, 0.36, 1),
      visibility 0.24s ease;
  }
  .qlhh-page.theme-light-blue .bg-mobile-dock {
    background: rgba(255, 255, 255, 0.95);
    border-color: rgba(2, 132, 199, 0.28);
    box-shadow: 0 14px 34px rgba(15, 23, 42, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.95);
  }
  :global(.app-layout.mobile-nav-hidden .bg-mobile-dock) {
    bottom: calc(10px + env(safe-area-inset-bottom, 0px)) !important;
  }
  .bg-mobile-dock.is-modal-hidden,
  :global(.app-layout.has-open-modal .bg-mobile-dock),
  :global(body.app-has-open-modal .bg-mobile-dock) {
    transform: translateY(calc(100% + 96px + env(safe-area-inset-bottom, 0px))) scale(0.96) !important;
    opacity: 0 !important;
    visibility: hidden !important;
    pointer-events: none !important;
  }

  .bg-dock-btn {
    position: relative;
    width: 100%;
    min-width: 0;
    min-height: 48px;
    margin: 0;
    padding: 5px 3px 4px;
    border-radius: 14px;
    border: 1px solid transparent;
    background: transparent;
    color: #94a3b8;
    font-size: 10.5px;
    font-weight: 700;
    line-height: 1.15;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    cursor: pointer;
    touch-action: manipulation;
    transition: all 0.16s ease;
  }
  .bg-dock-btn > span {
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .bg-dock-btn.active {
    color: #38bdf8;
    background: rgba(56, 189, 248, 0.14);
    border-color: rgba(56, 189, 248, 0.3);
  }
  .qlhh-page.theme-light-blue .bg-dock-btn {
    color: #475569;
  }
  .qlhh-page.theme-light-blue .bg-dock-btn.active {
    color: #0284c7;
    background: #e0f2fe;
    border-color: #7dd3fc;
  }
  .bg-dock-btn.is-primary.is-center-cta {
    background: linear-gradient(135deg, #10b981 0%, #059669 100%);
    color: #042f2e;
    font-weight: 800;
    border-color: rgba(110, 231, 183, 0.48);
    box-shadow: 0 6px 18px -4px rgba(16, 185, 129, 0.52);
  }
  .qlhh-page.theme-light-blue .bg-dock-btn.is-primary.is-center-cta {
    background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
    color: #ffffff;
    border-color: #38bdf8;
    box-shadow: 0 6px 18px -4px rgba(2, 132, 199, 0.42);
  }

  .bg-dock-icon-wrap {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 20px;
  }
  .bg-dock-badge {
    position: absolute;
    top: -5px;
    right: -14px;
    min-width: 17px;
    height: 15px;
    padding: 0 4px;
    border-radius: 999px;
    background: #0ea5e9;
    color: #ffffff;
    font-size: 9px;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1.5px solid #0f172a;
    white-space: nowrap;
  }
  .bg-dock-badge.is-emerald {
    background: #10b981;
  }
  .bg-dock-badge.is-mode {
    background: rgba(56, 189, 248, 0.22);
    color: #38bdf8;
    right: -20px;
  }
  .qlhh-page.theme-light-blue .bg-dock-badge {
    border-color: #ffffff;
  }
  .qlhh-page.theme-light-blue .bg-dock-badge.is-mode {
    background: #e0f2fe;
    color: #0369a1;
  }

  .bg-mob-display-popover {
    position: fixed;
    left: 12px;
    right: 12px;
    bottom: calc(138px + env(safe-area-inset-bottom, 0px));
    max-width: 390px;
    margin: 0 auto;
    z-index: 980;
    padding: 12px;
    border-radius: 16px;
    background: rgba(15, 23, 42, 0.97);
    border: 1px solid rgba(56, 189, 248, 0.34);
    box-shadow: 0 20px 48px rgba(0, 0, 0, 0.68);
    backdrop-filter: blur(18px);
    display: flex;
    flex-direction: column;
    gap: 10px;
    transition: bottom 0.38s cubic-bezier(0.22, 1, 0.36, 1);
  }
  .qlhh-page.theme-light-blue .bg-mob-display-popover {
    background: #ffffff;
    border-color: #93c5fd;
    box-shadow: 0 20px 44px rgba(15, 23, 42, 0.2);
  }
  :global(.app-layout.mobile-nav-hidden .bg-mob-display-popover) {
    bottom: calc(74px + env(safe-area-inset-bottom, 0px)) !important;
  }

  .bg-ds-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--border-subtle);
  }
  .bg-ds-title {
    font-size: 12.5px;
    font-weight: 800;
    color: var(--ink-strong);
  }
  .bg-ds-close {
    width: 26px;
    height: 26px;
    border-radius: 7px;
    border: 1px solid var(--border-control);
    background: var(--bg-input);
    color: var(--ink-muted);
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
  }
  .bg-ds-section {
    padding-bottom: 10px;
    border-bottom: 1px solid var(--border-subtle);
  }
  .bg-ds-section.is-last {
    padding-bottom: 0;
    border-bottom: none;
  }
  .bg-ds-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--ink-muted);
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.03em;
  }
  .bg-ds-grid-2 {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 6px;
  }
  .bg-ds-opt-btn {
    height: 34px;
    padding: 0 10px;
    border-radius: 9px;
    border: 1px solid var(--border-control);
    background: var(--bg-input);
    color: var(--ink-secondary);
    font-size: 12px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
  }
  .bg-ds-opt-btn.active {
    background: var(--sky-bg);
    border-color: var(--sky-border);
    color: var(--sky-text);
  }
  .bg-ds-reset-btn {
    width: 100%;
    height: 34px;
    border-radius: 9px;
    border: 1px solid var(--rose-border);
    background: var(--rose-bg);
    color: var(--rose-text);
    font-size: 12px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
  }
}

@media (max-width: 768px) {
  .qlhh-cards-grid {
    grid-template-columns: 1fr;
  }
  .qlhh-cards-grid.is-inside-group {
    padding: 10px;
  }
  .kpi-brand-chips {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .panel-content {
    grid-template-columns: 1fr;
  }
  .col-span-2,
  .col-span-3 {
    grid-column: span 1;
  }
  .quote-cart-right-sidebar {
    width: 100vw !important;
    max-width: 100vw !important;
  }
  /* Hub & Files Modals go Fullscreen Sheet ONLY on Phone (<= 768px), keeping USD & Alerts centered */
  .qlhh-hub-overlay:not(.qlhh-usd-overlay) {
    padding: 0;
    align-items: stretch;
  }
  .qlhh-hub-modal:not(.qlhh-usd-modal) {
    width: 100% !important;
    max-width: 100% !important;
    height: 100% !important;
    max-height: 100% !important;
    border-radius: 0 !important;
    border: none !important;
  }
  .qlhh-usd-overlay {
    padding: 10px;
  }
  .qlhh-usd-modal {
    width: 100%;
    max-height: calc(100dvh - 20px);
  }
  .qlhh-usd-kpi-grid {
    grid-template-columns: 1fr 1fr;
  }
}

/* ==========================================================================
   9. FULLSCREEN 100% ADD / EDIT PRODUCT MODAL (.qlhh-fm-overlay & .qlhh-fm-modal)
      Zero Emojis • Unified 5+1 Semantic Palette • Dark Navy & Light Blue Parity
========================================================================== */
.qlhh-fm-overlay {
  padding: 0 !important;
  align-items: stretch !important;
  justify-content: stretch !important;
  z-index: 10050;
}

.qlhh-fm-modal {
  width: 100%;
  max-width: 100%;
  height: 100%;
  max-height: 100%;
  border-radius: 0;
  border: none;
  background: var(--bg-canvas);
  color: var(--ink-primary);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Sticky Rich Header */
.qlhh-fm-head {
  padding: 12px 22px;
  background: linear-gradient(135deg, #0d1d36 0%, #102a49 55%, #0c223b 100%);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-shrink: 0;
}
.qlhh-fm-modal.theme-light-blue .qlhh-fm-head {
  background: linear-gradient(135deg, #e0f2fe 0%, #dbeafe 55%, #eff6ff 100%);
  border-bottom-color: #bfdbfe;
}

.qlhh-fm-head-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1 1 auto;
}

.qlhh-fm-head-ico {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.qlhh-fm-head-ico.is-sky {
  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
}
.qlhh-fm-head-ico.is-emerald {
  background: var(--emerald-bg);
  border: 1px solid var(--emerald-border);
  color: var(--emerald-text);
}

.qlhh-fm-title-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.qlhh-fm-title-row {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
}
.qlhh-fm-title-row h2 {
  margin: 0;
  font-size: 16.5px;
  font-weight: 800;
  color: var(--ink-strong);
  letter-spacing: -0.01em;
}

.qlhh-fm-meta-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.qlhh-fm-meta-pill {
  padding: 2px 9px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid var(--border-control);
  color: var(--ink-secondary);
  font-size: 11.5px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.qlhh-fm-modal.theme-light-blue .qlhh-fm-meta-pill {
  background: rgba(255, 255, 255, 0.85);
}
.qlhh-fm-meta-pill strong {
  color: var(--sky-text);
  font-weight: 700;
}
.qlhh-fm-meta-pill.is-amber {
  background: var(--amber-bg);
  border-color: var(--amber-border);
  color: var(--amber-text);
}
.qlhh-fm-meta-pill.is-amber strong {
  color: var(--amber-text);
}

.qlhh-fm-head-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.qlhh-fm-live-pills {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}
.fm-live-pill {
  padding: 5px 11px;
  border-radius: 9px;
  font-size: 12px;
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  white-space: nowrap;
}
.fm-live-pill small {
  font-size: 11px;
  font-weight: 600;
  opacity: 0.85;
}
.fm-live-pill strong {
  font-weight: 800;
}
.fm-live-pill.is-violet {
  background: var(--violet-bg);
  border: 1px solid var(--violet-border);
  color: var(--violet-text);
}
.fm-live-pill.is-emerald {
  background: var(--emerald-bg);
  border: 1px solid var(--emerald-border);
  color: var(--emerald-text);
}

.qlhh-fm-close {
  width: 34px;
  height: 34px;
  padding: 0;
  margin: 0;
  border-radius: 9px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-secondary);
  font-size: 15px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}
.qlhh-fm-close:hover {
  background: var(--rose-bg);
  border-color: var(--rose-border);
  color: var(--rose-text);
}

/* Scrollable 2-Column Bento Body */
.qlhh-fm-body {
  flex: 1 1 0%;
  min-height: 0;
  overflow-y: auto;
  padding: 16px 22px 24px;
  -webkit-overflow-scrolling: touch;
}

.qlhh-fm-2col {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  gap: 16px;
  align-items: start;
  max-width: 1720px;
  margin: 0 auto;
}

.qlhh-fm-col {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

.qlhh-bento-box {
  padding: 16px 18px;
  border-radius: 14px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  gap: 13px;
  min-width: 0;
}

.qlhh-bento-head {
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.qlhh-bento-head.is-between {
  justify-content: space-between;
  flex-wrap: wrap;
}
.qlhh-bento-head .bento-head-title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.qlhh-bento-head.is-sky {
  color: var(--sky-text);
}
.qlhh-bento-head.is-emerald {
  color: var(--emerald-text);
}
.qlhh-bento-head.is-slate {
  color: var(--ink-secondary);
}
.bento-count-pill {
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
  font-size: 11px;
  font-weight: 800;
}

/* Form Grids & Inputs */
.qlhh-fm-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 14px;
}
.qlhh-fm-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}
.qlhh-fm-stack {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.qlhh-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}
.qlhh-field.col-span-2 {
  grid-column: span 2;
}
.qlhh-field label {
  font-size: 11.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--ink-muted);
}

.qlhh-fm-input,
.qlhh-fm-select,
.qlhh-fm-textarea {
  width: 100%;
  padding: 9px 12px;
  border-radius: 9px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--ink-primary);
  font-size: 13.5px;
  font-weight: 500;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}
.qlhh-fm-input,
.qlhh-fm-select {
  height: 38px;
}
.qlhh-fm-textarea {
  resize: vertical;
  min-height: 68px;
  line-height: 1.45;
}
.qlhh-fm-input.is-mono {
  font-family: var(--font-mono) !important;
  font-weight: 700;
  font-size: 13px;
}
.qlhh-fm-input::placeholder,
.qlhh-fm-textarea::placeholder {
  color: var(--ink-faint);
  font-weight: 400;
}
.qlhh-fm-input:focus,
.qlhh-fm-select:focus,
.qlhh-fm-textarea:focus {
  outline: none;
  border-color: var(--sky-border);
  box-shadow: 0 0 0 3px rgba(14, 165, 233, 0.15);
}
.qlhh-fm-input:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

/* Price Calculation Sections (Flat, Borderless inside Bento Box) */
.qlhh-price-calc-card {
  padding: 10px 0 0;
  border-radius: 0;
  background: transparent;
  border: none;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.qlhh-price-calc-card.is-violet,
.qlhh-price-calc-card.is-sky,
.qlhh-price-calc-card.is-emerald {
  border-left: none;
  background: transparent;
}
.qlhh-price-calc-card.is-formula-bridge {
  padding: 10px 0 0;
  gap: 7px;
}

.pcc-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}
.pcc-label-cluster,
.pcc-right-cluster {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.pcc-label {
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.pcc-label.is-violet {
  color: var(--violet-text);
}
.pcc-label.is-sky {
  color: var(--sky-text);
}
.pcc-label.is-emerald {
  color: var(--emerald-text);
}
.pcc-caption {
  font-size: 11.5px;
  color: var(--ink-muted);
}
.pcc-caption strong {
  color: var(--ink-strong);
}

.qlhh-fm-input.is-hero-num {
  height: 44px;
  font-size: 16.5px;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.qlhh-fm-input.is-cost-hero {
  border-color: var(--border-control);
  color: var(--violet-text);
}
.qlhh-fm-input.is-sell-hero {
  border-color: var(--border-control);
  color: var(--emerald-text);
}
.qlhh-fm-modal.theme-light-blue .qlhh-fm-input.is-sell-hero {
  color: #047857;
}

/* Formula Bar (Flat Inline Row) */
.qlhh-formula-bar {
  padding: 8px 10px;
  border-radius: 9px;
  background: var(--bg-well);
  border: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}
.qlhh-formula-bar.is-amber {
  background: var(--amber-bg);
  border-color: var(--amber-border);
}

.formula-title {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  color: var(--ink-secondary);
}
.qlhh-flow-toggle-btn {
  padding: 5px 10px;
  border-radius: 8px;
  border: 1px solid var(--violet-border);
  background: var(--violet-bg);
  color: var(--violet-text);
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.16s ease, border-color 0.16s ease, color 0.16s ease, transform 0.12s ease;
}
.qlhh-flow-toggle-btn:hover {
  filter: brightness(1.06);
}
.qlhh-flow-toggle-btn:active {
  transform: scale(0.98);
}
.qlhh-flow-toggle-btn.is-reverse {
  border-color: var(--amber-border);
  background: var(--amber-bg);
  color: var(--amber-text);
}
.qlhh-formula-bar.is-amber .formula-title {
  color: var(--amber-text);
}

.formula-controls {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.qlhh-mini-select {
  height: 32px;
  padding: 0 9px;
  border-radius: 7px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--ink-primary);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}
.qlhh-mini-select.is-emerald {
  border-color: var(--emerald-border);
  color: var(--emerald-text);
  background: var(--emerald-bg);
}
.qlhh-mini-select.is-rose {
  border-color: var(--rose-border);
  color: var(--rose-text);
  background: var(--rose-bg);
}

.qlhh-unit-input-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}
.qlhh-mini-num {
  width: 92px;
  height: 32px;
  padding: 0 24px 0 9px;
  border-radius: 7px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--ink-strong);
  font-size: 13px;
  font-weight: 800;
  text-align: right;
}
.qlhh-mini-num.is-wide {
  width: 138px;
  padding-right: 10px;
}
.qlhh-mini-num:focus {
  outline: none;
  border-color: var(--sky-border);
}
.unit-suffix {
  position: absolute;
  right: 8px;
  font-size: 11.5px;
  font-weight: 800;
  color: var(--ink-muted);
  pointer-events: none;
}

/* Unified File History List (.qlhh-file-card + .tpl-file-* Palette) */
.qlhh-files-hint {
  margin: -4px 0 0;
  font-size: 11.5px;
  color: var(--ink-muted);
}

.qlhh-files-empty {
  padding: 18px 14px;
  border-radius: 10px;
  border: 1px dashed var(--border-control);
  background: var(--bg-well);
  color: var(--ink-muted);
  font-size: 12px;
  text-align: center;
  line-height: 1.5;
}

.qlhh-file-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 280px;
  overflow-y: auto;
  padding-right: 2px;
}
.qlhh-file-list.is-tall {
  max-height: 430px;
}

.qlhh-file-card {
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--bg-well);
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.qlhh-file-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.qlhh-file-name-wrap {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  flex: 1 1 200px;
}

.qlhh-file-rank {
  padding: 2px 7px;
  border-radius: 5px;
  background: var(--slate-bg);
  border: 1px solid var(--border-subtle);
  color: var(--ink-secondary);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  flex-shrink: 0;
}
.qlhh-file-rank.is-latest {
  background: var(--emerald-bg);
  border-color: var(--emerald-border);
  color: var(--emerald-text);
}

.qlhh-file-link {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--sky-text);
  text-decoration: underline;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.qlhh-file-plain {
  font-size: 12.5px;
  color: var(--ink-strong);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.qlhh-file-acts {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}

/* Strict Unified File-Action Button Rule (Sky Primary, Slate Neutral, Slate->Rose Delete) */
.qlhh-fbtn-primary {
  height: 26px;
  padding: 0 9px;
  border-radius: 6px;
  border: 1px solid var(--sky-border);
  background: var(--sky-bg);
  color: var(--sky-text);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
.qlhh-fbtn-primary:hover {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.qlhh-fbtn-neutral {
  height: 26px;
  padding: 0 8px;
  border-radius: 6px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-secondary);
  font-size: 11px;
  font-weight: 600;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
.qlhh-fbtn-neutral:hover {
  border-color: var(--sky-border);
  color: var(--sky-text);
}

.qlhh-fbtn-delete {
  width: 26px;
  height: 26px;
  padding: 0;
  border-radius: 6px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-muted);
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}
.qlhh-fbtn-delete:hover {
  background: var(--rose-bg);
  border-color: var(--rose-border);
  color: var(--rose-text);
}

.qlhh-file-card-meta {
  padding-top: 5px;
  border-top: 1px dashed var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 11.5px;
}
.file-time-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--ink-muted);
}
.file-note-inline {
  color: var(--ink-faint);
}

.file-prices-inline {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  font-size: 11.5px;
}
.fp-violet {
  color: var(--violet-text);
}
.fp-emerald {
  color: var(--emerald-text);
}
.fp-amber {
  color: var(--amber-text);
}

/* Sticky Action Footer */
.qlhh-fm-foot {
  padding: 12px 22px calc(12px + env(safe-area-inset-bottom, 0px));
  background: var(--bg-modal-head);
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-shrink: 0;
}
.qlhh-fm-foot-left,
.qlhh-fm-foot-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.qlhh-fm-btn-delete {
  height: 38px;
  padding: 0 13px;
  border-radius: 9px;
  border: 1px solid var(--rose-border);
  background: var(--rose-bg);
  color: var(--rose-text);
  font-size: 12.5px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
}
.qlhh-fm-btn-delete:hover {
  background: #ef4444;
  border-color: #ef4444;
  color: #ffffff;
}

.qlhh-btn-primary.is-save-cta {
  height: 38px;
  padding: 0 18px;
  font-size: 13px;
}
.qlhh-btn-primary.is-save-cta:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

@media (max-width: 1100px) {
  .hide-sm-head {
    display: none !important;
  }
  .qlhh-fm-head {
    padding: 11px 14px;
  }
  .qlhh-fm-body {
    padding: 12px 12px 20px;
  }
  .qlhh-fm-2col {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .qlhh-bento-box {
    padding: 13px 14px;
  }
  .qlhh-fm-input,
  .qlhh-fm-select,
  .qlhh-fm-textarea {
    font-size: 16px !important;
  }
  .qlhh-fm-foot {
    padding: 10px 12px calc(10px + env(safe-area-inset-bottom, 0px));
  }
}

@media (max-width: 768px) {
  .qlhh-fm-head {
    position: relative;
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
    padding: 11px 12px;
  }
  .qlhh-fm-head-left {
    padding-right: 40px;
    align-items: flex-start;
  }
  .qlhh-fm-head-ico {
    width: 32px;
    height: 32px;
  }
  .qlhh-fm-title-row h2 {
    font-size: 15.5px;
  }
  .qlhh-fm-head-right {
    justify-content: flex-start;
  }
  .qlhh-fm-close {
    position: absolute;
    top: 11px;
    right: 12px;
  }
  .qlhh-fm-grid,
  .qlhh-fm-grid-3 {
    grid-template-columns: 1fr;
  }
  .qlhh-field.col-span-2 {
    grid-column: span 1;
  }
  .qlhh-price-calc-card {
    padding: 8px 0 0;
    gap: 7px;
  }
  .qlhh-formula-bar {
    flex-direction: column;
    align-items: stretch;
    gap: 7px;
    padding: 8px;
  }
  .qlhh-flow-toggle-btn {
    width: 100%;
    justify-content: center;
    padding: 6px 10px;
    font-size: 12px;
  }
  .qlhh-formula-bar .formula-controls {
    display: flex;
    align-items: center;
    gap: 5px;
    width: 100%;
    flex-wrap: nowrap;
  }
  .qlhh-mini-select {
    flex: 0 1 auto;
    min-width: 0;
    height: 32px;
    padding: 0 6px;
    font-size: 12px !important;
    max-width: 100%;
  }
  .qlhh-unit-input-wrap,
  .qlhh-unit-input-wrap.is-amount {
    flex: 1 1 0;
    min-width: 0;
    width: auto;
  }
  .qlhh-mini-num,
  .qlhh-mini-num.is-wide {
    width: 100% !important;
    min-width: 0;
    height: 32px;
    padding: 0 22px 0 8px;
    font-size: 13px !important;
  }
  .qlhh-unit-input-wrap.is-amount .qlhh-mini-num,
  .qlhh-unit-input-wrap.is-amount .qlhh-mini-num.is-wide {
    padding-right: 8px;
  }
  .qlhh-fm-foot {
    gap: 8px;
    padding: 10px 12px calc(10px + env(safe-area-inset-bottom, 0px));
  }
  .qlhh-fm-btn-delete {
    padding: 0 10px;
    font-size: 12px;
  }
  .qlhh-fm-foot-right {
    flex: 1 1 auto;
    justify-content: flex-end;
    gap: 8px;
  }
  .qlhh-btn-primary.is-save-cta {
    padding: 0 14px;
    font-size: 12.5px;
  }
}

/* ==========================================================================
   10. REDESIGNED CARD FILE COMPARE MODAL (.qlhh-cmp-overlay & .qlhh-cmp-modal)
       Unified Template Bento • Dual-Theme (Dark Navy & Light Blue) • No Emoji
========================================================================== */
.qlhh-cmp-overlay {
  z-index: 10300;
  padding: 18px;
}

.qlhh-cmp-modal {
  width: min(1360px, 100%);
  max-width: 1360px;
  height: min(92vh, calc(100dvh - 36px));
  max-height: min(92vh, calc(100dvh - 36px));
  border-radius: 16px;
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow-modal);
}

.qlhh-fm-head-ico.is-violet {
  background: var(--violet-bg);
  border: 1px solid var(--violet-border);
  color: var(--violet-text);
}

.qlhh-cmp-vendor-tag {
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.05em;
  flex-shrink: 0;
}
.qlhh-cmp-vendor-tag.is-sophos {
  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
}
.qlhh-cmp-vendor-tag.is-kaspersky {
  background: var(--emerald-bg);
  border: 1px solid var(--emerald-border);
  color: var(--emerald-text);
}
.qlhh-cmp-vendor-tag.is-acronis {
  background: var(--violet-bg);
  border: 1px solid var(--violet-border);
  color: var(--violet-text);
}
.qlhh-cmp-subline {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 11.5px;
  color: var(--ink-muted);
}
.qlhh-cmp-subline strong {
  color: var(--ink-secondary);
}

.qlhh-cmp-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 11px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}
.qlhh-cmp-status-pill.is-match {
  background: var(--emerald-bg);
  border: 1px solid var(--emerald-border);
  color: var(--emerald-text);
}
.qlhh-cmp-status-pill.is-diff {
  background: var(--amber-bg);
  border: 1px solid var(--amber-border);
  color: var(--amber-text);
}
.qlhh-cmp-status-pill.is-miss {
  background: var(--rose-bg);
  border: 1px solid var(--rose-border);
  color: var(--rose-text);
}

.qlhh-cmp-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.qlhh-cmp-loading {
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 36px 20px;
  color: var(--sky-text);
  font-weight: 700;
}

.qlhh-cmp-alert {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12.5px;
  font-weight: 700;
}
.qlhh-cmp-alert.is-rose {
  background: var(--rose-bg);
  border: 1px solid var(--rose-border);
  color: var(--rose-text);
}

/* 1. Hero Comparison Card */
.qlhh-cmp-hero-card {
  padding: 14px 18px;
}
.qlhh-cmp-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 16px;
}
.qlhh-cmp-hero-side {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.qlhh-cmp-hero-side.is-right {
  align-items: flex-end;
  text-align: right;
}
.qlhh-cmp-eyebrow {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.qlhh-cmp-eyebrow.is-sky {
  color: var(--sky-text);
}
.qlhh-cmp-eyebrow.is-emerald {
  color: var(--emerald-text);
}
.qlhh-cmp-hero-price {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -0.02em;
  line-height: 1.2;
}
.qlhh-cmp-hero-price.is-sky {
  color: var(--sky-text);
}
.qlhh-cmp-hero-price.is-emerald {
  color: var(--emerald-text);
}
.qlhh-cmp-hero-sub {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 12px;
  font-size: 12px;
  color: var(--ink-muted);
}
.qlhh-cmp-hero-sub strong {
  color: var(--ink-strong);
}
.qlhh-cmp-hero-empty {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--rose-text);
}
.qlhh-cmp-hero-mid {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 14px;
  border-left: 1px dashed var(--border-control);
  border-right: 1px dashed var(--border-control);
}

/* 2. Files & Quick Jump Strip */
.qlhh-cmp-files-card {
  gap: 10px;
  padding: 12px 16px;
}
.qlhh-cmp-file-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.qlhh-cmp-file-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  flex-wrap: wrap;
  gap: 6px 10px;
  padding: 3px 0;
  min-width: 0;
}
.qlhh-cmp-file-text {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  flex: 0 1 auto;
  flex-wrap: wrap;
}
.qlhh-cmp-file-lbl {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--ink-secondary);
  white-space: nowrap;
}
.qlhh-cmp-file-name {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--sky-text);
  text-decoration: underline;
  word-break: break-word;
}
.qlhh-cmp-file-icons {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.qlhh-cmp-ico-btn {
  width: 28px;
  height: 28px;
  padding: 0;
  margin: 0;
  border-radius: 7px;
  border: 1px solid var(--border-control);
  background: var(--bg-well);
  color: var(--ink-secondary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.14s ease;
}
.qlhh-cmp-ico-btn:hover {
  border-color: var(--sky-border);
  background: var(--sky-bg);
  color: var(--sky-text);
}
.qlhh-cmp-change-btn {
  cursor: pointer;
}
.qlhh-cmp-nav-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  padding-top: 10px;
  border-top: 1px dashed var(--border-subtle);
}
.qlhh-cmp-ver-tag,
.qlhh-cmp-plain-meta {
  font-size: 11.5px;
  font-weight: 700;
  color: var(--ink-muted);
  white-space: nowrap;
}
.qlhh-cmp-body code {
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  color: var(--ink-strong) !important;
  font-size: inherit !important;
  font-weight: 700;
}

/* 3. ViewOffice Panel Dual-Theme Overrides */
.qlhh-cmp-office {
  margin-bottom: 0;
  border: 1px solid var(--sky-border);
  background: var(--bg-card);
  box-shadow: var(--shadow-card);
}
.qlhh-cmp-office .compare-office-embed-header {
  background: var(--bg-modal-head);
  border-bottom-color: var(--border-subtle);
  padding: 8px 12px;
}
.qlhh-cmp-office-left,
.qlhh-cmp-office-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.qlhh-cmp-office-brand {
  font-size: 12px;
  font-weight: 800;
  color: var(--sky-text);
  margin-right: 4px;
}
.qlhh-cmp-copied-msg {
  font-size: 11.5px;
  font-weight: 700;
  color: var(--emerald-text);
}
.qlhh-cmp-modal.theme-light-blue .qlhh-cmp-office .compare-office-role-btn {
  background: var(--bg-input);
  border-color: var(--border-control);
  color: var(--ink-secondary);
}
.qlhh-cmp-modal.theme-light-blue .qlhh-cmp-office .compare-office-role-btn.active {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
}
.qlhh-cmp-modal.theme-light-blue .qlhh-cmp-office .compare-office-close-btn {
  background: var(--rose-bg);
  border-color: var(--rose-border);
  color: var(--rose-text);
}

/* 4. Tabs, Stacks & Form Controls */
.qlhh-cmp-tabs {
  padding: 6px 8px;
  border-radius: 12px;
  border: 1px solid var(--border-subtle);
  background: var(--bg-card);
  flex-shrink: 0;
}
.qlhh-cmp-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.qlhh-cmp-params-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(145px, 1fr));
  gap: 10px 12px;
}
.qlhh-cmp-model-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px dashed var(--border-subtle);
}
.qlhh-cmp-model-left {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  min-width: 0;
}
.qlhh-cmp-sub-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink-muted);
}
.qlhh-cmp-model-sel {
  width: auto !important;
  min-width: 145px;
  height: 32px !important;
  padding: 0 10px !important;
  font-size: 12.5px !important;
  font-weight: 700 !important;
}
.qlhh-cmp-model-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 800;
}
.qlhh-cmp-model-chip.is-primary {
  background: var(--sky-bg);
  border: 1px solid var(--sky-border);
  color: var(--sky-text);
}
.qlhh-cmp-model-chip.is-secondary {
  background: var(--violet-bg);
  border: 1px solid var(--violet-border);
  color: var(--violet-text);
}
.qlhh-cmp-chip-x {
  background: transparent;
  border: none;
  color: inherit;
  font-weight: 900;
  cursor: pointer;
  padding: 0 2px;
  line-height: 1;
}

.qlhh-cmp-model-picker {
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--bg-well);
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.qlhh-cmp-model-group {
  display: grid;
  grid-template-columns: 185px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
}
.qlhh-cmp-mg-name {
  font-size: 12px;
  font-weight: 800;
  color: var(--sky-text);
}
.qlhh-cmp-mg-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
.qlhh-cmp-model-btn {
  padding: 3px 9px;
  border-radius: 6px;
  border: 1px solid var(--border-control);
  background: var(--bg-card);
  color: var(--ink-secondary);
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.14s ease;
}
.qlhh-cmp-model-btn.active {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
}

/* 5. Firewall Calculator Data Table (Template Styled) */
.qlhh-cmp-table-wrap {
  width: 100%;
  overflow-x: auto;
  border-radius: 14px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-card);
}
.qlhh-cmp-table {
  width: 100%;
  min-width: 840px;
  border-collapse: collapse;
  font-size: 12.5px;
}
.qlhh-cmp-table thead th {
  padding: 10px 11px;
  background: var(--bg-table-head);
  color: var(--ink-muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  text-align: left;
  border-bottom: 1px solid var(--border-subtle);
  white-space: nowrap;
}
.qlhh-cmp-table th.col-group-sep,
.qlhh-cmp-table td.col-group-sep {
  border-left: 1px solid var(--border-subtle);
}
.qlhh-cmp-cat-row td {
  padding: 7px 12px;
  background: var(--bg-well);
  color: var(--sky-text);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-bottom: 1px solid var(--border-subtle);
}
.qlhh-cmp-fw-row {
  cursor: pointer;
  transition: background 0.12s ease;
}
.qlhh-cmp-fw-row td {
  padding: 8px 11px;
  border-bottom: 1px solid var(--border-subtle);
  vertical-align: middle;
}
.qlhh-cmp-fw-row:hover {
  background: var(--bg-row-hover);
}
.qlhh-cmp-fw-row.is-unavail {
  opacity: 0.62;
}
.qlhh-cmp-fw-row.is-selected {
  background: var(--sky-bg);
}
.qlhh-cmp-fw-row.is-selected td:first-child {
  box-shadow: inset 3px 0 0 var(--sky-text);
}
.qlhh-cmp-row-title {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--ink-strong);
  font-size: 12.5px;
}
.qlhh-cmp-active-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--emerald-text);
  flex-shrink: 0;
}
.qlhh-cmp-row-sub {
  font-size: 10.5px;
  color: var(--ink-faint);
  margin-top: 1px;
}
.qlhh-cmp-sku-code {
  font-size: 12px !important;
}
.qlhh-cmp-cell-note {
  font-size: 10px;
  color: var(--amber-text);
  margin-top: 2px;
}
.qlhh-cmp-msrp-txt {
  color: var(--sky-text);
  font-size: 13px;
}
.qlhh-cmp-buy-txt {
  color: var(--emerald-text);
  font-size: 13px;
}
.qlhh-cmp-disc-txt {
  color: var(--amber-text);
  font-weight: 700;
}
.qlhh-cmp-muted {
  color: var(--ink-faint);
  font-size: 11.5px;
}
.qlhh-cmp-pct-input {
  width: 68px;
  height: 28px;
  padding: 0 7px;
  border-radius: 7px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--amber-text);
  font-size: 12px;
  font-weight: 800;
  text-align: right;
}
.qlhh-cmp-pct-input:focus {
  outline: none;
  border-color: var(--sky-border);
}

/* 6. Shared Grids, Key-Value Source Cards, Universal Search */
.qlhh-cmp-2col {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 14px;
}
.qlhh-cmp-3col-fields {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}
.qlhh-cmp-readonly-box {
  height: 38px;
  padding: 0 11px;
  border-radius: 9px;
  border: 1px solid var(--border-control);
  background: var(--bg-well);
  color: var(--amber-text);
  font-size: 12.5px;
  font-weight: 700;
  display: flex;
  align-items: center;
}
.qlhh-cmp-band-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 12px;
  color: var(--ink-muted);
}
.qlhh-cmp-warn-txt {
  color: var(--amber-text);
  font-weight: 700;
}
.qlhh-cmp-err-txt {
  color: var(--rose-text);
  font-weight: 700;
}
.is-emerald-txt {
  color: var(--emerald-text);
  font-weight: 700;
}
.qlhh-cmp-search-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.qlhh-cmp-search-row .qlhh-fm-input {
  flex: 1 1 240px;
}
.qlhh-cmp-search-drop {
  max-height: 220px;
  overflow-y: auto;
  border-radius: 10px;
  border: 1px solid var(--border-control);
  background: var(--bg-well);
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.qlhh-cmp-search-hit {
  padding: 7px 10px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  cursor: pointer;
  font-size: 12.5px;
}
.qlhh-cmp-search-hit:hover {
  background: var(--bg-row-hover);
}
.qlhh-cmp-hit-name {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  flex-wrap: wrap;
}
.qlhh-cmp-hit-name strong {
  color: var(--ink-strong);
}
.qlhh-cmp-hit-name span {
  font-size: 11.5px;
  color: var(--ink-muted);
}

.qlhh-cmp-sources-grid {
  display: grid;
  gap: 14px;
}
.qlhh-cmp-sources-grid.is-4col {
  grid-template-columns: repeat(auto-fit, minmax(255px, 1fr));
}
.qlhh-cmp-sources-grid.is-3col {
  grid-template-columns: repeat(auto-fit, minmax(290px, 1fr));
}
.qlhh-cmp-source-card.is-sky {
  border-top: 3px solid #38bdf8;
}
.qlhh-cmp-source-card.is-emerald {
  border-top: 3px solid #10b981;
}
.qlhh-cmp-source-card.is-violet {
  border-top: 3px solid #8b5cf6;
}
.qlhh-bento-head.is-violet {
  color: var(--violet-text);
}

.qlhh-cmp-kv-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.qlhh-cmp-kv-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  font-size: 12.5px;
}
.qlhh-cmp-kv-row > span:first-child {
  color: var(--ink-muted);
  flex-shrink: 0;
}
.qlhh-cmp-kv-row > strong,
.qlhh-cmp-kv-row > span:last-child,
.qlhh-cmp-kv-row > code {
  color: var(--ink-strong);
  text-align: right;
  word-break: break-word;
}
.qlhh-cmp-kv-row.is-total {
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px dashed var(--border-control);
  align-items: center;
}
.qlhh-cmp-price-lg {
  font-size: 16px;
  font-weight: 900;
}
.qlhh-cmp-price-lg.is-sky {
  color: var(--sky-text);
}
.qlhh-cmp-price-lg.is-emerald {
  color: var(--emerald-text);
}
.qlhh-cmp-empty-src {
  padding: 14px 0;
  font-size: 12.5px;
  color: var(--ink-muted);
}

.qlhh-cmp-note-box {
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--bg-well);
  border: 1px solid var(--border-subtle);
  font-size: 12px;
  color: var(--ink-secondary);
}
.qlhh-cmp-note-text {
  font-size: 12px;
  line-height: 1.5;
  color: var(--ink-secondary);
}
.qlhh-cmp-note-text.is-pre {
  white-space: pre-line;
}
.qlhh-cmp-note-warn {
  margin-top: 4px;
  padding: 7px 9px;
  border-radius: 8px;
  background: var(--amber-bg);
  border: 1px solid var(--amber-border);
  color: var(--amber-text);
  font-size: 11.5px;
  font-weight: 700;
}

/* Band Strip & Acronis Related Grid */
.qlhh-cmp-band-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(118px, 1fr));
  gap: 8px;
}
.qlhh-cmp-band-tile {
  padding: 8px 10px;
  border-radius: 9px;
  background: var(--bg-well);
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  cursor: pointer;
  transition: all 0.14s ease;
}
.qlhh-cmp-band-tile:hover {
  border-color: var(--emerald-border);
  background: var(--emerald-bg);
}
.qlhh-cmp-band-tile.is-active {
  background: var(--emerald-bg);
  border: 1.5px solid var(--emerald-border);
}
.qlhh-cmp-bt-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--ink-muted);
}
.qlhh-cmp-bt-price {
  font-size: 12.5px;
  font-weight: 800;
  color: var(--emerald-text);
}

.qlhh-cmp-foot-note {
  font-size: 12px;
  color: var(--ink-muted);
}

@media (max-width: 1100px) {
  .qlhh-cmp-overlay {
    padding: 0;
  }
  .qlhh-cmp-modal {
    width: 100%;
    max-width: 100%;
    height: 100%;
    max-height: 100%;
    border-radius: 0;
    border: none;
  }
}

@media (max-width: 768px) {
  .qlhh-cmp-head .qlhh-cmp-status-pill {
    display: none;
  }
  .qlhh-cmp-head .qlhh-fm-title-row h2 {
    font-size: 14.5px;
    line-height: 1.3;
  }
  .qlhh-cmp-body {
    gap: 10px;
  }
  .qlhh-cmp-hero-card {
    padding: 12px;
  }
  .qlhh-cmp-hero-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .qlhh-cmp-hero-side.is-right {
    align-items: flex-start;
    text-align: left;
  }
  .qlhh-cmp-hero-price {
    font-size: 19px;
  }
  .qlhh-cmp-hero-mid {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: space-between;
    padding: 9px 0;
    border-left: none;
    border-right: none;
    border-top: 1px dashed var(--border-control);
    border-bottom: 1px dashed var(--border-control);
  }
  .qlhh-cmp-files-card {
    padding: 10px 12px;
  }
  .qlhh-cmp-file-grid,
  .qlhh-cmp-2col,
  .qlhh-cmp-sources-grid.is-3col,
  .qlhh-cmp-sources-grid.is-4col {
    grid-template-columns: 1fr;
  }
  .qlhh-cmp-model-group,
  .qlhh-cmp-3col-fields {
    grid-template-columns: 1fr;
  }
  .qlhh-cmp-params-grid {
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }
  .qlhh-cmp-band-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .qlhh-cmp-foot {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
  }
  .qlhh-cmp-foot .qlhh-fm-foot-right {
    width: 100%;
    justify-content: flex-end;
  }
}

/* ==========================================================================
   SỬA HÀNG LOẠT & XÓA HÀNG LOẠT (BULK EDIT / BULK DELETE)
========================================================================== */
.qlhh-bulk-toggle-btn.is-active {
  background: var(--sky-bg);
  border-color: var(--sky-border);
  color: var(--sky-text);
  font-weight: 800;
}
.qlhh-bulk-btn-count {
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--sky-text);
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.3;
}

.qlhh-bulk-check {
  width: 18px;
  height: 18px;
  margin: 0;
  padding: 0;
  border-radius: 5px;
  border: 1.5px solid var(--border-control);
  background: var(--bg-input);
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.14s ease;
}
.qlhh-bulk-check:hover {
  border-color: var(--sky-text);
}
.qlhh-bulk-check.selected {
  background: #0284c7;
  border-color: #38bdf8;
  color: #ffffff;
}
.qlhh-bulk-check.is-partial {
  background: var(--sky-bg);
  border-color: #38bdf8;
}
.qlhh-bulk-chk-dash {
  width: 8px;
  height: 2px;
  border-radius: 999px;
  background: var(--sky-text);
}
.qlhh-bulk-check.is-on-header {
  border-color: rgba(255, 255, 255, 0.55);
  background: rgba(2, 18, 38, 0.35);
}
.qlhh-bulk-check.is-on-header.selected {
  background: #ffffff;
  border-color: #ffffff;
  color: #0369a1;
}
.qlhh-bulk-check.is-on-header.is-partial {
  background: rgba(255, 255, 255, 0.25);
  border-color: #ffffff;
}
.qlhh-bulk-check.is-on-header .qlhh-bulk-chk-dash {
  background: #ffffff;
}
.qlhh-page.theme-light-blue .qlhh-bulk-check:not(.is-on-header) {
  background: #ffffff;
  border-color: #94a3b8;
}
.qlhh-page.theme-light-blue .qlhh-bulk-check:not(.is-on-header).selected {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.qlhh-data-table th.col-bulk-chk,
.qlhh-data-table td.col-bulk-chk {
  width: 38px;
  text-align: center;
  padding-left: 10px;
  padding-right: 6px;
}

.qlhh-table-row.is-bulk-selected td {
  background: rgba(14, 165, 233, 0.14) !important;
}
.qlhh-page.theme-light-blue .qlhh-table-row.is-bulk-selected td {
  background: #e0f2fe !important;
}

.qlhh-card.is-bulk-selected {
  border-color: #38bdf8 !important;
  box-shadow: inset 3px 0 0 #0284c7, 0 8px 22px -8px rgba(2, 132, 199, 0.35) !important;
}
.qlhh-page.theme-light-blue .qlhh-card.is-bulk-selected {
  background: #f0f9ff !important;
  border-color: #0284c7 !important;
  box-shadow: inset 4px 0 0 #0284c7, 0 8px 20px -8px rgba(2, 132, 199, 0.22) !important;
}

/* Floating Bulk Action Bar */
.qlhh-bulk-float-bar {
  position: fixed;
  left: 50%;
  bottom: 20px;
  transform: translateX(-50%);
  z-index: 985;
  max-width: calc(100vw - 24px);
  padding: 9px 14px;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(12, 74, 110, 0.96) 0%, rgba(15, 23, 42, 0.97) 100%);
  border: 1.5px solid rgba(56, 189, 248, 0.55);
  box-shadow: 0 18px 44px -10px rgba(2, 6, 23, 0.72);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  color: #ffffff;
}
.qlhh-bulk-float-bar.is-mobile-offset {
  bottom: calc(84px + env(safe-area-inset-bottom, 0px));
  width: calc(100vw - 20px);
  padding: 9px 11px;
  gap: 8px;
}
.qlhh-bulk-float-left {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.qlhh-bulk-float-badge {
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.3);
  font-size: 12px;
  font-weight: 700;
  color: #ffffff;
  white-space: nowrap;
}
.qlhh-bulk-float-link {
  padding: 4px 8px;
  border-radius: 7px;
  border: 1px solid rgba(125, 211, 252, 0.35);
  background: rgba(14, 165, 233, 0.18);
  color: #e0f2fe;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.14s ease;
}
.qlhh-bulk-float-link:hover {
  background: rgba(14, 165, 233, 0.35);
  color: #ffffff;
}
.qlhh-bulk-float-actions {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}
.qlhh-bulk-float-btn {
  height: 34px;
  padding: 0 12px;
  border-radius: 9px;
  border: 1px solid transparent;
  font-size: 12.5px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}
.qlhh-bulk-float-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.qlhh-bulk-float-btn.is-primary {
  background: linear-gradient(135deg, #0ea5e9 0%, #2563eb 100%);
  color: #ffffff;
  border-color: rgba(186, 230, 253, 0.5);
  box-shadow: 0 4px 12px -2px rgba(14, 165, 233, 0.45);
}
.qlhh-bulk-float-btn.is-primary:hover:not(:disabled) {
  filter: brightness(1.08);
}
.qlhh-bulk-float-btn.is-danger {
  background: rgba(239, 68, 68, 0.24);
  color: #fecaca;
  border-color: rgba(252, 165, 165, 0.45);
}
.qlhh-bulk-float-btn.is-danger:hover:not(:disabled) {
  background: #dc2626;
  color: #ffffff;
  border-color: #fca5a5;
}
.qlhh-bulk-float-btn.is-ghost {
  background: rgba(255, 255, 255, 0.12);
  color: #e2e8f0;
  border-color: rgba(255, 255, 255, 0.25);
}
.qlhh-bulk-float-btn.is-ghost:hover {
  background: rgba(255, 255, 255, 0.22);
  color: #ffffff;
}

/* Bulk Edit Modal */
.qlhh-bulk-overlay,
.qlhh-bulk-del-overlay {
  position: fixed !important;
  inset: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: rgba(2, 6, 23, 0.78);
  z-index: 10060 !important;
  padding: 14px !important;
  box-sizing: border-box;
}
.qlhh-bulk-tbl-search {
  height: 28px;
  width: 195px;
  padding: 0 9px;
  border-radius: 7px;
  border: 1px solid var(--border-control);
  background: var(--bg-input);
  color: var(--ink-primary);
  font-size: 11.5px;
}
.qlhh-bulk-tbl-search:focus {
  outline: none;
  border-color: var(--sky-border);
}
.qlhh-bulk-load-more-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 11px 14px;
  background: var(--bg-table-head);
  border-top: 1px solid var(--border-subtle);
  font-size: 12px;
  color: var(--ink-secondary);
}
.qlhh-bulk-del-overlay {
  z-index: 10070 !important;
}
.qlhh-bulk-modal {
  width: min(1480px, 98vw);
  height: min(94dvh, 920px);
  max-height: 94dvh;
  background: var(--bg-modal);
  border: 1px solid var(--border-control);
  border-radius: 16px;
  box-shadow: var(--shadow-modal);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color: var(--ink-primary);
}
.qlhh-bulk-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 18px;
  background: linear-gradient(135deg, #0c4a6e 0%, #0369a1 52%, #0f766e 100%);
  border-bottom: 1.5px solid rgba(56, 189, 248, 0.48);
  color: #ffffff;
  flex-shrink: 0;
}
.qlhh-bulk-overlay.theme-light-blue .qlhh-bulk-head {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 55%, #1d4ed8 100%);
  border-bottom-color: #1d4ed8;
}
.qlhh-bulk-head-left {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}
.qlhh-bulk-head-ico {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.36);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  flex-shrink: 0;
}
.qlhh-bulk-head-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.qlhh-bulk-head-title-row h3 {
  margin: 0;
  font-size: 15.5px;
  font-weight: 800;
  color: #ffffff;
}
.qlhh-bulk-head-pill {
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.36);
  color: #ffffff;
}
.qlhh-bulk-head-pill.is-origin {
  background: rgba(16, 185, 129, 0.32);
  border-color: rgba(167, 243, 208, 0.65);
}
.qlhh-bulk-head-sub {
  margin: 2px 0 0;
  font-size: 12px;
  color: rgba(224, 242, 254, 0.9);
}
.qlhh-bulk-close {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  background: rgba(2, 18, 38, 0.28);
  color: #ffffff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.qlhh-bulk-close:hover {
  background: rgba(239, 68, 68, 0.8);
  border-color: #fecaca;
}

.qlhh-bulk-notice {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 18px;
  background: var(--amber-bg);
  border-bottom: 1px solid var(--amber-border);
  color: var(--amber-text);
  font-size: 12px;
  font-weight: 600;
  flex-shrink: 0;
}

.qlhh-bulk-body {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px 16px;
  overflow: hidden;
  background: var(--bg-well);
}

/* Batch Apply Panel */
.qlhh-bulk-panel {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  overflow: hidden;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
